-- 設問の取り込み（import_cbt_basic_2026、1/2本目、324問）。
-- 元のデータ: cbt_batch_basic_2026.json
-- status は pending（審査待ち）で入り、人の医学的レビューで公開するまで学習者には出ない。
-- 何度流しても結果は同じ（すでにある問題は入れない）。本数が複数あるときは全部流す。順番は問わない。
-- 最後に「追加した問題／すでにあった問題」の表が出る。
-- scripts/build_question_import_sql.py で作り直せる。
WITH v (category, topic, difficulty, exam_type, question_text, choices, correct_choice_key, explanation, choice_explanations, visibility, question_type, blueprint_code, class_group, status, source) AS (VALUES
('基礎医学', '塩基性アミノ酸', 2, 'CBT', '蛋白質の立体構造や機能は、構成するアミノ酸の側鎖の性質に大きく左右される。生理的なpHで側鎖が正に荷電しているアミノ酸はどれか。', '[{"key": "A", "text": "リシン"}, {"key": "B", "text": "グルタミン酸"}, {"key": "C", "text": "セリン"}, {"key": "D", "text": "ロイシン"}, {"key": "E", "text": "フェニルアラニン"}]'::jsonb, 'A', '塩基性アミノ酸はリシン、アルギニン、ヒスチジンである。リシンのε-アミノ基とアルギニンのグアニジノ基は生理的pHでほぼ完全にプロトン化され、正に荷電する。ヒスチジンのイミダゾール基はpKaが約6で、生理的pHでは一部しか荷電しない。酸性アミノ酸はアスパラギン酸とグルタミン酸である。ヒストンはリシンとアルギニンに富み、正の電荷で負に荷電したDNAと結合する。', '{"B": "カルボキシ基をもつ酸性アミノ酸で、生理的pHでは負に荷電する。", "C": "ヒドロキシ基をもつ極性アミノ酸だが、電荷はもたない。", "D": "分枝鎖をもつ疎水性アミノ酸で、電荷はもたない。", "E": "芳香環をもつ疎水性アミノ酸で、電荷はもたない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '蛋白質の二次構造', 2, 'CBT', '蛋白質の構造は一次から四次までの階層に分けて理解される。αヘリックスやβシートといった二次構造を主に安定化させている結合はどれか。', '[{"key": "A", "text": "疎水性の側鎖どうしの疎水性相互作用"}, {"key": "B", "text": "主鎖のカルボニル基とイミノ基の間の水素結合"}, {"key": "C", "text": "システイン残基の側鎖どうしのジスルフィド結合"}, {"key": "D", "text": "アミノ酸どうしをつなぐペプチド結合"}, {"key": "E", "text": "酸性と塩基性の側鎖の間のイオン結合"}]'::jsonb, 'B', '二次構造は主鎖（ポリペプチド骨格）の局所的な立体配置で、αヘリックスでは4残基離れたC=O基とN-H基が、βシートでは隣り合う鎖どうしのC=O基とN-H基が水素結合をつくって安定化する。側鎖どうしのジスルフィド結合、イオン結合、疎水性相互作用は主に三次構造の形成に関わる。一次構造はペプチド結合によるアミノ酸の配列である。', '{"A": "蛋白質が折りたたまれる際の駆動力で、主に三次構造に関わる。", "C": "共有結合で、主に三次構造や四次構造を安定化させる。", "D": "一次構造（アミノ酸配列）をつくる結合である。", "E": "側鎖どうしの相互作用で、三次構造の安定化に関わる。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '必須アミノ酸', 2, 'CBT', '食事から摂取しなければならない栄養素を整理している。ヒトの体内で合成できないため食事からの摂取が必要な必須アミノ酸はどれか。', '[{"key": "A", "text": "アスパラギン酸"}, {"key": "B", "text": "チロシン"}, {"key": "C", "text": "イソロイシン"}, {"key": "D", "text": "アラニン"}, {"key": "E", "text": "グリシン"}]'::jsonb, 'C', '成人の必須アミノ酸はバリン、ロイシン、イソロイシン、リシン、メチオニン、フェニルアラニン、トレオニン、トリプトファン、ヒスチジンの9種類である。イソロイシンはロイシン、バリンとともに分枝鎖アミノ酸で、主に骨格筋で代謝される。チロシンは通常フェニルアラニンから合成されるが、フェニルアラニン水酸化酵素が欠損するフェニルケトン尿症では合成できず、必須となる。', '{"A": "オキサロ酢酸からアミノ基転移で合成できる非必須アミノ酸である。", "B": "フェニルアラニンの水酸化で合成できるため、通常は必須ではない。", "D": "ピルビン酸からアミノ基転移で合成できる非必須アミノ酸である。", "E": "セリンから合成できる非必須アミノ酸である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '二糖類の構成', 2, 'CBT', '食事中の二糖類は小腸刷子縁の酵素で単糖に分解されてから吸収される。スクロース（ショ糖）を構成する単糖の組合せはどれか。', '[{"key": "A", "text": "グルコースとグルコース"}, {"key": "B", "text": "ガラクトースとフルクトース"}, {"key": "C", "text": "グルコースとリボース"}, {"key": "D", "text": "グルコースとフルクトース"}, {"key": "E", "text": "グルコースとガラクトース"}]'::jsonb, 'D', 'スクロースはグルコースとフルクトースが結合した二糖類で、小腸刷子縁のスクラーゼ（スクラーゼ-イソマルターゼ）によって分解される。ラクトースはグルコースとガラクトース、マルトースはグルコース2分子からなる。ラクターゼの活性が低いと乳糖不耐症となり、分解されない乳糖が大腸で発酵して下痢や腹部膨満をきたす。', '{"A": "マルトース（麦芽糖）の構成である。", "B": "食品中に一般的な二糖類としては存在しない組合せである。", "C": "リボースは核酸の構成糖で、二糖類の成分ではない。", "E": "ラクトース（乳糖）の構成である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'コレステロールの役割', 2, 'CBT', '細胞膜を構成する脂質の役割について整理している。脂質二重層の流動性を調節し、ステロイドホルモンや胆汁酸の前駆体にもなる脂質はどれか。', '[{"key": "A", "text": "トリアシルグリセロール"}, {"key": "B", "text": "ホスファチジルコリン"}, {"key": "C", "text": "アラキドン酸"}, {"key": "D", "text": "スフィンゴミエリン"}, {"key": "E", "text": "コレステロール"}]'::jsonb, 'E', 'コレステロールはステロイド骨格をもつ脂質で、リン脂質の間に入り込んで膜の流動性を調節する。副腎皮質ホルモンや性ホルモンなどのステロイドホルモンと、肝でつくられる胆汁酸の前駆体となる。体内では主に肝でアセチルCoAから合成され、HMG-CoA還元酵素がその律速酵素である。合成の中間体である7-デヒドロコレステロールは、皮膚で紫外線を受けてビタミンD3になる。', '{"A": "脂肪組織に蓄えられる貯蔵脂質で、膜の構成成分ではない。", "B": "膜の主要なリン脂質だが、ステロイド骨格をもたず前駆体にならない。", "C": "プロスタグランジンなどエイコサノイドの前駆体となる脂肪酸である。", "D": "髄鞘に多いスフィンゴリン脂質で、ステロイドの前駆体ではない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'RNAの特徴', 2, 'CBT', '遺伝情報を担う核酸にはDNAとRNAがあり、構成成分や高次構造が異なる。DNAと比較したRNAの特徴として正しいのはどれか。', '[{"key": "A", "text": "塩基としてチミンの代わりにウラシルをもつ"}, {"key": "B", "text": "構成する糖がデオキシリボースである"}, {"key": "C", "text": "細胞内では常に二本鎖として存在する"}, {"key": "D", "text": "アデニンはシトシンと塩基対をつくる"}, {"key": "E", "text": "ヌクレオチドどうしが水素結合だけでつながる"}]'::jsonb, 'A', 'RNAは糖がリボースで、塩基はアデニン、グアニン、シトシン、ウラシルからなる。DNAは糖がデオキシリボースで、ウラシルの代わりにチミンをもち、通常は二本鎖の二重らせん構造をとる。RNAは一本鎖が基本で、tRNAのように分子内で塩基対をつくり立体構造をとるものもある。リボースの2′位のヒドロキシ基のため、RNAはDNAより加水分解されやすい。', '{"B": "デオキシリボースはDNAの糖で、RNAの糖はリボースである。", "C": "RNAは通常一本鎖で、部分的に分子内で塩基対をつくる。", "D": "アデニンはRNAではウラシル、DNAではチミンと対をつくる。", "E": "RNAもDNAもヌクレオチドはホスホジエステル結合で連結する。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '血液の緩衝系', 2, 'CBT', '動脈血のpHは7.35〜7.45の狭い範囲に保たれている。細胞外液の酸塩基緩衝において量的に最も大きな役割を果たす緩衝系はどれか。', '[{"key": "A", "text": "アンモニア緩衝系"}, {"key": "B", "text": "炭酸-重炭酸緩衝系"}, {"key": "C", "text": "リン酸緩衝系"}, {"key": "D", "text": "ヘモグロビンによる緩衝系"}, {"key": "E", "text": "血漿蛋白緩衝系"}]'::jsonb, 'B', '細胞外液の緩衝の主体は炭酸-重炭酸緩衝系である。二酸化炭素は肺から、重炭酸イオンは腎で調節されるため、開放系として大きな緩衝能をもつ。pHはHenderson-Hasselbalchの式で重炭酸イオン濃度と二酸化炭素分圧の比によって決まる。細胞内ではリン酸や蛋白質、赤血球内ではヘモグロビンが緩衝に働く。', '{"A": "尿細管で酸を排泄する際に働く系で、血液の緩衝系ではない。", "C": "主に細胞内液と尿で働き、細胞外液での寄与は小さい。", "D": "赤血球の中で働く緩衝系で、細胞外液の主体ではない。", "E": "寄与はあるが、量的には重炭酸系より小さい。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'Michaelis定数', 2, 'CBT', '酵素反応の速度論を学習している。Michaelis-Menten式に従う酵素のミカエリス定数（Km）について正しいのはどれか。', '[{"key": "A", "text": "反応速度が最大となる基質濃度である"}, {"key": "B", "text": "温度やpHの影響を受けない定数である"}, {"key": "C", "text": "最大反応速度の半分の速度を与える基質濃度である"}, {"key": "D", "text": "値が大きいほど酵素と基質の親和性が高いことを示す"}, {"key": "E", "text": "酵素濃度を2倍にするとKmも2倍になる"}]'::jsonb, 'C', 'Michaelis-Menten式では、基質濃度がKmに等しいとき反応速度は最大反応速度（Vmax）の半分になる。Kmは酵素と基質の親和性の目安で、小さいほど低い基質濃度で反応が進む。酵素量を増やすとVmaxは比例して増えるが、Kmは変わらない。Lineweaver-Burkプロット（二重逆数プロット）では横軸の切片が-1/Km、縦軸の切片が1/Vmaxとなる。', '{"A": "最大反応速度には基質濃度を上げても漸近するだけで、そこに達する濃度は定まらない。", "B": "Kmは温度やpHなど反応条件によって変化する。", "D": "Kmが大きいほど、半分の速度に達するのに多くの基質を要し、親和性は低い。", "E": "酵素濃度で変わるのは最大反応速度で、Kmは変わらない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '酵素の阻害様式', 2, 'CBT', 'ある酵素に阻害薬を加えて反応速度を測定した。最大反応速度は変わらず、見かけのミカエリス定数が大きくなった。この阻害様式はどれか。', '[{"key": "A", "text": "不競合阻害"}, {"key": "B", "text": "不可逆的阻害"}, {"key": "C", "text": "アロステリック活性化"}, {"key": "D", "text": "競合阻害"}, {"key": "E", "text": "非競合阻害"}]'::jsonb, 'D', '競合阻害薬は基質と同じ活性部位を奪い合うため、基質濃度を十分に上げれば阻害に打ち勝ち、最大反応速度は変わらない。一方で半分の速度を得るにはより多くの基質を要するため、見かけのKmは大きくなる。非競合阻害では活性部位以外に結合して働く酵素を減らすのと同じ効果となり、Vmaxが低下しKmは変わらない。メトトレキサート（ジヒドロ葉酸還元酵素）やスタチン（HMG-CoA還元酵素）は競合阻害の例である。', '{"A": "酵素-基質複合体に結合し、最大反応速度とミカエリス定数がともに低下する。", "B": "働く酵素の量が減るのと同じで、最大反応速度が低下する。", "C": "反応を促進する調節であり、阻害様式ではない。", "E": "最大反応速度が低下し、ミカエリス定数は変わらない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'アロステリック酵素', 2, 'CBT', '代謝経路の律速段階を担う酵素には、アロステリック調節を受けるものが多い。アロステリック酵素の性質として正しいのはどれか。', '[{"key": "A", "text": "活性部位以外に物質が結合しても活性は変化しない"}, {"key": "B", "text": "反応速度は常にMichaelis-Menten式に従う"}, {"key": "C", "text": "経路の最終産物によって活性が高まることが多い"}, {"key": "D", "text": "単一のサブユニットのみからなることが多い"}, {"key": "E", "text": "基質濃度と反応速度の関係がS字状の曲線を示す"}]'::jsonb, 'E', 'アロステリック酵素は複数のサブユニットからなることが多く、基質の結合が他のサブユニットの親和性を変える協同性のため、反応速度はS字状（シグモイド）曲線を示す。活性部位とは別の部位にエフェクターが結合して活性が調節される。解糖系のホスホフルクトキナーゼ1はATPやクエン酸で抑制され、AMPやフルクトース2,6-ビスリン酸で活性化される。', '{"A": "活性部位以外（アロステリック部位）への結合で活性が変わるのが特徴である。", "B": "協同性があるため双曲線にならず、この式に従わない。", "C": "最終産物は多くの場合、負のフィードバックとして活性を抑える。", "D": "多くは複数のサブユニットからなり、サブユニット間の協同性を示す。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ビタミンB1の活性型', 2, 'CBT', 'ピルビン酸をアセチルCoAに変換するピルビン酸脱水素酵素複合体には、ビタミン由来の補酵素が必要である。ビタミンB1の活性型の補酵素はどれか。', '[{"key": "A", "text": "チアミン二リン酸"}, {"key": "B", "text": "ピリドキサールリン酸"}, {"key": "C", "text": "フラビンアデニンジヌクレオチド"}, {"key": "D", "text": "ニコチンアミドアデニンジヌクレオチド"}, {"key": "E", "text": "テトラヒドロ葉酸"}]'::jsonb, 'A', 'ピルビン酸脱水素酵素複合体は、チアミン二リン酸、リポ酸、補酵素A、FAD、NAD+を補酵素とする。ビタミンB1が欠乏するとピルビン酸がアセチルCoAへ変換されず、乳酸アシドーシスをきたしやすい。α-ケトグルタル酸脱水素酵素やトランスケトラーゼもチアミン二リン酸を要する。欠乏症には脚気やWernicke脳症があり、アルコール多飲者などでブドウ糖の輸液が先行すると誘発されることがある。', '{"B": "ビタミンB6の活性型で、アミノ基転移反応などに働く。", "C": "ビタミンB2（リボフラビン）に由来する補酵素である。", "D": "ナイアシンに由来する補酵素である。", "E": "葉酸の活性型で、一炭素単位の運搬に働く。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'アミノ基転移の補酵素', 2, 'CBT', '肝機能検査で測定されるALTやASTは、アミノ基転移反応を触媒する酵素である。アミノ基転移酵素の補酵素として働くものはどれか。', '[{"key": "A", "text": "フラビンアデニンジヌクレオチド"}, {"key": "B", "text": "ピリドキサールリン酸"}, {"key": "C", "text": "チアミン二リン酸"}, {"key": "D", "text": "ビオチン"}, {"key": "E", "text": "コバラミン"}]'::jsonb, 'B', 'アミノ基転移酵素は、アミノ酸のアミノ基をα-ケト酸へ移す。ALTはアラニンとα-ケトグルタル酸からピルビン酸とグルタミン酸をつくり、ASTはアスパラギン酸をオキサロ酢酸に変える。補酵素はビタミンB6の活性型であるピリドキサールリン酸で、アミノ酸の脱炭酸やヘム合成の最初の段階（δ-アミノレブリン酸合成酵素）にも必要である。', '{"A": "ビタミンB2に由来し、酸化還元反応の補酵素として働く。", "C": "α-ケト酸の脱炭酸反応などに働くビタミンB1の活性型である。", "D": "カルボキシ化反応の補酵素である。", "E": "メチオニン合成酵素やメチルマロニルCoAムターゼの補酵素である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ビタミンK依存性の修飾', 2, 'CBT', '肝で合成される凝固因子の一部は、ビタミンKを補因子とする翻訳後修飾を受けて初めてカルシウムイオンと結合できるようになる。この修飾はどれか。', '[{"key": "A", "text": "セリン残基のリン酸化"}, {"key": "B", "text": "アスパラギン残基へのN-結合型糖鎖の付加"}, {"key": "C", "text": "グルタミン酸残基のγ-カルボキシ化"}, {"key": "D", "text": "プロリン残基の水酸化"}, {"key": "E", "text": "リシン残基のアセチル化"}]'::jsonb, 'C', '第II、VII、IX、X因子とプロテインC、プロテインSは、ビタミンK依存性のγ-グルタミルカルボキシラーゼによってグルタミン酸残基がγ-カルボキシグルタミン酸に変換される。この構造がカルシウムイオンを介してリン脂質膜に結合することで凝固反応が進む。ワルファリンはビタミンKエポキシド還元酵素を阻害して還元型ビタミンKの再生を妨げ、この修飾を抑制する。', '{"A": "キナーゼによる細胞内シグナル伝達の修飾である。", "B": "小胞体で行われる糖鎖の付加で、凝固因子のカルシウム結合とは関係しない。", "D": "ビタミンCを要するコラーゲンの修飾である。", "E": "ヒストンなどで遺伝子発現の調節に関わる修飾である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ビタミンCの作用', 2, 'CBT', '長期間にわたり野菜や果物をほとんど摂取していない患者で、歯肉出血と創傷治癒の遅れを認めた。欠乏が疑われるビタミンの生化学的な作用はどれか。', '[{"key": "A", "text": "網膜の杆体にある視物質ロドプシンの構成成分となる"}, {"key": "B", "text": "凝固因子のγ-カルボキシ化を担う"}, {"key": "C", "text": "メチオニン合成酵素の補酵素となる"}, {"key": "D", "text": "プロリンとリシンの水酸化反応の補因子となる"}, {"key": "E", "text": "カルシウムの腸管からの吸収を促進する"}]'::jsonb, 'D', 'ビタミンC（アスコルビン酸）は、コラーゲンのプロリン残基とリシン残基を水酸化する酵素の補因子で、水酸化されたコラーゲンは安定な三重らせんをつくる。欠乏するとコラーゲンが脆弱になり、歯肉出血、皮下出血、創傷治癒の遅延などを示す壊血病となる。ビタミンCは水溶性の抗酸化物質でもあり、非ヘム鉄の吸収を促進する。', '{"A": "ビタミンA（レチナール）の役割である。", "B": "ビタミンKの役割である。", "C": "ビタミンB12の役割である。", "E": "活性型ビタミンDの作用である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ビタミンAの欠乏', 2, 'CBT', '胆道が閉塞して胆汁が腸管に排出されない患者では、脂溶性ビタミンの吸収が低下する。欠乏すると暗順応が障害されて夜盲をきたすビタミンはどれか。', '[{"key": "A", "text": "ビタミンB1"}, {"key": "B", "text": "ビタミンB12"}, {"key": "C", "text": "ビタミンC"}, {"key": "D", "text": "ナイアシン"}, {"key": "E", "text": "ビタミンA"}]'::jsonb, 'E', '脂溶性ビタミンはA、D、E、Kで、吸収には胆汁酸によるミセル形成が必要である。ビタミンAの誘導体であるレチナールは、オプシンと結合して杆体の視物質ロドプシンをつくる。欠乏すると暗順応が低下して夜盲となり、角膜乾燥症もきたす。閉塞性黄疸ではビタミンKの吸収も低下し、プロトロンビン時間が延長する。', '{"A": "水溶性ビタミンで、欠乏すると脚気やWernicke脳症をきたす。", "B": "回腸末端で内因子と結合して吸収され、欠乏すると巨赤芽球性貧血をきたす。", "C": "水溶性ビタミンで、欠乏すると壊血病をきたす。", "D": "水溶性ビタミンで、欠乏するとペラグラをきたす。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ナイアシンの欠乏', 2, 'CBT', 'トウモロコシを主食とする地域やアルコール多飲者にみられる欠乏症がある。トリプトファンから一部合成され、欠乏すると皮膚炎・下痢・認知機能障害をきたすビタミンはどれか。', '[{"key": "A", "text": "ナイアシン"}, {"key": "B", "text": "リボフラビン"}, {"key": "C", "text": "ピリドキシン"}, {"key": "D", "text": "葉酸"}, {"key": "E", "text": "パントテン酸"}]'::jsonb, 'A', 'ナイアシン（ニコチン酸、ニコチンアミド）はNAD+やNADP+の構成成分で、多くの酸化還元反応に必要である。欠乏症のペラグラは皮膚炎、下痢、認知症を三徴とする。トリプトファンから一部合成されるため、トリプトファンの少ないトウモロコシ主体の食事や、トリプトファンが腫瘍で大量に消費されるカルチノイド症候群でも欠乏しうる。', '{"B": "欠乏すると口角炎や舌炎、脂漏性皮膚炎をきたす。", "C": "欠乏すると末梢神経障害やけいれん、口内炎をきたす。", "D": "欠乏すると巨赤芽球性貧血をきたし、妊娠中は神経管閉鎖障害の危険が高まる。", "E": "補酵素Aの構成成分で、食品に広く含まれ欠乏症はまれである。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '葉酸の役割', 2, 'CBT', '葉酸は細胞増殖の盛んな組織で特に必要とされる。生体内で葉酸の活性型であるテトラヒドロ葉酸が担う役割として正しいのはどれか。', '[{"key": "A", "text": "アミノ基を運搬し、アミノ基転移反応に関わる"}, {"key": "B", "text": "一炭素単位を運び、核酸塩基の合成に関わる"}, {"key": "C", "text": "アシル基を運搬し、脂肪酸の代謝に関わる"}, {"key": "D", "text": "電子を運搬し、酸化還元反応に関わる"}, {"key": "E", "text": "二酸化炭素を固定し、カルボキシ化反応に関わる"}]'::jsonb, 'B', 'テトラヒドロ葉酸はメチル基やホルミル基などの一炭素単位を運搬し、プリン塩基の合成や、dUMPからdTMPをつくるチミジル酸合成に必要である。欠乏するとDNA合成が障害され、巨赤芽球性貧血をきたす。メトトレキサートはジヒドロ葉酸還元酵素を阻害してテトラヒドロ葉酸の再生を妨げ、抗腫瘍作用や免疫抑制作用を示す。', '{"A": "ピリドキサールリン酸の役割である。", "C": "補酵素Aの役割である。", "D": "NAD+やFADなどの役割である。", "E": "ビオチンの役割である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'リガーゼ', 2, 'CBT', '酵素は触媒する反応の種類によって分類される。ATPなどの高エネルギー結合の加水分解と共役して、2つの分子を結合させる酵素群はどれか。', '[{"key": "A", "text": "トランスフェラーゼ"}, {"key": "B", "text": "ヒドロラーゼ"}, {"key": "C", "text": "リガーゼ"}, {"key": "D", "text": "リアーゼ"}, {"key": "E", "text": "イソメラーゼ"}]'::jsonb, 'C', 'リガーゼ（合成酵素）はATPなどの加水分解のエネルギーを使って2つの分子を共有結合でつなぐ。DNAリガーゼは岡崎フラグメントをつなぎ、ピルビン酸カルボキシラーゼやアセチルCoAカルボキシラーゼもこの群に入る。酵素番号の分類では酸化還元酵素、転移酵素、加水分解酵素、脱離酵素、異性化酵素、合成酵素などに分けられる。', '{"A": "ある分子から別の分子へ官能基を移す反応を触媒する。", "B": "水を用いて結合を切断する加水分解反応を触媒する。", "D": "加水分解や酸化によらずに基を脱離させ、二重結合をつくる（またはその逆の）反応を触媒する。", "E": "分子内の構造を変える異性化反応を触媒する。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'アイソザイム', 2, 'CBT', '血清の乳酸脱水素酵素（LD）の分画を調べると、障害された臓器を推定できることがある。アイソザイムの説明として正しいのはどれか。', '[{"key": "A", "text": "異なる反応を触媒するが、同じ遺伝子から翻訳される酵素群である"}, {"key": "B", "text": "1種類のサブユニットのみからなる単量体の酵素である"}, {"key": "C", "text": "臓器が障害されても血中での分画の比率は変わらない"}, {"key": "D", "text": "同じ反応を触媒するが、構造や臓器分布が異なる酵素群である"}, {"key": "E", "text": "同じ分子が臓器によって異なる反応を触媒するものである"}]'::jsonb, 'D', 'アイソザイムは同じ化学反応を触媒するが、アミノ酸配列や物理化学的性質、臓器分布が異なる酵素群である。LDはH（心筋型）とM（骨格筋型）のサブユニットからなる四量体で、LD1〜LD5の5種類がある。心筋や赤血球ではLD1、LD2、肝や骨格筋ではLD5が多い。CKもMM、MB、BBのアイソザイムがあり、CK-MBは心筋障害の指標となる。', '{"A": "触媒する反応は同じで、多くは異なる遺伝子の産物である。", "B": "LDはH型とM型のサブユニットからなる四量体で、組合せで5種類になる。", "C": "障害臓器から逸脱した分画が増えるので、比率が変わり臓器の推定に使える。", "E": "アイソザイムは同じ反応を触媒し、分子の構造が異なる。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ABO血液型抗原の生化学', 2, 'CBT', 'ABO式血液型は赤血球膜の糖鎖構造の違いで決まる。A型抗原とB型抗原の違いを生み出しているものはどれか。', '[{"key": "A", "text": "膜蛋白のアミノ酸配列の違い"}, {"key": "B", "text": "膜リン脂質を構成する脂肪酸の組成"}, {"key": "C", "text": "赤血球内のヘモグロビンの種類"}, {"key": "D", "text": "赤血球膜のコレステロール含量"}, {"key": "E", "text": "糖鎖の末端に付加される糖の種類"}]'::jsonb, 'E', 'ABO抗原は共通の前駆体であるH抗原の末端に、A型ではN-アセチルガラクトサミン、B型ではガラクトースが糖転移酵素によって付加されてできる。O型はどちらの転移酵素も働かず、H抗原のままである。A遺伝子とB遺伝子の産物は数個のアミノ酸の違いで基質特異性が変わった糖転移酵素である。', '{"A": "アミノ酸配列の違いで決まるのはRh式のD抗原などである。", "B": "ABO抗原は糖鎖の違いで、脂肪酸組成とは関係しない。", "C": "ヘモグロビンは細胞内にあり、血液型抗原ではない。", "D": "血液型抗原の違いを生むものではない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '蛋白質の変性', 2, 'CBT', '卵白を加熱すると白く固まるように、蛋白質は条件によって変性する。蛋白質の変性について正しいのはどれか。', '[{"key": "A", "text": "高次構造は壊れるが、ペプチド結合による一次構造は保たれる"}, {"key": "B", "text": "ペプチド結合が切断されてアミノ酸に分解される"}, {"key": "C", "text": "いったん変性すると元の構造には決して戻らない"}, {"key": "D", "text": "加熱したときにだけ起こり、酸やアルカリを加えても起こらない"}, {"key": "E", "text": "変性すると酵素活性は上昇する"}]'::jsonb, 'A', '変性は、熱、酸・アルカリ、尿素、界面活性剤などで水素結合や疎水性相互作用が壊れ、蛋白質の二次〜四次構造が失われることをいう。ペプチド結合は切れないので一次構造は保たれる。Anfinsenのリボヌクレアーゼの実験では、変性剤を除くと活性が回復し、立体構造がアミノ酸配列によって決まることが示された。', '{"B": "それは加水分解（消化）であり、変性ではペプチド結合は切れない。", "C": "条件を戻すと元の構造と活性を回復する例がある（リボヌクレアーゼの再生実験）。", "D": "酸、アルカリ、尿素、界面活性剤、有機溶媒などでも起こる。", "E": "立体構造が崩れるため、酵素活性は通常失われる。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ヘモグロビンの鉄', 2, 'CBT', 'ヘモグロビンのヘムは、ポルフィリン環の中心に金属イオンをもつ。ヘモグロビンが酸素を可逆的に結合するために必要なヘム鉄の状態はどれか。', '[{"key": "A", "text": "マグネシウムイオン"}, {"key": "B", "text": "2価鉄（Fe2+）"}, {"key": "C", "text": "3価鉄（Fe3+）"}, {"key": "D", "text": "銅イオン（Cu2+）"}, {"key": "E", "text": "亜鉛イオン"}]'::jsonb, 'B', 'ヘモグロビンは2価鉄（Fe2+）のヘムに酸素が可逆的に結合する。鉄が3価に酸化されたメトヘモグロビンは酸素を結合できず、亜硝酸薬やある種の局所麻酔薬などで増えるとチアノーゼをきたす（メトヘモグロビン血症）。赤血球内ではNADH-シトクロムb5還元酵素がメトヘモグロビンを還元しており、治療にはメチレンブルーが用いられる。', '{"A": "植物のクロロフィルの中心金属で、ヘムには含まれない。", "C": "3価鉄のヘモグロビンはメトヘモグロビンで、酸素を運搬できない。", "D": "セルロプラスミンや電子伝達系の複合体IVに含まれ、ヘモグロビンにはない。", "E": "炭酸脱水酵素などの補因子で、ヘモグロビンの酸素結合部位ではない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '膜リン脂質の非対称性', 2, 'CBT', '細胞膜の脂質二重層では、内層と外層でリン脂質の組成が異なる。通常は内層に分布し、外層に露出するとアポトーシス細胞が貪食される目印となるリン脂質はどれか。', '[{"key": "A", "text": "ガングリオシド"}, {"key": "B", "text": "コレステロール"}, {"key": "C", "text": "ホスファチジルセリン"}, {"key": "D", "text": "ホスファチジルコリン"}, {"key": "E", "text": "スフィンゴミエリン"}]'::jsonb, 'C', '健常な細胞では、フリッパーゼの働きでホスファチジルセリンやホスファチジルエタノールアミンが内層に偏って分布する。アポトーシスが起こるとこの非対称性が失われ、外層に露出したホスファチジルセリンをマクロファージが認識して、炎症を起こさずに貪食する。アネキシンVがホスファチジルセリンに結合する性質は、アポトーシスの検出に利用される。', '{"A": "外層に分布する糖脂質で、貪食の目印となるリン脂質ではない。", "B": "両層に分布するステロール類で、リン脂質ではない。", "D": "主に外層に多く分布するリン脂質である。", "E": "主に外層に多く分布するスフィンゴリン脂質である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '活性酸素の消去', 2, 'CBT', '好気的代謝ではミトコンドリアなどで活性酸素が生じ、細胞は複数の酵素でこれを消去している。スーパーオキシドを過酸化水素に変換する酵素はどれか。', '[{"key": "A", "text": "グルタチオンペルオキシダーゼ"}, {"key": "B", "text": "NADPHオキシダーゼ"}, {"key": "C", "text": "ミエロペルオキシダーゼ"}, {"key": "D", "text": "スーパーオキシドジスムターゼ"}, {"key": "E", "text": "カタラーゼ"}]'::jsonb, 'D', 'スーパーオキシド（O2-）はスーパーオキシドジスムターゼ（SOD）によって過酸化水素に変換され、過酸化水素はカタラーゼやグルタチオンペルオキシダーゼで水に分解される。過酸化水素が鉄イオンと反応すると、反応性の高いヒドロキシルラジカルが生じる。銅・亜鉛SOD1の遺伝子変異は家族性筋萎縮性側索硬化症の原因の一つである。', '{"A": "還元型グルタチオンを用いて過酸化水素や過酸化脂質を還元する。", "B": "食細胞で酸素からスーパーオキシドをつくる酵素で、消去ではなく産生を担う。", "C": "好中球で過酸化水素と塩化物イオンから次亜塩素酸をつくる。", "E": "過酸化水素を水と酸素に分解する酵素である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '蛋白質の等電点', 2, 'CBT', '血清蛋白の電気泳動では、pHの条件によって蛋白質の移動の向きと距離が変わる。蛋白質の等電点について正しいのはどれか。', '[{"key": "A", "text": "等電点では蛋白質は電気泳動で陰極へ移動する"}, {"key": "B", "text": "等電点はすべての蛋白質で同じ値になる"}, {"key": "C", "text": "等電点より低いpHでは蛋白質は負に荷電する"}, {"key": "D", "text": "等電点では蛋白質の水への溶解度が最も高くなる"}, {"key": "E", "text": "分子全体の正味の電荷がゼロとなるpHである"}]'::jsonb, 'E', '蛋白質はアミノ基やカルボキシ基などの解離基をもち、pHによって電荷が変わる。正味の電荷がゼロになるpHを等電点といい、このとき電気泳動では移動せず、分子どうしの反発が小さいため沈殿しやすい。等電点より低いpHでは正、高いpHでは負に荷電する。血清蛋白の電気泳動（pH8.6）では、多くの蛋白質が負に荷電して陽極側へ移動する。', '{"A": "正味の電荷がゼロなので、電場の中でどちらにも移動しない。", "B": "酸性・塩基性アミノ酸の組成によって蛋白質ごとに異なる。", "C": "等電点より低いpHではプロトン化が進み、正に荷電する。", "D": "分子間の静電的な反発がなくなるため、溶解度は最も低くなりやすい。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'グルコキナーゼ', 2, 'CBT', 'グルコースを細胞内でリン酸化する酵素には、ヘキソキナーゼとグルコキナーゼがある。肝細胞や膵β細胞にあるグルコキナーゼの特徴として正しいのはどれか。', '[{"key": "A", "text": "グルコースに対するKmが高く、血糖が高いときに働く"}, {"key": "B", "text": "生成物のグルコース6-リン酸によって強く阻害される"}, {"key": "C", "text": "全身のほぼすべての細胞に発現している"}, {"key": "D", "text": "低い血糖でも十分に働くほどグルコースとの親和性が高い"}, {"key": "E", "text": "解糖系の最後の段階の反応を触媒する"}]'::jsonb, 'A', 'ヘキソキナーゼはKmが低く、低い血糖でもグルコースを取り込んでリン酸化できるが、生成物のグルコース6-リン酸で阻害される。グルコキナーゼはKmが高く、食後に血糖が上がったときに肝でグルコースを取り込んでグリコーゲン合成に回し、膵β細胞では血糖の感知器としてインスリン分泌の閾値を決める。グルコキナーゼ遺伝子の異常はMODY2の原因となる。', '{"B": "生成物で強く阻害されるのはヘキソキナーゼで、グルコキナーゼは阻害を受けにくい。", "C": "ほぼすべての細胞にあるのはヘキソキナーゼである。", "D": "親和性が高い（Kmが低い）のはヘキソキナーゼである。", "E": "解糖系の最初の段階（グルコースのリン酸化）を触媒する。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '乳酸産生の意義', 2, 'CBT', '短距離走のような激しい運動中の骨格筋では、酸素の供給が追いつかず乳酸が産生される。このとき乳酸が産生される意義として正しいのはどれか。', '[{"key": "A", "text": "酸素が十分に供給されているときほど多く産生される"}, {"key": "B", "text": "NADHを酸化してNAD+を再生し、解糖を続けられるようにする"}, {"key": "C", "text": "乳酸からATPが直接合成される"}, {"key": "D", "text": "ミトコンドリアでの酸化的リン酸化を促進する"}, {"key": "E", "text": "乳酸は骨格筋の中でそのままグリコーゲンに戻される"}]'::jsonb, 'B', '解糖系のグリセルアルデヒド3-リン酸脱水素酵素の反応にはNAD+が必要である。酸素が十分ならNADHは電子伝達系で再酸化されるが、不足すると乳酸脱水素酵素がピルビン酸を乳酸に還元してNAD+を再生し、解糖によるATP産生を続けさせる。産生された乳酸は肝で糖新生の材料となり、グルコースとして筋に戻る（Cori回路）。', '{"A": "酸素が不足し、NADHが再酸化されないときに増える。", "C": "乳酸脱水素酵素の反応ではATPは生じない。", "D": "乳酸産生は酸化的リン酸化が追いつかないときの経路である。", "E": "乳酸は主に血中を肝へ運ばれ、糖新生でグルコースに戻る（Cori回路）。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '赤血球のエネルギー代謝', 2, 'CBT', '成熟赤血球は核もミトコンドリアももたないため、利用できる代謝経路が限られている。成熟赤血球がATPを得る主な経路はどれか。', '[{"key": "A", "text": "電子伝達系による酸化的リン酸化"}, {"key": "B", "text": "ケトン体の酸化"}, {"key": "C", "text": "解糖系"}, {"key": "D", "text": "クエン酸回路"}, {"key": "E", "text": "脂肪酸のβ酸化"}]'::jsonb, 'C', '成熟赤血球はミトコンドリアをもたないので、ATPはグルコースの嫌気的解糖によって得られ、最終産物は乳酸である。ATPは膜のイオンポンプの維持などに使われる。ピルビン酸キナーゼ欠損症ではATPが不足して溶血性貧血をきたす。解糖の側路でつくられる2,3-ビスホスホグリセリン酸は、ヘモグロビンの酸素親和性を下げて組織への酸素供給を助ける。', '{"A": "ミトコンドリア内膜で行われるため、成熟赤血球では働かない。", "B": "ミトコンドリアでアセチルCoAに戻して利用するため、成熟赤血球では使えない。", "D": "ミトコンドリアのマトリックスで進むため、成熟赤血球では働かない。", "E": "ミトコンドリアで行われるため、成熟赤血球では働かない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ペントースリン酸回路', 2, 'CBT', 'ペントースリン酸回路は、グルコース6-リン酸から分岐する解糖系の側路である。この回路の主な役割として正しいのはどれか。', '[{"key": "A", "text": "NADHを産生して電子伝達系に渡す"}, {"key": "B", "text": "乳酸やアミノ酸からグルコースを新たにつくる"}, {"key": "C", "text": "アンモニアを尿素に変換して無毒化する"}, {"key": "D", "text": "NADPHとリボース5-リン酸を供給する"}, {"key": "E", "text": "ATPを大量に産生する"}]'::jsonb, 'D', 'ペントースリン酸回路の酸化的段階ではグルコース6-リン酸脱水素酵素などによりNADPHが生じ、非酸化的段階では核酸合成に必要なリボース5-リン酸が供給される。NADPHは脂肪酸やコレステロールの合成、グルタチオンの還元、食細胞のNADPHオキシダーゼに使われる。脂肪組織、肝、副腎皮質、赤血球などで活発である。', '{"A": "産生されるのはNADHではなくNADPHである。", "B": "それは糖新生の役割である。", "C": "それは肝の尿素回路の役割である。", "E": "この回路ではATPは産生されない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'G6PD欠損症の溶血', 2, 'CBT', 'グルコース6-リン酸脱水素酵素欠損症の患者が、ある種の薬物やソラマメの摂取、感染症を契機に溶血を起こした。溶血が起こる機序として正しいのはどれか。', '[{"key": "A", "text": "ATPが不足し、膜のナトリウムポンプが働かなくなる"}, {"key": "B", "text": "赤血球膜の骨格蛋白が欠損し、球状になる"}, {"key": "C", "text": "補体を制御する膜蛋白が欠損し、補体で壊される"}, {"key": "D", "text": "ヘモグロビンのβ鎖の変異で重合しやすくなる"}, {"key": "E", "text": "NADPHが不足し、還元型グルタチオンを保てず酸化ストレスに弱くなる"}]'::jsonb, 'E', '赤血球ではNADPHの供給源がペントースリン酸回路に限られ、グルコース6-リン酸脱水素酵素（G6PD）が欠損するとNADPHが不足する。その結果、グルタチオン還元酵素が還元型グルタチオンを再生できず、酸化ストレスでヘモグロビンが変性してHeinz小体をつくり、溶血が起こる。X連鎖性の遺伝形式をとり、原因薬にはプリマキンやサルファ剤などがある。', '{"A": "解糖系の酵素欠損（ピルビン酸キナーゼ欠損症など）の機序である。", "B": "遺伝性球状赤血球症の機序である。", "C": "発作性夜間ヘモグロビン尿症の機序である。", "D": "鎌状赤血球症の機序である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'クエン酸回路の場', 2, 'CBT', 'アセチルCoAは、クエン酸回路で二酸化炭素にまで酸化される。クエン酸回路について正しいのはどれか。', '[{"key": "A", "text": "ミトコンドリアのマトリックスで進行する"}, {"key": "B", "text": "細胞質基質で進行する"}, {"key": "C", "text": "回路の反応の中で酸素を直接消費する"}, {"key": "D", "text": "1回転でグルコース1分子が完全に酸化される"}, {"key": "E", "text": "回路の中間体はほかの代謝経路には利用されない"}]'::jsonb, 'A', 'クエン酸回路はミトコンドリアのマトリックスで進み、アセチルCoAとオキサロ酢酸からクエン酸ができ、1回転で2分子の二酸化炭素、3分子のNADH、1分子のFADH2、1分子のGTP（またはATP）を生じる。NADHとFADH2は電子伝達系で再酸化されるため、酸素がないと回路は止まる。中間体はアミノ酸や糖新生、ヘム合成の材料にもなる。', '{"B": "細胞質基質で進むのは解糖系であり、クエン酸回路はミトコンドリアで進む。", "C": "酸素を直接使うのは電子伝達系で、クエン酸回路はNADHなどの再酸化を通じて間接的に酸素を要する。", "D": "1回転で酸化されるのはアセチル基（炭素2個）で、グルコース1分子からは2回転分となる。", "E": "オキサロ酢酸やα-ケトグルタル酸は糖新生やアミノ酸合成に使われる。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '褐色脂肪組織の熱産生', 2, 'CBT', '新生児では、ふるえによらない熱産生が体温の維持に重要である。褐色脂肪組織で熱が産生される仕組みとして正しいのはどれか。', '[{"key": "A", "text": "電子伝達系を停止させて酸素消費を減らす"}, {"key": "B", "text": "脱共役蛋白質によりATPを合成せずに熱を生じる"}, {"key": "C", "text": "ATP合成酵素の働きを高めてATPを大量につくる"}, {"key": "D", "text": "解糖系だけでATPを産生して熱を生じる"}, {"key": "E", "text": "骨格筋を細かく収縮させて熱を生じる"}]'::jsonb, 'B', '褐色脂肪細胞はミトコンドリアに富み、内膜に脱共役蛋白質1（UCP1、サーモゲニン）をもつ。電子伝達系でつくられたプロトン勾配をATP合成酵素を通さずに解消するため、酸化のエネルギーが熱として放出される。寒冷刺激で交感神経からノルアドレナリンが放出され、β3受容体を介して脂肪分解とUCP1の活性化が起こる。新生児では肩甲骨の間や腎周囲に多い。', '{"A": "電子伝達は亢進し、酸素消費はむしろ増える。", "C": "褐色脂肪ではATP合成を迂回してエネルギーを熱として放出する。", "D": "褐色脂肪の熱産生はミトコンドリアでの脂肪酸の酸化による。", "E": "それはふるえによる熱産生で、骨格筋で起こる。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'シアン中毒の機序', 2, 'CBT', '火災現場から救出された患者で、シアン化物による中毒が疑われた。シアン化物が組織の酸素利用を妨げる機序として正しいのはどれか。', '[{"key": "A", "text": "ATP合成酵素のプロトンの通り道をふさぐ"}, {"key": "B", "text": "プロトン勾配を解消して脱共役を起こす"}, {"key": "C", "text": "電子伝達系の複合体IVを阻害する"}, {"key": "D", "text": "ヘモグロビンの酸素結合部位を占拠する"}, {"key": "E", "text": "解糖系のヘキソキナーゼを阻害する"}]'::jsonb, 'C', 'シアン化物はシトクロム酸化酵素（複合体IV）の3価鉄に結合し、電子を酸素に渡す最終段階を止める。組織は酸素を利用できず、嫌気的解糖に頼るため乳酸アシドーシスとなる。酸素が使われないため静脈血の酸素分圧は高く保たれる。治療にはヒドロキソコバラミンや亜硝酸薬とチオ硫酸ナトリウムが用いられる。', '{"A": "オリゴマイシンなどの作用で、シアン化物の機序ではない。", "B": "2,4-ジニトロフェノールなど脱共役剤の作用である。", "D": "一酸化炭素中毒の機序である。", "E": "シアン化物の主な作用点ではない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '糖新生の基質', 2, 'CBT', '長時間の絶食では、肝は糖以外の物質からグルコースをつくって血糖を維持する。糖新生の材料となる物質はどれか。', '[{"key": "A", "text": "アセト酢酸"}, {"key": "B", "text": "ロイシン"}, {"key": "C", "text": "リシン"}, {"key": "D", "text": "アラニン"}, {"key": "E", "text": "パルミチン酸"}]'::jsonb, 'D', '糖新生の主な材料は乳酸、グリセロール、糖原性アミノ酸（アラニンやグルタミンなど）である。アラニンは筋から肝へ運ばれ、アミノ基転移でピルビン酸になって糖新生に入る（グルコース-アラニン回路）。アセチルCoAはピルビン酸に戻れず、クエン酸回路では炭素2個が二酸化炭素として失われるため、偶数鎖脂肪酸やケト原性アミノ酸からは正味のグルコースはできない。', '{"A": "ケトン体はアセチルCoAを経て利用され、糖新生の材料にならない。", "B": "アセチルCoAやアセトアセチルCoAにしかならない純粋なケト原性アミノ酸である。", "C": "ロイシンと同じく純粋なケト原性アミノ酸である。", "E": "偶数鎖脂肪酸はアセチルCoAにしかならず、グルコースの正味の材料にならない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ピルビン酸カルボキシラーゼ', 2, 'CBT', '糖新生は解糖系の不可逆な段階を別の酵素で迂回して進む。糖新生の最初の段階で、ミトコンドリア内でピルビン酸をオキサロ酢酸に変換する酵素はどれか。', '[{"key": "A", "text": "ピルビン酸キナーゼ"}, {"key": "B", "text": "ピルビン酸脱水素酵素"}, {"key": "C", "text": "ホスホエノールピルビン酸カルボキシキナーゼ"}, {"key": "D", "text": "乳酸脱水素酵素"}, {"key": "E", "text": "ピルビン酸カルボキシラーゼ"}]'::jsonb, 'E', 'ピルビン酸カルボキシラーゼはビオチンを補酵素とし、ATPを使ってピルビン酸をカルボキシ化しオキサロ酢酸をつくる。アセチルCoAによって活性化されるため、脂肪酸のβ酸化が盛んな絶食時には糖新生が進みやすい。オキサロ酢酸はホスホエノールピルビン酸カルボキシキナーゼでホスホエノールピルビン酸になり、解糖系を逆にたどってグルコースに至る。', '{"A": "解糖系でホスホエノールピルビン酸からピルビン酸をつくる酵素である。", "B": "ピルビン酸をアセチルCoAに変換する酵素である。", "C": "オキサロ酢酸をホスホエノールピルビン酸に変換する次の段階の酵素である。", "D": "ピルビン酸と乳酸を相互に変換する酵素である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '肝グリコーゲンと血糖', 2, 'CBT', '肝のグリコーゲンは血糖の維持に使われるが、筋のグリコーゲンは主に筋自身のエネルギー源となる。この違いを生んでいる、肝にはあって筋にはない酵素はどれか。', '[{"key": "A", "text": "グルコース-6-ホスファターゼ"}, {"key": "B", "text": "グリコーゲンホスホリラーゼ"}, {"key": "C", "text": "グリコーゲン合成酵素"}, {"key": "D", "text": "ヘキソキナーゼ"}, {"key": "E", "text": "ホスホグルコムターゼ"}]'::jsonb, 'A', 'グリコーゲンの分解で生じたグルコース1-リン酸はグルコース6-リン酸になる。肝や腎にはグルコース-6-ホスファターゼがあるため、リン酸を外して遊離グルコースとして血中に放出できる。筋にはこの酵素がなく、グルコース6-リン酸は解糖系で筋自身に使われる。この酵素が欠損する糖原病I型（von Gierke病）では空腹時低血糖と肝腫大をきたす。', '{"B": "肝にも筋にもあり、グリコーゲンを分解する。", "C": "肝にも筋にもあり、グリコーゲンを合成する。", "D": "筋を含む多くの組織にあり、グルコースをリン酸化する。", "E": "肝にも筋にもあり、グルコース1-リン酸と6-リン酸を相互に変換する。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'インスリンの肝での作用', 2, 'CBT', '食後に分泌されるインスリンは、肝の代謝を同化の方向に切り替える。インスリンが肝で促進する代謝はどれか。', '[{"key": "A", "text": "ケトン体の産生"}, {"key": "B", "text": "グリコーゲンの合成"}, {"key": "C", "text": "糖新生"}, {"key": "D", "text": "グリコーゲンの分解"}, {"key": "E", "text": "脂肪酸のβ酸化"}]'::jsonb, 'B', 'インスリンは肝でグリコーゲン合成酵素を活性化してグリコーゲン合成を促し、糖新生やグリコーゲン分解を抑えて肝からの糖放出を減らす。さらにアセチルCoAカルボキシラーゼを活性化して脂肪酸合成を促し、生じたマロニルCoAがカルニチンパルミトイルトランスフェラーゼIを阻害してβ酸化とケトン体産生を抑える。インスリンが欠乏するとこれらが逆転し、高血糖とケトアシドーシスに向かう。', '{"A": "β酸化が抑えられるため、ケトン体の産生も抑制される。", "C": "インスリンは糖新生の酵素の発現を抑制する。", "D": "インスリンはグリコーゲンホスホリラーゼを不活性化し、分解を抑える。", "E": "インスリンはマロニルCoAを増やしてβ酸化を抑える。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'カルニチンの役割', 2, 'CBT', '脂肪酸は細胞質でアシルCoAに活性化された後、ミトコンドリアでβ酸化を受ける。長鎖アシル基がミトコンドリア内膜を通過するために必要な物質はどれか。', '[{"key": "A", "text": "グルタチオン"}, {"key": "B", "text": "クレアチン"}, {"key": "C", "text": "カルニチン"}, {"key": "D", "text": "ビオチン"}, {"key": "E", "text": "ユビキノン（補酵素Q）"}]'::jsonb, 'C', '長鎖脂肪酸のアシル基は、外膜のカルニチンパルミトイルトランスフェラーゼI（CPT-I）でカルニチンに移され、内膜の輸送体でマトリックスに入り、CPT-IIでアシルCoAに戻されてβ酸化を受ける。CPT-Iは脂肪酸合成の中間体であるマロニルCoAで阻害されるため、合成と分解が同時に進まない。カルニチン欠乏では空腹時の低ケトン性低血糖や筋力低下をきたす。', '{"A": "抗酸化や解毒に働くトリペプチドである。", "B": "筋でリン酸化されて高エネルギーリン酸の貯蔵に使われる。", "D": "カルボキシ化反応の補酵素で、脂肪酸の輸送には関わらない。", "E": "電子伝達系で電子を運ぶ物質である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '脂肪酸の合成', 2, 'CBT', '糖質を過剰に摂取すると、余ったアセチルCoAから脂肪酸が合成され、脂肪として蓄えられる。脂肪酸の合成について正しいのはどれか。', '[{"key": "A", "text": "還元剤としてNADHが用いられる"}, {"key": "B", "text": "律速酵素はカルニチンパルミトイルトランスフェラーゼIである"}, {"key": "C", "text": "空腹時にグルカゴンの作用で亢進する"}, {"key": "D", "text": "細胞質でアセチルCoAからマロニルCoAを経て合成される"}, {"key": "E", "text": "ミトコンドリアのマトリックスで行われる"}]'::jsonb, 'D', 'ミトコンドリアのアセチルCoAはクエン酸として細胞質に運ばれ、再びアセチルCoAとなる。アセチルCoAカルボキシラーゼ（ビオチン依存）がマロニルCoAをつくり、脂肪酸合成酵素がNADPHを使って炭素を2個ずつ伸ばし、主にパルミチン酸を生じる。NADPHは主にペントースリン酸回路から供給される。インスリンで促進され、グルカゴンで抑制される。', '{"A": "脂肪酸合成の還元剤はNADPHである。", "B": "律速酵素はアセチルCoAカルボキシラーゼで、CPT-Iはβ酸化の調節点である。", "C": "摂食時にインスリンの作用で亢進し、グルカゴンは抑制する。", "E": "マトリックスで行われるのは脂肪酸の分解（β酸化）である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ケトン体の利用臓器', 2, 'CBT', '絶食時に肝はケトン体を産生して他の臓器に供給するが、肝自身はケトン体をほとんど利用しない。その理由として正しいのはどれか。', '[{"key": "A", "text": "肝細胞がミトコンドリアをもたないから"}, {"key": "B", "text": "ケトン体が肝細胞の中に入れないから"}, {"key": "C", "text": "肝では脂肪酸のβ酸化が起こらないから"}, {"key": "D", "text": "肝ではクエン酸回路がまったく働かないから"}, {"key": "E", "text": "ケトン体を利用する酵素を肝がもたないから"}]'::jsonb, 'E', 'アセト酢酸を利用するには、スクシニルCoAからCoAを移してアセトアセチルCoAにする酵素（スクシニルCoA:3-ケト酸CoAトランスフェラーゼ）が必要である。この酵素は脳、心筋、骨格筋、腎などにあるが肝にはないため、肝はケトン体を産生して放出するだけになる。赤血球はミトコンドリアをもたないため、やはりケトン体を利用できない。', '{"A": "肝細胞はミトコンドリアに富む。ミトコンドリアをもたないのは赤血球である。", "B": "ケトン体は肝細胞の中でつくられており、膜の通過は問題ではない。", "C": "ケトン体の材料となるアセチルCoAは肝のβ酸化で生じる。", "D": "肝でもクエン酸回路は働いている。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'キロミクロン', 2, 'CBT', '脂質は水に溶けないため、血中ではリポ蛋白として運ばれる。食事由来のトリアシルグリセロールを小腸から末梢組織へ運ぶリポ蛋白はどれか。', '[{"key": "A", "text": "キロミクロン"}, {"key": "B", "text": "VLDL"}, {"key": "C", "text": "LDL"}, {"key": "D", "text": "HDL"}, {"key": "E", "text": "IDL"}]'::jsonb, 'A', '小腸上皮細胞は吸収した脂肪酸とモノアシルグリセロールからトリアシルグリセロールを再合成し、アポB-48をもつキロミクロンとしてリンパ管へ分泌する。キロミクロンは胸管を経て血中に入り、毛細血管内皮のリポ蛋白リパーゼで分解されて脂肪酸を筋や脂肪組織に渡し、残りはレムナントとして肝に取り込まれる。', '{"B": "肝で合成されたトリアシルグリセロールを末梢へ運ぶ。", "C": "VLDLが代謝されて生じ、コレステロールを末梢組織へ運ぶ。", "D": "末梢組織の余剰なコレステロールを肝へ戻す。", "E": "VLDLがトリアシルグリセロールを失う途中で生じる中間型である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '家族性高コレステロール血症', 2, 'CBT', '若年で冠動脈疾患を発症した患者で、腱黄色腫と著明な高LDLコレステロール血症を認め、家族にも同様の患者がいる。血中LDLが高値となる主な機序はどれか。', '[{"key": "A", "text": "腸管でのコレステロールの吸収が完全に停止する"}, {"key": "B", "text": "LDL受容体の機能が低下し、肝でのLDLの取り込みが減る"}, {"key": "C", "text": "リポ蛋白リパーゼが欠損し、キロミクロンが血中で分解されない"}, {"key": "D", "text": "肝でのコレステロール合成酵素が恒常的に阻害される"}, {"key": "E", "text": "HDLの産生が過剰になり、コレステロールが肝へ戻らない"}]'::jsonb, 'B', '家族性高コレステロール血症は、主にLDL受容体遺伝子の異常による常染色体顕性（優性）遺伝の疾患である。肝でのLDLの取り込みが減るため血中LDLが上昇し、アキレス腱などの腱黄色腫や若年性の冠動脈疾患をきたす。ホモ接合体ではLDLが著明に高く、小児期から動脈硬化が進む。アポB-100やPCSK9の遺伝子異常でも同様の病態となる。', '{"A": "吸収の停止はLDLを低下させる方向に働く。", "C": "高キロミクロン血症（I型）の機序で、主にトリアシルグリセロールが増える。", "D": "合成が抑えられれば、LDLはむしろ低下する方向に働く。", "E": "HDLはコレステロールを肝へ戻す働きで、LDL上昇の原因ではない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '尿素回路の律速酵素', 2, 'CBT', '尿素回路の反応の一部はミトコンドリアで、残りは細胞質で進む。尿素回路の律速酵素で、N-アセチルグルタミン酸によって活性化される酵素はどれか。', '[{"key": "A", "text": "アルギナーゼ"}, {"key": "B", "text": "グルタミン合成酵素"}, {"key": "C", "text": "カルバモイルリン酸合成酵素I"}, {"key": "D", "text": "オルニチントランスカルバミラーゼ"}, {"key": "E", "text": "アルギニノコハク酸合成酵素"}]'::jsonb, 'C', 'ミトコンドリアでアンモニアと炭酸水素イオンからカルバモイルリン酸がつくられる段階が律速で、カルバモイルリン酸合成酵素IはN-アセチルグルタミン酸を必須の活性化因子とする。カルバモイルリン酸はオルニチンと反応してシトルリンとなり、細胞質でアスパラギン酸の窒素を取り込んでアルギニンを経て尿素ができる。尿素回路異常症では高アンモニア血症をきたし、新生児期に哺乳不良や意識障害で発症することがある。', '{"A": "アルギニンを尿素とオルニチンに分解する最後の段階の酵素である。", "B": "尿素回路の酵素ではなく、アンモニアをグルタミンとして固定する酵素である。", "D": "カルバモイルリン酸とオルニチンからシトルリンをつくる次の段階の酵素である。", "E": "細胞質でシトルリンとアスパラギン酸を縮合させる酵素である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ヘム合成の最初の段階', 2, 'CBT', '赤芽球や肝細胞では、ミトコンドリアと細胞質を行き来しながらヘムが合成される。ヘム合成の最初の段階で、グリシンとスクシニルCoAから生成される物質はどれか。', '[{"key": "A", "text": "プロトポルフィリンIX"}, {"key": "B", "text": "ビリルビン"}, {"key": "C", "text": "ビリベルジン"}, {"key": "D", "text": "δ-アミノレブリン酸"}, {"key": "E", "text": "ポルホビリノーゲン"}]'::jsonb, 'D', 'ヘム合成はミトコンドリアでδ-アミノレブリン酸合成酵素（ピリドキサールリン酸依存）がグリシンとスクシニルCoAを縮合させる段階から始まり、これが律速である。細胞質でポルホビリノーゲン、ウロポルフィリノーゲンなどを経て、再びミトコンドリアでプロトポルフィリンIXに鉄が挿入されてヘムとなる。鉛はδ-アミノレブリン酸脱水酵素とフェロキラターゼを阻害し、貧血をきたす。', '{"A": "合成の最終段階で鉄が挿入される直前の物質である。", "B": "ヘムが分解されて生じる物質である。", "C": "ヘムオキシゲナーゼによるヘムの分解で最初に生じる物質である。", "E": "δ-アミノレブリン酸2分子から生じる次の段階の産物である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ビリルビンの代謝', 2, 'CBT', '老化した赤血球が脾臓などで処理されると、ヘムからビリルビンが生じる。ビリルビンの代謝について正しいのはどれか。', '[{"key": "A", "text": "非抱合型ビリルビンは水溶性で、腎で濾過されてそのまま尿中に排泄される"}, {"key": "B", "text": "ヘムはヘムオキシゲナーゼで直接ビリルビンに分解される"}, {"key": "C", "text": "腸で生じたウロビリノゲンはすべて便中に排泄される"}, {"key": "D", "text": "抱合型ビリルビンは血中でアルブミンと結合して運ばれる"}, {"key": "E", "text": "肝でグルクロン酸抱合を受けて水溶性となり、胆汁中に排泄される"}]'::jsonb, 'E', 'ヘムはヘムオキシゲナーゼでビリベルジンとなり、還元されて非抱合型ビリルビンになる。非抱合型ビリルビンはアルブミンと結合して肝に運ばれ、UDP-グルクロン酸転移酵素で抱合されて胆汁中に排泄される。腸内細菌によりウロビリノゲンとなり、大部分は便中に、一部は再吸収されて尿中に出る。新生児では抱合能が未熟で、非抱合型高ビリルビン血症をきたしやすい。', '{"A": "非抱合型は脂溶性でアルブミンと結合しているため、尿中には出ない。", "B": "ヘムはまずビリベルジンとなり、還元されてビリルビンになる。", "C": "一部は再吸収され、腸肝循環に入り、尿中にも排泄される。", "D": "アルブミンと結合して運ばれるのは非抱合型ビリルビンである。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'プリンのサルベージ経路', 2, 'CBT', '幼児期から高尿酸血症、不随意運動、自傷行為を示す男児がいる。プリン塩基を再利用するサルベージ経路の酵素欠損が原因と考えられる。欠損している酵素はどれか。', '[{"key": "A", "text": "ヒポキサンチン-グアニンホスホリボシルトランスフェラーゼ"}, {"key": "B", "text": "キサンチンオキシダーゼ"}, {"key": "C", "text": "アデノシンデアミナーゼ"}, {"key": "D", "text": "ホスホリボシルピロリン酸合成酵素"}, {"key": "E", "text": "グルコース6-リン酸脱水素酵素"}]'::jsonb, 'A', 'Lesch-Nyhan症候群は、ヒポキサンチン-グアニンホスホリボシルトランスフェラーゼ（HGPRT）の欠損によるX連鎖性の疾患である。ヒポキサンチンやグアニンが再利用されずに尿酸へ分解され、さらにプリンの新規合成も亢進するため、高尿酸血症となる。舞踏病様の不随意運動や、唇や指をかむ自傷行為が特徴である。', '{"B": "尿酸をつくる酵素で、欠損すれば尿酸はむしろ低下する。", "C": "欠損すると重症複合免疫不全症をきたす。", "D": "活性が過剰になると痛風をきたすが、欠損による病態ではない。", "E": "欠損すると酸化ストレスによる溶血をきたす。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'アルデヒド脱水素酵素', 2, 'CBT', '少量の飲酒で顔面紅潮、動悸、頭痛をきたしやすい体質は、東アジアの人に多い。この体質の原因となる、遺伝的に活性が低い酵素はどれか。', '[{"key": "A", "text": "アセチルCoA合成酵素"}, {"key": "B", "text": "アルデヒド脱水素酵素2"}, {"key": "C", "text": "アルコール脱水素酵素"}, {"key": "D", "text": "シトクロムP450 2E1"}, {"key": "E", "text": "カタラーゼ"}]'::jsonb, 'B', 'エタノールはアルコール脱水素酵素でアセトアルデヒドとなり、ミトコンドリアのアルデヒド脱水素酵素2（ALDH2）で酢酸に分解される。ALDH2の遺伝子多型で活性が低いとアセトアルデヒドが蓄積し、顔面紅潮や動悸、悪心を起こす。この体質の人が飲酒を続けると食道癌の危険が高まる。抗酒薬のジスルフィラムはALDHを阻害する。', '{"A": "酢酸をアセチルCoAにする酵素で、この体質の原因ではない。", "C": "エタノールをアセトアルデヒドに変える最初の段階の酵素である。", "D": "大量飲酒時にエタノールの酸化を担う補助的な経路の酵素である。", "E": "エタノールの酸化にわずかに関わるが、この体質の原因ではない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '飲酒後の低血糖', 2, 'CBT', '食事をとらずに大量に飲酒した人で、翌朝に低血糖を認めた。エタノールの代謝が低血糖をきたす機序として正しいのはどれか。', '[{"key": "A", "text": "腎からのグルコースの排泄が増加する"}, {"key": "B", "text": "甲状腺ホルモンの分泌が急に低下する"}, {"key": "C", "text": "NADH/NAD+比が上昇し、肝での糖新生が抑制される"}, {"key": "D", "text": "膵β細胞からのインスリン分泌が持続的に過剰になる"}, {"key": "E", "text": "肝でのグリコーゲン合成が亢進する"}]'::jsonb, 'C', 'エタノールとアセトアルデヒドの酸化でNAD+がNADHに変わり、肝細胞内のNADH/NAD+比が上昇する。するとピルビン酸は乳酸に、オキサロ酢酸はリンゴ酸に傾き、糖新生の材料が減って糖新生が抑制される。絶食でグリコーゲンが枯渇していると血糖を保てず低血糖となる。同じ機序で乳酸アシドーシスや脂肪肝も起こりやすい。', '{"A": "エタノールが尿糖を増やす機序ではない。", "B": "アルコール性低血糖の機序ではない。", "D": "アルコール性低血糖の主な機序ではない。", "E": "絶食状態ではグリコーゲンはすでに枯渇しており、主因ではない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ガラクトース血症', 2, 'CBT', '母乳を飲み始めた新生児が、嘔吐、黄疸、肝腫大をきたし、のちに白内障も認めた。乳糖を含む乳を中止すると症状が改善した。欠損が考えられる酵素はどれか。', '[{"key": "A", "text": "ラクターゼ"}, {"key": "B", "text": "グルコース-6-ホスファターゼ"}, {"key": "C", "text": "フェニルアラニン水酸化酵素"}, {"key": "D", "text": "ガラクトース-1-リン酸ウリジルトランスフェラーゼ"}, {"key": "E", "text": "アルドラーゼB"}]'::jsonb, 'D', '古典型ガラクトース血症は、ガラクトース-1-リン酸ウリジルトランスフェラーゼの欠損による常染色体潜性（劣性）遺伝の疾患である。乳糖に由来するガラクトース-1-リン酸が蓄積して肝障害、黄疸、嘔吐、大腸菌による敗血症などをきたし、ガラクチトールの蓄積で白内障が生じる。新生児マススクリーニングの対象で、乳糖除去乳で治療する。', '{"A": "欠乏では下痢や腹部膨満が主で、肝障害や白内障はきたさない。", "B": "欠損すると糖原病I型となり、空腹時低血糖と肝腫大をきたす。", "C": "欠損するとフェニルケトン尿症となり、知的障害の原因となる。", "E": "欠損すると遺伝性果糖不耐症となり、果物や蔗糖の摂取で症状が出る。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'クレアチンリン酸', 2, 'CBT', '全力疾走を始めた最初の数秒間、骨格筋は収縮で消費したATPをきわめて速やかに再生する。このとき主にATPの再生に使われる物質はどれか。', '[{"key": "A", "text": "筋グリコーゲン"}, {"key": "B", "text": "乳酸"}, {"key": "C", "text": "遊離脂肪酸"}, {"key": "D", "text": "ケトン体"}, {"key": "E", "text": "クレアチンリン酸"}]'::jsonb, 'E', '筋に蓄えられたクレアチンリン酸は、クレアチンキナーゼの反応でADPにリン酸を渡して速やかにATPを再生する。ごく短時間の最大運動を支えるが量が少なく、数秒〜十数秒で減少し、その後は解糖、さらに長くなると酸化的リン酸化が主となる。クレアチンは非酵素的にクレアチニンとなり、筋量に比例して一定量が尿中に排泄される。', '{"A": "解糖によりATPを供給するが、最初の数秒の再生はクレアチンリン酸が担う。", "B": "解糖の最終産物で、筋でATPを再生する材料ではない。", "C": "β酸化でATPを供給するが、立ち上がりが遅く持久的な運動で主となる。", "D": "絶食時のエネルギー源で、短時間の運動でATPを速やかに再生するものではない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'テロメラーゼ', 2, 'CBT', '体細胞が分裂を繰り返すと、染色体末端のテロメアは少しずつ短くなる。生殖細胞や多くの癌細胞でテロメアの長さを保っている酵素の性質として正しいのはどれか。', '[{"key": "A", "text": "RNAを鋳型にDNAを伸長する逆転写酵素である"}, {"key": "B", "text": "DNAを鋳型にしてRNAを合成する酵素である"}, {"key": "C", "text": "二本鎖DNAに生じたねじれを解消する酵素である"}, {"key": "D", "text": "ラギング鎖の岡崎フラグメントどうしをつなぐ酵素である"}, {"key": "E", "text": "誤って取り込まれた塩基を3′側から取り除く酵素である"}]'::jsonb, 'A', 'DNAポリメラーゼはプライマーを必要とするため、線状染色体の末端は複製のたびに短くなる（末端複製問題）。テロメラーゼは鋳型となるRNAを含む逆転写酵素で、テロメアの反復配列を付け足して長さを保つ。体細胞の多くではテロメラーゼ活性が低く、テロメアの短縮が細胞老化の一因となる。癌細胞の多くはテロメラーゼを再活性化して無限の増殖能を得ている。', '{"B": "RNAポリメラーゼの性質である。", "C": "トポイソメラーゼの性質である。", "D": "DNAリガーゼの性質である。", "E": "DNAポリメラーゼの校正（エキソヌクレアーゼ）活性である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'トポイソメラーゼ', 2, 'CBT', 'DNAの複製や転写で二重らせんがほどかれると、その先にねじれ（超らせん）がたまる。このねじれを、DNA鎖の切断と再結合によって解消する酵素はどれか。', '[{"key": "A", "text": "DNAポリメラーゼ"}, {"key": "B", "text": "トポイソメラーゼ"}, {"key": "C", "text": "ヘリカーゼ"}, {"key": "D", "text": "プライマーゼ"}, {"key": "E", "text": "DNAリガーゼ"}]'::jsonb, 'B', 'トポイソメラーゼはDNA鎖を一時的に切断して再結合することで超らせんを解消する。I型は1本鎖を、II型は2本鎖を切断する。細菌のII型トポイソメラーゼ（DNAジャイレース）はキノロン系抗菌薬の標的であり、ヒトのトポイソメラーゼIはイリノテカン、IIはエトポシドなどの抗癌薬の標的となる。', '{"A": "鋳型に相補的なDNA鎖を伸長する酵素である。", "C": "二重らせんの塩基対の水素結合を切って2本の鎖をほどく酵素である。", "D": "DNA合成の起点となるRNAプライマーを合成する酵素である。", "E": "DNA断片の切れ目をつなぐ酵素で、ねじれは解消しない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ミスマッチ修復', 2, 'CBT', '若年で大腸癌を発症し、家系内に大腸癌や子宮体癌の患者が多い。腫瘍組織ではマイクロサテライト不安定性を認めた。この家系で機能が低下しているDNA修復機構はどれか。', '[{"key": "A", "text": "相同組換え修復"}, {"key": "B", "text": "非相同末端結合"}, {"key": "C", "text": "ミスマッチ修復"}, {"key": "D", "text": "ヌクレオチド除去修復"}, {"key": "E", "text": "塩基除去修復"}]'::jsonb, 'C', 'Lynch症候群（遺伝性非ポリポーシス大腸癌）は、MLH1、MSH2などのミスマッチ修復遺伝子の生殖細胞系列変異による常染色体顕性（優性）遺伝の疾患である。複製時の塩基の誤対合が修復されず、反復配列の長さが変化するマイクロサテライト不安定性を示す。大腸癌のほか子宮体癌、胃癌、卵巣癌、尿路上皮癌などが多い。ミスマッチ修復欠損の腫瘍には免疫チェックポイント阻害薬が効きやすい。', '{"A": "二本鎖切断を修復する機構で、BRCA1/2の異常で障害される。", "B": "二本鎖切断の末端を直接つなぐ機構で、この家系の病態には当たらない。", "D": "紫外線によるピリミジン二量体などを修復する機構で、色素性乾皮症で障害される。", "E": "脱アミノ化や酸化で傷ついた1塩基を取り除いて修復する機構である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ヌクレオチド除去修復', 2, 'CBT', '幼児期から日光に当たった部位にしみや水疱が生じ、若年で皮膚癌が多発する疾患がある。この疾患で障害されているDNA修復機構はどれか。', '[{"key": "A", "text": "塩基除去修復"}, {"key": "B", "text": "相同組換え修復"}, {"key": "C", "text": "DNAポリメラーゼの校正機能"}, {"key": "D", "text": "ヌクレオチド除去修復"}, {"key": "E", "text": "ミスマッチ修復"}]'::jsonb, 'D', '色素性乾皮症は、紫外線で生じたチミン二量体などのピリミジン二量体を除去するヌクレオチド除去修復の遺伝子（XPA〜XPGなど）の異常による常染色体潜性（劣性）遺伝の疾患である。日光曝露部に色素沈着や水疱が生じ、若年から基底細胞癌、有棘細胞癌、悪性黒色腫が多発する。一部の型では神経症状を伴う。遮光の徹底が基本となる。', '{"A": "損傷した1塩基を除去する機構で、紫外線によるピリミジン二量体の修復の主体ではない。", "B": "二本鎖切断を姉妹染色分体を鋳型に修復する機構である。", "C": "複製中の誤りをその場で取り除く機能で、紫外線損傷の修復ではない。", "E": "複製時の誤対合を修復する機構で、Lynch症候群で障害される。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '相同組換え修復とBRCA', 2, 'CBT', 'BRCA1またはBRCA2の生殖細胞系列変異をもつ人では、乳癌や卵巣癌の発症の危険が高い。BRCA1/2の蛋白質が主に関わるDNA修復機構はどれか。', '[{"key": "A", "text": "誤対合した塩基を修正するミスマッチ修復"}, {"key": "B", "text": "ピリミジン二量体を除去するヌクレオチド除去修復"}, {"key": "C", "text": "傷ついた1塩基を取り除く塩基除去修復"}, {"key": "D", "text": "DNAポリメラーゼの3′→5′エキソヌクレアーゼ活性"}, {"key": "E", "text": "相同組換えによる二本鎖切断の修復"}]'::jsonb, 'E', 'BRCA1/2は、DNAの二本鎖切断を姉妹染色分体の配列を鋳型にして正確に修復する相同組換え修復に必要である。欠損すると誤りの多い修復に頼るためゲノムが不安定になる。一本鎖切断の修復に働くPARPを阻害すると、相同組換え修復を欠く癌細胞は二本鎖切断を修復できず死滅する（合成致死）。この原理でPARP阻害薬がBRCA変異陽性の乳癌や卵巣癌に用いられる。', '{"A": "MLH1やMSH2などが担い、Lynch症候群で障害される。", "B": "XP遺伝子群が担い、色素性乾皮症で障害される。", "C": "DNAグリコシラーゼなどが担い、BRCAの主な役割ではない。", "D": "複製中の校正機能で、BRCAの役割ではない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'RNAポリメラーゼII', 2, 'CBT', '真核細胞には転写するRNAの種類ごとに異なるRNAポリメラーゼがある。mRNAの前駆体を転写するRNAポリメラーゼはどれか。', '[{"key": "A", "text": "RNAポリメラーゼII"}, {"key": "B", "text": "RNAポリメラーゼI"}, {"key": "C", "text": "RNAポリメラーゼIII"}, {"key": "D", "text": "DNAポリメラーゼα"}, {"key": "E", "text": "逆転写酵素"}]'::jsonb, 'A', '真核細胞のRNAポリメラーゼIIはmRNAの前駆体と多くの非コードRNA（マイクロRNAなど）を転写する。プロモーターのTATAボックスなどに基本転写因子が集まり、RNAポリメラーゼIIが呼び込まれて転写が始まる。タマゴテングタケの毒素であるα-アマニチンはRNAポリメラーゼIIを強く阻害し、重篤な肝障害をきたす。', '{"B": "核小体で28S、18S、5.8SのrRNAの前駆体を転写する。", "C": "tRNAや5S rRNAなどの小さなRNAを転写する。", "D": "DNA複製の開始に関わる酵素で、RNAの転写は行わない。", "E": "RNAを鋳型にしてDNAを合成する酵素で、細胞の転写の主体ではない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'エンハンサー', 2, 'CBT', '遺伝子の転写量は、プロモーターだけでなく離れた位置の調節配列によっても大きく変わる。エンハンサーの性質として正しいのはどれか。', '[{"key": "A", "text": "転写を抑制する働きだけをもつ配列を指す"}, {"key": "B", "text": "転写開始点から離れていても、向きに関係なく転写を促進できる"}, {"key": "C", "text": "必ず転写開始点の直前の決まった位置に存在する"}, {"key": "D", "text": "mRNAに翻訳されてアミノ酸配列を決める領域である"}, {"key": "E", "text": "RNAポリメラーゼが直接結合して転写を開始する配列である"}]'::jsonb, 'B', 'エンハンサーには活性化因子とよばれる転写因子が結合し、DNAがループをつくることでプロモーター上の転写装置に働きかける。位置や向きに依存せず、数十キロ塩基離れていても作用しうる。組織特異的な遺伝子発現の多くはエンハンサーと転写因子の組合せで決まる。逆に転写を抑える配列はサイレンサーとよばれる。', '{"A": "転写を抑制する配列はサイレンサーとよばれる。", "C": "エンハンサーは上流、下流、イントロン内など離れた位置にもある。", "D": "エンハンサーは転写を調節するDNA配列で、翻訳される領域ではない。", "E": "それはプロモーターの説明である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'mRNAのプロセシング', 2, 'CBT', '真核細胞では、転写されたmRNAの前駆体が核内で加工されてから細胞質へ運ばれる。核内で行われるプロセシングとして正しいのはどれか。', '[{"key": "A", "text": "細胞質のリボソーム上でのスプライシング"}, {"key": "B", "text": "5′末端へのポリA鎖の付加"}, {"key": "C", "text": "5′末端へのキャップ構造の付加"}, {"key": "D", "text": "3′末端へのShine-Dalgarno配列の付加"}, {"key": "E", "text": "エキソンの除去とイントロンどうしの連結"}]'::jsonb, 'C', 'mRNA前駆体は核内で、5′末端への7-メチルグアノシンのキャップ付加、スプライソソームによるイントロンの除去（スプライシング）、3′末端へのポリA鎖の付加を受ける。キャップ構造とポリA鎖はmRNAを分解から守り、核外輸送や翻訳の開始を助ける。スプライシングの異常はβサラセミアなど多くの遺伝性疾患の原因となる。', '{"A": "スプライシングは核内でスプライソソームによって行われる。", "B": "ポリA鎖は3′末端に付加される。", "D": "Shine-Dalgarno配列は原核生物のmRNAにある配列で、付加されるものではない。", "E": "スプライシングではイントロンが除かれ、エキソンどうしがつながる。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '選択的スプライシング', 2, 'CBT', 'ヒトの遺伝子数はおよそ2万であるが、つくられる蛋白質の種類はそれよりはるかに多い。その理由の一つである選択的スプライシングの結果として正しいのはどれか。', '[{"key": "A", "text": "翻訳された後にポリペプチドが切断されて活性化する"}, {"key": "B", "text": "mRNAの分解が促進されて発現量が減る"}, {"key": "C", "text": "mRNAの塩基が別の塩基に置き換えられる"}, {"key": "D", "text": "1つの遺伝子から複数の異なる蛋白質がつくられる"}, {"key": "E", "text": "遺伝子のDNA配列そのものが組み換えられる"}]'::jsonb, 'D', '選択的スプライシングでは、1つの遺伝子の前駆体mRNAから、どのエキソンを残すかの組合せを変えて複数のmRNAがつくられる。その結果、組織や発生段階に応じて構造や機能の異なる蛋白質（アイソフォーム）が生じる。カルシトニン遺伝子から甲状腺ではカルシトニン、神経ではカルシトニン遺伝子関連ペプチドがつくられるのが代表例である。', '{"A": "それは翻訳後のプロセシング（前駆体の切断）である。", "B": "スプライシングの選び方の違いで、分解の促進を指すものではない。", "C": "それはRNA編集で、アポB-48の産生などでみられる。", "E": "DNAの再編成はリンパ球の抗原受容体遺伝子などで起こる別の現象である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '開始コドン', 2, 'CBT', 'リボソームはmRNAの5′側から読み進み、最初に現れる開始コドンから翻訳を始める。真核細胞の細胞質での翻訳において、開始コドンAUGが指定するアミノ酸はどれか。', '[{"key": "A", "text": "N-ホルミルメチオニン"}, {"key": "B", "text": "トリプトファン"}, {"key": "C", "text": "グリシン"}, {"key": "D", "text": "ロイシン"}, {"key": "E", "text": "メチオニン"}]'::jsonb, 'E', '真核細胞では開始tRNAがメチオニンを運び、AUGから翻訳が始まる。細菌やミトコンドリアではN-ホルミルメチオニンで翻訳が始まり、その断片は好中球の走化性因子として働く。終止コドンはUAA、UAG、UGAの3種類で、対応するtRNAはなく、終結因子が認識して翻訳を終える。', '{"A": "細菌やミトコンドリアでの翻訳開始に使われるアミノ酸である。", "B": "UGGで指定されるアミノ酸で、開始には使われない。", "C": "GGNで指定されるアミノ酸で、開始には使われない。", "D": "6種類のコドンで指定されるアミノ酸で、開始には使われない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '遺伝暗号の縮重', 2, 'CBT', '遺伝暗号は64種類のコドンで20種類のアミノ酸と翻訳の終止を指定している。遺伝暗号の性質として正しいのはどれか。', '[{"key": "A", "text": "1つのアミノ酸を複数のコドンが指定することがある"}, {"key": "B", "text": "1つのコドンが複数のアミノ酸を指定することがある"}, {"key": "C", "text": "終止コドンもそれぞれ1つのアミノ酸を指定する"}, {"key": "D", "text": "連続する2塩基で1つのアミノ酸を指定する"}, {"key": "E", "text": "生物の種によって遺伝暗号はまったく異なる"}]'::jsonb, 'A', '遺伝暗号は連続する3つの塩基からなるコドンで表され、64通りのうち61がアミノ酸を、3つが終止を指定する。多くのアミノ酸は複数のコドンで指定され（縮重）、違いは主に3番目の塩基にある。tRNAのアンチコドンの1番目は3番目の塩基と緩く対合できる（ゆらぎ）。そのため3番目の塩基の置換はアミノ酸を変えない同義置換になりやすい。', '{"B": "1つのコドンが指定するアミノ酸は1種類に決まっている。", "C": "終止コドンはアミノ酸を指定せず、翻訳の終わりを示す。", "D": "コドンは連続する3塩基からなる。", "E": "遺伝暗号はほぼすべての生物で共通で、例外はミトコンドリアなど一部に限られる。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'アミノアシルtRNA合成酵素', 2, 'CBT', '翻訳の正確さは、tRNAに正しいアミノ酸が結合していることにかかっている。アミノアシルtRNA合成酵素の役割として正しいのはどれか。', '[{"key": "A", "text": "終止コドンを認識して翻訳を終わらせる"}, {"key": "B", "text": "特定のアミノ酸を対応するtRNAの3′末端に結合させる"}, {"key": "C", "text": "mRNAのコドンとtRNAのアンチコドンの対合を触媒する"}, {"key": "D", "text": "アミノ酸どうしのペプチド結合の形成を触媒する"}, {"key": "E", "text": "核内でtRNAの遺伝子を転写する"}]'::jsonb, 'B', 'アミノアシルtRNA合成酵素はアミノ酸ごとにあり、ATPを使って対応するアミノ酸を正しいtRNAの3′末端（CCA末端）に結合させる。リボソームはアンチコドンしか見ないため、この段階の正確さが翻訳の正確さを決める。多くの合成酵素は誤って結合したアミノ酸を除く校正機能をもつ。', '{"A": "終止コドンを認識するのは終結因子である。", "C": "コドンとアンチコドンの対合はリボソーム上で起こる。", "D": "ペプチド結合はリボソームの大サブユニットのrRNAが触媒する。", "E": "tRNAはRNAポリメラーゼIIIが転写する。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'リボザイムとしてのリボソーム', 2, 'CBT', 'リボソームは大小2つのサブユニットからなり、rRNAとリボソーム蛋白質で構成される。ペプチド結合の形成を触媒する活性を担う分子として正しいのはどれか。', '[{"key": "A", "text": "tRNAのアンチコドン"}, {"key": "B", "text": "アミノアシルtRNA合成酵素"}, {"key": "C", "text": "大サブユニットのrRNA"}, {"key": "D", "text": "小サブユニットのリボソーム蛋白質"}, {"key": "E", "text": "mRNAの5′キャップ構造"}]'::jsonb, 'C', 'ペプチジルトランスフェラーゼ活性は、大サブユニットのrRNAが担う。蛋白質ではなくRNAが触媒として働くため、リボソームはリボザイムの一種である。この活性部位の周辺は、クロラムフェニコールやマクロライド系など細菌の50Sサブユニットに作用する抗菌薬の標的となる。', '{"A": "mRNAのコドンと対合する部分で、触媒活性はもたない。", "B": "tRNAにアミノ酸を結合させる酵素で、ペプチド結合は形成しない。", "D": "小サブユニットは主にmRNAの結合とコドンの読み取りに関わる。", "E": "翻訳の開始に働く構造で、ペプチド結合を触媒しない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '分泌蛋白の合成', 2, 'CBT', 'インスリンや免疫グロブリンのような分泌蛋白は、細胞質の遊離リボソームで翻訳が始まる。その後の合成と輸送の過程として正しいのはどれか。', '[{"key": "A", "text": "ゴルジ装置にあるリボソームで翻訳される"}, {"key": "B", "text": "滑面小胞体の表面で翻訳される"}, {"key": "C", "text": "ミトコンドリアのリボソームで翻訳される"}, {"key": "D", "text": "シグナル配列により粗面小胞体へ送られながら翻訳される"}, {"key": "E", "text": "遊離リボソームで翻訳を終えた後に核へ運ばれて修飾される"}]'::jsonb, 'D', '分泌蛋白や膜蛋白はN末端にシグナル配列をもつ。翻訳中にシグナル認識粒子がこれに結合してリボソームを粗面小胞体の膜へ導き、ポリペプチドは翻訳されながら内腔へ送り込まれる。小胞体でシグナル配列の切断、ジスルフィド結合の形成、N-結合型糖鎖の付加を受け、ゴルジ装置でさらに修飾・選別されて分泌小胞で細胞外へ運ばれる。', '{"A": "ゴルジ装置は糖鎖の修飾と選別を担い、リボソームはない。", "B": "滑面小胞体にはリボソームがなく、脂質合成や解毒を担う。", "C": "ミトコンドリアのリボソームはミトコンドリアDNAの遺伝子を翻訳する。", "E": "核へ運ばれるのは核移行シグナルをもつ蛋白質で、分泌蛋白の経路ではない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ユビキチン-プロテアソーム系', 2, 'CBT', '細胞内では、不要になった蛋白質や異常な蛋白質が選択的に分解されている。細胞質のプロテアソームによる分解の目印となる修飾はどれか。', '[{"key": "A", "text": "セリン残基のリン酸化"}, {"key": "B", "text": "アスパラギン残基へのN-結合型糖鎖付加"}, {"key": "C", "text": "リシン残基のメチル化"}, {"key": "D", "text": "マンノース6-リン酸の付加"}, {"key": "E", "text": "ユビキチンが鎖状に結合するポリユビキチン化"}]'::jsonb, 'E', '分解される蛋白質は、E1、E2、E3の酵素の連携でユビキチンが鎖状に結合され、26Sプロテアソームで分解される。細胞周期の進行（サイクリンの分解）やp53の量の調節、折りたたみに失敗した蛋白質の除去などを担う。プロテアソーム阻害薬のボルテゾミブは多発性骨髄腫の治療に用いられる。', '{"A": "主にシグナル伝達で活性を切り替える修飾で、それ自体は分解の目印ではない。", "B": "小胞体で行われる糖鎖の付加で、分解の目印ではない。", "C": "ヒストンなどで転写の調節に関わる修飾である。", "D": "リソソーム酵素をリソソームへ運ぶための目印である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'DNAメチル化', 2, 'CBT', 'エピジェネティクスは、塩基配列を変えずに遺伝子発現を調節する仕組みである。遺伝子のプロモーター領域にあるCpG配列のシトシンがメチル化されたときの一般的な影響はどれか。', '[{"key": "A", "text": "その遺伝子の転写が抑制される"}, {"key": "B", "text": "塩基配列が変化して突然変異となる"}, {"key": "C", "text": "その遺伝子の転写が強く促進される"}, {"key": "D", "text": "mRNAの翻訳の速度が上がる"}, {"key": "E", "text": "mRNA前駆体のスプライシングが起こらなくなる"}]'::jsonb, 'A', 'プロモーター領域のCpGアイランドがメチル化されると、メチル化DNA結合蛋白質が集まり、ヒストンの脱アセチル化とともにクロマチンが凝縮して転写が抑制される。癌では癌抑制遺伝子がメチル化で不活化されることがある。ゲノムインプリンティングやX染色体の不活化にもDNAメチル化が関わる。細胞分裂の後も維持メチル化酵素によってパターンが受け継がれる。', '{"B": "メチル化は塩基配列を変えない修飾である。", "C": "プロモーターのメチル化は一般に転写を抑える。", "D": "DNAのメチル化は翻訳の速度を直接変えるものではない。", "E": "プロモーターのメチル化の一般的な影響ではない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ヒストンのアセチル化', 2, 'CBT', '真核細胞のDNAはヒストンに巻きついてヌクレオソームをつくり、クロマチンとして核に収まっている。ヒストンのアセチル化について正しいのはどれか。', '[{"key": "A", "text": "ヒストンがプロテアソームで分解される"}, {"key": "B", "text": "クロマチンが緩み、転写が促進されやすくなる"}, {"key": "C", "text": "DNAの塩基配列が変化する"}, {"key": "D", "text": "ヒストンの正電荷が増し、DNAとの結合が強まる"}, {"key": "E", "text": "その領域の転写が強く抑制される"}]'::jsonb, 'B', 'ヒストンのリシン残基がヒストンアセチル基転移酵素でアセチル化されると、正電荷が中和されて負に荷電したDNAとの結合が緩み、転写因子が近づきやすくなる。ヒストン脱アセチル化酵素は逆に転写を抑える。ヒストン脱アセチル化酵素阻害薬は一部のリンパ腫などの治療に使われる。', '{"A": "アセチル化は分解の目印ではない。", "C": "ヒストンの修飾で塩基配列は変わらない。", "D": "リシン残基のアセチル化は正電荷を打ち消し、DNAとの結合を弱める。", "E": "転写の抑制に働くのは主に脱アセチル化である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'PCR法', 2, 'CBT', '感染症の診断や遺伝子検査では、微量のDNAをPCR法で増幅して検出する。PCR法で各サイクルに行う操作として正しいのはどれか。', '[{"key": "A", "text": "抗体を用いて特定の蛋白質を検出する"}, {"key": "B", "text": "RNAを鋳型に逆転写酵素でDNAを合成するだけで終える"}, {"key": "C", "text": "熱変性、プライマーのアニーリング、伸長を繰り返す"}, {"key": "D", "text": "制限酵素で切断した断片をベクターに連結する"}, {"key": "E", "text": "電気泳動で分離したDNAを膜に移して検出する"}]'::jsonb, 'C', 'PCR法は、約95°Cで二本鎖DNAを1本鎖にほどき（熱変性）、温度を下げて標的配列の両端にプライマーを結合させ（アニーリング）、耐熱性DNAポリメラーゼで伸長する操作を繰り返す。1サイクルごとに標的配列がほぼ2倍になり、指数関数的に増える。RNAが対象のときは逆転写してからPCRを行い（RT-PCR）、増幅をリアルタイムで測れば定量もできる。', '{"A": "ELISAやウエスタンブロット法の原理である。", "B": "逆転写は増幅の前段階で、それだけでは増幅にならない。", "D": "遺伝子のクローニングの操作である。", "E": "サザンブロット法の操作である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ウエスタンブロット法', 2, 'CBT', 'ある腫瘍組織で、特定の蛋白質が発現しているかどうかと、その分子量を調べたい。目的に最も適した方法はどれか。', '[{"key": "A", "text": "ノーザンブロット法"}, {"key": "B", "text": "PCR法"}, {"key": "C", "text": "サンガー法"}, {"key": "D", "text": "ウエスタンブロット法"}, {"key": "E", "text": "サザンブロット法"}]'::jsonb, 'D', 'ウエスタンブロット法では、蛋白質をSDSポリアクリルアミドゲル電気泳動で分子量によって分離し、膜に転写したあと特異的な抗体で検出する。バンドの位置から分子量が、濃さからおおよその量がわかる。DNAを調べるのがサザン、RNAを調べるのがノーザンである。組織内での局在を見たいときは免疫組織化学を用いる。', '{"A": "RNAを電気泳動して膜に移し、プローブで検出する方法である。", "B": "DNAを増幅する方法で、蛋白質は検出できない。", "C": "DNAの塩基配列を決める方法である。", "E": "DNAを電気泳動して膜に移し、標識したプローブで検出する方法である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'FISH法', 2, 'CBT', '白血病細胞の染色体転座や、染色体の微細な欠失を細胞ごとに検出したい。蛍光色素で標識したDNAプローブを標的配列に結合させて検出する方法はどれか。', '[{"key": "A", "text": "G分染法"}, {"key": "B", "text": "ELISA"}, {"key": "C", "text": "フローサイトメトリー"}, {"key": "D", "text": "サンガー法"}, {"key": "E", "text": "FISH法"}]'::jsonb, 'E', 'FISH（蛍光 in situ ハイブリダイゼーション）法は、標的のDNA配列に相補的な蛍光標識プローブを細胞や染色体標本に結合させて、その数や位置を顕微鏡で観察する方法である。分裂中期でない間期核でも解析でき、BCR-ABL融合遺伝子などの転座、22q11.2欠失のような微細欠失、HER2遺伝子の増幅の評価などに使われる。', '{"A": "染色体全体の縞模様を見る方法で、微細な欠失は検出しにくい。", "B": "抗体を用いて溶液中の蛋白質や抗体を定量する方法である。", "C": "細胞表面の抗原などを蛍光標識抗体で解析する方法である。", "D": "DNAの塩基配列を決める方法で、細胞ごとの染色体異常は見られない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'CRISPR-Cas9', 2, 'CBT', 'ゲノム編集技術CRISPR-Cas9は、狙った塩基配列を切断して遺伝子を改変できる。Cas9がゲノム上のどこを切断するかを決めている分子はどれか。', '[{"key": "A", "text": "標的配列に相補的なガイドRNA"}, {"key": "B", "text": "制限酵素が認識する回文配列"}, {"key": "C", "text": "逆転写酵素"}, {"key": "D", "text": "DNAリガーゼ"}, {"key": "E", "text": "標的蛋白質に対するモノクローナル抗体"}]'::jsonb, 'A', 'CRISPR-Cas9では、約20塩基の標的配列に相補的なガイドRNAがCas9ヌクレアーゼを導き、標的のすぐ隣にPAMとよばれる短い配列があると二本鎖を切断する。切断は非相同末端結合で修復されて小さな挿入や欠失が生じるか、鋳型DNAを与えると相同組換えで狙った配列に置き換わる。もとは細菌がウイルスに抵抗するための獲得免疫の仕組みである。', '{"B": "制限酵素の切断位置を決める配列で、Cas9の標的の決定には関わらない。", "C": "RNAからDNAを合成する酵素で、標的の選択には関わらない。", "D": "切断後の断片をつなぐ酵素で、切断の位置は決めない。", "E": "抗体は蛋白質を認識するもので、DNAの切断位置は決めない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'RNA干渉', 2, 'CBT', '特定の遺伝子と相補的な配列をもつ短い二本鎖RNAを細胞に導入すると、その遺伝子のmRNAが分解されて発現が低下する。この現象はどれか。', '[{"key": "A", "text": "ゲノムインプリンティング"}, {"key": "B", "text": "RNA干渉"}, {"key": "C", "text": "選択的スプライシング"}, {"key": "D", "text": "逆転写"}, {"key": "E", "text": "相同組換え"}]'::jsonb, 'B', '短い二本鎖RNA（siRNA）はRISCとよばれる複合体に取り込まれ、1本鎖となって相補的なmRNAに結合し、これを切断する。生体内ではマイクロRNAが同様の仕組みで多くの遺伝子の翻訳を抑えている。遺伝子機能の解析に広く使われ、トランスサイレチン型アミロイドーシスなど一部の疾患ではsiRNA製剤が治療に用いられている。', '{"A": "親由来によって遺伝子の発現が決まる現象である。", "C": "エキソンの組合せを変えて複数のmRNAをつくる現象である。", "D": "RNAを鋳型にDNAを合成する反応である。", "E": "相同な配列の間でDNA鎖を交換する現象である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '逆転写酵素', 2, 'CBT', 'HIVやB型肝炎ウイルスは、増殖の過程で逆転写酵素を用いる。逆転写酵素の働きとして正しいのはどれか。', '[{"key": "A", "text": "mRNAを読み取って蛋白質を合成する"}, {"key": "B", "text": "前駆体蛋白質を切断してウイルス粒子を成熟させる"}, {"key": "C", "text": "RNAを鋳型としてDNAを合成する"}, {"key": "D", "text": "DNAを鋳型としてRNAを合成する"}, {"key": "E", "text": "RNAを鋳型としてRNAを合成する"}]'::jsonb, 'C', '逆転写酵素はRNA依存性DNAポリメラーゼで、HIVではゲノムRNAから二本鎖DNAをつくり、インテグラーゼで宿主のゲノムに組み込む。B型肝炎ウイルスはDNAウイルスだが、複製の途中でRNAを鋳型に逆転写してゲノムDNAをつくる。逆転写酵素は校正機能をもたず変異が起こりやすい。核酸アナログ製剤はこの酵素を阻害する。', '{"A": "リボソームによる翻訳の働きである。", "B": "ウイルスのプロテアーゼの働きである。", "D": "RNAポリメラーゼによる転写の働きである。", "E": "インフルエンザウイルスなどのRNA依存性RNAポリメラーゼの働きである。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '制限酵素', 2, 'CBT', '遺伝子組換え技術では、DNAを特定の位置で切断する酵素が欠かせない。制限酵素の性質として正しいのはどれか。', '[{"key": "A", "text": "鋳型なしで1本鎖DNAを合成する"}, {"key": "B", "text": "切断されたDNA断片どうしを共有結合でつなぎ合わせる"}, {"key": "C", "text": "蛋白質の特定のアミノ酸配列を切断する"}, {"key": "D", "text": "特定の塩基配列を認識して二本鎖DNAを切断する"}, {"key": "E", "text": "RNAを特異的に分解する"}]'::jsonb, 'D', '制限酵素は細菌がもつ酵素で、多くは4〜8塩基の回文配列を認識して二本鎖DNAを切断する。自身のDNAはメチル化で守り、侵入したファージのDNAを切断する防御の仕組みである。切断でできた付着末端をDNAリガーゼでつなぐことでベクターに遺伝子を組み込める。切断断片の長さの違いは遺伝子多型の解析にも使われる。', '{"A": "制限酵素に合成の働きはない。", "B": "断片をつなぐのはDNAリガーゼである。", "C": "蛋白質を切断するのはプロテアーゼである。", "E": "RNAを分解するのはリボヌクレアーゼである。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ラクトースオペロン', 2, 'CBT', '大腸菌は、培地にグルコースがなくラクトースがあるときに、ラクトースの分解に必要な酵素群をまとめて転写する。このとき転写が始まる仕組みとして正しいのはどれか。', '[{"key": "A", "text": "ラクトースがRNAポリメラーゼに直接結合してこれを活性化する"}, {"key": "B", "text": "リプレッサーがオペレーターに強く結合して転写を促す"}, {"key": "C", "text": "オペロンのDNA配列が組み換えられて遺伝子が活性化する"}, {"key": "D", "text": "グルコースが多いほどcAMPが増えて転写が強まる"}, {"key": "E", "text": "誘導物質が結合したリプレッサーがオペレーターから外れる"}]'::jsonb, 'E', 'ラクトースオペロンでは、ラクトースから生じるアロラクトースが誘導物質としてリプレッサーに結合し、リプレッサーがオペレーターから外れて転写が始まる。さらにグルコースが乏しいとcAMPが増え、cAMP受容蛋白（CAP）がプロモーター近くに結合して転写を強める。機能的に関連した遺伝子を1つの単位で調節する仕組みは原核生物に特徴的である。', '{"A": "ラクトースの代謝産物はリプレッサーに結合して働く。", "B": "リプレッサーがオペレーターに結合すると転写は抑えられる。", "C": "DNA配列は変わらず、蛋白質とDNAの結合で調節される。", "D": "グルコースが多いとcAMPは減り、転写は弱まる。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'リソソーム酵素の選別', 2, 'CBT', 'I細胞病では、多くのリソソーム酵素がリソソームに届かずに細胞外へ分泌され、未分解の物質が細胞内にたまる。この疾患で欠けている、リソソーム酵素の選別に必要な修飾はどれか。', '[{"key": "A", "text": "マンノース6-リン酸の付加"}, {"key": "B", "text": "ポリユビキチン鎖の付加"}, {"key": "C", "text": "N末端にあるシグナル配列の切断"}, {"key": "D", "text": "GPIアンカーの付加"}, {"key": "E", "text": "核移行シグナルの付加"}]'::jsonb, 'A', 'リソソーム酵素はゴルジ装置のシス側で糖鎖のマンノースがリン酸化され、マンノース6-リン酸受容体に認識されてリソソームへ運ばれる。I細胞病（ムコリピドーシスII型）ではこのリン酸化を担う酵素が欠損し、酵素が細胞外へ分泌されて血中で高値となる一方、細胞内には封入体が蓄積する。粗な顔貌、骨格異常、発達の遅れなどをきたす。', '{"B": "プロテアソームで分解される蛋白質の目印である。", "C": "粗面小胞体に入る段階の処理で、リソソームへの選別の目印ではない。", "D": "蛋白質を細胞膜の外側につなぎとめるための修飾である。", "E": "核へ運ばれる蛋白質がもつ配列で、リソソームへの選別には関わらない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ペルオキシソーム', 2, 'CBT', '副腎白質ジストロフィーでは、極長鎖脂肪酸が分解されずに蓄積して中枢神経の脱髄と副腎不全をきたす。極長鎖脂肪酸のβ酸化を担う細胞小器官はどれか。', '[{"key": "A", "text": "粗面小胞体"}, {"key": "B", "text": "ペルオキシソーム"}, {"key": "C", "text": "ミトコンドリア"}, {"key": "D", "text": "リソソーム"}, {"key": "E", "text": "ゴルジ装置"}]'::jsonb, 'B', 'ペルオキシソームは極長鎖脂肪酸のβ酸化、胆汁酸やプラスマローゲンの合成などを担い、生じた過酸化水素はカタラーゼで分解される。X連鎖性の副腎白質ジストロフィーは極長鎖脂肪酸をペルオキシソームへ取り込む輸送体（ABCD1）の異常による。ペルオキシソームの形成そのものが障害されるとZellweger症候群となる。', '{"A": "分泌蛋白や膜蛋白の合成を担う細胞小器官である。", "C": "長鎖以下の脂肪酸のβ酸化を担うが、極長鎖脂肪酸はまずペルオキシソームで短くされる。", "D": "酸性の加水分解酵素で高分子を分解する細胞小器官である。", "E": "蛋白質の糖鎖修飾と選別を担う細胞小器官である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '滑面小胞体', 2, 'CBT', '細胞小器官の働きを、細胞の種類ごとに整理している。滑面小胞体の機能として正しいのはどれか。', '[{"key": "A", "text": "加水分解酵素で取り込んだ異物を分解する"}, {"key": "B", "text": "酸化的リン酸化でATPを産生する"}, {"key": "C", "text": "骨格筋でカルシウムイオンを蓄えて放出する"}, {"key": "D", "text": "分泌蛋白を翻訳しながら内腔へ送り込む"}, {"key": "E", "text": "蛋白質に糖鎖を付けて行き先ごとに選別する"}]'::jsonb, 'C', '滑面小胞体はリボソームをもたない小胞体で、脂質やステロイドホルモンの合成、肝細胞での薬物代謝（シトクロムP450）、グリコーゲン分解で生じたグルコース6-リン酸の脱リン酸化などを担う。骨格筋や心筋では筋小胞体としてカルシウムイオンを蓄え、活動電位に応じて放出して筋収縮を起こす。ステロイドを産生する副腎皮質や精巣のLeydig細胞でよく発達している。', '{"A": "リソソームの機能である。", "B": "ミトコンドリアの機能である。", "D": "リボソームが付着した粗面小胞体の機能である。", "E": "ゴルジ装置の機能である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '密着結合', 2, 'CBT', '小腸や尿細管の上皮では、細胞と細胞の隙間を通る物質の移動が厳密に制限されている。上皮細胞間の隙間をふさぎ、細胞間隙を通る物質の移動を制限する構造はどれか。', '[{"key": "A", "text": "デスモソーム"}, {"key": "B", "text": "ヘミデスモソーム"}, {"key": "C", "text": "接着結合"}, {"key": "D", "text": "密着結合"}, {"key": "E", "text": "ギャップ結合"}]'::jsonb, 'D', '密着結合（タイトジャンクション）は上皮細胞の頂端側を帯状に取り巻き、クローディンやオクルディンが隣の細胞と密着して細胞間隙をふさぐ。これにより上皮の内外で物質が勝手に行き来するのを防ぎ、頂端側と基底側の膜蛋白が混ざるのも防いで細胞の極性を保つ。脳の毛細血管内皮の密着結合は血液脳関門の本体である。', '{"A": "中間径フィラメントをつなぎ、細胞どうしを機械的に強く接着させる。", "B": "上皮細胞を基底膜につなぎとめる構造である。", "C": "カドヘリンとアクチンフィラメントを介して細胞どうしを接着させる。", "E": "コネキシンからなる通路で、隣り合う細胞の細胞質をつなぎイオンや小分子を通す。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'デスモソームと天疱瘡', 2, 'CBT', '尋常性天疱瘡では、表皮細胞どうしの接着が失われて表皮内に水疱が生じる。この疾患の自己抗体が標的とする蛋白質が存在する細胞接着構造はどれか。', '[{"key": "A", "text": "ヘミデスモソーム"}, {"key": "B", "text": "密着結合"}, {"key": "C", "text": "ギャップ結合"}, {"key": "D", "text": "核膜孔"}, {"key": "E", "text": "デスモソーム"}]'::jsonb, 'E', 'デスモソームはデスモグレインなどのカドヘリン型接着分子と中間径フィラメント（ケラチン）で細胞どうしを強く結びつける。尋常性天疱瘡ではデスモグレイン3（と1）に対する自己抗体で表皮細胞が離れ（棘融解）、表皮内に弛緩性水疱が生じる。水疱性類天疱瘡ではヘミデスモソームのBP180などが標的となり、表皮下に緊満性水疱が生じる。', '{"A": "表皮と基底膜の接着構造で、水疱性類天疱瘡の自己抗体の標的である。", "B": "細胞間隙をふさぐ構造で、天疱瘡の標的ではない。", "C": "細胞間の物質の通り道で、天疱瘡の標的ではない。", "D": "核と細胞質の間の物質輸送を担う構造で、細胞接着構造ではない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'コラーゲンの一次構造', 2, 'CBT', 'コラーゲンは3本のポリペプチド鎖がより合わさった三重らせん構造をとる。コラーゲンのアミノ酸配列で3残基ごとに繰り返し現れ、三重らせんの形成に不可欠なアミノ酸はどれか。', '[{"key": "A", "text": "グリシン"}, {"key": "B", "text": "プロリン"}, {"key": "C", "text": "システイン"}, {"key": "D", "text": "トリプトファン"}, {"key": "E", "text": "チロシン"}]'::jsonb, 'A', 'コラーゲンはグリシン-X-Yの繰り返し配列をもち、Xにはプロリン、Yにはヒドロキシプロリンが多い。側鎖が水素だけのグリシンでなければ三重らせんの中心に収まらないため、グリシンの置換は重い異常をきたす。骨形成不全症の多くはI型コラーゲン遺伝子の変異によるもので、グリシンの置換では重症型となりやすい。', '{"B": "コラーゲンに多いが、3残基ごとに必ず現れるのはグリシンである。", "C": "三重らせん部分にはほとんど含まれない。", "D": "コラーゲンにはほとんど含まれない。", "E": "コラーゲンの繰り返し配列を構成するアミノ酸ではない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'IV型コラーゲン', 2, 'CBT', '血尿で発見され、進行性の腎障害と感音難聴を伴う家系がある。糸球体基底膜の主要な構成成分で、その遺伝子異常がこの疾患の原因となるコラーゲンはどれか。', '[{"key": "A", "text": "VII型コラーゲン"}, {"key": "B", "text": "IV型コラーゲン"}, {"key": "C", "text": "I型コラーゲン"}, {"key": "D", "text": "II型コラーゲン"}, {"key": "E", "text": "III型コラーゲン"}]'::jsonb, 'B', 'IV型コラーゲンは線維をつくらず網目状に集まって基底膜を形成する。Alport症候群はIV型コラーゲンのα5鎖（COL4A5、X連鎖性）などの遺伝子異常によって糸球体基底膜が層状に分裂し、血尿から腎不全へ進行する。内耳や水晶体の基底膜も侵され、感音難聴や水晶体の異常を伴う。Goodpasture症候群ではα3鎖に対する自己抗体が生じる。', '{"A": "表皮と真皮をつなぐ係留線維の成分で、栄養障害型表皮水疱症の原因となる。", "C": "骨、皮膚、腱の主成分で、骨形成不全症の原因となる。", "D": "硝子軟骨や硝子体の主成分である。", "E": "細網線維や血管壁に多く、血管型Ehlers-Danlos症候群の原因となる。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'サイクリン依存性キナーゼ', 2, 'CBT', '細胞周期は、各時期に特有のサイクリンとサイクリン依存性キナーゼ（CDK）によって順序よく進められる。CDKについて正しいのはどれか。', '[{"key": "A", "text": "p53によって誘導され、細胞周期の進行を促進する"}, {"key": "B", "text": "細胞膜上で増殖因子の受容体として働く"}, {"key": "C", "text": "サイクリンと結合して初めてキナーゼ活性を示す"}, {"key": "D", "text": "細胞周期の時期に応じて量が大きく変動する"}, {"key": "E", "text": "DNAを直接切断して細胞分裂を進める"}]'::jsonb, 'C', 'CDKは単独では不活性で、時期に応じて合成と分解を繰り返すサイクリンと結合して活性化し、標的蛋白質をリン酸化して細胞周期を進める。サイクリンはユビキチン-プロテアソーム系で分解されて周期がリセットされる。p21やp16などのCDK阻害因子はブレーキとして働く。CDK4/6阻害薬はホルモン受容体陽性乳癌の治療に用いられる。', '{"A": "p53が誘導するのはCDK阻害因子のp21で、細胞周期は停止する。", "B": "CDKは細胞内の酵素で、受容体ではない。", "D": "量が周期的に変動するのはサイクリンで、CDKの量はほぼ一定である。", "E": "CDKは標的蛋白質をリン酸化する酵素で、DNAは切断しない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'Rb蛋白の働き', 2, 'CBT', '網膜芽細胞腫の原因遺伝子の産物であるRb蛋白は、G1期からS期への移行を制御する。Rb蛋白の働きとして正しいのはどれか。', '[{"key": "A", "text": "微小管と結合して分裂期の紡錘体を形成する"}, {"key": "B", "text": "RASのGTPase活性を促進してシグナルを止める"}, {"key": "C", "text": "β-カテニンの分解を促してWntシグナルを抑える"}, {"key": "D", "text": "E2Fに結合してS期の遺伝子の転写を抑える"}, {"key": "E", "text": "DNAの損傷を感知して細胞にアポトーシスを誘導する"}]'::jsonb, 'D', '低リン酸化型のRb蛋白は転写因子E2Fに結合し、S期に必要な遺伝子の転写を抑えている。増殖刺激でサイクリンD-CDK4/6がRbをリン酸化するとE2Fが解放され、細胞はS期へ進む。網膜芽細胞腫は両方の対立遺伝子が失われて発症し（Knudsonの2ヒット説）、遺伝性では1つ目の変異が生殖細胞系列にある。ヒトパピローマウイルスのE7蛋白はRbに結合して不活化する。', '{"A": "Rb蛋白の働きではない。", "B": "神経線維腫症1型の原因遺伝子産物ニューロフィブロミンの働きである。", "C": "APC蛋白の働きである。", "E": "主にp53の働きである。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'p53の働き', 2, 'CBT', 'p53は「ゲノムの守護者」とよばれ、ヒトの癌で最も高頻度に変異がみられる遺伝子である。DNAが損傷を受けた細胞でp53が果たす役割として正しいのはどれか。', '[{"key": "A", "text": "細胞増殖を促進する癌遺伝子の産物として働く"}, {"key": "B", "text": "損傷したDNAの部分を自ら切り出して正しく修復する酵素である"}, {"key": "C", "text": "細胞膜の受容体型チロシンキナーゼとして働く"}, {"key": "D", "text": "テロメアを伸長して細胞を不死化させる"}, {"key": "E", "text": "細胞周期を止め、修復できなければアポトーシスを誘導する"}]'::jsonb, 'E', 'DNAが損傷するとp53は分解を免れて蓄積し、転写因子としてCDK阻害因子のp21を誘導してG1期で細胞周期を止める。修復が困難なときはBAXなどを誘導してアポトーシスを起こさせる。平常時はMDM2によってユビキチン化され、速やかに分解されている。生殖細胞系列のTP53変異はLi-Fraumeni症候群の原因となり、ヒトパピローマウイルスのE6蛋白はp53の分解を促す。', '{"A": "p53は癌抑制遺伝子の産物である。", "B": "p53は転写因子で、修復酵素の発現などを誘導するが自ら修復はしない。", "C": "p53は核で働く転写因子である。", "D": "テロメアを伸長させるのはテロメラーゼである。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'アポトーシスの内因性経路', 2, 'CBT', 'DNA損傷や増殖因子の欠乏で起こるアポトーシスでは、ミトコンドリアが中心的な役割を果たす。内因性経路で、ミトコンドリアから細胞質へ放出されてカスパーゼの活性化を引き起こす物質はどれか。', '[{"key": "A", "text": "シトクロム c"}, {"key": "B", "text": "Bcl-2"}, {"key": "C", "text": "Fasリガンド"}, {"key": "D", "text": "腫瘍壊死因子α"}, {"key": "E", "text": "カルモジュリン"}]'::jsonb, 'A', '内因性経路では、BAXやBAKがミトコンドリア外膜に孔をあけ、シトクロム c が細胞質へ放出される。シトクロム c はApaf-1と複合体（アポトソーム）をつくってカスパーゼ9を活性化し、カスパーゼ3などの実行カスパーゼが細胞を解体する。Bcl-2は外膜の透過性亢進を抑える。濾胞性リンパ腫ではt(14;18)転座でBcl-2が過剰発現し、細胞が死ににくくなる。', '{"B": "ミトコンドリア外膜にとどまり、アポトーシスを抑える側に働く。", "C": "細胞外から細胞死受容体に結合する外因性経路の分子である。", "D": "細胞死受容体に結合する外因性経路のリガンドである。", "E": "カルシウムイオンと結合して酵素を調節する蛋白質で、アポトーシスの引き金ではない。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'Gq共役型受容体', 2, 'CBT', '血管平滑筋のα1受容体や、平滑筋・腺のムスカリンM3受容体はGq蛋白質と共役している。Gq共役型受容体が刺激されたときに細胞内で生じる変化として正しいのはどれか。', '[{"key": "A", "text": "受容体が核内に移行して転写を直接調節する"}, {"key": "B", "text": "ホスホリパーゼCが活性化されIP3とDAGが生じる"}, {"key": "C", "text": "アデニル酸シクラーゼが活性化され、cAMPが増える"}, {"key": "D", "text": "アデニル酸シクラーゼが抑制され、cAMPが減る"}, {"key": "E", "text": "受容体自身のチロシンキナーゼが活性化される"}]'::jsonb, 'B', 'Gq蛋白質はホスホリパーゼCβを活性化し、膜のホスファチジルイノシトール4,5-ビスリン酸をIP3とジアシルグリセロール（DAG）に分解する。IP3は小胞体のIP3受容体に結合してカルシウムイオンを放出させ、ジアシルグリセロールはプロテインキナーゼCを活性化する。その結果、平滑筋の収縮や腺分泌が起こる。', '{"A": "ステロイドホルモンなどの核内受容体の働きである。", "C": "Gs共役型受容体（β受容体など）で生じる変化である。", "D": "Gi共役型受容体（α2受容体、M2受容体など）で生じる変化である。", "E": "受容体型チロシンキナーゼ（増殖因子受容体など）で生じる変化である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'EGF受容体', 2, 'CBT', '肺腺癌の一部では上皮成長因子（EGF）受容体の遺伝子変異がみられ、その阻害薬が治療に使われる。EGF受容体の性質として正しいのはどれか。', '[{"key": "A", "text": "細胞質から核に移行して転写因子として働く"}, {"key": "B", "text": "細胞外でリガンドを分解して作用を終わらせる"}, {"key": "C", "text": "リガンド結合で二量体化し自己リン酸化する"}, {"key": "D", "text": "7回膜貫通型でG蛋白質と共役する"}, {"key": "E", "text": "リガンドの結合で開口するイオンチャネルである"}]'::jsonb, 'C', 'EGF受容体は受容体型チロシンキナーゼで、リガンドの結合で二量体をつくり、互いのチロシン残基をリン酸化する。リン酸化チロシンにアダプター蛋白質が結合してRAS-MAPK経路やPI3K-AKT経路が活性化され、細胞増殖が促される。EGFR遺伝子の活性化変異をもつ肺腺癌にはEGFRチロシンキナーゼ阻害薬が有効である。', '{"A": "ステロイドホルモン受容体などの核内受容体の性質である。", "B": "受容体の性質ではない。", "D": "G蛋白質共役型受容体の性質である。", "E": "ニコチン性アセチルコリン受容体などの性質である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'JAK-STAT経路', 2, 'CBT', 'エリスロポエチン、成長ホルモン、インターフェロンなどの受容体は、自身は酵素活性をもたない。これらの受容体が利用する細胞内シグナル伝達経路はどれか。', '[{"key": "A", "text": "IP3-カルシウムイオン経路"}, {"key": "B", "text": "一酸化窒素-cGMP経路"}, {"key": "C", "text": "Wnt-β-カテニン経路"}, {"key": "D", "text": "JAK-STAT経路"}, {"key": "E", "text": "cAMP-プロテインキナーゼA経路"}]'::jsonb, 'D', 'サイトカイン受容体はリガンドの結合で会合し、細胞内に結合したJAK（ヤヌスキナーゼ）が活性化して受容体をリン酸化する。そこに結合したSTATがリン酸化されて二量体となり、核に移行して転写因子として働く。JAK2のV617F変異は真性赤血球増加症の多くでみられ、JAK阻害薬は骨髄線維症や関節リウマチなどの治療に用いられる。', '{"A": "Gq共役型受容体の主な経路である。", "B": "可溶性グアニル酸シクラーゼを介する経路である。", "C": "Frizzled受容体を介する経路で、APC遺伝子の異常と関わる。", "E": "Gs共役型受容体の主な経路である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '一酸化窒素とcGMP', 2, 'CBT', '血管内皮細胞は一酸化窒素を産生し、隣接する血管平滑筋を弛緩させる。一酸化窒素が血管平滑筋を弛緩させる機序として正しいのはどれか。', '[{"key": "A", "text": "アデニル酸シクラーゼを抑制し、cAMPを減らす"}, {"key": "B", "text": "ホスホリパーゼCを活性化し、IP3を増やす"}, {"key": "C", "text": "電位依存性カルシウムチャネルを開口させる"}, {"key": "D", "text": "ミオシン軽鎖キナーゼを活性化する"}, {"key": "E", "text": "グアニル酸シクラーゼを活性化しcGMPを増やす"}]'::jsonb, 'E', '内皮の一酸化窒素合成酵素がアルギニンから一酸化窒素をつくり、一酸化窒素は拡散して平滑筋の可溶性グアニル酸シクラーゼを活性化する。増えたcGMPはプロテインキナーゼGを介して細胞内カルシウムイオン濃度を下げ、ミオシン軽鎖を脱リン酸化して弛緩させる。硝酸薬は一酸化窒素を放出して作用し、ホスホジエステラーゼ5阻害薬はcGMPの分解を抑える。', '{"A": "cAMPの減少は平滑筋の弛緩をもたらす機序ではない。", "B": "IP3はカルシウムイオンを放出させ、平滑筋を収縮させる。", "C": "カルシウムイオンが流入して平滑筋は収縮する。", "D": "ミオシン軽鎖のリン酸化が進み、平滑筋は収縮する。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'iPS細胞', 2, 'CBT', 'iPS細胞を用いた再生医療や、患者由来の細胞による病態の研究が進められている。iPS細胞の特徴として正しいのはどれか。', '[{"key": "A", "text": "体細胞に遺伝子を導入して多能性をもたせた細胞である"}, {"key": "B", "text": "受精卵が発生した胚の内部細胞塊を取り出して樹立した細胞である"}, {"key": "C", "text": "分化できる細胞の種類が1種類に限られている"}, {"key": "D", "text": "胎盤を含むすべての細胞に分化できる全能性をもつ"}, {"key": "E", "text": "移植しても腫瘍を形成する危険はない"}]'::jsonb, 'A', 'iPS細胞（人工多能性幹細胞）は、皮膚の線維芽細胞などの体細胞にOct3/4、Sox2、Klf4、c-Mycなどの遺伝子を導入して初期化し、ES細胞と同様の多能性と自己複製能をもたせた細胞である。受精卵を壊さずにつくれ、患者本人の細胞から樹立できる。一方で、腫瘍化の危険を減らすことが臨床応用の課題となる。', '{"B": "ES細胞（胚性幹細胞）の説明である。", "C": "iPS細胞は三胚葉のさまざまな細胞に分化できる多能性をもつ。", "D": "全能性をもつのは受精卵などで、iPS細胞は多能性である。", "E": "未分化な細胞が残ると奇形腫などの腫瘍をつくる危険がある。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '減数分裂', 2, 'CBT', '精子や卵子は減数分裂によってつくられ、染色体数が半分になる。減数分裂について正しいのはどれか。', '[{"key": "A", "text": "皮膚や腸の上皮などの体細胞でも普通に起こる"}, {"key": "B", "text": "第一分裂で相同染色体が対合し、乗換えが起こる"}, {"key": "C", "text": "1回の分裂で2個の二倍体の細胞ができる"}, {"key": "D", "text": "分裂の間にDNAの複製が2回起こる"}, {"key": "E", "text": "第二分裂で対合していた相同染色体どうしが分離する"}]'::jsonb, 'B', '減数分裂では、DNAが1回複製されたあと2回の分裂が続く。第一分裂の前期に相同染色体が対合して二価染色体をつくり、乗換え（交叉）によって遺伝子の組換えが起こる。第一分裂で相同染色体が、第二分裂で姉妹染色分体が分かれ、4個の一倍体細胞ができる。この過程で染色体が正しく分かれないと（不分離）、トリソミーやモノソミーの原因となる。', '{"A": "減数分裂は生殖細胞だけで起こる。", "C": "それは体細胞分裂で、減数分裂では4個の一倍体の細胞ができる。", "D": "DNAの複製は第一分裂の前に1回だけ起こる。", "E": "相同染色体が分離するのは第一分裂で、第二分裂では姉妹染色分体が分かれる。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'Down症候群の成因', 2, 'CBT', 'Down症候群の大部分は、21番染色体を3本もつ標準型トリソミーである。標準型トリソミーの成因として最も多いものはどれか。', '[{"key": "A", "text": "21番染色体の一部が欠失すること"}, {"key": "B", "text": "21番染色体上の単一遺伝子の点変異"}, {"key": "C", "text": "母親の卵形成時の減数分裂における染色体の不分離"}, {"key": "D", "text": "父親の精子形成時に生じたロバートソン転座"}, {"key": "E", "text": "受精後の初期胚の体細胞分裂で起こる染色体の不分離"}]'::jsonb, 'C', '標準型の21トリソミーの多くは、母親の卵形成時、特に第一減数分裂での不分離による。母体年齢が高くなるほど頻度が上がる。転座型は数%で、親が均衡型転座の保因者であれば次の子の再発率が高くなるため、転座型では両親の染色体検査を検討する。モザイク型は受精後の体細胞分裂の不分離による。', '{"A": "欠失ではなく、染色体が1本余分に存在する状態である。", "B": "単一遺伝子の変異ではなく、染色体数の異常である。", "D": "転座型は全体の数%で、標準型の成因ではない。", "E": "正常細胞とトリソミー細胞が混在するモザイク型の成因で、頻度は低い。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '常染色体潜性遺伝の再発率', 2, 'CBT', 'ある常染色体潜性（劣性）遺伝の疾患について、両親はともに発症しておらず保因者であることがわかっている。この夫婦の次の子が罹患する確率はどれか。', '[{"key": "A", "text": "3/4"}, {"key": "B", "text": "2/3"}, {"key": "C", "text": "1/3"}, {"key": "D", "text": "1/4"}, {"key": "E", "text": "1/2"}]'::jsonb, 'D', '保因者どうしの子は、それぞれの親から変異をもつ対立遺伝子を1/2の確率で受け継ぐ。両方から受け継ぐと罹患するので確率は1/2×1/2＝1/4、保因者となる確率は1/2、変異をもたない確率は1/4である。罹患していないとわかっている子に限ると、保因者である確率は2/3となる。近親婚では同じ変異を共有する確率が高く、潜性遺伝の疾患が現れやすい。', '{"A": "この夫婦の子が罹患しない確率である。", "B": "この夫婦の罹患していない子が保因者である確率である。", "C": "この夫婦の罹患していない子が保因者でない確率である。", "E": "親の一方が罹患者である常染色体顕性（優性）遺伝の疾患で、子が罹患する確率である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ミトコンドリア遺伝', 2, 'CBT', 'ミトコンドリアDNAの変異による疾患には、MELASやLeber遺伝性視神経症などがある。ミトコンドリアDNAの変異による疾患の遺伝の特徴として正しいのはどれか。', '[{"key": "A", "text": "父親から子に伝わり、母親からは伝わらない"}, {"key": "B", "text": "男児だけが発症し、女児は発症しない"}, {"key": "C", "text": "メンデルの法則に従い1/4の確率で発症する"}, {"key": "D", "text": "変異をもつDNAの割合はすべての細胞で等しい"}, {"key": "E", "text": "母親から子に伝わり、父親からは伝わらない"}]'::jsonb, 'E', 'ミトコンドリアは卵子の細胞質を通じて受け継がれるため、ミトコンドリアDNAの変異は母系遺伝する。1つの細胞に多数のミトコンドリアDNAがあり、正常と変異のDNAが混在するヘテロプラスミーの割合によって症状の出方が異なる。エネルギー需要の大きい脳、筋、心筋、網膜が侵されやすく、乳酸アシドーシスを伴うことが多い。', '{"A": "精子のミトコンドリアは受精後に排除されるため、父親からは伝わらない。", "B": "性別にかかわらず発症しうる。", "C": "核の遺伝子ではないため、メンデルの法則には従わない。", "D": "正常と変異のDNAが混在（ヘテロプラスミー）し、その割合は細胞や組織で異なる。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'Hardy-Weinbergの法則', 2, 'CBT', 'ある集団で、常染色体潜性（劣性）遺伝の疾患の罹患者の頻度が1/10,000であった。Hardy-Weinbergの法則が成り立つとき、この集団における保因者の頻度に最も近いのはどれか。', '[{"key": "A", "text": "1/50"}, {"key": "B", "text": "1/100"}, {"key": "C", "text": "1/200"}, {"key": "D", "text": "1/5,000"}, {"key": "E", "text": "1/10,000"}]'::jsonb, 'A', '変異の対立遺伝子の頻度を q、正常の対立遺伝子の頻度を p とすると、罹患者の頻度は q² ＝ 1/10,000 なので q ＝ 1/100 となる。保因者の頻度は 2pq で、p はほぼ1とみなせるため2×1/100＝1/50となる。潜性遺伝の疾患では、罹患者がまれであっても保因者はかなり多いことがわかる。この法則は任意交配、十分大きな集団、選択や移入がないことなどを前提とする。', '{"B": "変異をもつ対立遺伝子の頻度であり、保因者の頻度ではない。", "C": "保因者の頻度を正しく求めた値の半分である。", "D": "罹患者の頻度を2倍しただけの値である。", "E": "罹患者の頻度そのものである。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '表現促進現象', 2, 'CBT', 'Huntington病や筋強直性ジストロフィーでは、世代を経るごとに発症年齢が早まり、症状が重くなる傾向がある。この現象はどれか。', '[{"key": "A", "text": "片親性ダイソミー"}, {"key": "B", "text": "表現促進"}, {"key": "C", "text": "ゲノムインプリンティング"}, {"key": "D", "text": "不完全浸透"}, {"key": "E", "text": "遺伝的異質性"}]'::jsonb, 'B', '表現促進は、3塩基の繰り返し配列（トリプレットリピート）が世代を経るごとに伸長することで起こる。Huntington病（CAGリピート）は父親から伝わるときに、筋強直性ジストロフィー1型（CTGリピート）は母親から伝わるときに伸長しやすく、後者では先天型の重症例が生まれることがある。脆弱X症候群（CGGリピート）でも同様の現象がみられる。', '{"A": "1対の染色体の両方を一方の親から受け継ぐ状態である。", "C": "親由来によって遺伝子の発現が異なる現象である。", "D": "変異をもっていても発症しない人がいる現象である。", "E": "異なる遺伝子の変異が同じ病気を起こす現象である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'ゲノムインプリンティング', 2, 'CBT', 'Prader-Willi症候群とAngelman症候群は、いずれも15番染色体の同じ領域（15q11-q13）の異常で起こるが、症状は大きく異なる。この違いを説明する現象はどれか。', '[{"key": "A", "text": "不完全浸透"}, {"key": "B", "text": "X染色体の不活化"}, {"key": "C", "text": "ゲノムインプリンティング"}, {"key": "D", "text": "表現促進"}, {"key": "E", "text": "モザイク"}]'::jsonb, 'C', 'ゲノムインプリンティングでは、一部の遺伝子がDNAメチル化などによって一方の親由来の対立遺伝子だけ発現する。15q11-q13では父親由来のみ発現する遺伝子と母親由来のみ発現するUBE3Aがある。父親由来の領域が欠失するか母親性ダイソミーではPrader-Willi症候群に、母親由来の領域が失われるか父親性ダイソミーではAngelman症候群になる。', '{"A": "変異をもっていても発症しない人がいる現象である。", "B": "女性で2本のX染色体の一方が不活化される現象で、15番染色体とは関係しない。", "D": "繰り返し配列の伸長で世代ごとに重症化する現象である。", "E": "1人の体内に遺伝的に異なる細胞が混在する状態である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'X染色体の不活化', 2, 'CBT', '女性の体細胞では、2本のX染色体のうち1本が不活化されている。X染色体の不活化について正しいのはどれか。', '[{"key": "A", "text": "細胞分裂のたびに不活化されるX染色体が別のものに入れ替わる"}, {"key": "B", "text": "男性の体細胞でも1本のX染色体が不活化される"}, {"key": "C", "text": "不活化されたX染色体は細胞から失われる"}, {"key": "D", "text": "細胞ごとにランダムに起こり、娘細胞に受け継がれる"}, {"key": "E", "text": "常に父親由来のX染色体が不活化される"}]'::jsonb, 'D', 'X染色体の不活化は発生初期に起こり、XIST RNAが片方のX染色体を覆い、DNAメチル化やヒストン修飾によって凝縮させることで起こり、核膜に接するBarr小体として観察される。どちらが不活化されるかは細胞ごとにランダムなので、X連鎖潜性遺伝病の保因者女性はモザイクとなり、偏りによっては症状が出ることがある。遺伝子量を男女でそろえる仕組みである。', '{"A": "いったん決まった不活化は娘細胞にそのまま受け継がれる。", "B": "男性のX染色体は1本で、不活化されない。", "C": "不活化されたX染色体は凝縮したBarr小体として核内に残る。", "E": "ヒトの体細胞ではどちらが不活化されるかは細胞ごとにランダムである。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', 'オートファジー', 2, 'CBT', '栄養が欠乏した細胞では、自身の細胞質成分を分解して材料とエネルギーを確保する。細胞質の一部や細胞小器官を膜で包み込み、リソソームと融合させて分解する現象はどれか。', '[{"key": "A", "text": "アポトーシス"}, {"key": "B", "text": "ネクローシス"}, {"key": "C", "text": "エンドサイトーシス"}, {"key": "D", "text": "エキソサイトーシス"}, {"key": "E", "text": "オートファジー"}]'::jsonb, 'E', 'オートファジーでは、隔離膜が細胞質成分や傷んだミトコンドリアを包み込んでオートファゴソームとなり、リソソームと融合して内容物を分解する。飢餓時の栄養の確保に加え、異常な蛋白質や細胞小器官の除去、細胞内に侵入した細菌の排除にも働く。この機構の解明で大隅良典は2016年のノーベル生理学・医学賞を受賞した。', '{"A": "遺伝子に制御された細胞死で、細胞質成分の再利用の仕組みではない。", "B": "細胞膜が破れて内容物が漏れ出る受動的な細胞死である。", "C": "細胞外の物質を細胞膜で包んで取り込む現象である。", "D": "分泌小胞の内容物を細胞外へ放出する現象である。"}'::jsonb, 'public', 'M', 'C-1', '', 'pending', 'llm'),
('基礎医学', '線維軟骨', 2, 'CBT', '軟骨は基質に含まれる線維の種類と量によって3つに分けられる。椎間板の線維輪や恥骨結合、関節半月を構成する軟骨はどれか。', '[{"key": "A", "text": "線維軟骨"}, {"key": "B", "text": "硝子軟骨"}, {"key": "C", "text": "弾性軟骨"}, {"key": "D", "text": "海綿骨"}, {"key": "E", "text": "密性結合組織"}]'::jsonb, 'A', '線維軟骨はI型コラーゲンの太い線維束を多く含み、圧縮や引っ張りに強い。椎間板の線維輪、恥骨結合、膝の半月板などにみられる。硝子軟骨はII型コラーゲンを主とし、関節軟骨や肋軟骨、気管軟骨、胎児の骨格の原型をつくる。弾性軟骨は弾性線維に富み、耳介や喉頭蓋にみられる。軟骨には血管がなく、栄養は周囲からの拡散による。', '{"B": "関節軟骨、肋軟骨、気管軟骨などを構成する。", "C": "耳介や喉頭蓋を構成し、弾性線維に富む。", "D": "骨の内部の骨梁からなる骨組織で、軟骨ではない。", "E": "腱や靱帯を構成する組織で、軟骨ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '骨単位', 2, 'CBT', '緻密骨は、骨単位（オステオン）とよばれる円柱状の構造が集まってできている。骨単位の中心を骨の長軸方向に走り、血管と神経を通す管はどれか。', '[{"key": "A", "text": "髄腔"}, {"key": "B", "text": "ハバース管"}, {"key": "C", "text": "フォルクマン管"}, {"key": "D", "text": "骨小腔"}, {"key": "E", "text": "骨細管"}]'::jsonb, 'B', '骨単位は中心のハバース管を同心円状の骨層板が取り巻いた構造で、層板の間の骨小腔に骨細胞がある。骨細胞は骨細管を通る突起で互いにつながり、ハバース管の血管から栄養を受ける。フォルクマン管は長軸に直交して走り、ハバース管どうしや骨膜・骨髄の血管を結ぶ。', '{"A": "骨幹の中心にある骨髄を入れる腔である。", "C": "骨の長軸に直交して走り、ハバース管どうしや骨膜とをつなぐ管である。", "D": "骨細胞が入っている小さな腔である。", "E": "骨細胞の突起が通る細い管で、血管は通らない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '長管骨の成長', 2, 'CBT', '小児の長管骨のエックス線写真では、骨端と骨幹端の間に透亮帯がみられる。長管骨が長さの方向に成長する場として正しいのはどれか。', '[{"key": "A", "text": "関節軟骨"}, {"key": "B", "text": "骨幹の緻密骨"}, {"key": "C", "text": "骨端軟骨（成長板）"}, {"key": "D", "text": "骨幹部の外側を覆う骨膜"}, {"key": "E", "text": "骨髄"}]'::jsonb, 'C', '骨端軟骨では軟骨細胞が増殖して柱状に並び、肥大して石灰化した軟骨が骨に置き換わる（軟骨内骨化）ことで骨が長くなる。成長ホルモンとIGF-1、甲状腺ホルモン、性ホルモンが調節し、思春期の終わりに性ホルモンの作用で骨端線が閉鎖する。軟骨無形成症はFGFR3遺伝子の活性化変異で軟骨細胞の増殖が抑えられ、四肢短縮型の低身長となる。', '{"A": "関節面を覆う軟骨で、長さの成長の主な場ではない。", "B": "すでに骨化した部分で、長さの成長は起こらない。", "D": "骨膜の骨芽細胞は骨を太くする（付加成長）が、長さの成長は担わない。", "E": "造血の場で、骨の長さの成長を担う場ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '心筋の組織', 2, 'CBT', '筋組織は骨格筋、心筋、平滑筋に分けられ、それぞれ形態と機能が異なる。心筋の組織学的特徴として正しいのはどれか。', '[{"key": "A", "text": "横紋を欠く紡錘形の細胞である"}, {"key": "B", "text": "核が細胞膜の直下の周辺部に多数並ぶ"}, {"key": "C", "text": "体性運動神経の支配で随意的に収縮する"}, {"key": "D", "text": "細胞どうしが介在板で結合している"}, {"key": "E", "text": "多数の核をもつ長い合胞体である"}]'::jsonb, 'D', '心筋は横紋をもつ不随意筋で、枝分かれした細胞が介在板で端と端をつないでいる。介在板には機械的に結合するデスモソームや接着結合と、興奮を隣の細胞へ伝えるギャップ結合があり、心臓全体が機能的な合胞体として同期して収縮する。成人の心筋細胞はほとんど分裂しないため、梗塞で失われた心筋は瘢痕で置き換わる。', '{"A": "平滑筋の特徴で、心筋には横紋がある。", "B": "骨格筋の特徴で、心筋の核は細胞の中央にある。", "C": "骨格筋の特徴で、心筋は不随意筋である。", "E": "骨格筋の特徴で、心筋細胞は核を1〜2個もつ。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '中枢神経の髄鞘', 2, 'CBT', '多発性硬化症では、中枢神経系の髄鞘が障害されて神経伝導が遅くなる。中枢神経系で髄鞘を形成する細胞はどれか。', '[{"key": "A", "text": "シュワン細胞"}, {"key": "B", "text": "アストロサイト"}, {"key": "C", "text": "ミクログリア"}, {"key": "D", "text": "上衣細胞"}, {"key": "E", "text": "オリゴデンドロサイト"}]'::jsonb, 'E', '中枢神経系ではオリゴデンドロサイトが複数の突起を伸ばし、それぞれが別の軸索に巻きついて髄鞘をつくる。末梢神経系ではシュワン細胞が1本の軸索の一区間だけを覆う。髄鞘のある軸索では興奮がRanvier絞輪を跳ぶように伝わる（跳躍伝導）。多発性硬化症は中枢の、Guillain-Barré症候群は末梢の髄鞘が主に障害される。', '{"A": "末梢神経系で髄鞘を形成する細胞である。", "B": "神経細胞の支持や血液脳関門の維持、イオン環境の調節を担う。", "C": "中枢神経系の免疫を担う食細胞である。", "D": "脳室や脊髄中心管の内面を覆う細胞である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '外胚葉の派生', 2, 'CBT', 'ヒトの胚は、発生の第3週に外胚葉、中胚葉、内胚葉の三胚葉を形成する。外胚葉に由来するものはどれか。', '[{"key": "A", "text": "表皮"}, {"key": "B", "text": "骨格筋"}, {"key": "C", "text": "腸管上皮"}, {"key": "D", "text": "肝細胞"}, {"key": "E", "text": "腎臓の尿細管"}]'::jsonb, 'A', '外胚葉からは表皮とその付属器（毛、爪、汗腺、乳腺）、水晶体、内耳、神経管（脳、脊髄、網膜）、神経堤が生じる。中胚葉からは骨格筋、骨・軟骨、心臓と血管、血球、腎臓、生殖腺、副腎皮質などが生じる。内胚葉からは消化管と呼吸器の上皮、肝臓、膵臓、甲状腺などが生じる。', '{"B": "中胚葉（体節）に由来する。", "C": "内胚葉に由来する。", "D": "内胚葉に由来する。", "E": "中胚葉（中間中胚葉）に由来する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '内胚葉の派生', 2, 'CBT', '器官の発生の由来は、先天異常や腫瘍の性質を理解する手がかりになる。内胚葉に由来するものはどれか。', '[{"key": "A", "text": "真皮"}, {"key": "B", "text": "甲状腺の濾胞上皮"}, {"key": "C", "text": "副腎髄質のクロム親和細胞"}, {"key": "D", "text": "心筋"}, {"key": "E", "text": "水晶体"}]'::jsonb, 'B', '内胚葉は原始腸管の上皮となり、消化管と気道の上皮、肝臓、胆道、膵臓、甲状腺の濾胞上皮、副甲状腺、胸腺の上皮、膀胱の上皮の多くなどをつくる。甲状腺は舌根の盲孔の位置から下降して頸部に達する。副腎は皮質が中胚葉、髄質が神経堤と、由来の異なる2つの組織からできている。', '{"A": "中胚葉に由来する。", "C": "神経堤に由来する。", "D": "中胚葉に由来する。", "E": "表面外胚葉に由来する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '神経堤細胞', 2, 'CBT', '神経堤細胞は神経管が閉じる際に分かれ出て全身へ移動し、多様な細胞に分化する。神経堤細胞に由来するものはどれか。', '[{"key": "A", "text": "骨格筋細胞"}, {"key": "B", "text": "肝細胞"}, {"key": "C", "text": "メラノサイト"}, {"key": "D", "text": "オリゴデンドロサイト"}, {"key": "E", "text": "網膜の視細胞"}]'::jsonb, 'C', '神経堤細胞からは、メラノサイト、末梢神経の感覚神経節と自律神経節の神経細胞、シュワン細胞、副腎髄質のクロム親和細胞、頭頸部の骨や軟骨の多く、心臓の流出路の中隔などが生じる。腸管の神経節細胞の移動が途中で止まるとHirschsprung病となる。神経芽腫や褐色細胞腫、悪性黒色腫は神経堤由来の細胞から発生する。', '{"A": "中胚葉の体節に由来する。", "B": "内胚葉に由来する。", "D": "神経管に由来する中枢神経系の神経膠細胞である。", "E": "神経管から伸び出た眼杯に由来する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '第1咽頭弓の派生', 2, 'CBT', '頭頸部の筋や骨の多くは、咽頭弓（鰓弓）から発生し、各咽頭弓は固有の脳神経に支配される。第1咽頭弓に由来する筋はどれか。', '[{"key": "A", "text": "茎突咽頭筋"}, {"key": "B", "text": "輪状甲状筋"}, {"key": "C", "text": "内舌筋"}, {"key": "D", "text": "咬筋"}, {"key": "E", "text": "口輪筋"}]'::jsonb, 'D', '第1咽頭弓からは咀嚼筋（咬筋、側頭筋、内側・外側翼突筋）、顎二腹筋前腹、鼓膜張筋、ツチ骨・キヌタ骨、下顎骨などが生じ、三叉神経（下顎神経）に支配される。第2咽頭弓は表情筋、アブミ骨筋、アブミ骨、舌骨小角をつくり顔面神経に、第3咽頭弓は茎突咽頭筋をつくり舌咽神経に、第4・6咽頭弓は喉頭の筋をつくり迷走神経に支配される。', '{"A": "第3咽頭弓に由来し、舌咽神経に支配される。", "B": "第4咽頭弓に由来し、迷走神経（上喉頭神経）に支配される。", "C": "後頭部の体節に由来し、舌下神経に支配される。", "E": "表情筋で、第2咽頭弓に由来し顔面神経に支配される。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '第3咽頭嚢の派生', 2, 'CBT', '22q11.2欠失症候群では、咽頭嚢の発生異常により低カルシウム血症と細胞性免疫不全をきたす。第3咽頭嚢から発生する器官の組合せはどれか。', '[{"key": "A", "text": "口蓋扁桃と中耳腔"}, {"key": "B", "text": "上副甲状腺と甲状腺"}, {"key": "C", "text": "甲状腺と胸腺"}, {"key": "D", "text": "耳管と口蓋扁桃"}, {"key": "E", "text": "胸腺と下副甲状腺"}]'::jsonb, 'E', '第1咽頭嚢は中耳腔と耳管、第2咽頭嚢は口蓋扁桃の陰窩、第3咽頭嚢は胸腺と下副甲状腺、第4咽頭嚢は上副甲状腺と鰓後体（傍濾胞細胞）をつくる。第3咽頭嚢由来の副甲状腺は胸腺とともに下降するため、下副甲状腺となる。22q11.2欠失症候群（DiGeorge症候群）では第3・4咽頭嚢の発生が障害され、胸腺低形成、副甲状腺機能低下、心臓の流出路の奇形を伴う。', '{"A": "口蓋扁桃は第2咽頭嚢、中耳腔は第1咽頭嚢に由来する。", "B": "上副甲状腺は第4咽頭嚢に由来し、甲状腺は咽頭嚢由来ではない。", "C": "甲状腺は咽頭の底部から下降して形成され、咽頭嚢には由来しない。", "D": "耳管は第1咽頭嚢、口蓋扁桃は第2咽頭嚢に由来する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '正中頸嚢胞', 2, 'CBT', '頸部の正中に、嚥下や舌の突出で上下に動く嚢胞を認めた。甲状腺の原基が下降した経路の遺残から生じるこの嚢胞の由来はどれか。', '[{"key": "A", "text": "甲状舌管"}, {"key": "B", "text": "第2鰓溝"}, {"key": "C", "text": "尿膜管"}, {"key": "D", "text": "卵黄腸管"}, {"key": "E", "text": "中腎管"}]'::jsonb, 'A', '甲状腺の原基は舌根の盲孔の位置から舌骨の前を通って頸部へ下降し、その通り道の甲状舌管は通常は消失する。遺残すると正中頸嚢胞となり、舌骨と連続するため嚥下や舌の突出で上下に動く。治療では再発を防ぐため舌骨の中央部を含めて摘出する（Sistrunk法）。舌根に甲状腺がとどまると舌根部甲状腺となる。', '{"B": "頸部の側方にできる側頸嚢胞の由来である。", "C": "膀胱の頂部から臍へ向かう管で、正中臍索となる。", "D": "遺残するとMeckel憩室などとなる。", "E": "男性で精管などになる管で、頸部の嚢胞とは関係しない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '動脈管', 2, 'CBT', '胎児では肺がまだ呼吸に使われないため、血液の多くは肺を迂回して体循環へ送られる。胎児循環で肺動脈から大動脈へ血液を短絡させる構造はどれか。', '[{"key": "A", "text": "臍静脈"}, {"key": "B", "text": "動脈管"}, {"key": "C", "text": "卵円孔"}, {"key": "D", "text": "静脈管"}, {"key": "E", "text": "臍動脈"}]'::jsonb, 'B', '動脈管は肺動脈と大動脈弓をつなぎ、胎児期にはプロスタグランジンE2などで開いている。出生後は動脈血の酸素分圧の上昇とプロスタグランジンの低下で収縮し、やがて動脈管索となる。閉じない動脈管開存症では、未熟児にインドメタシンなどのプロスタグランジン合成阻害薬を使う。逆に動脈管に依存する先天性心疾患では、プロスタグランジンE1で開存を保つ。', '{"A": "胎盤から酸素に富む血液を胎児へ運ぶ血管である。", "C": "右心房から左心房へ血液を通す孔である。", "D": "臍静脈の血液の一部を、肝臓を迂回させて下大静脈へ送る。", "E": "胎児の内腸骨動脈から胎盤へ血液を送る血管である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '卵円孔の閉鎖', 2, 'CBT', '出生して肺呼吸が始まると、胎児循環は数分から数日のうちに成人型の循環へ切り替わる。出生後に卵円孔が機能的に閉鎖する主な理由はどれか。', '[{"key": "A", "text": "臍静脈の血流が増えて右心房圧が上昇するため"}, {"key": "B", "text": "プロスタグランジンE2の血中濃度が上昇するため"}, {"key": "C", "text": "肺血流が増え、左心房圧が右心房圧より高くなるため"}, {"key": "D", "text": "肺血管抵抗が上昇し、右心房圧が左心房圧より高くなるため"}, {"key": "E", "text": "動脈管から大量の血液が右心房へ流れ込むため"}]'::jsonb, 'C', '肺呼吸が始まると肺血管抵抗が下がって肺血流が増え、肺静脈から左心房への還流が増す。同時に臍帯の結紮で胎盤からの還流がなくなり、右心房圧は下がる。左心房圧が右心房圧を上回ると一次中隔が二次中隔に押しつけられ、卵円孔が弁のように閉じる。成人の約4分の1では解剖学的な癒合が不完全な卵円孔開存が残り、奇異性塞栓の経路となりうる。', '{"A": "臍帯の結紮で臍静脈からの還流は途絶え、右心房圧は下がる。", "B": "出生後はプロスタグランジンE2が低下し、主に動脈管の閉鎖に関わる。", "D": "出生後は肺が広がって肺血管抵抗は低下する。", "E": "動脈管は大動脈と肺動脈をつなぐもので、右心房には流れ込まない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '尿管芽の分化', 2, 'CBT', '後腎（永久腎）は、尿管芽と後腎間葉の相互作用によって形成される。尿管芽から分化する構造はどれか。', '[{"key": "A", "text": "近位尿細管"}, {"key": "B", "text": "Henleループ"}, {"key": "C", "text": "遠位尿細管"}, {"key": "D", "text": "集合管"}, {"key": "E", "text": "糸球体"}]'::jsonb, 'D', '尿管芽は中腎管から出芽して後腎間葉に入り込み、分岐を繰り返して尿管、腎盂、腎杯、集合管をつくる。尿管芽の先端に誘導された後腎間葉はネフロン（糸球体のBowman嚢、近位尿細管、Henleループ、遠位尿細管）に分化する。この相互作用が損なわれると腎無形成や多嚢胞性異形成腎が生じる。', '{"A": "後腎間葉から生じるネフロンの一部である。", "B": "後腎間葉から生じるネフロンの一部である。", "C": "後腎間葉から生じるネフロンの一部である。", "E": "後腎間葉から生じるネフロンの一部である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'Müller管の退縮', 2, 'CBT', '性腺が精巣へ分化すると、女性生殖器の原基であるMüller管は退縮する。Müller管を退縮させる抗Müller管ホルモンを分泌する細胞はどれか。', '[{"key": "A", "text": "Leydig細胞"}, {"key": "B", "text": "顆粒膜細胞"}, {"key": "C", "text": "莢膜細胞"}, {"key": "D", "text": "副腎皮質の網状層の細胞"}, {"key": "E", "text": "Sertoli細胞"}]'::jsonb, 'E', 'Y染色体上のSRYの働きで性腺が精巣に分化すると、Sertoli細胞が抗Müller管ホルモンを分泌してMüller管（卵管、子宮、腟上部の原基）を退縮させ、Leydig細胞のテストステロンがWolff管を精巣上体、精管、精嚢に分化させる。精巣がない女性の胎児ではMüller管が残り、Wolff管は退縮する。', '{"A": "テストステロンを分泌し、Wolff管を精巣上体や精管に分化させる。", "B": "卵巣の卵胞でエストロゲンの合成に関わる細胞である。", "C": "卵巣の卵胞でアンドロゲンを産生する細胞である。", "D": "副腎アンドロゲンを分泌するが、Müller管は退縮させない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '外性器の男性化', 2, 'CBT', '5α還元酵素が欠損した46,XYの児では、精巣とWolff管由来の構造があるのに外性器は女性型に近くなる。外性器の男性化を直接担うホルモンはどれか。', '[{"key": "A", "text": "ジヒドロテストステロン"}, {"key": "B", "text": "テストステロン"}, {"key": "C", "text": "抗Müller管ホルモン"}, {"key": "D", "text": "エストラジオール"}, {"key": "E", "text": "ヒト絨毛性ゴナドトロピン"}]'::jsonb, 'A', 'テストステロンは標的組織で5α還元酵素によってより強力なジヒドロテストステロンに変換され、陰茎、陰嚢、前立腺の形成を担う。Wolff管の分化はテストステロン自体が担う。5α還元酵素欠損症では外性器が女性型に近いが、思春期にはテストステロンの増加で男性化が進む。アンドロゲン受容体の異常ではどちらの作用も現れない（アンドロゲン不応症）。', '{"B": "Wolff管の分化を担うが、外性器の男性化には5α還元酵素による変換が必要である。", "C": "Müller管を退縮させるホルモンで、外性器の分化には関わらない。", "D": "女性ホルモンで、外性器の男性化は担わない。", "E": "胎児のLeydig細胞を刺激するが、外性器に直接作用するのではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '神経管閉鎖障害', 2, 'CBT', '胎児の神経管は発生第4週に閉鎖するが、この閉鎖が障害されるとさまざまな奇形が生じる。神経管の頭側端の閉鎖不全で生じる奇形はどれか。', '[{"key": "A", "text": "先天性水頭症"}, {"key": "B", "text": "無脳症"}, {"key": "C", "text": "二分脊椎"}, {"key": "D", "text": "口唇裂"}, {"key": "E", "text": "臍帯ヘルニア"}]'::jsonb, 'B', '神経管の頭側端（前神経孔）が閉じないと無脳症、尾側端（後神経孔）が閉じないと二分脊椎となる。いずれも羊水中や母体血中のα-フェトプロテインが高くなる。妊娠前からの葉酸の摂取で発生の危険が下がるため、妊娠を計画する女性には食事に加えて葉酸の補充が勧められる。バルプロ酸などの薬剤も危険因子となる。', '{"A": "脳脊髄液の流れの障害などで生じ、頭側端の閉鎖不全そのものではない。", "C": "神経管の尾側の閉鎖不全で生じる。", "D": "顔面の突起の癒合不全で生じ、神経管とは関係しない。", "E": "腹壁の閉鎖不全で生じ、神経管とは関係しない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '胎盤を通過する抗体', 2, 'CBT', '新生児は生後しばらく、母親から受け取った抗体によって一部の感染症から守られている。胎盤を通過して母体から胎児へ移行する免疫グロブリンはどれか。', '[{"key": "A", "text": "IgE"}, {"key": "B", "text": "IgD"}, {"key": "C", "text": "IgG"}, {"key": "D", "text": "IgM"}, {"key": "E", "text": "IgA"}]'::jsonb, 'C', 'IgGは胎盤の合胞体栄養膜にある新生児Fc受容体（FcRn）を介して能動的に胎児へ運ばれ、特に妊娠後期に多く移行する。そのため早産児では移行抗体が少ない。母親由来のIgGは生後数か月で減少し、自身の産生が追いつくまでの時期に血中IgGが最も低くなる。臍帯血でIgMが高ければ、胎児自身が産生したもので子宮内感染を示唆する。', '{"A": "胎盤を通過しない。", "B": "胎盤を通過しない。", "D": "五量体で分子が大きく、胎盤を通過しない。", "E": "胎盤は通過せず、分泌型IgAとして母乳から児に与えられる。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '全分泌腺', 2, 'CBT', '外分泌腺は、分泌物を放出する様式によって分類される。細胞そのものが崩壊して分泌物となる全分泌（ホロクリン分泌）を行う腺はどれか。', '[{"key": "A", "text": "膵臓の腺房"}, {"key": "B", "text": "唾液腺"}, {"key": "C", "text": "涙腺"}, {"key": "D", "text": "皮脂腺"}, {"key": "E", "text": "エクリン汗腺"}]'::jsonb, 'D', '外分泌の様式には、分泌顆粒を開口分泌で放出する漏出分泌（エクリン汗腺、唾液腺、膵臓など）、細胞の頂部の一部がちぎれて放出される離出分泌（乳腺の脂質など）、細胞全体が崩壊して分泌物になる全分泌（皮脂腺）がある。皮脂腺は毛包に開口し、アンドロゲンで分泌が増えるため思春期に尋常性痤瘡が生じやすい。', '{"A": "消化酵素を分泌顆粒の開口分泌で放出する。", "B": "開口分泌で唾液を分泌する。", "C": "開口分泌で涙液を分泌する。", "E": "開口分泌（漏出分泌）で汗を分泌する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '細網線維', 2, 'CBT', 'リンパ節、脾臓、骨髄などの造血・リンパ組織では、細い線維が網目をつくって細胞を支えている。この支持組織をつくる線維はどれか。', '[{"key": "A", "text": "弾性線維"}, {"key": "B", "text": "太い膠原線維の束"}, {"key": "C", "text": "中間径フィラメント"}, {"key": "D", "text": "フィブリン"}, {"key": "E", "text": "細網線維"}]'::jsonb, 'E', '細網線維はIII型コラーゲンを主とする細い線維で、銀染色で黒く染まるため好銀線維ともよばれる。リンパ節、脾臓、骨髄、肝臓の類洞の周囲などで網目をつくり、血球やリンパ球を支える。創傷治癒の初期にもまずIII型コラーゲンが沈着し、のちに強いI型コラーゲンへ置き換わる。', '{"A": "エラスチンを主成分とし、大動脈や肺、皮膚に弾性を与える。", "B": "I型コラーゲンからなり、腱や靱帯に強い張力を与える。", "C": "細胞の中にある細胞骨格で、細胞外の支持線維ではない。", "D": "血液凝固で生じる線維で、組織の支持構造ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '弾性型動脈', 2, 'CBT', '動脈は壁の構造によって弾性型動脈と筋型動脈に分けられる。弾性型動脈に分類される血管はどれか。', '[{"key": "A", "text": "大動脈"}, {"key": "B", "text": "大腿動脈"}, {"key": "C", "text": "橈骨動脈"}, {"key": "D", "text": "細動脈"}, {"key": "E", "text": "大伏在静脈"}]'::jsonb, 'A', '大動脈や肺動脈などの心臓に近い太い動脈は、中膜に弾性板が何層も重なる弾性型動脈である。収縮期に拡張して血液を蓄え、拡張期に戻る力で血液を送り出すため（Windkessel機能）、拡張期にも血流が保たれる。加齢や動脈硬化で弾性が失われると収縮期血圧が上がり脈圧が大きくなる。末梢の中等大の動脈は平滑筋に富む筋型動脈である。', '{"B": "中膜に平滑筋が多い筋型動脈である。", "C": "中膜に平滑筋が多い筋型動脈である。", "D": "平滑筋の層が薄く、血管抵抗の調節を担う細い動脈である。", "E": "下肢の表在静脈で、動脈ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '洞様毛細血管', 2, 'CBT', '毛細血管は内皮と基底膜の構造によって3種類に分けられ、臓器の機能と結びついている。肝臓の類洞や脾臓、骨髄にみられる毛細血管はどれか。', '[{"key": "A", "text": "動静脈吻合"}, {"key": "B", "text": "洞様毛細血管"}, {"key": "C", "text": "連続型毛細血管"}, {"key": "D", "text": "有窓型毛細血管"}, {"key": "E", "text": "細静脈"}]'::jsonb, 'B', '不連続型の洞様毛細血管は内径が広く、内皮細胞の間に大きな隙間があり、基底膜も不完全である。肝臓の類洞では血漿蛋白が肝細胞と自由に行き来し、脾臓や骨髄では血球が血管の内外を出入りできる。連続型は筋や中枢神経に、有窓型は物質交換の盛んな腎糸球体、内分泌腺、腸絨毛にみられる。', '{"A": "毛細血管を経ずに細動脈と細静脈をつなぐ短絡路である。", "C": "筋、肺、中枢神経などにみられ、内皮に隙間がない。", "D": "腎糸球体、内分泌腺、腸絨毛などにみられ、内皮に小孔がある。", "E": "毛細血管の下流の血管で、炎症時に白血球が遊出する場である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '気道の上皮', 2, 'CBT', '気道の上皮は、吸い込んだ粉塵や微生物を粘液とともに口側へ運び出している。気管の粘膜上皮はどれか。', '[{"key": "A", "text": "移行上皮"}, {"key": "B", "text": "単層扁平上皮"}, {"key": "C", "text": "多列線毛上皮"}, {"key": "D", "text": "重層扁平上皮"}, {"key": "E", "text": "単層立方上皮"}]'::jsonb, 'C', '気管や気管支の上皮は、すべての細胞が基底膜に接しながら核の高さが不ぞろいに見える多列線毛上皮で、杯細胞が粘液を分泌し、線毛が一方向に打って粘液を喉頭へ運ぶ（粘液線毛クリアランス）。喫煙などの慢性刺激では重層扁平上皮に置き換わる扁平上皮化生が起こる。線毛の構造異常では慢性副鼻腔炎や気管支拡張症をきたす（原発性線毛機能不全症）。', '{"A": "膀胱や尿管などの尿路を覆い、伸展に応じて形を変える上皮である。", "B": "肺胞や血管の内皮などを構成する薄い上皮である。", "D": "口腔、食道、腟などの摩擦を受ける部位を覆う上皮である。", "E": "尿細管や甲状腺の濾胞などを構成する上皮である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '受精と着床', 2, 'CBT', '排卵された卵子は卵管采に取り込まれ、卵管を子宮に向かって運ばれる。受精から着床までの経過として正しいのはどれか。', '[{"key": "A", "text": "受精卵は受精した翌日には子宮内膜に着床する"}, {"key": "B", "text": "胚盤胞は卵管の内膜に着床するのが正常である"}, {"key": "C", "text": "受精卵は卵巣の表面に着床して発育する"}, {"key": "D", "text": "受精は卵管膨大部で起こり、約1週間後に子宮内膜に着床する"}, {"key": "E", "text": "受精は子宮腔内で起こり、受精卵はその直後に子宮内膜に着床する"}]'::jsonb, 'D', '受精は排卵後およそ1日以内に卵管膨大部で起こる。受精卵は卵割を繰り返しながら卵管を下り、受精後4〜5日で胚盤胞として子宮腔に達し、受精後約6〜7日で子宮内膜に着床する。着床した胚の栄養膜合胞体層がヒト絨毛性ゴナドトロピンを分泌し、黄体を維持する。子宮腔以外に着床すると異所性妊娠となり、その大部分は卵管妊娠である。', '{"A": "卵割を続けながら数日かけて子宮に達し、胚盤胞となってから着床する。", "B": "卵管への着床は異所性妊娠（卵管妊娠）である。", "C": "卵巣への着床は異所性妊娠である。", "E": "受精は通常、卵管膨大部で起こる。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '骨格筋の再生', 2, 'CBT', '骨格筋は損傷を受けても、ある程度まで再生することができる。骨格筋の再生を担い、筋線維の基底膜の内側にある幹細胞はどれか。', '[{"key": "A", "text": "線維芽細胞"}, {"key": "B", "text": "周皮細胞"}, {"key": "C", "text": "骨芽細胞"}, {"key": "D", "text": "マクロファージ"}, {"key": "E", "text": "衛星細胞"}]'::jsonb, 'E', '衛星細胞は筋線維の細胞膜と基底膜の間にある筋幹細胞で、ふだんは休止している。筋が損傷すると活性化して筋芽細胞となって増殖し、互いに融合して新しい筋線維をつくる。Duchenne型筋ジストロフィーでは壊死と再生が繰り返されるうちに再生能が追いつかなくなり、筋は脂肪と線維組織に置き換わる。心筋にはこのような幹細胞がほとんどない。', '{"A": "膠原線維などの細胞外基質をつくる細胞で、筋線維にはならない。", "B": "毛細血管を取り巻く細胞である。", "C": "骨基質をつくる細胞である。", "D": "壊死した組織を貪食する細胞で、筋線維にはならない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '静止膜電位', 2, 'CBT', '神経細胞の膜電位は、静止時に細胞内が細胞外に対しておよそ-70mVに保たれている。この静止膜電位を主に決めている要因はどれか。', '[{"key": "A", "text": "静止時にはカリウムイオンの膜透過性が高いこと"}, {"key": "B", "text": "静止時にはナトリウムイオンの膜透過性が高いこと"}, {"key": "C", "text": "塩化物イオンが能動的に細胞内へ汲み入れられること"}, {"key": "D", "text": "カルシウムイオンが細胞内へ流入し続けること"}, {"key": "E", "text": "ナトリウムポンプの起電性だけで電位がつくられること"}]'::jsonb, 'A', '細胞内はカリウムイオンが多く、静止時に開いているカリウムチャネルを通ってカリウムイオンが濃度勾配に従って流出しようとするため、細胞内が負になる。静止膜電位はカリウムイオンの平衡電位（約-90mV）に近く、わずかなナトリウムイオンの透過でやや浅くなる。ナトリウムポンプはこの濃度勾配を維持する。高カリウム血症では勾配が小さくなって静止膜電位が浅くなり、心筋の興奮性が変化して不整脈の原因となる。', '{"B": "静止時のナトリウムイオンの透過性は低く、高ければ膜電位は正に近づく。", "C": "静止膜電位の主因ではない。", "D": "カルシウムイオンの流入は脱分極の方向に働き、静止膜電位の主因ではない。", "E": "ポンプの起電性の寄与は数mVにとどまり、主因はカリウムイオンの透過性である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '絶対不応期', 2, 'CBT', '神経細胞では、活動電位が生じた直後のしばらくの間、どれほど強い刺激を与えても次の活動電位が生じない。この絶対不応期が生じる主な理由はどれか。', '[{"key": "A", "text": "髄鞘によって膜が電気的に絶縁されているため"}, {"key": "B", "text": "ナトリウムチャネルが不活性化しているため"}, {"key": "C", "text": "カリウムチャネルがすべて閉じているため"}, {"key": "D", "text": "ナトリウムポンプが停止しているため"}, {"key": "E", "text": "細胞外のカルシウムイオンが枯渇しているため"}]'::jsonb, 'B', '電位依存性ナトリウムチャネルは開いた直後に不活性化ゲートが閉じ、膜が再分極するまで再び開くことができない。この間は刺激しても活動電位が生じない（絶対不応期）。その後、一部のチャネルが回復すると強い刺激でのみ興奮する相対不応期となる。不応期があるため興奮は後戻りせず一方向に伝わり、発火頻度にも上限ができる。', '{"A": "髄鞘は跳躍伝導に関わるもので、不応期の原因ではない。", "C": "再分極期にはカリウムチャネルが開いてカリウムイオンが流出している。", "D": "ナトリウムポンプは不応期にも働いており、不応期の原因ではない。", "E": "神経の不応期の原因ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '神経線維の伝導速度', 2, 'CBT', '末梢神経線維は、太さと髄鞘の有無によって伝導速度が大きく異なる。最も伝導速度が速い神経線維はどれか。', '[{"key": "A", "text": "自律神経の節前線維であるB線維"}, {"key": "B", "text": "筋紡錘の錘内筋線維を支配するAγ線維"}, {"key": "C", "text": "骨格筋の筋線維を支配するAα線維"}, {"key": "D", "text": "鋭い痛みを伝えるAδ線維"}, {"key": "E", "text": "鈍い痛みを伝えるC線維"}]'::jsonb, 'C', '伝導速度は線維が太いほど、また髄鞘があるほど速い。Aα線維（運動神経と筋紡錘からのIa線維など）は最も太い有髄線維で、秒速70〜120mに達する。鋭い一次痛はAδ線維で、遅れて来る鈍い二次痛は無髄のC線維で伝わる。自律神経の節前線維はB線維、節後線維はC線維である。', '{"A": "細い有髄線維で、伝導速度はAα線維より遅い。", "B": "中等度の太さの有髄線維で、Aα線維より遅い。", "D": "細い有髄線維で、伝導速度はAα線維より遅い。", "E": "無髄線維で、伝導速度が最も遅い。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '伝達物質の放出', 2, 'CBT', '活動電位が神経終末に達すると、シナプス小胞の神経伝達物質がシナプス間隙へ放出される。この放出の直接の引き金となるのはどれか。', '[{"key": "A", "text": "カリウムイオンの流出による再分極"}, {"key": "B", "text": "塩化物イオンの流入による過分極"}, {"key": "C", "text": "アセチルコリンエステラーゼによる伝達物質の分解"}, {"key": "D", "text": "カルシウムチャネルからのカルシウムイオンの流入"}, {"key": "E", "text": "ナトリウムポンプによるナトリウムイオンの汲み出し"}]'::jsonb, 'D', '神経終末が脱分極すると電位依存性カルシウムチャネルが開き、流入したカルシウムイオンがシナプトタグミンに結合して、SNARE蛋白質の働きでシナプス小胞が細胞膜と融合し、伝達物質が放出される。Lambert-Eaton症候群ではこのカルシウムチャネルに対する自己抗体が、ボツリヌス毒素ではSNARE蛋白質の切断が、アセチルコリンの放出を妨げる。', '{"A": "活動電位を終わらせる過程で、放出の引き金ではない。", "B": "抑制性の変化で、放出の引き金ではない。", "C": "放出後の伝達物質を分解して作用を終わらせる過程である。", "E": "イオン勾配を保つ働きで、放出の引き金ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '黒質線条体路', 2, 'CBT', '中脳の黒質緻密部の神経細胞は線条体に投射し、運動の開始や調節に関わっている。この神経細胞が用いる神経伝達物質はどれか。', '[{"key": "A", "text": "ノルアドレナリン"}, {"key": "B", "text": "セロトニン"}, {"key": "C", "text": "アセチルコリン"}, {"key": "D", "text": "グリシン"}, {"key": "E", "text": "ドパミン"}]'::jsonb, 'E', '黒質緻密部のドパミン作動性ニューロンは線条体に投射し、直接路を促進し間接路を抑制して運動を起こしやすくする。Parkinson病ではこの細胞が変性して線条体のドパミンが減り、無動、筋強剛、安静時振戦をきたす。中脳の腹側被蓋野からのドパミン系は報酬や意欲に関わり、統合失調症の病態や抗精神病薬の作用とも関係する。', '{"A": "主に橋の青斑核の神経細胞が用いる。", "B": "主に脳幹の縫線核の神経細胞が用いる。", "C": "前脳基底部のMeynert基底核や線条体の介在ニューロンなどが用いる。", "D": "主に脊髄や脳幹で働く抑制性の伝達物質である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'グリシン', 2, 'CBT', '破傷風毒素は脊髄の抑制性介在ニューロンからの伝達物質の放出を妨げ、全身の筋の強直を起こす。脊髄で主に働く抑制性の神経伝達物質はどれか。', '[{"key": "A", "text": "グリシン"}, {"key": "B", "text": "グルタミン酸"}, {"key": "C", "text": "アセチルコリン"}, {"key": "D", "text": "サブスタンスP"}, {"key": "E", "text": "ドパミン"}]'::jsonb, 'A', 'グリシンは脊髄と脳幹の抑制性介在ニューロン（Renshaw細胞など）の伝達物質で、塩化物イオンチャネルを開いて過分極を起こす。大脳ではGABAが主な抑制性伝達物質である。破傷風毒素は抑制性ニューロンからのグリシンとGABAの放出を妨げ、運動ニューロンが抑制を失って強直性けいれんをきたす。ストリキニーネはグリシン受容体を遮断する。', '{"B": "中枢神経系で最も主要な興奮性の伝達物質である。", "C": "神経筋接合部や自律神経節などで働く興奮性の伝達物質である。", "D": "痛覚の一次求心線維が放出する興奮性のペプチドである。", "E": "中脳から線条体などへ投射する神経が用いるモノアミンである。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '錐体交叉', 2, 'CBT', '随意運動の指令は、大脳皮質の運動野から皮質脊髄路を通って脊髄の運動ニューロンに伝わる。皮質脊髄路の線維の大部分が正中を越えて反対側へ交叉する部位はどれか。', '[{"key": "A", "text": "脊髄の各髄節にある前交連"}, {"key": "B", "text": "延髄下部（錐体交叉）"}, {"key": "C", "text": "中脳の大脳脚"}, {"key": "D", "text": "橋の底部"}, {"key": "E", "text": "内包後脚"}]'::jsonb, 'B', '皮質脊髄路は内包後脚、中脳の大脳脚、橋底部、延髄の錐体を下行し、延髄下部の錐体交叉で約8〜9割が反対側へ移って外側皮質脊髄路となる。残りは前皮質脊髄路として同側を下り、髄節レベルで交叉する。そのため錐体交叉より上の障害では反対側、脊髄の障害では同側の運動麻痺となる。', '{"A": "交叉しなかった一部の線維が髄節レベルで交叉するが、大部分ではない。", "C": "皮質脊髄路が通過する部位だが、交叉は起こらない。", "D": "皮質脊髄路が束に分かれて通過する部位で、交叉は起こらない。", "E": "皮質脊髄路が通過する大脳の部位で、交叉は起こらない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '脊髄半側障害', 2, 'CBT', '外傷により第10胸髄の右半側が完全に損傷された。障害された高さより下の左半身に生じる症状はどれか。', '[{"key": "A", "text": "深部腱反射の亢進"}, {"key": "B", "text": "関節の位置覚の低下"}, {"key": "C", "text": "温痛覚の低下"}, {"key": "D", "text": "痙性の運動麻痺"}, {"key": "E", "text": "振動覚の低下"}]'::jsonb, 'C', '脊髄半側障害（Brown-Séquard症候群）では、損傷側で錐体路障害による運動麻痺と後索障害による深部感覚・識別性触覚の低下が、反対側で温痛覚の低下が生じる。温痛覚の線維は脊髄に入ると1〜2髄節上行したのちに前交連で交叉して反対側の外側脊髄視床路を上行するためである。後索は同側を上行し、延髄で交叉する。', '{"A": "上位運動ニューロンの障害として、損傷と同じ右側に生じる。", "B": "後索は同側を上行するため、損傷と同じ右側で低下する。", "D": "皮質脊髄路は延髄で交叉を終えているため、麻痺は損傷と同じ右側に生じる。", "E": "後索は同側を上行するため、損傷と同じ右側で低下する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'Huntington病の病変', 2, 'CBT', '30歳代から舞踏運動と認知機能の低下が進行し、父親にも同じ症状があった。この疾患で早期から萎縮が目立つ部位はどれか。', '[{"key": "A", "text": "小脳歯状核"}, {"key": "B", "text": "視床下核"}, {"key": "C", "text": "海馬"}, {"key": "D", "text": "尾状核"}, {"key": "E", "text": "黒質緻密部"}]'::jsonb, 'D', 'Huntington病はHTT遺伝子のCAGリピートの伸長による常染色体顕性（優性）遺伝の疾患で、線条体（特に尾状核）の中型有棘ニューロンが早期から脱落する。間接路の抑制が失われて舞踏運動などの不随意運動が生じ、画像では尾状核の萎縮で側脳室前角が拡大する。父親から伝わると表現促進が起こりやすい。', '{"A": "小脳の出力核で、この疾患で早期から萎縮する部位ではない。", "B": "障害されると反対側のヘミバリズムを起こす部位である。", "C": "Alzheimer病で早期から萎縮が目立つ部位である。", "E": "Parkinson病で変性が目立つ部位である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '小脳障害の症状', 2, 'CBT', '脳血管障害で右の小脳半球が障害された患者を診察している。この患者にみられる症状として正しいのはどれか。', '[{"key": "A", "text": "左上下肢の協調運動の障害"}, {"key": "B", "text": "左上下肢の片麻痺"}, {"key": "C", "text": "安静時の振戦"}, {"key": "D", "text": "流暢だが意味の通らない発話"}, {"key": "E", "text": "右上下肢の協調運動の障害"}]'::jsonb, 'E', '小脳半球は同側の四肢の協調運動を調節する。小脳からの出力は上小脳脚で交叉して反対側の視床から大脳皮質に至り、その大脳からの指令が錐体交叉で再び交叉するため、症状は障害と同じ側に現れる。測定障害、変換運動障害、企図振戦、筋緊張の低下などを示し、虫部の障害では体幹の失調と歩行のふらつきが目立つ。', '{"A": "小脳半球の障害は同側の四肢に症状を生じる。", "B": "運動麻痺は錐体路の障害で生じ、小脳障害の症状ではない。", "C": "Parkinson病などの大脳基底核の障害でみられる。", "D": "Wernicke失語で、優位半球の側頭葉の障害で生じる。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '視床を経由しない感覚', 2, 'CBT', '多くの感覚は、視床の特定の核で中継されてから大脳皮質の感覚野に達する。視床で中継されずに大脳皮質に達する感覚はどれか。', '[{"key": "A", "text": "嗅覚"}, {"key": "B", "text": "視覚"}, {"key": "C", "text": "聴覚"}, {"key": "D", "text": "味覚"}, {"key": "E", "text": "体幹の触覚"}]'::jsonb, 'A', '嗅細胞からの情報は嗅神経を経て嗅球に入り、嗅索を通って視床を経由せずに梨状皮質や扁桃体などの嗅覚野に達する。嗅覚が情動や記憶と結びつきやすいのはこのためとされる。嗅覚の低下はParkinson病やAlzheimer病の早期にもみられ、頭部外傷では篩板を通る嗅糸の断裂で生じる。', '{"B": "視床の外側膝状体で中継されて後頭葉の一次視覚野に達する。", "C": "視床の内側膝状体で中継されて側頭葉の一次聴覚野に達する。", "D": "視床の後内側腹側核で中継されて島皮質などに達する。", "E": "視床の後外側腹側核で中継されて中心後回に達する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '内包の障害', 2, 'CBT', '高血圧のある患者で、左の内包後脚に限局した小さな梗塞が生じた。この患者に生じる可能性が最も高い症状はどれか。', '[{"key": "A", "text": "両耳側の視野欠損"}, {"key": "B", "text": "右上下肢と顔面下部の運動麻痺"}, {"key": "C", "text": "左上下肢と左顔面下部の運動麻痺"}, {"key": "D", "text": "両下肢だけの運動麻痺"}, {"key": "E", "text": "左側の顔面の温痛覚の低下"}]'::jsonb, 'B', '内包後脚には皮質脊髄路と皮質延髄路が密に通るため、小さな病変でも反対側の上下肢と顔面下部の運動麻痺が生じる（純粋運動性片麻痺）。穿通枝の細動脈が閉塞するラクナ梗塞の好発部位である。内包後脚の後方には視床から中心後回へ向かう感覚線維や視放線も通る。', '{"A": "視交叉の障害で生じる。", "C": "内包は錐体交叉より上にあるため、麻痺は反対側に生じる。", "D": "両下肢の麻痺は脊髄の障害などで生じる。", "E": "内包の障害では反対側に症状が出る。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '感覚性失語', 2, 'CBT', '脳梗塞の患者が、流暢に話すが言い誤りが多く、話の内容がまとまらない。話しかけられた言葉の理解も障害されている。障害された部位として最も考えられるのはどれか。', '[{"key": "A", "text": "劣位半球の頭頂葉"}, {"key": "B", "text": "両側の後頭葉の鳥距溝"}, {"key": "C", "text": "優位半球の上側頭回後部"}, {"key": "D", "text": "優位半球の下前頭回の後部"}, {"key": "E", "text": "優位半球の中心前回"}]'::jsonb, 'C', 'Wernicke野は優位半球（多くは左）の上側頭回後部にあり、障害されると言葉の理解が障害される感覚性失語となる。発話は流暢だが錯語が多く、内容が伝わらない。復唱も障害される。Broca野（下前頭回後部）の障害では理解は比較的保たれるが、発話が非流暢でたどたどしくなる。両者を結ぶ弓状束の障害では、復唱が特に障害される伝導失語となる。', '{"A": "障害されると左半側空間無視などを生じる。", "B": "一次視覚野で、障害されると皮質盲を生じる。", "D": "運動性失語（Broca失語）の責任病巣で、発話が非流暢になる。", "E": "一次運動野で、障害されると反対側の運動麻痺を生じる。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '視交叉の障害', 2, 'CBT', '下垂体腺腫が上方へ進展し、視交叉が正中から圧迫された。この患者に生じる視野障害として最も考えられるのはどれか。', '[{"key": "A", "text": "片眼の全盲"}, {"key": "B", "text": "上1/4同名半盲"}, {"key": "C", "text": "両鼻側半盲"}, {"key": "D", "text": "両耳側半盲"}, {"key": "E", "text": "同名半盲"}]'::jsonb, 'D', '網膜の鼻側半分からの線維は視交叉で交叉し、耳側半分からの線維は交叉しない。視交叉の正中が圧迫されると両眼の鼻側網膜からの線維が障害され、両眼とも耳側の視野が欠ける両耳側半盲となる。下垂体腺腫や頭蓋咽頭腫でみられ、初期には上耳側から欠けることが多い。', '{"A": "視交叉より前の視神経の障害で生じる。", "B": "側頭葉を通る視放線（Meyerループ）の障害で生じる。", "C": "視交叉の外側からの圧迫でまれに生じるが、正中からの圧迫では生じない。", "E": "視交叉より後ろの視索や視放線、後頭葉の障害で生じる。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '対光反射の遠心路', 2, 'CBT', 'ペンライトで片眼に光を当てると、両眼の瞳孔が収縮する。この対光反射の遠心路となる神経はどれか。', '[{"key": "A", "text": "視神経"}, {"key": "B", "text": "三叉神経"}, {"key": "C", "text": "顔面神経に含まれる運動線維"}, {"key": "D", "text": "頸部交感神経"}, {"key": "E", "text": "動眼神経の副交感線維"}]'::jsonb, 'E', '光の情報は視神経から視蓋前域に達し、両側のEdinger-Westphal核に伝わる。そこから動眼神経の副交感線維が毛様体神経節で乗り換え、瞳孔括約筋を収縮させる。両側に投射するため、光を当てた眼の直接反射と反対眼の間接反射が生じる。動眼神経が圧迫されると、外眼筋の麻痺より先に瞳孔の散大と対光反射の消失が現れることがある。', '{"A": "対光反射の求心路である。", "B": "角膜反射の求心路となる神経である。", "C": "角膜反射の遠心路（眼輪筋の収縮）となる神経である。", "D": "瞳孔散大筋を支配し、瞳孔を散大させる。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '顔面神経の機能', 2, 'CBT', '顔面神経は運動線維のほか、感覚線維や副交感線維も含む混合神経である。顔面神経が担う機能はどれか。', '[{"key": "A", "text": "舌の前2/3の味覚"}, {"key": "B", "text": "咀嚼筋の運動"}, {"key": "C", "text": "舌の後ろ1/3の味覚"}, {"key": "D", "text": "顔面の皮膚の感覚"}, {"key": "E", "text": "眼球の外転"}]'::jsonb, 'A', '顔面神経は表情筋とアブミ骨筋の運動、舌の前2/3の味覚（鼓索神経）、涙腺・顎下腺・舌下腺の分泌（副交感線維）を担う。末梢性顔面神経麻痺（Bell麻痺など）では、障害の部位により味覚障害、聴覚過敏、涙の分泌低下を伴う。顔面の皮膚感覚と咀嚼筋は三叉神経が担う。', '{"B": "三叉神経（下顎神経）が担う。", "C": "舌咽神経が担う。", "D": "三叉神経が担う。", "E": "外転神経が担う。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '舌下神経麻痺', 2, 'CBT', '右の舌下神経が障害された患者に、舌をまっすぐ前に出すよう指示した。このときの舌の所見として正しいのはどれか。', '[{"key": "A", "text": "口蓋垂が右側へ偏位する"}, {"key": "B", "text": "舌の先端が右側へ偏位する"}, {"key": "C", "text": "舌の先端が左側へ偏位する"}, {"key": "D", "text": "舌は偏位せず、まっすぐ前に出る"}, {"key": "E", "text": "舌をまったく前に出せない"}]'::jsonb, 'B', '舌を前に突き出すのは主にオトガイ舌筋で、左右の筋が舌を反対側の前方へ押し出す。右の舌下神経が障害されると左の筋だけが働くため、舌は右（障害側）へ偏位する。末梢性の障害では障害側の舌に萎縮や線維束性収縮を伴う。迷走神経の障害では、発声時に口蓋垂が健側へ引かれる（カーテン徴候）。', '{"A": "口蓋垂の偏位は迷走神経の障害でみられ、健側に偏位する。", "C": "偏位は障害された側に向かう。", "D": "片側の麻痺があると健側の筋に押されて偏位する。", "E": "片側の障害では、健側の筋で舌を出すことはできる。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '脳脊髄液の循環', 2, 'CBT', '脳脊髄液は、脳と脊髄を浮かべて衝撃から守り、脳の周囲の環境を保っている。脳脊髄液の産生と吸収について正しいのはどれか。', '[{"key": "A", "text": "総量は約1.5Lで、1日に1回だけ入れ替わる"}, {"key": "B", "text": "第四脳室から側脳室へ向かって流れる"}, {"key": "C", "text": "主に脈絡叢で産生され、くも膜顆粒から吸収される"}, {"key": "D", "text": "主に硬膜で産生され、脳室の上衣細胞から吸収される"}, {"key": "E", "text": "主に脳実質の神経細胞が分泌し、リンパ管だけから吸収される"}]'::jsonb, 'C', '脳脊髄液は主に側脳室などの脈絡叢で1日に約500mL産生され、総量は約150mLなので1日に3〜4回入れ替わる。側脳室からMonro孔、第三脳室、中脳水道、第四脳室を経て、Magendie孔とLuschka孔からくも膜下腔に出て、くも膜顆粒から硬膜静脈洞へ吸収される。流れや吸収が妨げられると水頭症となる。', '{"A": "総量は約150mLで、1日に3〜4回入れ替わる。", "B": "側脳室から第三脳室、中脳水道、第四脳室へと流れる。", "D": "産生の主体は脈絡叢で、吸収は主にくも膜顆粒で行われる。", "E": "脳脊髄液の大部分は脈絡叢が産生する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'レボドパと血液脳関門', 2, 'CBT', 'Parkinson病の治療では、ドパミンそのものではなく、その前駆体のレボドパを投与する。その理由として正しいのはどれか。', '[{"key": "A", "text": "レボドパはドパミンより強くドパミン受容体を刺激するから"}, {"key": "B", "text": "ドパミンは脳内でレボドパに変換されないと作用しないから"}, {"key": "C", "text": "レボドパは末梢でまったく代謝されないから"}, {"key": "D", "text": "ドパミンは血液脳関門を通過しにくいから"}, {"key": "E", "text": "ドパミンは消化管で吸収されるが、レボドパは吸収されないから"}]'::jsonb, 'D', '脳の毛細血管は内皮細胞が密着結合で結ばれ、水溶性の物質の多くは通過できない（血液脳関門）。ドパミンは通過できないが、レボドパは大型中性アミノ酸輸送体で脳に入り、芳香族L-アミノ酸脱炭酸酵素でドパミンになる。末梢での変換を防ぐため、血液脳関門を通らない脱炭酸酵素阻害薬（カルビドパなど）を併用し、悪心などの末梢の副作用を減らす。', '{"A": "レボドパ自体は受容体をほとんど刺激せず、脳内でドパミンに変換されて作用する。", "B": "変換の向きが逆で、レボドパがドパミンに変換される。", "C": "末梢でも脱炭酸されるため、脱炭酸酵素阻害薬を併用する。", "E": "レボドパは小腸のアミノ酸輸送体で吸収される。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '伸張反射の受容器', 2, 'CBT', '膝蓋腱をハンマーでたたくと大腿四頭筋が収縮して下腿が伸展する。この膝蓋腱反射で、筋が引き伸ばされたことを感知する受容器はどれか。', '[{"key": "A", "text": "Golgi腱器官"}, {"key": "B", "text": "Pacini小体"}, {"key": "C", "text": "Meissner小体"}, {"key": "D", "text": "自由神経終末"}, {"key": "E", "text": "筋紡錘"}]'::jsonb, 'E', '筋が伸ばされると筋紡錘の錘内筋線維が伸展され、Ia群線維から脊髄に入った情報が同じ筋のα運動ニューロンに単シナプスで伝わって筋が収縮する（伸張反射）。膝蓋腱反射の中枢は第3・4腰髄である。γ運動ニューロンは錘内筋を収縮させて筋紡錘の感度を調節する。上位運動ニューロンの障害では反射が亢進し、末梢神経や筋の障害では低下する。', '{"A": "腱にあって筋の張力を感知し、同じ筋を抑制する反射に関わる。", "B": "皮下にあって振動や圧の変化を感知する。", "C": "皮膚の真皮乳頭にあって触覚を感知する。", "D": "痛みや温度を感知する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'レム睡眠', 2, 'CBT', '睡眠はノンレム睡眠とレム睡眠からなり、一晩のうちに約90分の周期で繰り返される。レム睡眠の特徴として正しいのはどれか。', '[{"key": "A", "text": "急速眼球運動と筋緊張の低下を伴い、夢を見ることが多い"}, {"key": "B", "text": "脳波で高振幅の徐波（δ波）が主体となる"}, {"key": "C", "text": "成長ホルモンの分泌が最も多い時期である"}, {"key": "D", "text": "健常成人では入眠直後に最初に出現する"}, {"key": "E", "text": "一晩の睡眠の前半に多く、明け方にはほとんど出現しなくなる"}]'::jsonb, 'A', 'レム睡眠では脳波は覚醒時に近い低振幅の速い波となり、急速眼球運動が生じ、抗重力筋の緊張が著しく低下する。夢の多くはこの時期に見る。筋の緊張低下が起こらずに夢の内容どおりに体が動くのがレム睡眠行動障害で、Parkinson病などに先行することがある。ノンレム睡眠は深さで段階に分けられ、深い徐波睡眠は睡眠の前半に多い。', '{"B": "深いノンレム睡眠（徐波睡眠）の特徴である。", "C": "成長ホルモンは入眠後早期の徐波睡眠で多く分泌される。", "D": "健常成人ではノンレム睡眠から始まる。入眠直後のレム睡眠はナルコレプシーでみられる。", "E": "レム睡眠は明け方に向かって長くなる。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'α波', 2, 'CBT', '脳波は覚醒の程度や脳の状態によって周波数が変化する。健常成人が安静にして閉眼しているとき、後頭部を中心にみられる脳波はどれか。', '[{"key": "A", "text": "3Hzの棘徐波複合"}, {"key": "B", "text": "8〜13Hzのα波"}, {"key": "C", "text": "14Hz以上の速いβ波"}, {"key": "D", "text": "4〜7Hzのθ波"}, {"key": "E", "text": "4Hz未満のδ波"}]'::jsonb, 'B', '安静閉眼時の健常成人では、後頭部優位に8〜13Hzのα波がみられ、開眼や暗算などで抑制される（α波の減衰）。覚醒度が下がるとθ波、深い睡眠ではδ波が目立つ。ベンゾジアゼピン系薬ではβ波が増える。覚醒した成人で徐波が広範にみられれば、意識障害や脳症を疑う。', '{"A": "欠神てんかんの発作時にみられる。", "C": "開眼や精神活動時、また一部の薬剤の使用時に目立つ。", "D": "眠気が強いときや浅い睡眠でみられる。", "E": "深い睡眠でみられ、覚醒した成人では異常である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '海馬と記憶', 2, 'CBT', 'Alzheimer病の初期には、昔のことはよく覚えているのに最近の出来事を覚えられなくなる。新しい出来事の記憶（エピソード記憶）の形成に特に重要な部位はどれか。', '[{"key": "A", "text": "視交叉上核"}, {"key": "B", "text": "中心前回"}, {"key": "C", "text": "海馬"}, {"key": "D", "text": "扁桃体"}, {"key": "E", "text": "小脳"}]'::jsonb, 'C', '海馬は側頭葉内側にあり、新しいエピソード記憶や意味記憶を一時的に保持して大脳皮質に定着させる働きをもつ。両側の海馬が障害されると新しいことを覚えられない前向性健忘となるが、古い記憶や手続き記憶は保たれやすい。海馬は虚血や低血糖にも弱く、Alzheimer病では早期から萎縮がみられる。', '{"A": "概日リズムの中枢である。", "B": "一次運動野で、随意運動の指令を出す。", "D": "恐怖などの情動や、情動と結びついた記憶に関わる。", "E": "運動の協調や、自転車の乗り方のような手続き記憶の学習に関わる。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '概日リズムの中枢', 2, 'CBT', '夜勤や海外旅行で昼夜が逆転すると、睡眠や体温、ホルモン分泌のリズムが乱れる。網膜から光の情報を直接受け、概日リズムの中枢として働く視床下部の神経核はどれか。', '[{"key": "A", "text": "視索上核"}, {"key": "B", "text": "弓状核"}, {"key": "C", "text": "乳頭体"}, {"key": "D", "text": "視交叉上核"}, {"key": "E", "text": "室傍核"}]'::jsonb, 'D', '視交叉上核は網膜の一部の神経節細胞から光の情報を受け、約24時間のリズムを外界の明暗に合わせる。その信号は松果体に伝わり、夜間にメラトニンの分泌を増やす。細胞内では時計遺伝子の転写と翻訳のフィードバックがリズムをつくる。朝の光を浴びることはリズムの前進に役立つ。', '{"A": "主にバソプレシンを産生し、下垂体後葉へ送る。", "B": "摂食調節や、ドパミンによるプロラクチン分泌の抑制などに関わる。", "C": "記憶の回路に関わり、Wernicke脳症で障害される。", "E": "副腎皮質刺激ホルモン放出ホルモンやオキシトシンなどを産生する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '汗腺の神経支配', 2, 'CBT', '交感神経の節後線維の多くはノルアドレナリンを放出するが、例外がある。体温調節に働くエクリン汗腺を支配する交感神経の節後線維が放出する伝達物質はどれか。', '[{"key": "A", "text": "ノルアドレナリン"}, {"key": "B", "text": "アドレナリン"}, {"key": "C", "text": "ドパミン"}, {"key": "D", "text": "セロトニン"}, {"key": "E", "text": "アセチルコリン"}]'::jsonb, 'E', 'エクリン汗腺は交感神経に支配されるが、節後線維はアセチルコリンを放出し、ムスカリン受容体を介して発汗が起こる。そのため抗コリン薬の中毒では発汗が止まり、皮膚が乾燥して体温が上がる。一方、副腎髄質は交感神経の節前線維が直接支配し、アセチルコリンを受けてアドレナリンを分泌する。', '{"A": "多くの交感神経節後線維の伝達物質だが、エクリン汗腺では例外的に使われない。", "B": "主に副腎髄質からホルモンとして分泌される。", "C": "腎血管の一部などで働くが、汗腺の伝達物質ではない。", "D": "消化管や中枢で働くが、汗腺の伝達物質ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '心室筋のプラトー相', 2, 'CBT', '心室筋の活動電位は、神経の活動電位と異なり、脱分極が長く続くプラトー相をもつ。プラトー相（第2相）を形成する主なイオンの動きはどれか。', '[{"key": "A", "text": "L型カルシウムチャネルを通るカルシウムイオンの流入"}, {"key": "B", "text": "電位依存性の速いナトリウムチャネルを通るナトリウムイオンの流入"}, {"key": "C", "text": "カリウムイオンの流出だけ"}, {"key": "D", "text": "塩化物イオンの大量の流入"}, {"key": "E", "text": "過分極で活性化される陽イオン電流"}]'::jsonb, 'A', '心室筋の活動電位は、第0相でナトリウムイオンが急速に流入して脱分極し、第1相で一過性に再分極したあと、第2相でL型カルシウムチャネルからのカルシウムイオンの流入とカリウムイオンの流出が釣り合ってプラトーをつくる。流入したカルシウムイオンは筋小胞体からの放出を誘発して収縮を起こす。プラトーのため不応期が長く、心筋は強縮を起こさない。', '{"B": "急速な脱分極（第0相）を形成するイオンの動きである。", "C": "プラトー相でもカリウムイオンは流出するが、カルシウムイオンの流入と釣り合って電位が保たれる。", "D": "プラトー相を形成する主な動きではない。", "E": "洞房結節などの歩調取り細胞の緩徐脱分極に関わる電流である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '洞房結節の自動能', 2, 'CBT', '洞房結節の細胞は安定した静止膜電位をもたず、拡張期にゆっくり脱分極して自発的に興奮する。この拡張期緩徐脱分極（第4相）に関わる電流はどれか。', '[{"key": "A", "text": "ナトリウムポンプによる外向き電流"}, {"key": "B", "text": "過分極で活性化される陽イオン電流（If）"}, {"key": "C", "text": "速いナトリウムチャネルを通る内向き電流"}, {"key": "D", "text": "遅延整流カリウム電流"}, {"key": "E", "text": "塩化物イオンの外向きの電流"}]'::jsonb, 'B', '洞房結節の細胞では、再分極して膜電位が深くなるとHCNチャネルが開き、ナトリウムイオンを主とする陽イオンが流入する（If、ファニー電流）。これに続いてT型・L型カルシウムチャネルが開いて活動電位が生じる。交感神経はIfを増やして心拍数を上げ、迷走神経はアセチルコリンでカリウムチャネルを開いて心拍数を下げる。イバブラジンはIfを抑えて心拍数を下げる。', '{"A": "緩徐脱分極を担う電流ではない。", "C": "洞房結節の細胞ではほとんど働かない。", "D": "再分極を担う外向きの電流である。", "E": "緩徐脱分極を担う電流ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'QRS波', 2, 'CBT', '心電図の各波は、心臓の各部位の電気的な興奮と回復を反映している。心電図のQRS波が主に反映する電気現象はどれか。', '[{"key": "A", "text": "房室結節での伝導の遅れ"}, {"key": "B", "text": "洞房結節の自発的な興奮"}, {"key": "C", "text": "心室の脱分極"}, {"key": "D", "text": "心房の脱分極"}, {"key": "E", "text": "心室の再分極"}]'::jsonb, 'C', 'P波は心房の脱分極、QRS波は心室の脱分極、T波は心室の再分極を表す。心房の再分極はQRS波に重なって見えない。PQ間隔は心房から心室への伝導時間で、主に房室結節の遅れを反映する。脚ブロックや心室性期外収縮では、心室内の伝導が遅れてQRS幅が広くなる。', '{"A": "PQ部分（PR間隔の平坦な部分）に反映され、波としては現れない。", "B": "洞房結節の興奮は小さく、体表の心電図には波として現れない。", "D": "P波が反映する。", "E": "T波が反映する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'Frank-Starlingの法則', 2, 'CBT', '臥位で下肢を挙上すると静脈還流が増え、左室の拡張末期容積が増える。健常な心臓でこのとき生じる変化として正しいのはどれか。', '[{"key": "A", "text": "交感神経の興奮によってのみ一回拍出量が増加する"}, {"key": "B", "text": "大動脈圧が下がり、後負荷が低下する"}, {"key": "C", "text": "一回拍出量は変わらず、心拍数だけが増加する"}, {"key": "D", "text": "心筋の伸展により収縮力が増し、一回拍出量が増える"}, {"key": "E", "text": "心筋が引き伸ばされて収縮力が落ち、一回拍出量が減少する"}]'::jsonb, 'D', 'Frank-Starlingの法則は、拡張末期の心筋線維の長さ（前負荷）が大きいほど収縮力が増して一回拍出量が増えるという心筋固有の性質である。サルコメアの長さが至適に近づき、アクチンとミオシンの重なりやカルシウム感受性が増すためである。これにより左右の心室の拍出量が自動的にそろう。心不全では曲線が下方に移り、前負荷を増やしても拍出量が増えにくい。', '{"A": "神経を介さない心筋自体の性質で拍出量が増える。", "B": "拡張末期容積の増加は前負荷の増加である。", "C": "一回拍出量が増加するのがこの法則の要点である。", "E": "健常な心臓の生理的な範囲では、伸展により収縮力は増す。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '後負荷', 2, 'CBT', '心臓のポンプ機能は、前負荷、後負荷、心筋収縮力、心拍数によって決まる。左室の後負荷を主に規定するものはどれか。', '[{"key": "A", "text": "静脈還流量"}, {"key": "B", "text": "左室の拡張末期容積"}, {"key": "C", "text": "心拍数"}, {"key": "D", "text": "心房の収縮力"}, {"key": "E", "text": "大動脈圧（体血管抵抗）"}]'::jsonb, 'E', '後負荷は心室が血液を駆出するときに打ち勝たなければならない負荷で、左室では主に大動脈圧と体血管抵抗で決まる。高血圧や大動脈弁狭窄症では後負荷が増え、左室は求心性に肥大する。血管拡張薬は後負荷を減らして一回拍出量を増やし、心筋の酸素消費を減らす。前負荷は拡張末期の心室の容積や圧で表される。', '{"A": "前負荷を規定する。", "B": "前負荷の指標である。", "C": "心拍出量を規定する要素だが、後負荷そのものではない。", "D": "心室の充満を助け、前負荷に関わる。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '駆出率の計算', 2, 'CBT', '心エコー検査で、左室の拡張末期容積が120mL、収縮末期容積が50mLであった。この左室の駆出率に最も近いのはどれか。', '[{"key": "A", "text": "58%"}, {"key": "B", "text": "42%"}, {"key": "C", "text": "70%"}, {"key": "D", "text": "71%"}, {"key": "E", "text": "140%"}]'::jsonb, 'A', '一回拍出量は拡張末期容積から収縮末期容積を引いた値で、120−50＝70mLとなる。駆出率は一回拍出量を拡張末期容積で割った値で、70÷120≒0.58、すなわち約58%である。左室駆出率の正常値はおよそ55%以上で、心不全は駆出率が低下したものと保たれたものに分けて治療を考える。', '{"B": "収縮末期容積を拡張末期容積で割った値である。", "C": "一回拍出量（mL）の値を百分率と取り違えた値である。", "D": "収縮末期容積を一回拍出量で割った値である。", "E": "一回拍出量を収縮末期容積で割った値である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '冠血流の時相', 2, 'CBT', '左室の心筋を灌流する冠動脈の血流は、心周期によって大きく変動する。左冠動脈の血流が主に流れる時相はどれか。', '[{"key": "A", "text": "収縮期と拡張期で差はない"}, {"key": "B", "text": "拡張期"}, {"key": "C", "text": "収縮期"}, {"key": "D", "text": "等容性収縮期"}, {"key": "E", "text": "急速駆出期"}]'::jsonb, 'B', '左室の心筋は収縮期に壁内の血管を強く圧迫するため、左冠動脈の血流は主に拡張期に流れる。頻脈では拡張期が短くなって冠血流が減り、酸素需要は増えるため、虚血が起こりやすい。心内膜側は圧迫を強く受けるため虚血に弱い。右室は壁が薄く、収縮期にも比較的血流が保たれる。', '{"A": "左冠動脈の血流は時相によって大きく異なる。", "C": "心筋の収縮で壁内の血管が圧迫され、血流は大きく減る。", "D": "心室の収縮が始まり壁内の血管が圧迫されるため、血流は少ない。", "E": "心室壁が強く収縮して血管を圧迫するため、血流は少ない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'I音の成因', 2, 'CBT', '心尖部を聴診すると、収縮期の始まりと終わりに2つの心音が聴取される。このうちI音の主な成因はどれか。', '[{"key": "A", "text": "拡張末期の心房の収縮"}, {"key": "B", "text": "狭窄した房室弁の開放"}, {"key": "C", "text": "房室弁の閉鎖"}, {"key": "D", "text": "大動脈弁と肺動脈弁の閉鎖"}, {"key": "E", "text": "拡張早期の心室への急速な流入"}]'::jsonb, 'C', 'I音は収縮期の始まりに僧帽弁と三尖弁が閉じる音で、心尖部でよく聴かれる。II音は収縮期の終わりに大動脈弁と肺動脈弁が閉じる音である。III音は拡張早期の急速な流入で心室壁が振動する音で、若年者では生理的だが、中高年では心不全などを示す。IV音は硬くなった心室へ心房が血液を押し込む音で、肥大心などで聴かれる。', '{"A": "IV音の成因である。", "B": "僧帽弁狭窄症でII音の後に聴かれる開放音の成因である。", "D": "II音の成因である。", "E": "III音の成因である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'II音の呼吸性分裂', 2, 'CBT', '健常な若年者の胸骨左縁上部を聴診すると、吸気時にII音が2つに分かれて聴こえる。吸気時にII音の分裂が大きくなる主な理由はどれか。', '[{"key": "A", "text": "吸気時に僧帽弁の閉鎖が遅れるから"}, {"key": "B", "text": "吸気時に心房の収縮が強まるから"}, {"key": "C", "text": "吸気時に右室への流入が減るから"}, {"key": "D", "text": "右室の駆出が延び、肺動脈弁の閉鎖が遅れるから"}, {"key": "E", "text": "大動脈弁の閉鎖が吸気時に早まり、肺動脈弁より先に閉じるから"}]'::jsonb, 'D', '吸気で胸腔内圧が下がると右心系への静脈還流が増え、右室の駆出時間が延びて肺動脈弁の閉鎖（IIp）が遅れる。同時に肺の血管床が広がって左心系への還流が一時的に減り、大動脈弁の閉鎖（IIa）はやや早まる。その結果、吸気時に分裂が大きくなる。心房中隔欠損症では呼吸に関係なく分裂が続く（固定性分裂）。', '{"A": "僧帽弁はI音に関わり、II音の分裂とは関係しない。", "B": "心房の収縮はII音の分裂の原因ではない。", "C": "吸気で胸腔内圧が下がると右心系への還流は増える。", "E": "大動脈弁も多少早まるが、主な理由は肺動脈弁の閉鎖の遅れである。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '血管抵抗と血管の半径', 2, 'CBT', '動脈硬化や血管の収縮で血管が細くなると、血流の抵抗は大きく変化する。Poiseuilleの法則に従うとき、血管の半径が1/2になると血流抵抗はもとの何倍になるか。', '[{"key": "A", "text": "2倍"}, {"key": "B", "text": "4倍"}, {"key": "C", "text": "8倍"}, {"key": "D", "text": "1/16倍"}, {"key": "E", "text": "16倍"}]'::jsonb, 'E', 'Poiseuilleの法則では、血流抵抗は血液の粘度と血管の長さに比例し、半径の4乗に反比例する。半径が1/2になると抵抗は2の4乗で16倍となる。細動脈のわずかな収縮や拡張が血圧や臓器血流を大きく変えるのはこのためで、細動脈は抵抗血管とよばれる。貧血では粘度が下がり、抵抗は減る。', '{"A": "抵抗が半径に反比例すると考えた場合の値である。", "B": "抵抗が半径の2乗に反比例すると考えた場合の値である。", "C": "抵抗が半径の3乗に反比例すると考えた場合の値である。", "D": "抵抗と半径の関係を逆にとらえた値である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '静脈還流', 2, 'CBT', '立位では、下肢の静脈血は重力に逆らって心臓へ戻らなければならない。下肢の静脈血の還流を助ける仕組みとして正しいのはどれか。', '[{"key": "A", "text": "骨格筋の収縮と静脈弁による筋ポンプ"}, {"key": "B", "text": "動脈の拍動が静脈血を直接押し上げる働き"}, {"key": "C", "text": "呼気時の胸腔内圧の上昇による吸い上げ"}, {"key": "D", "text": "静脈の平滑筋による蠕動運動"}, {"key": "E", "text": "重力による下方への血液の移動"}]'::jsonb, 'A', '下肢の深部静脈は筋に囲まれ、筋が収縮するたびに圧迫されて血液が押し出され、静脈弁が逆流を防ぐ（筋ポンプ）。吸気時の胸腔内圧の低下も静脈還流を助ける（呼吸ポンプ）。長時間の座位や臥床で筋ポンプが働かないと静脈のうっ滞が起こり、深部静脈血栓症の危険が高まる。静脈弁の機能不全は下肢静脈瘤の原因となる。', '{"B": "隣接する動脈の拍動の影響はわずかで、主な仕組みではない。", "C": "静脈還流は吸気時の胸腔内圧の低下で促進される。", "D": "静脈は蠕動運動で血液を送り出すことはない。", "E": "重力は下肢に血液をためる方向に働く。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '膠質浸透圧', 2, 'CBT', '血漿の膠質浸透圧は、毛細血管から組織へ水分が漏れ出るのを防ぐ方向に働く。血漿の膠質浸透圧を主に形成している成分はどれか。', '[{"key": "A", "text": "ブドウ糖"}, {"key": "B", "text": "アルブミン"}, {"key": "C", "text": "γ-グロブリン"}, {"key": "D", "text": "フィブリノゲン"}, {"key": "E", "text": "ナトリウムイオン"}]'::jsonb, 'B', '毛細血管壁は水や電解質、ブドウ糖を通すが蛋白質はほとんど通さないため、血漿蛋白が膠質浸透圧をつくる。その大部分は分子数が多いアルブミンによる。ネフローゼ症候群や肝硬変、低栄養で低アルブミン血症になると膠質浸透圧が下がり、浮腫や胸水、腹水が生じる。', '{"A": "毛細血管壁を自由に通過するため、膠質浸透圧はつくらない。", "C": "量が少なく、分子も大きいため膠質浸透圧への寄与はアルブミンより小さい。", "D": "凝固因子で、膠質浸透圧への寄与は小さい。", "E": "毛細血管壁を自由に通過するため、膠質浸透圧はつくらない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'エンドセリン', 2, 'CBT', '血管内皮細胞は、血管を拡張させる物質と収縮させる物質の両方を産生して血管の緊張を調節する。血管内皮細胞が産生し、強力な血管収縮作用をもつペプチドはどれか。', '[{"key": "A", "text": "ブラジキニン"}, {"key": "B", "text": "心房性ナトリウム利尿ペプチド"}, {"key": "C", "text": "エンドセリン"}, {"key": "D", "text": "一酸化窒素"}, {"key": "E", "text": "プロスタサイクリン"}]'::jsonb, 'C', 'エンドセリン1は血管内皮細胞が産生する21個のアミノ酸からなるペプチドで、既知の物質の中で最も強力な部類の血管収縮作用をもつ。肺動脈性肺高血圧症ではエンドセリン系が亢進しており、エンドセリン受容体拮抗薬が治療に用いられる。内皮は一酸化窒素やプロスタサイクリンも産生し、収縮と拡張の均衡を保っている。', '{"A": "血管を拡張させ、透過性を高めるペプチドである。", "B": "心房から分泌され、血管拡張とナトリウム利尿に働く。", "D": "血管内皮が産生する血管拡張物質で、ペプチドではない。", "E": "血管内皮が産生し、血管拡張と血小板凝集の抑制に働く。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '脳性ナトリウム利尿ペプチド', 2, 'CBT', '息切れと下腿浮腫で受診した患者で、心不全の診断と重症度の評価のために血液検査を行う。心室の壁応力の増大に応じて主に心室から分泌され、心不全で上昇するペプチドはどれか。', '[{"key": "A", "text": "アルドステロン"}, {"key": "B", "text": "レニン"}, {"key": "C", "text": "バソプレシン"}, {"key": "D", "text": "脳性ナトリウム利尿ペプチド（BNP）"}, {"key": "E", "text": "心房性ナトリウム利尿ペプチド（ANP）"}]'::jsonb, 'D', 'BNPは主に心室の心筋細胞が、壁の伸展や圧負荷に応じて分泌する。前駆体が切断されてBNPとNT-proBNPが同量ずつ放出され、どちらも心不全の診断や重症度、治療効果の評価に用いられる。ナトリウム利尿と血管拡張によってレニン-アンジオテンシン-アルドステロン系に拮抗する。腎機能が低下すると値が高めに出る。', '{"A": "副腎皮質球状層から分泌されるステロイドホルモンである。", "B": "腎の傍糸球体細胞から分泌される酵素である。", "C": "下垂体後葉から分泌されるホルモンである。", "E": "主に心房から分泌される。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '運動時の筋血流', 2, 'CBT', '激しい運動中の骨格筋では、血流が安静時の十数倍にまで増える。運動中の骨格筋の血流増加に最も大きく関わる因子はどれか。', '[{"key": "A", "text": "交感神経のα受容体を介する血管収縮"}, {"key": "B", "text": "バソプレシンの分泌増加"}, {"key": "C", "text": "アンジオテンシンIIの増加"}, {"key": "D", "text": "エンドセリンの分泌増加"}, {"key": "E", "text": "代謝産物による局所の血管拡張"}]'::jsonb, 'E', '運動中の筋では、アデノシン、二酸化炭素、水素イオン、カリウムイオン、乳酸などの代謝産物がたまり、低酸素とともに細動脈を拡張させる（代謝性調節）。この局所の拡張が交感神経による収縮に打ち勝ち、需要に見合った血流が確保される。一方、腎臓や消化管などでは交感神経の働きで血管が収縮し、血流が筋へ振り分けられる。', '{"A": "血管を収縮させる方向に働く。", "B": "血管を収縮させ、水の再吸収を促すホルモンである。", "C": "血管を収縮させる方向に働く。", "D": "血管を収縮させる方向に働く。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '脳血流と二酸化炭素', 2, 'CBT', '脳血流は平均血圧が一定の範囲で変動しても、ほぼ一定に保たれる（自動調節能）。生理的な範囲の変動で、脳血流を最も強く変化させる因子はどれか。', '[{"key": "A", "text": "動脈血の二酸化炭素分圧"}, {"key": "B", "text": "動脈血の酸素分圧"}, {"key": "C", "text": "平均血圧"}, {"key": "D", "text": "交感神経の活動"}, {"key": "E", "text": "血糖値"}]'::jsonb, 'A', '二酸化炭素分圧が上がると脳の細動脈が拡張し、下がると収縮する。過換気で二酸化炭素分圧が下がると脳血流が減るため、頭蓋内圧亢進の急場しのぎに過換気が使われることがあるが、脳虚血の危険があり長くは続けない。平均血圧がおよそ60〜150mmHgの範囲では自動調節能により脳血流は一定だが、慢性の高血圧ではこの範囲が高い方へずれる。', '{"B": "大きく低下したとき（おおよそ50mmHg未満）に初めて脳血流を増やす。", "C": "自動調節の範囲内では脳血流はほぼ一定に保たれる。", "D": "脳血管への影響は比較的小さい。", "E": "脳血流を直接大きく変える因子ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '房室結節の伝導遅延', 2, 'CBT', '洞房結節で生じた興奮は心房を通り、房室結節を経て心室へ伝わる。房室結節で伝導が遅くなることの生理的な意義として正しいのはどれか。', '[{"key": "A", "text": "心室内の興奮の伝わりを遅くして不整脈を防ぐ"}, {"key": "B", "text": "心房の収縮後に心室を収縮させる"}, {"key": "C", "text": "心室の興奮を心房へ逆向きに伝えやすくする"}, {"key": "D", "text": "心室の収縮時間を長くして拍出量を増やす"}, {"key": "E", "text": "洞房結節の自動能を高める"}]'::jsonb, 'B', '房室結節は伝導速度が遅く、心房から心室への興奮の伝わりを約0.1秒遅らせる。そのため心房の収縮で心室への充満が完了してから心室が収縮できる。また心房細動のように心房が高頻度で興奮しても、房室結節が一部しか伝えないため、心室の拍動数は抑えられる。His束とPurkinje線維は伝導が速く、心室全体をほぼ同時に興奮させる。', '{"A": "心室内はPurkinje線維で速く伝わり、同期して収縮する。", "C": "逆向きの伝導は生理的な意義ではない。", "D": "心室の収縮時間を決める仕組みではない。", "E": "房室結節の遅れは洞房結節の自動能を高めない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '迷走神経の心臓への作用', 2, 'CBT', '頸動脈洞マッサージや息ごらえで迷走神経の緊張が高まると、心臓の働きが変化する。迷走神経刺激による心臓への作用として正しいのはどれか。', '[{"key": "A", "text": "房室伝導が速くなり、PQ間隔が短縮する"}, {"key": "B", "text": "β1受容体を介して作用する"}, {"key": "C", "text": "心拍数が減り、房室伝導が遅くなる"}, {"key": "D", "text": "心室筋の収縮力が大きく増強する"}, {"key": "E", "text": "洞房結節の自動能が高まり、心拍数が増加する"}]'::jsonb, 'C', '迷走神経末端から放出されたアセチルコリンは、M2受容体（Gi）を介してアデニル酸シクラーゼを抑え、カリウムチャネルを開いて洞房結節の拡張期脱分極を遅くし、房室結節の伝導を遅らせる。迷走神経は主に心房と刺激伝導系に分布し、心室筋への直接の作用は小さい。発作性上室頻拍の停止に迷走神経刺激法が使われる。', '{"A": "交感神経の作用である。", "B": "迷走神経はアセチルコリンでムスカリンM2受容体を介して作用する。", "D": "心室筋の収縮力を高めるのは交感神経である。", "E": "交感神経の作用である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '心筋の興奮収縮連関', 2, 'CBT', '心筋も骨格筋も、細胞内カルシウムイオン濃度の上昇で収縮するが、その引き金の仕組みが異なる。心筋細胞で収縮が起こる仕組みとして正しいのはどれか。', '[{"key": "A", "text": "細胞膜の受容体と筋小胞体のチャネルが機械的に連結して放出が起こる"}, {"key": "B", "text": "カルシウムイオンがミオシンに直接結合して収縮が始まる"}, {"key": "C", "text": "ナトリウムイオンの流入だけで収縮が起こる"}, {"key": "D", "text": "流入したカルシウムイオンが筋小胞体からの放出を誘発する"}, {"key": "E", "text": "細胞外のカルシウムイオンにまったく依存せずに収縮する"}]'::jsonb, 'D', '心筋では活動電位のプラトー相にL型カルシウムチャネルから少量のカルシウムイオンが流入し、これが筋小胞体のリアノジン受容体を開いて大量のカルシウムイオンを放出させる（カルシウム誘発性カルシウム放出）。骨格筋では細胞膜の電位センサーとリアノジン受容体が機械的に連結しており、細胞外のカルシウムイオンがなくても収縮できる。カルシウム拮抗薬が心筋の収縮力を下げるのはこのためである。', '{"A": "骨格筋で主にみられる仕組みである。", "B": "カルシウムイオンはトロポニンCに結合して収縮を起こす。", "C": "収縮の引き金はカルシウムイオン濃度の上昇である。", "E": "心筋の収縮は細胞外からのカルシウムイオン流入に依存する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '心筋酸素消費量', 2, 'CBT', '狭心症の患者では、心筋の酸素需要が冠血流による供給を上回ると胸痛が生じる。心筋の酸素消費量を増やす因子はどれか。', '[{"key": "A", "text": "心拍数の減少"}, {"key": "B", "text": "後負荷の低下"}, {"key": "C", "text": "前負荷の低下"}, {"key": "D", "text": "心筋収縮力の低下"}, {"key": "E", "text": "心拍数の増加"}]'::jsonb, 'E', '心筋の酸素消費量は主に心拍数、心筋収縮力、心室の壁応力（前負荷と後負荷）で決まる。臨床では心拍数と収縮期血圧の積（二重積）が目安となる。β遮断薬は心拍数と収縮力を抑え、硝酸薬は主に静脈を拡張して前負荷を減らすことで、心筋の酸素需要を下げて狭心症を改善する。', '{"A": "心筋の酸素消費量を減らす。", "B": "壁応力が減るため、酸素消費量は減る。", "C": "心室の容積と壁応力が減るため、酸素消費量は減る。", "D": "酸素消費量を減らす方向に働く。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '肺サーファクタント', 2, 'CBT', '在胎28週で出生した児が、生後まもなく多呼吸と陥没呼吸をきたし、胸部エックス線写真で両肺のすりガラス状の陰影を認めた。この病態で不足している物質を産生する細胞はどれか。', '[{"key": "A", "text": "II型肺胞上皮細胞"}, {"key": "B", "text": "I型肺胞上皮細胞"}, {"key": "C", "text": "肺胞マクロファージ"}, {"key": "D", "text": "気管支の杯細胞"}, {"key": "E", "text": "気管支の線毛細胞"}]'::jsonb, 'A', '肺サーファクタントはII型肺胞上皮細胞が産生するリン脂質（主にジパルミトイルホスファチジルコリン）と蛋白質の複合体で、肺胞の表面張力を下げて呼気時に小さな肺胞がつぶれるのを防ぐ。産生は妊娠後期に増えるため、早産児では不足して新生児呼吸窮迫症候群となる。早産が予想されるときは母体に副腎皮質ステロイドを投与して肺の成熟を促し、出生後にはサーファクタントを気管内に投与する。', '{"B": "薄く広がって肺胞の表面の大部分を覆い、ガス交換の場となる。", "C": "肺胞内の異物や古くなったサーファクタントを処理する。", "D": "粘液を分泌する細胞で、サーファクタントは産生しない。", "E": "線毛運動で粘液を運ぶ細胞で、サーファクタントは産生しない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '肺コンプライアンス', 2, 'CBT', '肺コンプライアンスは、一定の圧の変化でどれだけ肺の容積が変わるかを示す、肺の膨らみやすさの指標である。肺コンプライアンスが低下する病態はどれか。', '[{"key": "A", "text": "慢性気管支炎"}, {"key": "B", "text": "特発性肺線維症"}, {"key": "C", "text": "肺気腫"}, {"key": "D", "text": "気管支喘息の発作"}, {"key": "E", "text": "加齢による肺の変化"}]'::jsonb, 'B', '肺線維症では間質に線維が増えて肺が硬くなり、コンプライアンスが低下する。膨らませるのに大きな力が要るため、浅く速い呼吸となり、肺活量や全肺気量が減る拘束性障害を示す。肺気腫では肺胞壁が壊れて弾性収縮力が失われ、コンプライアンスは上がるが、呼気時に気道がつぶれやすく閉塞性障害となる。サーファクタントの欠乏もコンプライアンスを下げる。', '{"A": "主に気道の病変で、肺のコンプライアンス低下が主体ではない。", "C": "肺胞壁の破壊で弾性収縮力が失われ、コンプライアンスはむしろ上昇する。", "D": "主に気道抵抗が上昇する病態で、肺実質のコンプライアンス低下が主体ではない。", "E": "弾性線維の変化で弾性収縮力が落ち、コンプライアンスはやや上昇する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '気道抵抗の主な部位', 2, 'CBT', '気道は分岐を繰り返すごとに1本1本は細くなるが、本数が急増する。健常者の気道で、気道抵抗が最も大きい部位はどれか。', '[{"key": "A", "text": "肺胞管"}, {"key": "B", "text": "肺胞"}, {"key": "C", "text": "中等大の気管支"}, {"key": "D", "text": "終末細気管支"}, {"key": "E", "text": "呼吸細気管支"}]'::jsonb, 'C', '気道抵抗の大部分は、区域気管支前後までの中等大の気管支で生じる。末梢の細い気道は並列に多数あり、総断面積が大きいため抵抗への寄与は小さい。そのため末梢気道の病変は抵抗の測定では気づかれにくく、「静かな領域」とよばれる。喘息では気管支平滑筋の収縮と炎症で気道が狭くなり、抵抗が大きく上がる。', '{"A": "総断面積が大きく、気流は遅く抵抗は小さい。", "B": "ガス交換の場で、気道抵抗にはほとんど寄与しない。", "D": "1本は細いが本数が非常に多く、並列の総断面積が大きいため抵抗は小さい。", "E": "総断面積がさらに大きく、抵抗は小さい。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '肺胞換気量の計算', 2, 'CBT', '安静時の健常成人で、一回換気量500mL、呼吸数12/分、解剖学的死腔量150mLであった。このときの肺胞換気量に最も近いのはどれか。', '[{"key": "A", "text": "1.8L/分"}, {"key": "B", "text": "7.8L/分"}, {"key": "C", "text": "0.35L/分"}, {"key": "D", "text": "4.2L/分"}, {"key": "E", "text": "6.0L/分"}]'::jsonb, 'D', '吸い込んだ空気のうち、気道にとどまってガス交換に関わらない部分が死腔である。肺胞換気量は（一回換気量−死腔量）×呼吸数で、（500−150）×12＝4,200mL/分となる。同じ分時換気量でも、浅く速い呼吸では死腔の割合が増えて肺胞換気量が減る。動脈血二酸化炭素分圧は肺胞換気量に反比例する。', '{"A": "死腔量に呼吸数をかけた死腔換気量である。", "B": "一回換気量に死腔量を足してから呼吸数をかけた、根拠のない値である。", "C": "1回の呼吸で肺胞に届く量（L）で、1分あたりの量ではない。", "E": "一回換気量に呼吸数をかけた分時換気量である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '換気血流比の部位差', 2, 'CBT', '立位では、重力のために肺の上下で換気と血流の分布が異なる。立位の健常者で換気血流比が最も高いのはどこか。', '[{"key": "A", "text": "肺底部"}, {"key": "B", "text": "肺門部"}, {"key": "C", "text": "右肺の中葉"}, {"key": "D", "text": "肺のどの部位でも等しい"}, {"key": "E", "text": "肺尖部"}]'::jsonb, 'E', '立位では換気も血流も肺底部で多いが、血流のほうが重力の影響を強く受けるため、換気血流比は肺尖部で高く（約3）、肺底部で低い（約0.6）。肺尖部は酸素分圧が高く血流が少ないため、結核菌が増殖しやすく、成人の二次結核が肺尖部に好発する一因とされる。', '{"A": "換気も血流も多いが、血流の増え方が大きく、換気血流比は低い。", "B": "換気血流比が最も高い部位ではない。", "C": "換気血流比が最も高い部位ではない。", "D": "立位では重力の影響で上下に差がある。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '低酸素性肺血管収縮', 2, 'CBT', '肺炎などで一部の肺胞の換気が低下すると、その領域の肺動脈に特有の反応が起こる。肺胞の酸素分圧が低下した領域の肺動脈に生じる反応として正しいのはどれか。', '[{"key": "A", "text": "収縮して、血流を換気のよい領域へ振り分ける"}, {"key": "B", "text": "拡張して、その領域の血流を増やす"}, {"key": "C", "text": "変化せず、その領域の血流はそのまま保たれる"}, {"key": "D", "text": "気管支が収縮して換気がさらに減る"}, {"key": "E", "text": "肺静脈だけが拡張して血流が増える"}]'::jsonb, 'A', '肺胞の酸素分圧が下がると、その領域の小肺動脈が収縮して血流を換気のよい領域に回し、換気血流比の不均衡を小さくする（低酸素性肺血管収縮）。体循環の血管が低酸素で拡張するのとは逆である。高地や慢性閉塞性肺疾患のように肺全体が低酸素になると、広範な収縮によって肺高血圧をきたし、右心不全（肺性心）の原因となる。胎児期の肺の血流が少ないのもこの反応による。', '{"B": "体循環の血管は低酸素で拡張するが、肺の血管は逆に収縮する。", "C": "低酸素を感知して収縮する反応がある。", "D": "低酸素に対する肺動脈の反応ではない。", "E": "主に反応するのは小肺動脈である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '中枢化学受容器', 2, 'CBT', '呼吸は、血液のガスの状態を感知する化学受容器からの情報によって調節されている。延髄の中枢化学受容器が主に感知しているものはどれか。', '[{"key": "A", "text": "肺の伸展の程度"}, {"key": "B", "text": "脳脊髄液の水素イオン濃度"}, {"key": "C", "text": "動脈血の酸素分圧"}, {"key": "D", "text": "動脈血圧"}, {"key": "E", "text": "血中のカリウムイオン濃度"}]'::jsonb, 'B', '動脈血の二酸化炭素は血液脳関門を容易に通過して脳脊髄液に入り、水素イオンを生じる。延髄腹側の中枢化学受容器はこの水素イオン濃度の変化を感知し、換気を調節する。安静時の換気の調節の大部分はこの経路による。水素イオンそのものは血液脳関門を通りにくいため、代謝性アシドーシスへの反応は主に末梢化学受容器が担う。', '{"A": "気道平滑筋の伸展受容器が感知し、迷走神経を介して吸気を止める（Hering-Breuer反射）。", "C": "主に頸動脈小体などの末梢化学受容器が感知する。", "D": "頸動脈洞や大動脈弓の圧受容器が感知する。", "E": "呼吸調節の主な入力ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '頸動脈小体の求心路', 2, 'CBT', '頸動脈小体は、動脈血の酸素分圧の低下に鋭敏に反応して換気を増やす末梢化学受容器である。頸動脈小体からの情報を延髄へ伝える神経はどれか。', '[{"key": "A", "text": "顔面神経"}, {"key": "B", "text": "副神経"}, {"key": "C", "text": "舌咽神経"}, {"key": "D", "text": "迷走神経"}, {"key": "E", "text": "横隔神経"}]'::jsonb, 'C', '頸動脈小体は総頸動脈の分岐部にあり、動脈血の酸素分圧の低下、二酸化炭素分圧の上昇、pHの低下を感知する。情報は舌咽神経（頸動脈洞神経）を経て延髄の孤束核に伝わる。大動脈小体は迷走神経を介する。酸素分圧がおよそ60mmHgを下回ると換気の増加が急に大きくなる。', '{"A": "表情筋の運動や味覚などを担い、化学受容器の情報は伝えない。", "B": "胸鎖乳突筋と僧帽筋を支配する運動神経である。", "D": "大動脈小体からの情報を伝えるが、頸動脈小体の求心路ではない。", "E": "横隔膜を支配する運動神経である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '二酸化炭素の運搬', 2, 'CBT', '組織で産生された二酸化炭素は、血液によって肺へ運ばれて排出される。血液中の二酸化炭素が運ばれる形として最も多いものはどれか。', '[{"key": "A", "text": "ヘモグロビンのアミノ基と結合したカルバミノ化合物"}, {"key": "B", "text": "ヘモグロビンのヘム鉄に結合した二酸化炭素"}, {"key": "C", "text": "解離していない炭酸"}, {"key": "D", "text": "重炭酸イオン"}, {"key": "E", "text": "血漿に物理的に溶解した二酸化炭素"}]'::jsonb, 'D', '二酸化炭素は赤血球の中で炭酸脱水酵素により水と反応して炭酸となり、ただちに水素イオンと重炭酸イオンに解離する。重炭酸イオンは塩化物イオンとの交換で血漿へ出て運ばれる（塩素移動）。水素イオンはヘモグロビンが緩衝する。全体の約7割が重炭酸イオン、約2割がカルバミノ化合物、約1割が溶解した二酸化炭素として運ばれる。', '{"A": "全体の1〜2割程度である。", "B": "二酸化炭素はヘム鉄には結合しない。", "C": "炭酸はすぐに解離し、この形ではほとんど運ばれない。", "E": "溶解した二酸化炭素は全体の1割程度である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '胎児ヘモグロビン', 2, 'CBT', '胎児は、母体より低い酸素分圧の環境で胎盤から酸素を受け取っている。胎児ヘモグロビン（HbF）の酸素親和性が成人ヘモグロビンより高い理由として正しいのはどれか。', '[{"key": "A", "text": "ヘム鉄が3価の状態にあるから"}, {"key": "B", "text": "α鎖をもたず、β鎖だけからなるから"}, {"key": "C", "text": "胎児の血液のpHが常に高いから"}, {"key": "D", "text": "ヘモグロビンの濃度が低いから"}, {"key": "E", "text": "2,3-BPGと結合しにくいから"}]'::jsonb, 'E', 'HbFはα2γ2の四量体で、γ鎖は2,3-ビスホスホグリセリン酸（2,3-BPG）との結合が弱い。2,3-BPGはヘモグロビンの酸素親和性を下げる物質なので、その作用を受けにくいHbFは酸素解離曲線が左にずれ、胎盤で母体の血液から酸素を受け取りやすい。HbFは生後に成人型（α2β2）へ置き換わる。HbFを多く残すことは鎌状赤血球症の症状を軽くする。', '{"A": "3価鉄のヘモグロビン（メトヘモグロビン）は酸素を結合できない。", "B": "HbFはα鎖2本とγ鎖2本からなる。", "C": "胎児の血液のpHはむしろやや低い。", "D": "濃度は親和性を決める要因ではなく、胎児ではむしろ高い。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '一酸化炭素中毒', 2, 'CBT', '換気の悪い室内で練炭を使っていた人が、頭痛と意識障害で搬送された。一酸化炭素中毒で組織が低酸素になる機序として正しいのはどれか。', '[{"key": "A", "text": "ヘモグロビンに強く結合し、残った酸素も組織で離れにくくする"}, {"key": "B", "text": "肺胞から毛細血管へのガスの拡散を妨げて動脈血酸素分圧を大きく下げる"}, {"key": "C", "text": "電子伝達系の複合体IVを阻害し、酸素を利用できなくする"}, {"key": "D", "text": "ヘム鉄を3価に酸化してメトヘモグロビンをつくる"}, {"key": "E", "text": "呼吸中枢を直接抑制して換気を止める"}]'::jsonb, 'A', '一酸化炭素はヘモグロビンに酸素の200倍以上の親和性で結合し、酸素を運べるヘモグロビンを減らす。さらに酸素解離曲線を左に移し、残った酸素も組織で離れにくくする。動脈血酸素分圧は正常で、一般的なパルスオキシメータはカルボキシヘモグロビンを区別できず、酸素飽和度が見かけ上正常に出る。治療は高濃度酸素の投与で、重症では高気圧酸素療法を考慮する。', '{"B": "動脈血酸素分圧は通常ほぼ正常に保たれる。", "C": "主にシアン化物の機序である。", "D": "亜硝酸薬などによるメトヘモグロビン血症の機序である。", "E": "一酸化炭素中毒の主な機序ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '肺拡散能の低下', 2, 'CBT', '肺拡散能力（DLCO）は、肺胞から毛細血管の血液へのガスの移りやすさを示す。肺拡散能力が低下する疾患はどれか。', '[{"key": "A", "text": "気管の腫瘍による狭窄"}, {"key": "B", "text": "間質性肺炎"}, {"key": "C", "text": "気管支喘息"}, {"key": "D", "text": "肺胞出血"}, {"key": "E", "text": "多血症"}]'::jsonb, 'B', '拡散能力は、肺胞と毛細血管の間の膜の厚さ、ガス交換に使える面積、毛細血管の血液量やヘモグロビン量で決まり、一酸化炭素の取り込みで測定する。間質性肺炎では膜が厚くなり、肺気腫では肺胞が壊れて面積が減るため、いずれも低下する。貧血でも低下し、多血症や肺胞出血では高く出る。拡散障害は安静時より運動時の低酸素血症として現れやすい。', '{"A": "上気道の閉塞で、拡散能力は低下しない。", "C": "気道の疾患で、拡散能力は正常かむしろ高いことが多い。", "D": "肺胞内の赤血球が一酸化炭素を取り込むため、見かけ上高くなる。", "E": "ヘモグロビンが多いため、拡散能力は高くなる。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '安静吸気の主な筋', 2, 'CBT', '安静呼吸では吸気は筋の収縮で能動的に行われ、呼気は肺と胸郭の弾性で受動的に行われる。安静吸気の主な筋はどれか。', '[{"key": "A", "text": "胸鎖乳突筋"}, {"key": "B", "text": "大胸筋"}, {"key": "C", "text": "横隔膜"}, {"key": "D", "text": "内肋間筋"}, {"key": "E", "text": "腹直筋"}]'::jsonb, 'C', '横隔膜は収縮すると下がって胸腔を上下に広げ、安静時の吸気の大部分を担う。支配神経は第3〜5頸髄から出る横隔神経で、高位頸髄損傷では自発呼吸が保てなくなる。外肋間筋も吸気を助ける。努力性の吸気では胸鎖乳突筋や斜角筋が、努力性の呼気では内肋間筋や腹筋群が働く。', '{"A": "努力性の吸気で働く呼吸補助筋である。", "B": "上肢を固定したときに補助的に吸気を助けるが、主な筋ではない。", "D": "努力性の呼気で肋骨を引き下げる筋である。", "E": "努力性の呼気で腹圧を高めて横隔膜を押し上げる筋である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '胸腔内圧', 2, 'CBT', '胸膜腔は臓側胸膜と壁側胸膜の間のわずかな空間で、少量の胸水で満たされている。安静呼吸時の胸腔内圧について正しいのはどれか。', '[{"key": "A", "text": "呼気の終わりには大気圧より高くなる"}, {"key": "B", "text": "常に大気圧と等しい"}, {"key": "C", "text": "常に肺胞内圧と等しい"}, {"key": "D", "text": "吸気時も呼気時も大気圧より低い"}, {"key": "E", "text": "吸気時に大気圧より高くなる"}]'::jsonb, 'D', '肺は弾性で縮もうとし、胸郭は広がろうとするため、その間の胸膜腔は大気圧より低い陰圧（安静時におよそ-5〜-8cmH2O）に保たれる。吸気で胸郭が広がると陰圧が強まり、肺が膨らむ。胸膜腔に空気が入ると陰圧が失われて肺が虚脱し、気胸となる。一方弁のように空気がたまり続けると緊張性気胸となる。', '{"A": "安静呼気の終わりにも大気圧より低い。大気圧を上回るのは努力性の呼気のときである。", "B": "肺が縮もうとする力と胸郭が広がろうとする力が釣り合い、陰圧になっている。", "C": "両者の差が肺を膨らませる経肺圧となる。", "E": "吸気時には胸郭が広がり、胸腔内圧はさらに低くなる。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '肺胞気-動脈血酸素分圧較差', 2, 'CBT', '海面の高さで室内気を吸入している患者の動脈血ガス分析で、PaO2 60Torr、PaCO2 40Torrであった。肺胞気-動脈血酸素分圧較差（A-aDO2）に最も近いのはどれか。ただし呼吸商は0.8とする。', '[{"key": "A", "text": "10Torr"}, {"key": "B", "text": "90Torr"}, {"key": "C", "text": "100Torr"}, {"key": "D", "text": "50Torr"}, {"key": "E", "text": "40Torr"}]'::jsonb, 'E', '肺胞気の酸素分圧は、吸入気の酸素分圧（(760−47)×0.21≒150Torr）から、PaCO2を呼吸商で割った値を引いて求める。150−40÷0.8＝100Torrとなり、A-aDO2は100−60＝40Torrと開大している。A-aDO2が正常（10〜20Torr程度）のまま低酸素なら肺胞低換気を、開大していれば換気血流比の不均衡、シャント、拡散障害を考える。', '{"A": "健常な若年者でみられる程度の値で、この患者の値ではない。", "B": "吸入気の酸素分圧（約150Torr）からPaO2だけを引いた値である。", "C": "肺胞気の酸素分圧そのものの値である。", "D": "PaCO2を呼吸商で割らずに吸入気の酸素分圧から引いた場合の値である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '腹腔動脈の分枝', 2, 'CBT', '腹部大動脈からは、消化管に血液を送る3本の無対の動脈が分かれる。腹腔動脈から直接分かれる動脈はどれか。', '[{"key": "A", "text": "脾動脈"}, {"key": "B", "text": "上腸間膜動脈"}, {"key": "C", "text": "右結腸動脈"}, {"key": "D", "text": "下膵十二指腸動脈"}, {"key": "E", "text": "腎動脈"}]'::jsonb, 'A', '腹腔動脈は第12胸椎の高さで腹部大動脈から出て、左胃動脈、総肝動脈、脾動脈の3本に分かれ、前腸由来の臓器（食道下部から十二指腸下行部まで、肝臓、胆嚢、膵臓の一部、脾臓）に血液を送る。中腸由来の臓器は上腸間膜動脈、後腸由来の臓器は下腸間膜動脈が支配する。', '{"B": "腹腔動脈の少し下で腹部大動脈から直接分かれる。", "C": "上腸間膜動脈の枝である。", "D": "上腸間膜動脈の枝である。", "E": "腹部大動脈から左右に分かれる有対の動脈である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '上腸間膜動脈の灌流域', 2, 'CBT', '心房細動のある高齢者が突然の激しい腹痛を訴え、上腸間膜動脈の塞栓症と診断された。この血管の閉塞で虚血に陥る臓器はどれか。', '[{"key": "A", "text": "直腸"}, {"key": "B", "text": "回腸"}, {"key": "C", "text": "胃"}, {"key": "D", "text": "脾臓"}, {"key": "E", "text": "下行結腸"}]'::jsonb, 'B', '上腸間膜動脈は中腸由来の臓器、すなわち十二指腸の下部から空腸、回腸、盲腸、虫垂、上行結腸、横行結腸の右側約2/3までに血液を送る。塞栓症では腹部所見に乏しいわりに激しい腹痛を訴えるのが特徴で、発見が遅れると広範な腸管壊死に至る。下腸間膜動脈は横行結腸の左側から直腸上部までを支配する。', '{"A": "主に下腸間膜動脈の上直腸動脈と内腸骨動脈の枝から血液を受ける。", "C": "主に腹腔動脈の枝から血液を受ける。", "D": "腹腔動脈の枝である脾動脈から血液を受ける。", "E": "下腸間膜動脈から血液を受ける。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '食道静脈瘤の血行路', 2, 'CBT', '肝硬変で門脈圧が上がると、門脈系と体循環系の静脈の間の吻合路が発達する。食道静脈瘤の形成に関わる門脈側の静脈はどれか。', '[{"key": "A", "text": "下大静脈"}, {"key": "B", "text": "奇静脈"}, {"key": "C", "text": "左胃静脈"}, {"key": "D", "text": "上直腸静脈"}, {"key": "E", "text": "臍傍静脈"}]'::jsonb, 'C', '門脈圧が上がると、門脈系の左胃静脈（胃冠状静脈）から食道下部の静脈叢を経て奇静脈へ血液が流れ、食道静脈瘤が生じる。破裂すると大量に吐血し、致死的となりうる。ほかに臍傍静脈から腹壁の静脈（メズサの頭）、上直腸静脈から中・下直腸静脈、脾静脈から左腎静脈への短絡路が発達する。', '{"A": "体循環系の静脈で、門脈側の静脈ではない。", "B": "食道静脈の血液を受ける体循環系の静脈で、門脈側ではない。", "D": "中・下直腸静脈との吻合で直腸の静脈瘤に関わる。", "E": "腹壁の静脈との吻合でメズサの頭に関わる。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '胃の壁細胞', 2, 'CBT', '胃底腺は胃の体部と底部に多数あり、数種類の細胞が胃液の成分を分泌している。胃底腺の壁細胞が分泌するものはどれか。', '[{"key": "A", "text": "ガストリン"}, {"key": "B", "text": "ソマトスタチン"}, {"key": "C", "text": "ヒスタミン"}, {"key": "D", "text": "塩酸と内因子"}, {"key": "E", "text": "ペプシノゲン"}]'::jsonb, 'D', '壁細胞はプロトンポンプ（H+,K+-ATPase）で塩酸を分泌し、ビタミンB12の吸収に必要な内因子も分泌する。自己免疫性胃炎では壁細胞が破壊されて無酸症と内因子の欠乏をきたし、ビタミンB12欠乏による巨赤芽球性貧血（悪性貧血）となる。胃酸が減るとガストリンの分泌は代償的に増える。', '{"A": "主に胃の前庭部にあるG細胞が分泌するホルモンである。", "B": "D細胞が分泌し、酸分泌を抑えるホルモンである。", "C": "腸クロム親和性細胞様細胞（ECL細胞）が分泌する。", "E": "主細胞が分泌する蛋白分解酵素の前駆体である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'ヒスタミンによる酸分泌', 2, 'CBT', '胃酸の分泌は、神経、ホルモン、局所の化学伝達物質によって調節されている。腸クロム親和性細胞様細胞（ECL細胞）から放出され、壁細胞のH2受容体を介して酸分泌を促す物質はどれか。', '[{"key": "A", "text": "アセチルコリン"}, {"key": "B", "text": "ガストリン"}, {"key": "C", "text": "ソマトスタチン"}, {"key": "D", "text": "プロスタグランジンE2"}, {"key": "E", "text": "ヒスタミン"}]'::jsonb, 'E', '壁細胞の酸分泌は、ヒスタミン（H2受容体）、アセチルコリン（M3受容体）、ガストリン（CCK2受容体）で刺激される。ガストリンは主にECL細胞からのヒスタミン放出を介して作用するため、ヒスタミンの作用が中心となる。H2受容体拮抗薬はこの経路を、プロトンポンプ阻害薬は最終段階のプロトンポンプを阻害する。NSAIDsはプロスタグランジンを減らして粘膜の防御を弱める。', '{"A": "迷走神経の終末から放出され、M3受容体を介して酸分泌を促す。", "B": "G細胞から分泌されるホルモンで、主にECL細胞を刺激してヒスタミンを放出させる。", "C": "D細胞から分泌され、酸分泌を抑える。", "D": "粘膜を保護し、酸分泌を抑える方向に働く。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'トリプシノーゲンの活性化', 2, 'CBT', '膵臓の蛋白分解酵素は不活性な前駆体として分泌され、膵臓自身が消化されるのを防いでいる。十二指腸で最初にトリプシノーゲンを活性化する酵素はどれか。', '[{"key": "A", "text": "エンテロペプチダーゼ"}, {"key": "B", "text": "ペプシン"}, {"key": "C", "text": "キモトリプシン"}, {"key": "D", "text": "カルボキシペプチダーゼ"}, {"key": "E", "text": "膵リパーゼ"}]'::jsonb, 'A', '十二指腸の刷子縁にあるエンテロペプチダーゼ（エンテロキナーゼ）がトリプシノーゲンをトリプシンに変え、トリプシンがさらにトリプシノーゲン、キモトリプシノーゲン、プロカルボキシペプチダーゼなどを次々に活性化する。膵臓内でトリプシンが早期に活性化されると自己消化が起こり、急性膵炎となる。膵液にはトリプシンの働きを抑える阻害因子も含まれる。', '{"B": "胃で働く蛋白分解酵素で、トリプシノーゲンを活性化しない。", "C": "トリプシンによって活性化される側の酵素である。", "D": "前駆体がトリプシンによって活性化される側の酵素である。", "E": "トリアシルグリセロールを分解する酵素である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '胆汁酸の再吸収', 2, 'CBT', '胆汁酸は肝で合成されて腸管に分泌され、大部分が再吸収されて肝に戻る（腸肝循環）。胆汁酸の大部分が能動的に再吸収される部位はどれか。', '[{"key": "A", "text": "胃"}, {"key": "B", "text": "回腸末端"}, {"key": "C", "text": "十二指腸"}, {"key": "D", "text": "空腸"}, {"key": "E", "text": "上行結腸"}]'::jsonb, 'B', '胆汁酸は空腸で脂肪の消化吸収を助けたあと、回腸末端のナトリウム依存性胆汁酸輸送体で約95%が再吸収され、門脈を経て肝に戻る。回腸を広く切除したりCrohn病で回腸が侵されたりすると、胆汁酸が大腸に流れ込んで下痢をきたし、胆汁酸が不足して脂肪の吸収障害や胆石の原因となる。回腸末端はビタミンB12の吸収部位でもある。', '{"A": "胆汁酸を再吸収する部位ではない。", "C": "胆汁が分泌される部位で、胆汁酸の再吸収の主な場ではない。", "D": "脂肪の吸収の主な場だが、胆汁酸の能動的な再吸収は回腸で行われる。", "E": "ここまで届いた胆汁酸は腸内細菌で変換され、一部が受動的に吸収されるにとどまる。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '鉄の吸収部位', 2, 'CBT', '食事中の鉄は吸収率が低く、体内の鉄の量は主に吸収の段階で調節されている。食事中の鉄が主に吸収される部位はどれか。', '[{"key": "A", "text": "上行結腸"}, {"key": "B", "text": "直腸"}, {"key": "C", "text": "十二指腸"}, {"key": "D", "text": "回腸末端"}, {"key": "E", "text": "胃"}]'::jsonb, 'C', '非ヘム鉄は胃酸やビタミンCで2価鉄に還元され、十二指腸の上皮細胞にDMT1で取り込まれる。細胞内の鉄はフェロポルチンを通って血中に出てトランスフェリンに結合する。肝で産生されるヘプシジンはフェロポルチンを分解して鉄の放出を抑える。炎症ではヘプシジンが増えて鉄が利用されにくくなり、慢性炎症に伴う貧血の原因となる。胃切除後は鉄の吸収が落ちやすい。', '{"A": "水と電解質の吸収が主で、鉄の吸収部位ではない。", "B": "鉄の吸収部位ではない。", "D": "ビタミンB12や胆汁酸が吸収される部位である。", "E": "胃酸は鉄を吸収しやすい形にするが、吸収の主な場ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '嚥下の咽頭期', 2, 'CBT', '嚥下は口腔期、咽頭期、食道期に分けられ、咽頭期で誤嚥を防ぐ仕組みが働く。嚥下の咽頭期に起こる現象として正しいのはどれか。', '[{"key": "A", "text": "下部食道括約筋が強く収縮する"}, {"key": "B", "text": "呼吸は止まらずに続けられる"}, {"key": "C", "text": "食道の蠕動が胃の側から口の側へ向かって進む"}, {"key": "D", "text": "軟口蓋と喉頭が挙上して気道が閉じられる"}, {"key": "E", "text": "随意運動として意識的に行われる"}]'::jsonb, 'D', '咽頭期では、軟口蓋が挙上して鼻咽腔を閉じ、舌骨と喉頭が前上方へ挙上して喉頭蓋が喉頭の入口を覆い、声門が閉じて呼吸が一時止まる。同時に上部食道括約筋が弛緩して食塊が食道へ送られる。この反射は延髄の嚥下中枢が制御しており、脳卒中や神経筋疾患で障害されると誤嚥性肺炎の原因となる。', '{"A": "嚥下に伴って下部食道括約筋は弛緩し、食塊を胃へ通す。", "B": "咽頭期には呼吸が一時的に止まる（嚥下性無呼吸）。", "C": "食道の蠕動は口側から胃へ向かって進む。", "E": "咽頭期は延髄の嚥下中枢による反射で、意識的には制御できない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '筋層間神経叢', 2, 'CBT', '消化管の壁の中には、中枢神経から独立して働くことができる腸管神経系がある。消化管の蠕動運動を主に制御する神経叢はどれか。', '[{"key": "A", "text": "粘膜下神経叢（Meissner神経叢）"}, {"key": "B", "text": "腹腔神経叢"}, {"key": "C", "text": "骨盤神経叢"}, {"key": "D", "text": "腕神経叢"}, {"key": "E", "text": "筋層間神経叢（Auerbach神経叢）"}]'::jsonb, 'E', '筋層間神経叢は輪走筋と縦走筋の間にあり、蠕動運動を制御する。粘膜下神経叢は分泌や血流を調節する。腸管神経系は自律神経の調節を受けつつ、単独でも反射を起こせる。神経堤由来の神経節細胞が大腸の遠位部まで達しないHirschsprung病では、その部分が弛緩できず機能的な閉塞をきたす。食道アカラシアでは筋層間神経叢の抑制性ニューロンが減少し、下部食道括約筋が弛緩しない。', '{"A": "主に粘膜の分泌や局所の血流を調節する。", "B": "腹腔動脈の周囲にある交感神経の神経叢で、腸管壁内の神経叢ではない。", "C": "骨盤内臓器に分布する自律神経の神経叢である。", "D": "上肢を支配する体性神経の神経叢である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '大腸の働き', 2, 'CBT', '小腸を通過した内容物は、大腸を進むうちに半固形の便になる。大腸の主な働きとして正しいのはどれか。', '[{"key": "A", "text": "水と電解質の吸収"}, {"key": "B", "text": "蛋白質の消化"}, {"key": "C", "text": "脂肪の消化と吸収"}, {"key": "D", "text": "単糖の吸収"}, {"key": "E", "text": "胆汁の分泌"}]'::jsonb, 'A', '大腸は小腸から流入する1日約1.5Lの内容物から水とナトリウムの大部分を吸収し、便を形成する。腸内細菌は食物繊維を発酵させて短鎖脂肪酸をつくり、大腸上皮のエネルギー源となる。大腸の吸収能を上回る水分が流入したり、大腸の分泌が増えたりすると下痢となる。', '{"B": "蛋白質の消化は胃と小腸で行われる。", "C": "脂肪は主に十二指腸と空腸で消化・吸収される。", "D": "糖の吸収は主に小腸で行われる。", "E": "胆汁は肝臓で産生され、胆管を通って十二指腸に分泌される。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '肝小葉の中心静脈周囲', 2, 'CBT', '肝小葉では、血液は門脈域から中心静脈に向かって類洞を流れる。中心静脈の周囲（第3帯）の肝細胞の特徴として正しいのはどれか。', '[{"key": "A", "text": "胆管の上皮細胞が集まっている"}, {"key": "B", "text": "酸素分圧が低く、虚血による障害を受けやすい"}, {"key": "C", "text": "門脈域に最も近く、酸素に富む血液を受ける"}, {"key": "D", "text": "薬物代謝酵素が乏しく、薬物性肝障害を受けにくい"}, {"key": "E", "text": "糖新生や尿素合成が最も盛んである"}]'::jsonb, 'B', '類洞の血液は門脈域（第1帯）から中心静脈（第3帯）に向かって流れるため、第3帯は酸素分圧が最も低い。そのためショックや右心不全によるうっ血で壊死しやすい。また第3帯はシトクロムP450（CYP2E1など）に富むため、アセトアミノフェンの過量服用では有害な代謝物が生じて小葉中心性の壊死が起こる。第1帯は糖新生、β酸化、尿素合成が盛んである。', '{"A": "胆管は門脈域にある。", "C": "門脈域の周囲（第1帯）の特徴である。", "D": "第3帯はシトクロムP450に富み、アセトアミノフェンなどによる障害を受けやすい。", "E": "糖新生や尿素合成は酸素の多い第1帯で盛んである。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'コレシストキニン', 2, 'CBT', '脂肪の多い食事をとると、胆嚢が収縮して胆汁が十二指腸へ送り出される。十二指腸のI細胞から分泌され、胆嚢を収縮させるホルモンはどれか。', '[{"key": "A", "text": "GIP（グルコース依存性インスリン分泌刺激ポリペプチド）"}, {"key": "B", "text": "モチリン"}, {"key": "C", "text": "コレシストキニン"}, {"key": "D", "text": "セクレチン"}, {"key": "E", "text": "ガストリン"}]'::jsonb, 'C', 'コレシストキニンは脂肪酸やアミノ酸が十二指腸に入ると分泌され、胆嚢を収縮させてOddi括約筋を弛緩させ、膵臓からの消化酵素の分泌も促す。胆石のある患者が脂肪の多い食事のあとに右季肋部痛を起こしやすいのはこのためである。胃の排出を遅らせ、満腹感をもたらす作用もある。', '{"A": "K細胞から分泌され、インスリン分泌を促す。", "B": "空腹時の消化管の周期的な強い収縮を起こす。", "D": "S細胞から分泌され、主に膵臓からの重炭酸イオンの分泌を促す。", "E": "G細胞から分泌され、胃酸の分泌を促す。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '蛋白質の吸収', 2, 'CBT', '食事中の蛋白質は、胃のペプシンと膵臓のプロテアーゼで分解されてから吸収される。蛋白質の消化産物が小腸上皮に吸収される主な形はどれか。', '[{"key": "A", "text": "数十個のアミノ酸がつながったポリペプチド"}, {"key": "B", "text": "脂肪酸と結合したリポ蛋白"}, {"key": "C", "text": "アンモニアと炭素骨格に分解された形"}, {"key": "D", "text": "アミノ酸と、ジペプチド・トリペプチド"}, {"key": "E", "text": "分解されない蛋白質のまま"}]'::jsonb, 'D', '蛋白質は刷子縁のペプチダーゼでさらに分解され、アミノ酸はナトリウムとの共輸送などで、ジペプチドとトリペプチドは水素イオンとの共輸送体（PepT1）で上皮細胞に取り込まれる。細胞内でアミノ酸にまで分解され、門脈に入る。中性アミノ酸の輸送体の異常によるHartnup病では、トリプトファンの吸収が減り、ペラグラに似た症状が出る。', '{"A": "長いペプチドはさらに分解されてから吸収される。", "B": "蛋白質の消化産物の吸収の形ではない。", "C": "アミノ酸の分解は吸収後に主に肝で行われる。", "E": "成人では蛋白質のままの吸収はごくわずかである。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'パイエル板のM細胞', 2, 'CBT', '小腸の粘膜には腸管関連リンパ組織が発達しており、腸管内の抗原に対する免疫応答が始まる。パイエル板を覆う上皮にあるM細胞の働きとして正しいのはどれか。', '[{"key": "A", "text": "大量の粘液を分泌して上皮を保護する"}, {"key": "B", "text": "抗菌ペプチドのディフェンシンを分泌する"}, {"key": "C", "text": "IgAを産生して腸管内へ分泌する"}, {"key": "D", "text": "栄養素を吸収するための微絨毛を表面に密にもつ"}, {"key": "E", "text": "腸管内の抗原を取り込み、リンパ組織へ渡す"}]'::jsonb, 'E', 'M細胞はパイエル板を覆う上皮にあり、腸管内の抗原や微生物を取り込んで基底側のポケットにいる樹状細胞やリンパ球に受け渡す。これをきっかけにIgAを産生するB細胞が誘導され、粘膜固有層の形質細胞が産生した二量体IgAが上皮を通って分泌型IgAとして腸管内へ出る。一部の病原体はM細胞を侵入口として利用する。', '{"A": "杯細胞の働きである。", "B": "主にPaneth細胞の働きである。", "C": "IgAは粘膜固有層の形質細胞が産生する。", "D": "吸収上皮細胞の特徴で、M細胞は微絨毛に乏しい。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '腸内細菌とビタミンK', 2, 'CBT', '新生児は生後早期に出血をきたすことがあり、予防のためにビタミンK製剤を経口で投与する。腸内細菌が産生し、体内の供給源の一つになっているビタミンはどれか。', '[{"key": "A", "text": "ビタミンK"}, {"key": "B", "text": "ビタミンA"}, {"key": "C", "text": "ビタミンC"}, {"key": "D", "text": "ビタミンD"}, {"key": "E", "text": "ビタミンE"}]'::jsonb, 'A', '腸内細菌はビタミンK2（メナキノン）を産生し、体内の供給源の一部となる。新生児は胎盤を通るビタミンKが少なく、腸内細菌叢も未熟で、母乳のビタミンK含量も低いため欠乏しやすく、頭蓋内出血などをきたす（ビタミンK欠乏性出血症）。広域抗菌薬の長期投与や絶食でも腸内細菌による供給が減り、プロトロンビン時間が延長することがある。', '{"B": "食事から摂取し、腸内細菌による供給は期待できない。", "C": "食事から摂取する必要があり、腸内細菌による供給はない。", "D": "主に皮膚で紫外線を受けて合成され、食事からも摂取する。", "E": "食事から摂取する脂溶性ビタミンである。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '後腹膜臓器', 2, 'CBT', '腹部の臓器は、腹膜に覆われて腸間膜で支えられるものと、後腹壁に固定されたものに分けられる。後腹膜臓器はどれか。', '[{"key": "A", "text": "脾臓"}, {"key": "B", "text": "膵頭部"}, {"key": "C", "text": "胃"}, {"key": "D", "text": "横行結腸"}, {"key": "E", "text": "空腸"}]'::jsonb, 'B', '膵臓（尾部を除く）、十二指腸の大部分、上行結腸と下行結腸は、発生の過程で後腹壁に固定された二次性の後腹膜臓器である。腎臓、副腎、尿管、腹部大動脈、下大静脈は初めから後腹膜にある。膵臓の病変は後腹膜に広がりやすく、急性膵炎では背部痛を伴うことが多い。', '{"A": "腹膜に覆われる腹膜内臓器である。", "C": "腹膜に覆われ、大網や小網で支えられる腹膜内臓器である。", "D": "横行結腸間膜で支えられる腹膜内臓器である。", "E": "腸間膜で支えられる腹膜内臓器である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'Cajal介在細胞', 2, 'CBT', '消化管の平滑筋は、ペースメーカー細胞が生み出す電気的なリズム（徐波）に従って収縮する。消化管のペースメーカー細胞で、消化管間質腫瘍（GIST）の発生母地と考えられる細胞はどれか。', '[{"key": "A", "text": "腸クロム親和性細胞"}, {"key": "B", "text": "杯細胞"}, {"key": "C", "text": "Cajal介在細胞"}, {"key": "D", "text": "消化管の平滑筋細胞"}, {"key": "E", "text": "シュワン細胞"}]'::jsonb, 'C', 'Cajal介在細胞は筋層に網目状に分布し、自発的に脱分極して徐波をつくり、平滑筋の収縮のリズムを決める。受容体型チロシンキナーゼのKITを発現しており、GISTの多くはKITやPDGFRAの活性化変異をもつ。そのためKITを阻害するイマチニブが切除不能・再発のGISTの治療に用いられる。', '{"A": "セロトニンを分泌する内分泌細胞で、神経内分泌腫瘍の発生母地となる。", "B": "粘液を分泌する上皮細胞である。", "D": "ペースメーカーのリズムに従って収縮する細胞である。", "E": "末梢神経の髄鞘をつくる細胞で、神経鞘腫の発生母地である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'Brunner腺', 2, 'CBT', '十二指腸の粘膜下層には特有の腺があり、胃から流れてくる酸から粘膜を守っている。粘膜下層にBrunner腺が存在する部位はどれか。', '[{"key": "A", "text": "回腸"}, {"key": "B", "text": "胃の前庭部"}, {"key": "C", "text": "横行結腸"}, {"key": "D", "text": "十二指腸"}, {"key": "E", "text": "空腸"}]'::jsonb, 'D', 'Brunner腺（十二指腸腺）は十二指腸の粘膜下層にある腺で、アルカリ性の粘液を分泌して胃酸から粘膜を守る。セクレチンで分泌が促される膵液の重炭酸イオンも酸を中和する。十二指腸潰瘍は胃酸の分泌過多やヘリコバクター・ピロリ感染などで、この防御を攻撃因子が上回ると生じる。小腸の標本で粘膜下層に腺があれば、組織学的に十二指腸と判断できる。', '{"A": "パイエル板が発達するが、Brunner腺はない。", "B": "幽門腺があるが、粘膜下層の腺ではない。", "C": "粘膜に陰窩があるが、粘膜下層の腺はない。", "E": "粘膜下層に腺をもたない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '中鎖脂肪酸の吸収', 2, 'CBT', '脂肪の吸収障害や乳び胸の患者の栄養管理では、中鎖脂肪酸トリグリセリドが用いられる。中鎖脂肪酸の吸収の特徴として正しいのはどれか。', '[{"key": "A", "text": "長鎖脂肪酸と同様にキロミクロンとしてリンパ管へ運ばれる"}, {"key": "B", "text": "吸収には必ず胆汁酸によるミセル形成が必要である"}, {"key": "C", "text": "大腸で腸内細菌に発酵されてから吸収される"}, {"key": "D", "text": "吸収されずにそのまま便中に排泄される"}, {"key": "E", "text": "キロミクロンを形成せず、門脈を経て直接肝に運ばれる"}]'::jsonb, 'E', '中鎖脂肪酸（炭素数8〜12程度）は水に比較的溶けやすく、胆汁酸やリパーゼへの依存が小さい。小腸上皮でトリアシルグリセロールに再合成されずに門脈へ入り、アルブミンと結合して肝に運ばれ、すばやくβ酸化を受ける。リンパ管を通らないため乳び胸での食事療法に、胆汁酸や膵酵素が不足する脂肪吸収障害でエネルギー源として用いられる。', '{"A": "長鎖脂肪酸の吸収経路で、中鎖脂肪酸はこの経路をほとんど使わない。", "B": "中鎖脂肪酸は水に溶けやすく、胆汁酸への依存が小さい。", "C": "中鎖脂肪酸は小腸で吸収される。", "D": "中鎖脂肪酸は効率よく吸収される。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'Na-K-2Cl共輸送体', 2, 'CBT', 'フロセミドはNa+-K+-2Cl-共輸送体を阻害して強い利尿作用を示す。この共輸送体が存在し、フロセミドが作用する部位はどれか。', '[{"key": "A", "text": "Henleループの太い上行脚"}, {"key": "B", "text": "近位尿細管"}, {"key": "C", "text": "Henleループの細い下行脚"}, {"key": "D", "text": "遠位曲尿細管"}, {"key": "E", "text": "集合管"}]'::jsonb, 'A', 'Henleループの太い上行脚は、管腔側のNa+-K+-2Cl-共輸送体で塩化ナトリウムを再吸収するが、水は通さない。これにより間質の浸透圧が高まり、尿の濃縮の基盤となる（対向流増幅系）。ループ利尿薬はこの輸送体を阻害して大量の利尿を起こし、濃縮力も低下させる。低カリウム血症や代謝性アルカローシス、高尿酸血症、聴覚障害などの副作用がある。Bartter症候群はこの部位の輸送体の遺伝子異常による。', '{"B": "濾過されたナトリウムの約2/3を再吸収するが、この共輸送体はない。", "C": "水の透過性が高い部位で、この共輸送体はない。", "D": "Na+-Cl-共輸送体があり、サイアザイド系利尿薬が作用する。", "E": "上皮型ナトリウムチャネルがあり、アルドステロンやアミロライドが作用する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '尿細管液の浸透圧', 2, 'CBT', '腎臓は血漿の約4倍の浸透圧まで尿を濃縮することができる。抗利尿ホルモンが十分に分泌されているとき、尿細管液の浸透圧が最も高くなる部位はどれか。', '[{"key": "A", "text": "遠位曲尿細管"}, {"key": "B", "text": "Henleループの折り返し部"}, {"key": "C", "text": "Bowman腔の糸球体濾過液"}, {"key": "D", "text": "近位尿細管の終末部"}, {"key": "E", "text": "Henleループの太い上行脚の終末部"}]'::jsonb, 'B', '下行脚では水が高浸透圧の髄質間質へ出ていくため、尿細管液はループの折り返し部で最も濃くなる。太い上行脚で塩化ナトリウムだけが再吸収されて低張となり、遠位尿細管まで低張のまま流れる。抗利尿ホルモンがあると集合管で水が再吸収され、最終的に髄質間質と同じ高張な尿となる。', '{"A": "希釈されて低張のまま流れる部位である。", "C": "糸球体濾過液は血漿とほぼ等しい浸透圧である。", "D": "水と溶質が同じ割合で再吸収されるため、血漿とほぼ等張である。", "E": "塩化ナトリウムが再吸収されて水は残るため、低張になる。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'バソプレシンの作用機序', 2, 'CBT', '脱水で血漿浸透圧が上がると、下垂体後葉からバソプレシンが分泌されて尿が濃縮される。腎でのバソプレシンの作用機序として正しいのはどれか。', '[{"key": "A", "text": "遠位曲尿細管のナトリウム-塩化物共輸送体を活性化する"}, {"key": "B", "text": "集合管の上皮型ナトリウムチャネルを増やす"}, {"key": "C", "text": "V2受容体を介しアクアポリン2を管腔側膜へ移す"}, {"key": "D", "text": "血管平滑筋のV1受容体を介し、集合管の水の透過性を高める"}, {"key": "E", "text": "近位尿細管のアクアポリン1を新たに合成させる"}]'::jsonb, 'C', 'バソプレシンは集合管主細胞の基底側膜のV2受容体（Gs共役）に結合し、cAMPとプロテインキナーゼAを介してアクアポリン2を含む小胞を管腔側膜に移動させ、水の再吸収を増やす。V2受容体やアクアポリン2の異常では腎性尿崩症となる。V2受容体拮抗薬のトルバプタンは、低ナトリウム血症や心不全の体液貯留、常染色体顕性多発性嚢胞腎の治療に用いられる。', '{"A": "主に遠位曲尿細管の塩類の再吸収に関わる機序で、バソプレシンの主作用ではない。", "B": "主にアルドステロンの作用である。", "D": "V1受容体は血管の収縮に関わり、集合管の水の透過性には関わらない。", "E": "アクアポリン1は近位尿細管に常にあり、バソプレシンの調節を受けない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'アルドステロンの腎作用', 2, 'CBT', '副腎皮質の球状層から分泌されるアルドステロンは、体液量と血清カリウム値の調節に働く。アルドステロンの腎での作用として正しいのはどれか。', '[{"key": "A", "text": "糸球体の輸入細動脈を拡張させて濾過量を増やす"}, {"key": "B", "text": "集合管で水素イオンの分泌を抑える"}, {"key": "C", "text": "Henleループでカルシウムの排泄を促す"}, {"key": "D", "text": "集合管でNa再吸収とK分泌を促す"}, {"key": "E", "text": "近位尿細管でブドウ糖の再吸収を促す"}]'::jsonb, 'D', 'アルドステロンは集合管主細胞の鉱質コルチコイド受容体に結合し、上皮型ナトリウムチャネルとナトリウムポンプを増やしてナトリウムを再吸収する。その結果、管腔が負に傾いてカリウムと水素イオンの分泌が促される。原発性アルドステロン症では高血圧、低カリウム血症、代謝性アルカローシスをきたす。スピロノラクトンはこの受容体を遮断するカリウム保持性利尿薬である。', '{"A": "アルドステロンの主作用ではない。", "B": "アルドステロンは間在細胞の水素イオンの分泌をむしろ促す。", "C": "アルドステロンの主作用ではない。", "E": "ブドウ糖の再吸収はSGLTによるもので、アルドステロンの主作用ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'レニン分泌の刺激', 2, 'CBT', 'レニンは腎の傍糸球体細胞から分泌され、レニン-アンジオテンシン-アルドステロン系の起点となる。レニンの分泌を促進する因子はどれか。', '[{"key": "A", "text": "緻密斑に届く塩化ナトリウムの増加"}, {"key": "B", "text": "全身の血圧の上昇"}, {"key": "C", "text": "心房性ナトリウム利尿ペプチドの増加"}, {"key": "D", "text": "アンジオテンシンIIの増加"}, {"key": "E", "text": "輸入細動脈の灌流圧の低下"}]'::jsonb, 'E', 'レニン分泌は、輸入細動脈の傍糸球体細胞が感知する灌流圧の低下、緻密斑に届く塩化ナトリウムの減少、交感神経のβ1受容体の刺激で増える。レニンはアンジオテンシノゲンをアンジオテンシンIに変え、アンジオテンシン変換酵素でできたアンジオテンシンIIが血管を収縮させ、アルドステロンの分泌を促す。腎動脈狭窄症では患側の灌流圧が下がってレニン分泌が増え、高血圧となる。', '{"A": "緻密斑への塩化ナトリウムの到達が減るとレニン分泌が増える。", "B": "血圧が上がると灌流圧が上がり、レニン分泌は抑えられる。", "C": "レニン分泌を抑える方向に働く。", "D": "負のフィードバックでレニン分泌を抑える。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '緻密斑', 2, 'CBT', '遠位尿細管が自分の糸球体の血管極に接する部分には、特殊な上皮細胞の集まりである緻密斑がある。緻密斑が感知しているものはどれか。', '[{"key": "A", "text": "尿細管液のNaCl濃度"}, {"key": "B", "text": "輸入細動脈の血圧"}, {"key": "C", "text": "血漿のカリウムイオン濃度"}, {"key": "D", "text": "尿細管液中のブドウ糖濃度"}, {"key": "E", "text": "血漿の浸透圧"}]'::jsonb, 'A', '緻密斑は太い上行脚の終わりにあり、Na+-K+-2Cl-共輸送体を介して尿細管液の塩化ナトリウム濃度を感知する。濾過量が増えて塩化ナトリウムの到達が増えると、アデノシンなどを介して輸入細動脈を収縮させ、濾過量を元に戻す（尿細管糸球体フィードバック）。到達が減るとレニンの分泌を促す。SGLT2阻害薬は緻密斑へのナトリウムの到達を増やし、糸球体の過剰濾過を和らげると考えられている。', '{"B": "主に傍糸球体細胞が感知する。", "C": "緻密斑が感知するものではない。", "D": "緻密斑が感知するものではない。", "E": "視床下部の浸透圧受容器が感知する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'GFRを測る物質', 2, 'CBT', '糸球体濾過量（GFR）を正確に求めるには、糸球体で自由に濾過され、尿細管で再吸収も分泌もされない物質のクリアランスを測定する。この条件を満たす物質はどれか。', '[{"key": "A", "text": "アルブミン"}, {"key": "B", "text": "イヌリン"}, {"key": "C", "text": "パラアミノ馬尿酸"}, {"key": "D", "text": "ブドウ糖"}, {"key": "E", "text": "尿素"}]'::jsonb, 'B', 'イヌリンは糸球体で自由に濾過され、尿細管で再吸収も分泌もされないため、そのクリアランスはGFRに等しい。日常診療ではクレアチニンのクリアランスや、血清クレアチニン値と年齢・性別から求める推算GFRを用いる。クレアチニンは尿細管からもわずかに分泌されるため、クリアランスはGFRをやや過大に評価する。', '{"A": "糸球体でほとんど濾過されない。", "C": "尿細管でほぼ完全に分泌されるため、腎血漿流量の測定に用いる。", "D": "正常では近位尿細管でほぼすべて再吸収される。", "E": "尿細管で一部が再吸収されるため、GFRを過小評価する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'ブドウ糖の腎閾値', 2, 'CBT', '血糖値が上がると、ある値を超えたところで尿糖が出現する。健常成人で尿糖が出現しはじめる血糖値の目安に最も近いのはどれか。', '[{"key": "A", "text": "約400mg/dL"}, {"key": "B", "text": "約600mg/dL"}, {"key": "C", "text": "約180mg/dL"}, {"key": "D", "text": "約70mg/dL"}, {"key": "E", "text": "約110mg/dL"}]'::jsonb, 'C', '濾過されたブドウ糖は近位尿細管のSGLT2とSGLT1でほぼすべて再吸収されるが、輸送には上限がある。血糖値がおよそ160〜180mg/dLを超えると再吸収しきれず、尿糖が出現する（腎閾値）。妊娠中や腎性糖尿では閾値が下がり、血糖が正常でも尿糖が出る。SGLT2阻害薬は再吸収を抑えて尿糖を増やし、血糖を下げる。', '{"A": "尿糖が出はじめる値としては高すぎる。", "B": "尿糖が出はじめる値としては高すぎる。", "D": "空腹時の正常な血糖値の下限程度で、尿糖は出ない。", "E": "空腹時血糖の正常上限程度で、通常は尿糖は出ない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'ビタミンDの活性化', 2, 'CBT', 'ビタミンDは肝と腎で順に水酸化されて活性型になり、カルシウムの吸収を促す。25-ヒドロキシビタミンDを活性型の1,25-ジヒドロキシビタミンDに変換する酵素が主に存在する部位はどれか。', '[{"key": "A", "text": "皮膚の表皮"}, {"key": "B", "text": "小腸の吸収上皮細胞"}, {"key": "C", "text": "副甲状腺"}, {"key": "D", "text": "腎の近位尿細管"}, {"key": "E", "text": "肝細胞"}]'::jsonb, 'D', '近位尿細管の1α-水酸化酵素は、副甲状腺ホルモンや低リン血症で促進され、FGF23や活性型ビタミンD自身で抑えられる。慢性腎臓病ではこの酵素が働かなくなって活性型ビタミンDが減り、低カルシウム血症と二次性副甲状腺機能亢進症、骨病変をきたすため、活性型ビタミンD製剤を用いる。サルコイドーシスでは肉芽腫のマクロファージがこの酵素をもち、高カルシウム血症をきたすことがある。', '{"A": "紫外線によってビタミンD3がつくられる場である。", "B": "活性型ビタミンDが作用してカルシウムを吸収する場である。", "C": "副甲状腺ホルモンを分泌し、腎での活性化を促す側の臓器である。", "E": "ビタミンDを25-ヒドロキシビタミンDに変換する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'エリスロポエチンの産生', 2, 'CBT', '慢性腎臓病が進行すると、鉄が十分にあっても正球性の貧血が進む。エリスロポエチンを主に産生する細胞はどれか。', '[{"key": "A", "text": "糸球体の臓側上皮である足細胞"}, {"key": "B", "text": "傍糸球体細胞"}, {"key": "C", "text": "集合管の主細胞"}, {"key": "D", "text": "骨髄の赤芽球"}, {"key": "E", "text": "腎の尿細管周囲の間質細胞"}]'::jsonb, 'E', 'エリスロポエチンは主に腎皮質の尿細管周囲間質の線維芽細胞様の細胞が、低酸素を感知して産生する。低酸素では低酸素誘導因子（HIF）が分解を免れて遺伝子の転写を促す。慢性腎臓病ではこの産生が減って腎性貧血となり、赤血球造血刺激因子製剤やHIFの分解を妨げるHIF-PH阻害薬で治療する。胎児期には主に肝で産生される。', '{"A": "濾過膜の一部をつくる細胞で、エリスロポエチンの産生は主な役割ではない。", "B": "レニンを分泌する細胞である。", "C": "水とナトリウムの再吸収を担う細胞である。", "D": "エリスロポエチンの作用を受けて増殖・分化する側の細胞である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'アシドーシス時の酸排泄', 2, 'CBT', '代謝性アシドーシスが数日続くと、腎は酸の排泄を大きく増やして適応する。このとき最も大きく増加して酸排泄の増加を担う仕組みはどれか。', '[{"key": "A", "text": "グルタミンからのアンモニア産生"}, {"key": "B", "text": "糸球体でのリン酸の濾過"}, {"key": "C", "text": "集合管での重炭酸イオンの分泌"}, {"key": "D", "text": "Henleループでの尿素の再吸収"}, {"key": "E", "text": "近位尿細管でのブドウ糖の再吸収"}]'::jsonb, 'A', '腎は1日に産生される不揮発酸を、滴定酸（主にリン酸）とアンモニウムイオンとして排泄する。滴定酸の量は濾過されるリン酸の量で限られるが、アンモニア産生は近位尿細管でグルタミンの代謝を増やして大きく増加できる。集合管では水素イオンが分泌され、アンモニアと結合してアンモニウムイオンとして尿中にとどまる。慢性腎臓病ではアンモニア産生が減り、代謝性アシドーシスをきたす。', '{"B": "滴定酸として酸排泄に関わるが、大きく増やすことはできない。", "C": "重炭酸イオンの分泌はアルカローシスへの反応である。", "D": "酸の排泄とは関係しない。", "E": "酸の排泄とは関係しない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '副甲状腺ホルモンの腎作用', 2, 'CBT', '副甲状腺ホルモンは、骨、腎、腸を介して血中カルシウム濃度を上げる。副甲状腺ホルモンの腎での作用として正しいのはどれか。', '[{"key": "A", "text": "糸球体でカルシウムの濾過を止める"}, {"key": "B", "text": "Ca再吸収を促し、リン再吸収を抑える"}, {"key": "C", "text": "遠位尿細管でカルシウムの排泄を促し、リンの再吸収を促す"}, {"key": "D", "text": "近位尿細管で1α-水酸化酵素を抑制する"}, {"key": "E", "text": "集合管でナトリウムの再吸収を強く促す"}]'::jsonb, 'B', '副甲状腺ホルモンは遠位尿細管でカルシウムの再吸収を増やし、近位尿細管のナトリウム-リン共輸送体を減らしてリンの排泄を増やす。さらに1α-水酸化酵素を促して活性型ビタミンDを増やし、腸からのカルシウム吸収を高める。原発性副甲状腺機能亢進症では高カルシウム血症と低リン血症をきたし、尿路結石や骨粗鬆症の原因となる。', '{"A": "副甲状腺ホルモンの作用ではない。", "C": "カルシウムについてもリンについても逆の作用である。", "D": "副甲状腺ホルモンは1α-水酸化酵素を促進する。", "E": "主にアルドステロンの作用である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '腎血流量', 2, 'CBT', '腎臓は両側で体重の0.5%程度の重さしかないが、非常に多くの血液を受けている。安静時の腎血流量は心拍出量のおよそ何%か。', '[{"key": "A", "text": "約15%"}, {"key": "B", "text": "約50%"}, {"key": "C", "text": "約20%"}, {"key": "D", "text": "約0.5%"}, {"key": "E", "text": "約5%"}]'::jsonb, 'C', '安静時の腎血流量は約1L/分で、心拍出量の20〜25%にあたる。この大量の血流は腎自身の酸素需要のためではなく、濾過のためで、1日に約150Lの原尿がつくられる。腎血流と糸球体濾過量は、平均血圧がおよそ80〜180mmHgの範囲では自動調節によってほぼ一定に保たれる。', '{"A": "脳の血流（心拍出量の約15%）に近い値である。", "B": "多すぎる値で、腎臓がこれほどの血流を受けることはない。", "D": "腎臓の重さが体重に占める割合に近い値で、血流の割合ではない。", "E": "冠動脈の血流（心拍出量の約5%）に近い値である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '糸球体濾過膜', 2, 'CBT', 'ネフローゼ症候群では、糸球体から大量の蛋白質が尿中へ漏れ出る。糸球体濾過膜で蛋白質の漏出を防ぐうえで重要な構造はどれか。', '[{"key": "A", "text": "メサンギウム細胞"}, {"key": "B", "text": "傍糸球体装置"}, {"key": "C", "text": "Bowman嚢の壁側上皮"}, {"key": "D", "text": "足細胞のスリット膜"}, {"key": "E", "text": "近位尿細管の刷子縁"}]'::jsonb, 'D', '糸球体濾過膜は、有窓型の毛細血管内皮、糸球体基底膜、足細胞のスリット膜の3層からなり、大きさと負の電荷によって蛋白質を通しにくくしている。スリット膜はネフリンやポドシンなどでつくられ、NPHS1遺伝子の異常では先天性ネフローゼ症候群（フィンランド型）となる。微小変化型ネフローゼ症候群では電子顕微鏡で足突起の消失がみられる。', '{"A": "糸球体の毛細血管を支え、貪食や収縮を担うが、濾過膜の主な障壁ではない。", "B": "レニンの分泌と尿細管糸球体フィードバックを担う構造である。", "C": "Bowman腔の外側を覆う上皮で、濾過膜ではない。", "E": "尿細管の吸収面を広げる構造で、濾過膜ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '排尿の神経支配', 2, 'CBT', '排尿時には膀胱の排尿筋が収縮し、内尿道括約筋と外尿道括約筋が弛緩する。排尿時に膀胱の排尿筋を収縮させる神経はどれか。', '[{"key": "A", "text": "下腹神経"}, {"key": "B", "text": "陰部神経"}, {"key": "C", "text": "閉鎖神経"}, {"key": "D", "text": "大腿神経"}, {"key": "E", "text": "骨盤神経"}]'::jsonb, 'E', '骨盤神経は第2〜4仙髄から出る副交感神経で、アセチルコリンでムスカリン受容体を刺激して排尿筋を収縮させる。蓄尿期には交感神経の下腹神経（β3受容体で排尿筋を弛緩、α1受容体で内尿道括約筋を収縮）と陰部神経が働く。排尿反射の中枢は橋にあり、大脳が抑制している。抗コリン薬やβ3作動薬は過活動膀胱に、α1遮断薬は前立腺肥大症の排尿障害に用いられる。', '{"A": "交感神経で、排尿筋を弛緩させ内尿道括約筋を収縮させて蓄尿に働く。", "B": "体性神経で、外尿道括約筋を収縮させて随意的に尿をこらえる。", "C": "大腿の内転筋群を支配する神経である。", "D": "大腿四頭筋などを支配する神経である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '左腎静脈の走行', 2, 'CBT', '若年のやせ型の患者で、左腎静脈の圧迫による血尿や左精索静脈瘤がみられることがある。左腎静脈が下大静脈に注ぐ途中で通過する部位はどれか。', '[{"key": "A", "text": "腹部大動脈と上腸間膜動脈の間"}, {"key": "B", "text": "腹部大動脈と椎体の間"}, {"key": "C", "text": "腹腔動脈と上腸間膜動脈の間"}, {"key": "D", "text": "下大静脈と右腎動脈の間"}, {"key": "E", "text": "上腸間膜動脈と下腸間膜動脈の間"}]'::jsonb, 'A', '左腎静脈は腹部大動脈の前、上腸間膜動脈の後ろを通って下大静脈に注ぐ。やせて両動脈のなす角度が狭いと左腎静脈が挟まれ、血尿や左の精索静脈瘤、骨盤内のうっ血をきたす（ナットクラッカー現象）。左精巣静脈は左腎静脈に、右精巣静脈は下大静脈に直接注ぐため、精索静脈瘤は左側に多い。', '{"B": "左腎静脈が大動脈の後ろを通る破格もあるが、通常の走行ではない。", "C": "左腎静脈の通常の走行ではない。", "D": "右腎動脈は下大静脈の後ろを通るが、左腎静脈の走行ではない。", "E": "左腎静脈の通常の走行ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '水利尿', 2, 'CBT', '健常成人が短時間に1Lの水を飲むと、しばらくして薄い尿が大量に出る。このときに起こっている変化として正しいのはどれか。', '[{"key": "A", "text": "集合管のアクアポリン2が管腔側膜に増える"}, {"key": "B", "text": "血漿浸透圧が下がり、バソプレシンの分泌が減る"}, {"key": "C", "text": "血漿浸透圧が上がり、バソプレシンの分泌が増える"}, {"key": "D", "text": "アルドステロンの分泌が増え、ナトリウムの再吸収が増える"}, {"key": "E", "text": "糸球体濾過量が数倍に増える"}]'::jsonb, 'B', '水を飲むと血漿浸透圧がわずかに下がり、視床下部の浸透圧受容器がこれを感知してバソプレシンの分泌を減らす。集合管のアクアポリン2が管腔側膜から引き込まれ、水の再吸収が減って薄い尿が大量に出る（水利尿）。バソプレシンの分泌が不適切に続く病態（SIADH）では、水を排泄できず低ナトリウム血症となる。', '{"A": "バソプレシンが減るため、アクアポリン2は管腔側膜から減る。", "C": "水を飲むと血漿浸透圧は下がる。", "D": "水負荷で薄い尿が出る主な機序ではない。", "E": "糸球体濾過量はほぼ一定で、尿量の増加は再吸収の低下による。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '炭酸脱水酵素阻害薬', 2, 'CBT', 'アセタゾラミドは炭酸脱水酵素を阻害し、重炭酸イオンの再吸収を減らして利尿を起こす。アセタゾラミドが主に作用する尿細管の部位はどれか。', '[{"key": "A", "text": "集合管"}, {"key": "B", "text": "糸球体"}, {"key": "C", "text": "近位尿細管"}, {"key": "D", "text": "Henleループの太い上行脚"}, {"key": "E", "text": "遠位曲尿細管"}]'::jsonb, 'C', '近位尿細管では、濾過された重炭酸イオンの約8割が炭酸脱水酵素の働きで再吸収される。アセタゾラミドはこれを阻害して重炭酸イオンとナトリウムを尿中に失わせ、代謝性アシドーシスをきたす。利尿作用は弱く、緑内障の眼圧低下、高山病の予防、代謝性アルカローシスの補正などに用いられる。', '{"A": "抗アルドステロン薬やバソプレシン受容体拮抗薬の作用部位である。", "B": "尿細管ではなく、利尿薬の主な作用部位ではない。", "D": "ループ利尿薬の作用部位である。", "E": "サイアザイド系利尿薬の作用部位である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '尿管の生理的狭窄部', 2, 'CBT', '尿管結石は、尿管の内腔が生理的に狭くなっている部位に引っかかりやすい。尿管の生理的狭窄部位として正しいのはどれか。', '[{"key": "A", "text": "尿管の中央部で腰椎の横突起の前を通る部位"}, {"key": "B", "text": "膀胱三角の中央部"}, {"key": "C", "text": "尿道の舟状窩"}, {"key": "D", "text": "尿管が総腸骨動脈と交差する部位"}, {"key": "E", "text": "腎杯と腎乳頭の接する部位"}]'::jsonb, 'D', '尿管の生理的狭窄部位は、腎盂尿管移行部、総腸骨動脈との交差部、膀胱壁を斜めに貫く膀胱尿管移行部の3か所で、結石が嵌頓しやすい。膀胱尿管移行部は最も狭い。尿管結石が嵌頓すると尿の流れが妨げられ、腰背部から下腹部、陰部に放散する疝痛発作と血尿をきたす。', '{"A": "生理的な狭窄部位ではない。", "B": "尿管の部位ではない。", "C": "尿道の部位で、尿管の狭窄部位ではない。", "E": "尿管の生理的狭窄部位には含まれない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '糸球体濾過量の正常値', 2, 'CBT', '腎機能の指標である糸球体濾過量（GFR）は、年齢とともに低下する。健常な若年成人の糸球体濾過量に最も近いのはどれか。', '[{"key": "A", "text": "約1mL/分"}, {"key": "B", "text": "約10mL/分"}, {"key": "C", "text": "約600mL/分"}, {"key": "D", "text": "約5L/分"}, {"key": "E", "text": "約100mL/分"}]'::jsonb, 'E', '健常な若年成人の糸球体濾過量は約100〜120mL/分（体表面積1.73m²あたり）で、1日に約150Lの原尿がつくられる。その99%が尿細管で再吸収され、尿量は1日1〜1.5L程度となる。腎血漿流量は約600mL/分で、そのうち約20%が濾過される（濾過率）。慢性腎臓病はGFRで重症度が分類される。', '{"A": "1日の尿量（約1.5L）を分あたりにした程度の値で、濾過量ではない。", "B": "腎代替療法を考えるほど低下した値である。", "C": "腎血漿流量に近い値である。", "D": "心拍出量に近い値である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '核内受容体に作用するホルモン', 2, 'CBT', 'ホルモンは、受容体が細胞膜にあるものと細胞内（核内）にあるものに分けられる。アミノ酸由来のホルモンであるが、核内受容体に結合して遺伝子の転写を調節するものはどれか。', '[{"key": "A", "text": "甲状腺ホルモン"}, {"key": "B", "text": "インスリン"}, {"key": "C", "text": "グルカゴン"}, {"key": "D", "text": "アドレナリン"}, {"key": "E", "text": "成長ホルモン"}]'::jsonb, 'A', '甲状腺ホルモンはチロシンから合成されるが脂溶性が高く、細胞内に入って核内の甲状腺ホルモン受容体に結合し、レチノイドX受容体と二量体をつくって標的遺伝子の転写を調節する。ステロイドホルモン、活性型ビタミンD、レチノイン酸も核内受容体を介して作用する。ペプチドホルモンやカテコラミンは細胞膜の受容体に結合し、セカンドメッセンジャーを介して速やかに作用する。', '{"B": "細胞膜の受容体型チロシンキナーゼに結合する。", "C": "細胞膜のG蛋白質共役型受容体に結合する。", "D": "細胞膜のアドレナリン受容体（G蛋白質共役型）に結合する。", "E": "細胞膜のサイトカイン受容体に結合し、JAK-STAT経路を活性化する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '甲状腺ペルオキシダーゼ', 2, 'CBT', '甲状腺の濾胞細胞では、取り込んだヨウ素を材料に甲状腺ホルモンがつくられる。甲状腺ペルオキシダーゼが触媒する反応はどれか。', '[{"key": "A", "text": "甲状腺刺激ホルモンを受容してcAMPを増やす"}, {"key": "B", "text": "ヨウ素をサイログロブリンのチロシン残基に結合させる"}, {"key": "C", "text": "ヨウ化物イオンを血中から濾胞細胞へ取り込む"}, {"key": "D", "text": "末梢組織でサイロキシンをトリヨードサイロニンに変換する"}, {"key": "E", "text": "サイログロブリンを分解して甲状腺ホルモンを放出する"}]'::jsonb, 'B', '濾胞細胞はナトリウム-ヨウ素共輸送体でヨウ化物イオンを取り込み、甲状腺ペルオキシダーゼが過酸化水素を使ってヨウ素を酸化し、サイログロブリンのチロシン残基に結合させる（有機化）。さらにヨウ素化チロシンどうしを縮合させてT4とT3をつくる。チアマゾールなどの抗甲状腺薬はこの酵素を阻害する。橋本病ではこの酵素に対する抗体が高率に陽性となる。', '{"A": "TSH受容体の働きである。", "C": "ナトリウム-ヨウ素共輸送体の働きである。", "D": "脱ヨウ素酵素の働きである。", "E": "リソソームの蛋白分解酵素の働きである。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '活性型の甲状腺ホルモン', 2, 'CBT', '甲状腺から分泌されるホルモンの大部分はサイロキシン（T4）である。標的細胞で主に作用を担う甲状腺ホルモンはどれか。', '[{"key": "A", "text": "サイログロブリン"}, {"key": "B", "text": "甲状腺刺激ホルモン（TSH）"}, {"key": "C", "text": "T3"}, {"key": "D", "text": "T4"}, {"key": "E", "text": "リバースT3"}]'::jsonb, 'C', '甲状腺から分泌されるのは主にT4（サイロキシン）で、肝や腎、筋などの脱ヨウ素酵素によってより活性の高いT3（トリヨードサイロニン）に変換される。T3は受容体への親和性がT4の約10倍高い。重い全身疾患や飢餓ではT3への変換が減り、T3だけが低下する（低T3症候群）。血中の甲状腺ホルモンの大部分は結合蛋白と結合しており、作用するのは遊離型である。', '{"A": "甲状腺ホルモンを合成・貯蔵する蛋白質で、ホルモンそのものではない。", "B": "下垂体前葉から分泌され、甲状腺を刺激するホルモンである。", "D": "受容体への親和性が低く、主に末梢でT3に変換されて作用する前駆体である。", "E": "T4の内側の環から脱ヨウ素された不活性な代謝物である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '副腎皮質の束状層', 2, 'CBT', '副腎皮質は外側から球状層、束状層、網状層の3層に分かれ、それぞれ異なるステロイドホルモンを分泌する。束状層から主に分泌されるホルモンはどれか。', '[{"key": "A", "text": "デヒドロエピアンドロステロン"}, {"key": "B", "text": "アドレナリン"}, {"key": "C", "text": "ノルアドレナリン"}, {"key": "D", "text": "コルチゾール"}, {"key": "E", "text": "アルドステロン"}]'::jsonb, 'D', '副腎皮質は外から球状層（アルドステロン）、束状層（コルチゾール）、網状層（副腎アンドロゲン）の順に並ぶ。束状層と網状層はACTHの調節を受け、球状層は主にアンジオテンシンIIと血清カリウムの調節を受ける。そのため下垂体の障害でACTHが欠乏しても、アルドステロンの分泌は比較的保たれる。', '{"A": "主に網状層から分泌される副腎アンドロゲンである。", "B": "副腎髄質から分泌されるカテコラミンである。", "C": "副腎髄質と交感神経の終末から分泌されるカテコラミンである。", "E": "球状層から分泌される鉱質コルチコイドである。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '副腎髄質のアドレナリン合成', 2, 'CBT', '副腎髄質から分泌されるカテコラミンの約8割はアドレナリンで、交感神経の終末では主にノルアドレナリンが放出される。副腎髄質でノルアドレナリンをアドレナリンに変える酵素の発現を高めているものはどれか。', '[{"key": "A", "text": "球状層から分泌されるアルドステロン"}, {"key": "B", "text": "膵臓から分泌されるインスリン"}, {"key": "C", "text": "甲状腺から分泌される甲状腺ホルモン"}, {"key": "D", "text": "下垂体後葉から分泌されるバソプレシン"}, {"key": "E", "text": "高濃度のコルチゾール"}]'::jsonb, 'E', '副腎の血液は皮質から髄質へ流れるため、髄質は高濃度のコルチゾールにさらされる。コルチゾールはフェニルエタノールアミンN-メチル基転移酵素の発現を高め、ノルアドレナリンがアドレナリンに変換される。副腎外の傍神経節から生じる褐色細胞腫がノルアドレナリンを主に分泌するのは、この酵素が乏しいためである。', '{"A": "アドレナリン合成の酵素の発現には関わらない。", "B": "アドレナリン合成の酵素の発現には関わらない。", "C": "アドレナリン合成の酵素の発現を高める主な因子ではない。", "D": "アドレナリン合成の酵素の発現には関わらない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'コルチゾールの作用', 2, 'CBT', '副腎皮質ステロイドを長期に内服している患者では、コルチゾールの過剰と同じ変化が起こる。コルチゾールの作用として正しいのはどれか。', '[{"key": "A", "text": "肝での糖新生を促進する"}, {"key": "B", "text": "筋での蛋白質合成を促進する"}, {"key": "C", "text": "血中の好酸球を増加させる"}, {"key": "D", "text": "骨芽細胞による骨形成を促進する"}, {"key": "E", "text": "炎症性サイトカインの産生を促進する"}]'::jsonb, 'A', 'コルチゾールは肝での糖新生を促し、末梢でのブドウ糖の利用を抑えて血糖を上げる。筋の蛋白質を分解し、脂肪を体幹に再分布させる。抗炎症・免疫抑制作用をもち、好酸球とリンパ球を減らして好中球を増やす。過剰になると中心性肥満、満月様顔貌、皮膚の菲薄化、高血糖、骨粗鬆症、易感染性などを示す（Cushing症候群）。', '{"B": "筋の蛋白質を分解し、糖新生の材料となるアミノ酸を供給する。", "C": "好酸球とリンパ球を減少させ、好中球を増加させる。", "D": "骨形成を抑えて骨粗鬆症の原因となる。", "E": "炎症性サイトカインの産生を抑え、抗炎症作用を示す。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '21-水酸化酵素欠損症', 2, 'CBT', '先天性副腎皮質過形成の約9割は21-水酸化酵素欠損症で、新生児マススクリーニングの対象となっている。この酵素の欠損で過剰に産生されるホルモンはどれか。', '[{"key": "A", "text": "アドレナリン"}, {"key": "B", "text": "副腎アンドロゲン"}, {"key": "C", "text": "コルチゾール"}, {"key": "D", "text": "アルドステロン"}, {"key": "E", "text": "デオキシコルチコステロン"}]'::jsonb, 'B', '21-水酸化酵素が欠損するとコルチゾールとアルドステロンがつくれず、負のフィードバックが外れてACTHが増える。前駆体の17-ヒドロキシプロゲステロンが蓄積し、副腎アンドロゲンの合成へ流れる。女児では外性器の男性化が、重症例では塩喪失による低ナトリウム血症、高カリウム血症、脱水が生後早期に生じる。治療は糖質コルチコイドと鉱質コルチコイドの補充である。', '{"A": "副腎髄質のホルモンで、この酵素欠損で過剰にはならない（髄質に届くコルチゾールが減り、むしろ低下しやすい）。", "C": "合成に21-水酸化が必要なため、産生が低下する。", "D": "合成に21-水酸化が必要なため、産生が低下する。", "E": "合成に21-水酸化が必要なため、産生が低下する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'インスリン分泌の機序', 2, 'CBT', 'スルホニル尿素薬は、膵β細胞に直接作用してインスリン分泌を促す。ブドウ糖の刺激で膵β細胞からインスリンが分泌される機序として正しいのはどれか。', '[{"key": "A", "text": "ナトリウムポンプが止まってナトリウムが蓄積する"}, {"key": "B", "text": "細胞外のカルシウムが減ることで分泌小胞が放出される"}, {"key": "C", "text": "ATP感受性Kチャネルが閉じて脱分極する"}, {"key": "D", "text": "ATPが減ってATP感受性カリウムチャネルが開き、過分極する"}, {"key": "E", "text": "ブドウ糖が細胞膜の受容体に結合してcAMPを増やす"}]'::jsonb, 'C', '膵β細胞はGLUT2でブドウ糖を取り込み、グルコキナーゼでリン酸化して代謝し、ATPを増やす。ATP/ADP比の上昇でATP感受性カリウムチャネルが閉じると膜が脱分極し、電位依存性カルシウムチャネルからカルシウムが流入してインスリンの分泌顆粒が放出される。スルホニル尿素薬はこのチャネルのSUR1に結合して閉じさせる。このチャネルの遺伝子異常は新生児糖尿病の原因となる。', '{"A": "インスリン分泌の機序ではない。", "B": "カルシウムの流入が分泌の引き金となる。", "D": "ブドウ糖の代謝でATPは増え、チャネルは閉じる。", "E": "ブドウ糖は輸送体で取り込まれて代謝されることで作用する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'インクレチン', 2, 'CBT', 'ブドウ糖を経口で摂取すると、同じ量を静脈内に投与したときより多くのインスリンが分泌される。この差を生む、食後に腸管から分泌されるホルモンはどれか。', '[{"key": "A", "text": "ソマトスタチン"}, {"key": "B", "text": "セクレチン"}, {"key": "C", "text": "ガストリン"}, {"key": "D", "text": "GLP-1"}, {"key": "E", "text": "グルカゴン"}]'::jsonb, 'D', 'GLP-1（グルカゴン様ペプチド1）は小腸下部から結腸のL細胞から、GIPは十二指腸と空腸のK細胞から分泌され、ブドウ糖濃度が高いときにだけインスリン分泌を増やす（インクレチン効果）。GLP-1はグルカゴン分泌の抑制、胃排出の遅延、食欲の抑制にも働く。GLP-1は酵素DPP-4で速やかに分解されるため、DPP-4阻害薬や分解されにくいGLP-1受容体作動薬が糖尿病や肥満症の治療に用いられる。', '{"A": "インスリンやグルカゴンの分泌を抑えるホルモンである。", "B": "膵臓からの重炭酸イオンの分泌を促すホルモンである。", "C": "胃酸の分泌を促すホルモンである。", "E": "膵α細胞から分泌され、血糖を上げるホルモンである。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'グルカゴンの作用', 2, 'CBT', '空腹時に血糖が下がると、膵α細胞からグルカゴンが分泌される。グルカゴンの主な作用として正しいのはどれか。', '[{"key": "A", "text": "骨格筋でグリコーゲン分解を強く促す"}, {"key": "B", "text": "脂肪組織でトリアシルグリセロールの合成を促す"}, {"key": "C", "text": "肝で脂肪酸の合成を促す"}, {"key": "D", "text": "骨格筋へのブドウ糖の取り込みを促す"}, {"key": "E", "text": "肝でグリコーゲン分解と糖新生を促す"}]'::jsonb, 'E', 'グルカゴンは肝のG蛋白質共役型受容体からcAMPを増やし、グリコーゲンの分解と糖新生を促して肝からのブドウ糖放出を増やす。脂肪酸の合成を抑えてβ酸化とケトン体の産生を促す。インスリンが欠乏してグルカゴンが優位になると、高血糖とケトアシドーシスに向かう。重症の低血糖で経口摂取できないときにグルカゴンを投与することがある。', '{"A": "骨格筋にはグルカゴン受容体がほとんどなく、主な標的は肝である。", "B": "脂肪の合成はインスリンの作用である。", "C": "グルカゴンは脂肪酸の合成を抑え、β酸化とケトン体の産生を促す。", "D": "インスリンの作用である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'IGF-1', 2, 'CBT', '下垂体腺腫で成長ホルモンが過剰に分泌されると、成人では手足の肥大や顔貌の変化をきたす。成長ホルモンの成長促進作用の多くを仲介し、主に肝で産生される因子はどれか。', '[{"key": "A", "text": "IGF-1"}, {"key": "B", "text": "ソマトスタチン"}, {"key": "C", "text": "成長ホルモン放出ホルモン"}, {"key": "D", "text": "グレリン"}, {"key": "E", "text": "レプチン"}]'::jsonb, 'A', '成長ホルモンは肝などでIGF-1（インスリン様成長因子1）の産生を促し、IGF-1が骨端軟骨の軟骨細胞の増殖などを担う。成長ホルモン自体にも脂肪分解や血糖を上げる作用がある。IGF-1は血中濃度が一日を通じて安定しているため、先端巨大症の診断や治療効果の判定に用いられる。成長ホルモンは睡眠中や空腹時に拍動的に分泌される。', '{"B": "成長ホルモンの分泌を抑える視床下部のホルモンである。", "C": "視床下部から分泌されて成長ホルモンの分泌を促す。", "D": "主に胃から分泌され、成長ホルモンの分泌と食欲を促す。", "E": "脂肪組織から分泌され、食欲を抑える。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'プロラクチンの分泌調節', 2, 'CBT', '統合失調症の治療薬を内服している女性が、無月経と乳汁の分泌を訴えた。下垂体からのプロラクチン分泌を主に抑制している視床下部の物質はどれか。', '[{"key": "A", "text": "副腎皮質刺激ホルモン放出ホルモン"}, {"key": "B", "text": "ドパミン"}, {"key": "C", "text": "甲状腺刺激ホルモン放出ホルモン"}, {"key": "D", "text": "オキシトシン"}, {"key": "E", "text": "ゴナドトロピン放出ホルモン"}]'::jsonb, 'B', 'プロラクチンは他の下垂体前葉ホルモンと異なり、視床下部からのドパミンによる抑制が主な調節となる。ドパミンD2受容体を遮断する抗精神病薬や制吐薬では抑制が外れ、高プロラクチン血症となる。下垂体茎が圧迫されてドパミンが届かなくなったときも上昇する。高プロラクチン血症はGnRHの分泌を抑え、無月経や不妊をきたす。プロラクチノーマの治療にはドパミン作動薬を用いる。', '{"A": "ACTHの分泌を促すホルモンである。", "C": "プロラクチンの分泌を促す方向に働く。", "D": "射乳や子宮収縮に働き、プロラクチンの主な抑制因子ではない。", "E": "LHとFSHの分泌を促すホルモンである。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'オキシトシンの作用', 2, 'CBT', '授乳中に児が乳頭を吸うと、反射的に乳汁が射出され、子宮も収縮する。この反射で分泌されるオキシトシンの作用として正しいのはどれか。', '[{"key": "A", "text": "卵胞を成熟させて排卵を起こす"}, {"key": "B", "text": "基礎体温を上昇させる"}, {"key": "C", "text": "筋上皮細胞を収縮させ射乳を起こす"}, {"key": "D", "text": "乳腺の腺房細胞に働いて乳汁の産生を促す"}, {"key": "E", "text": "集合管で水の再吸収を促す"}]'::jsonb, 'C', 'オキシトシンは視床下部の室傍核と視索上核でつくられ、下垂体後葉から分泌される。乳頭への吸啜刺激で分泌され、筋上皮細胞を収縮させて乳汁を射出させる。分娩時には子宮平滑筋を収縮させ、分娩の進行や産後の子宮の収縮を助ける。分娩誘発や産後の弛緩出血の治療に用いられる。', '{"A": "FSHとLHの作用である。", "B": "プロゲステロンの作用である。", "D": "乳汁の産生を促すのはプロラクチンである。", "E": "主にバソプレシンの作用である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'カルシトニン', 2, 'CBT', '甲状腺髄様癌では、血中のカルシトニンとCEAが腫瘍マーカーとなる。カルシトニンを分泌する細胞はどれか。', '[{"key": "A", "text": "副甲状腺の主細胞"}, {"key": "B", "text": "骨の破骨細胞"}, {"key": "C", "text": "腎の近位尿細管上皮細胞"}, {"key": "D", "text": "傍濾胞細胞（C細胞）"}, {"key": "E", "text": "甲状腺の濾胞上皮細胞"}]'::jsonb, 'D', 'カルシトニンは甲状腺の傍濾胞細胞から分泌され、破骨細胞の骨吸収を抑えて血中カルシウムを下げる。ヒトでの生理的な役割は小さく、甲状腺を全摘してもカルシウム代謝に大きな異常は生じない。傍濾胞細胞から生じる髄様癌は、RET遺伝子の異常による多発性内分泌腫瘍症2型の一部として発生することがある。', '{"A": "副甲状腺ホルモンを分泌する細胞である。", "B": "骨を吸収する細胞で、カルシトニンの作用を受ける側である。", "C": "活性型ビタミンDをつくる細胞である。", "E": "甲状腺ホルモンを合成・分泌する細胞である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '副甲状腺ホルモンの分泌調節', 2, 'CBT', '副甲状腺の主細胞は、細胞膜のカルシウム感知受容体で血中のカルシウム濃度を常に監視している。副甲状腺ホルモンの分泌を刺激するものはどれか。', '[{"key": "A", "text": "血中のイオン化カルシウム濃度の上昇"}, {"key": "B", "text": "活性型ビタミンDの増加"}, {"key": "C", "text": "血中のリン濃度の低下"}, {"key": "D", "text": "カルシトニンの増加"}, {"key": "E", "text": "イオン化カルシウムの低下"}]'::jsonb, 'E', 'イオン化カルシウムが下がると、カルシウム感知受容体の刺激が減って副甲状腺ホルモンが分泌される。高リン血症と活性型ビタミンDの不足は、慢性腎臓病で二次性副甲状腺機能亢進症を起こす要因となる。カルシウム感知受容体作動薬（カルシミメティクス）は副甲状腺ホルモンの分泌を抑える。', '{"A": "カルシウム感知受容体が刺激され、分泌は抑えられる。", "B": "副甲状腺ホルモンの遺伝子の転写を抑え、分泌を減らす。", "C": "リン濃度の上昇が分泌を刺激する方向に働く。", "D": "副甲状腺ホルモンの分泌を刺激する因子ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '排卵の引き金', 2, 'CBT', '月経周期の卵胞期後半には、成熟した卵胞から大量のエストロゲンが分泌される。排卵を直接引き起こす変化はどれか。', '[{"key": "A", "text": "LHの急激な分泌増加"}, {"key": "B", "text": "卵胞刺激ホルモン（FSH）の分泌の停止"}, {"key": "C", "text": "プロゲステロンの急激な分泌増加"}, {"key": "D", "text": "ヒト絨毛性ゴナドトロピンの分泌"}, {"key": "E", "text": "プロラクチンの急激な分泌増加"}]'::jsonb, 'A', '卵胞期の後半にエストロゲンが高い濃度で一定期間続くと、通常の負のフィードバックが正のフィードバックに切り替わり、黄体形成ホルモン（LH）が急激に分泌される（LHサージ）。LHサージの開始からおよそ36時間後に排卵が起こる。排卵後の卵胞は黄体となり、プロゲステロンとエストロゲンを分泌する。尿中LHの検査で排卵の時期を予測できる。', '{"B": "FSHもLHとともに一過性に増えるが、排卵の直接の引き金ではない。", "C": "プロゲステロンは主に排卵後の黄体から分泌される。", "D": "妊娠が成立したあとに胎盤から分泌されるホルモンである。", "E": "プロラクチンの増加は排卵を抑える方向に働く。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'プロゲステロンの作用', 2, 'CBT', '排卵後に基礎体温が上昇し、約2週間の高温期が続いたのちに月経が始まる。排卵後の黄体から主に分泌され、子宮内膜を分泌期に変化させるホルモンはどれか。', '[{"key": "A", "text": "オキシトシン"}, {"key": "B", "text": "プロゲステロン"}, {"key": "C", "text": "エストラジオール"}, {"key": "D", "text": "黄体形成ホルモン"}, {"key": "E", "text": "卵胞刺激ホルモン"}]'::jsonb, 'B', '黄体から分泌されるプロゲステロンは、エストロゲンで増殖した子宮内膜を分泌期に変え、受精卵の着床に適した状態にする。体温調節中枢に作用して基礎体温を0.3〜0.5°C上げるため、排卵後は高温期となる。妊娠が成立しなければ黄体は約2週間で退縮し、プロゲステロンの低下で内膜が剥がれて月経が起こる。', '{"A": "射乳や子宮の収縮を起こすホルモンである。", "C": "卵胞期に子宮内膜を増殖させるホルモンである。", "D": "下垂体前葉から分泌され、排卵と黄体の形成を促すホルモンである。", "E": "下垂体前葉から分泌され、卵胞の発育を促すホルモンである。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'ヒト絨毛性ゴナドトロピン', 2, 'CBT', '妊娠が成立すると、黄体は退縮せずに妊娠初期のプロゲステロン分泌を続ける。妊娠初期に黄体を維持しているホルモンはどれか。', '[{"key": "A", "text": "ヒト胎盤性ラクトーゲン"}, {"key": "B", "text": "オキシトシン"}, {"key": "C", "text": "ヒト絨毛性ゴナドトロピン（hCG）"}, {"key": "D", "text": "下垂体から分泌される黄体形成ホルモン"}, {"key": "E", "text": "プロラクチン"}]'::jsonb, 'C', 'hCGは着床した胚の栄養膜合胞体層から分泌され、LHと同じ受容体に作用して黄体を維持し、プロゲステロンの分泌を続けさせる。妊娠8〜10週ごろに最も多くなり、その後は胎盤がプロゲステロンを産生するようになる。妊娠検査薬は尿中のhCGを検出する。胞状奇胎や絨毛癌では著しく高値となる。', '{"A": "妊娠後期に増え、母体の糖や脂質の代謝を変化させる。", "B": "分娩時の子宮の収縮や射乳に働く。", "D": "妊娠中は抑制されており、黄体を維持する主体ではない。", "E": "乳腺の発達や乳汁の産生に働き、ヒトの黄体を維持する主体ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'Leydig細胞', 2, 'CBT', '精巣では、精子の形成とテストステロンの産生が異なる細胞によって担われている。黄体形成ホルモンの刺激を受けてテストステロンを産生する細胞はどれか。', '[{"key": "A", "text": "精祖細胞"}, {"key": "B", "text": "精巣上体の上皮細胞"}, {"key": "C", "text": "前立腺の腺上皮細胞"}, {"key": "D", "text": "Leydig細胞"}, {"key": "E", "text": "Sertoli細胞"}]'::jsonb, 'D', '精巣の間質にあるLeydig細胞はLHの刺激でテストステロンをつくる。Sertoli細胞はFSHとテストステロンの刺激で精子形成を支え、インヒビンを分泌してFSHの分泌を抑える。精細管の中のテストステロン濃度は血中よりはるかに高く、精子形成に欠かせない。外からテストステロンを投与するとLHが抑えられ、精子形成はむしろ低下する。', '{"A": "精子のもととなる生殖細胞である。", "B": "精子の成熟と貯蔵に関わる細胞である。", "C": "精液の成分を分泌する細胞である。", "E": "精子形成を支持し、インヒビンや抗Müller管ホルモンを分泌する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '閉経後のホルモン変化', 2, 'CBT', '52歳の女性。1年前から月経がなく、ほてりと発汗を訴える。この女性の血中で上昇しているホルモンはどれか。', '[{"key": "A", "text": "エストラジオール"}, {"key": "B", "text": "プロゲステロン"}, {"key": "C", "text": "インヒビン"}, {"key": "D", "text": "抗Müller管ホルモン"}, {"key": "E", "text": "卵胞刺激ホルモン"}]'::jsonb, 'E', '閉経後は卵巣の卵胞が枯渇してエストロゲンとインヒビンが低下し、負のフィードバックが外れて卵胞刺激ホルモン（FSH）とLHが上昇する。特にFSHの上昇が目立つ。エストロゲンの低下は、ほてりなどの血管運動神経症状、腟の萎縮、骨量の減少、脂質異常症の原因となる。抗Müller管ホルモンは卵巣予備能の指標として用いられる。', '{"A": "卵巣の卵胞が枯渇するため低下する。", "B": "排卵がなく黄体がつくられないため低下する。", "C": "卵胞の顆粒膜細胞から分泌されるため、卵胞の枯渇で低下する。", "D": "発育中の卵胞から分泌されるため、卵胞の枯渇で低下する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '産後の乳汁分泌', 2, 'CBT', '妊娠中はプロラクチンが高値であるにもかかわらず、本格的な乳汁の分泌は出産後に始まる。出産後に乳汁の分泌が本格化する主な理由はどれか。', '[{"key": "A", "text": "エストロゲンとプロゲステロンが急に低下するから"}, {"key": "B", "text": "出産後に初めて下垂体からプロラクチンの分泌が始まるから"}, {"key": "C", "text": "出産後にオキシトシンの分泌が完全に止まるから"}, {"key": "D", "text": "出産後にhCGが急に上昇するから"}, {"key": "E", "text": "出産後にドパミンの分泌が増えるから"}]'::jsonb, 'A', '妊娠中は胎盤から大量に分泌されるエストロゲンとプロゲステロンが乳腺の発達を促す一方で、プロラクチンによる乳汁の産生を抑えている。胎盤が娩出されるとこれらが急に低下し、プロラクチンの作用が現れて乳汁の分泌が本格化する。胎盤の一部が子宮内に残ると乳汁の分泌が遅れることがある。', '{"B": "プロラクチンは妊娠中から高値である。", "C": "オキシトシンは授乳のたびに分泌され、射乳を起こす。", "D": "hCGは胎盤の娩出後に低下する。", "E": "ドパミンはプロラクチンの分泌を抑える方向に働く。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '甲状腺ホルモンの作用', 2, 'CBT', '甲状腺ホルモンは全身のほぼすべての細胞に作用し、代謝の速度を調節している。甲状腺ホルモンの作用として正しいのはどれか。', '[{"key": "A", "text": "血中コレステロールを上昇させる"}, {"key": "B", "text": "基礎代謝量を増加させる"}, {"key": "C", "text": "心拍数を低下させる"}, {"key": "D", "text": "腸管の運動を低下させる"}, {"key": "E", "text": "深部腱反射の弛緩相を遅らせる"}]'::jsonb, 'B', '甲状腺ホルモンはナトリウムポンプや熱産生に関わる遺伝子の発現を増やし、酸素消費量と熱産生を高めて基礎代謝量を増やす。心臓ではβ受容体を増やしてカテコラミンへの反応を高め、心拍数と心拍出量を増やす。小児期の神経系の発達と骨の成長にも不可欠で、先天性甲状腺機能低下症は新生児マススクリーニングで早期に発見して治療する。', '{"A": "LDL受容体を増やして血中コレステロールを下げる。", "C": "心臓のβ受容体を増やすなどして心拍数を増加させる。", "D": "腸管の運動を促し、過剰では下痢をきたす。", "E": "甲状腺機能低下症でみられる所見である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'GnRHの分泌様式', 2, 'CBT', '前立腺癌の治療では、GnRH受容体の作動薬を持続的に投与してテストステロンを低下させる。作動薬なのにテストステロンが低下する理由と関係する、生理的なGnRHの分泌様式はどれか。', '[{"key": "A", "text": "食後にだけ分泌される"}, {"key": "B", "text": "月経周期の排卵の日にだけ分泌される"}, {"key": "C", "text": "パルス状の分泌"}, {"key": "D", "text": "一日中一定の濃度での持続的な分泌"}, {"key": "E", "text": "早朝に一度だけ大量に分泌される"}]'::jsonb, 'C', 'GnRHは視床下部から数十分〜数時間ごとにパルス状に分泌され、この間欠的な刺激によって下垂体のLHとFSHの分泌が保たれる。GnRH作動薬を持続的に投与すると、はじめは一時的にLHが増える（フレアアップ）が、やがて受容体が脱感作してLHとFSHが低下し、性ホルモンが去勢レベルまで下がる。これを前立腺癌、子宮内膜症、思春期早発症の治療に用いる。', '{"A": "GnRHの生理的な分泌様式ではない。", "B": "GnRHは周期を通じてパルス状に分泌される。", "D": "持続的に刺激すると受容体が脱感作し、LHとFSHの分泌はかえって止まる。", "E": "GnRHの生理的な分泌様式ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'インスリン依存性のブドウ糖取り込み', 2, 'CBT', 'インスリンは、ある種の組織で細胞膜のブドウ糖輸送体を増やして血中のブドウ糖を取り込ませる。インスリンの作用でブドウ糖の取り込みが大きく増える組織はどれか。', '[{"key": "A", "text": "赤血球"}, {"key": "B", "text": "肝臓"}, {"key": "C", "text": "膵β細胞"}, {"key": "D", "text": "骨格筋"}, {"key": "E", "text": "脳"}]'::jsonb, 'D', '骨格筋と脂肪組織の細胞では、インスリンの刺激で細胞内の小胞にあるGLUT4が細胞膜へ移動し、ブドウ糖の取り込みが増える。食後のブドウ糖の多くは骨格筋に取り込まれる。運動もインスリンと別の経路でGLUT4を細胞膜へ移動させるため、運動療法はインスリン抵抗性を改善する。脳や赤血球はインスリンに依存しないため、低血糖の影響を強く受ける。', '{"A": "GLUT1でインスリンに依存せずにブドウ糖を取り込む。", "B": "GLUT2で血糖の濃度に応じて取り込み、輸送体の数はインスリンで増えない。", "C": "GLUT2で血糖の濃度に応じてブドウ糖を取り込み、血糖を感知する。", "E": "主にGLUT1やGLUT3で、インスリンに依存せずにブドウ糖を取り込む。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'コルチゾールの日内変動', 2, 'CBT', '副腎皮質機能の検査では、採血の時刻を決めて血中コルチゾールを測定する。健常者の血中コルチゾール濃度の日内変動として正しいのはどれか。', '[{"key": "A", "text": "夕方から夜にかけて最も高く、早朝に最も低い"}, {"key": "B", "text": "一日を通じてほぼ一定である"}, {"key": "C", "text": "食事のあとにだけ上昇する"}, {"key": "D", "text": "深夜に最も高く、昼に最も低い"}, {"key": "E", "text": "早朝に最も高く、深夜に最も低い"}]'::jsonb, 'E', 'ACTHとコルチゾールは概日リズムに従い、起床前から早朝に最も高く、深夜に最も低くなる。Cushing症候群ではこのリズムが失われ、深夜にもコルチゾールが下がらない。そのため深夜の血中や唾液中のコルチゾールの測定がスクリーニングに使われる。ステロイドを補充するときは、生理的なリズムに合わせて朝に多く投与する。', '{"A": "日内変動の向きが逆である。", "B": "ACTHの分泌リズムに従って大きく変動する。", "C": "食事だけで決まる変動ではない。", "D": "健常者では深夜に最も低くなる。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '赤血球の寿命', 2, 'CBT', '赤血球は骨髄でつくられて末梢血に出たあと、一定の期間で処理される。健常成人の赤血球の寿命と、老化した赤血球が主に処理される臓器の組合せはどれか。', '[{"key": "A", "text": "約120日 — 脾臓"}, {"key": "B", "text": "約30日 — 肝臓"}, {"key": "C", "text": "約10日 — 骨髄"}, {"key": "D", "text": "約1年 — 腎臓"}, {"key": "E", "text": "約120日 — 肺"}]'::jsonb, 'A', '赤血球は核をもたず、蛋白質を新たにつくれないため、約120日で膜の柔軟性が失われる。狭い脾洞を通り抜けられなくなった赤血球は、脾臓の赤脾髄のマクロファージに捕らえられて処理される。ヘムからはビリルビンが、鉄は再利用される。遺伝性球状赤血球症では変形能の低い赤血球が脾臓で壊されるため、脾摘で溶血が改善する。', '{"B": "赤血球の寿命は約120日で、30日ではない。", "C": "約7〜10日は血小板の寿命に近い値である。", "D": "赤血球の寿命は約120日で、腎臓は処理の主な場ではない。", "E": "肺は老化赤血球を処理する主な臓器ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '網赤血球', 2, 'CBT', '貧血の原因を考えるとき、骨髄が赤血球を十分につくれているかを最初に確かめる。骨髄での赤血球の産生の程度を反映する指標はどれか。', '[{"key": "A", "text": "血清鉄"}, {"key": "B", "text": "網赤血球数"}, {"key": "C", "text": "平均赤血球容積（MCV）"}, {"key": "D", "text": "血清フェリチン"}, {"key": "E", "text": "血清ハプトグロビン"}]'::jsonb, 'B', '網赤血球は骨髄から出たばかりの若い赤血球で、リボソームRNAが網状に染まり、1〜2日で成熟赤血球になる。溶血や出血で骨髄が反応すると増え、再生不良性貧血や鉄・ビタミンB12の欠乏では増えない。鉄欠乏性貧血に鉄剤を投与すると、1週間ほどで網赤血球が増える（網赤血球反応）。', '{"A": "血中の鉄の量で、日内変動が大きく産生の指標ではない。", "C": "赤血球の大きさの指標で、貧血の分類に用いる。", "D": "体内の貯蔵鉄の指標である。", "E": "溶血で消費されて低下する指標で、産生の程度は示さない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '外因系凝固の開始', 2, 'CBT', '血管が傷つくと、血管の外の細胞がもつ因子に血液が触れて、速やかに凝固反応が始まる。外因系の凝固反応を開始させる因子の組合せはどれか。', '[{"key": "A", "text": "プラスミノゲンと組織プラスミノゲン活性化因子"}, {"key": "B", "text": "アンチトロンビンとヘパリン"}, {"key": "C", "text": "組織因子と第VII因子"}, {"key": "D", "text": "第XII因子と高分子キニノゲン"}, {"key": "E", "text": "von Willebrand因子と血小板"}]'::jsonb, 'C', '血管の外の線維芽細胞などが表面にもつ組織因子に第VII因子が結合して活性化し、第X因子と第IX因子を活性化してトロンビンの生成に向かう。プロトロンビン時間（PT）は外因系と共通系を反映し、ビタミンK欠乏やワルファリンの効果の指標となる。第VII因子は半減期が短いため、ビタミンKが欠乏すると最初にPTが延長する。', '{"A": "線溶系の組合せである。", "B": "凝固を抑える側の組合せである。", "D": "内因系の凝固反応の始まりに関わる因子である。", "E": "一次止血で血小板を血管壁に粘着させる組合せである。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '血友病AとAPTT', 2, 'CBT', '5歳の男児。軽い打撲のあとに膝関節が腫れ、関節内出血と診断された。母方の叔父にも同じ病気がある。この患児で延長している可能性が最も高い検査はどれか。', '[{"key": "A", "text": "出血時間"}, {"key": "B", "text": "血小板数"}, {"key": "C", "text": "血漿フィブリノゲン濃度"}, {"key": "D", "text": "APTT"}, {"key": "E", "text": "PT"}]'::jsonb, 'D', '血友病Aは第VIII因子、血友病Bは第IX因子の欠乏によるX連鎖潜性遺伝の疾患で、ほとんどが男性に発症する。内因系の因子が欠乏するため、活性化部分トロンボプラスチン時間（APTT）が延長し、プロトロンビン時間（PT）は正常である。関節内出血や筋肉内出血が特徴で、繰り返すと関節が変形する。欠乏した因子の製剤や、第VIII因子の働きを代替する二重特異性抗体で治療する。', '{"A": "血小板の数と機能を反映し、凝固因子の欠乏では延長しない。", "B": "凝固因子の欠乏では減少しない。", "C": "第VIII因子の欠乏では低下しない。", "E": "プロトロンビン時間は外因系の指標で、第VIII因子の欠乏では延長しない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'アンチトロンビン', 2, 'CBT', '静脈血栓症の治療に用いるヘパリンは、それ自体では凝固因子を阻害しない。ヘパリンの抗凝固作用を仲介する血漿蛋白はどれか。', '[{"key": "A", "text": "プロテインC"}, {"key": "B", "text": "プラスミノゲン"}, {"key": "C", "text": "フィブリノゲン"}, {"key": "D", "text": "ビタミンK"}, {"key": "E", "text": "アンチトロンビン"}]'::jsonb, 'E', 'アンチトロンビンはトロンビンや活性化第X因子などのセリンプロテアーゼを阻害する。ヘパリンが結合するとその阻害作用が1000倍ほどに強まる。そのため先天性アンチトロンビン欠乏症や、アンチトロンビンが消費される播種性血管内凝固では、ヘパリンの効果が十分に得られないことがある。先天性の欠乏は若年性の静脈血栓症の原因となる。', '{"A": "トロンボモジュリンに結合したトロンビンで活性化され、第V因子と第VIII因子を不活化する。", "B": "活性化されてプラスミンとなり、フィブリンを分解する線溶系の蛋白である。", "C": "トロンビンによってフィブリンに変わる凝固の基質である。", "D": "蛋白ではなく、凝固因子のγ-カルボキシ化に必要なビタミンである。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '線溶系', 2, 'CBT', '血管の修復が進むと、止血のためにできたフィブリン血栓は溶かされて取り除かれる。フィブリンを分解する酵素はどれか。', '[{"key": "A", "text": "プラスミン"}, {"key": "B", "text": "トロンビン"}, {"key": "C", "text": "組織プラスミノゲン活性化因子"}, {"key": "D", "text": "第XIII因子"}, {"key": "E", "text": "アンチトロンビン"}]'::jsonb, 'A', '血管内皮から放出される組織プラスミノゲン活性化因子（t-PA）は、フィブリンの上でプラスミノゲンをプラスミンに変え、プラスミンがフィブリンを分解する。架橋されたフィブリンの分解で生じるDダイマーは、体内で血栓ができて溶かされていることを示し、深部静脈血栓症や肺血栓塞栓症の除外に用いられる。遺伝子組換えのt-PAは急性期脳梗塞の血栓溶解療法に用いられる。', '{"B": "フィブリノゲンをフィブリンに変える凝固の酵素である。", "C": "プラスミノゲンをプラスミンに変える酵素で、フィブリンを直接は分解しない。", "D": "フィブリンどうしを架橋して血栓を安定させる。", "E": "トロンビンなどを阻害する凝固抑制因子である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'von Willebrand因子', 2, 'CBT', '血管内皮が傷ついて内皮下のコラーゲンが露出すると、まず血小板がそこに粘着する。血小板の粘着を仲介し、血小板膜の糖蛋白GPIbに結合する因子はどれか。', '[{"key": "A", "text": "プロスタサイクリン"}, {"key": "B", "text": "von Willebrand因子"}, {"key": "C", "text": "フィブリノゲン"}, {"key": "D", "text": "トロンボキサンA2"}, {"key": "E", "text": "第VIII因子"}]'::jsonb, 'B', 'von Willebrand因子は血管内皮と巨核球でつくられ、露出したコラーゲンと血小板のGPIbを橋渡しして粘着させる。血中では第VIII因子と結合してその分解を防いでいる。von Willebrand病は最も多い先天性出血性疾患で、出血時間とAPTTが延長しうる。GPIbの欠損はBernard-Soulier症候群、GPIIb/IIIaの欠損は血小板無力症の原因となる。', '{"A": "血管内皮が産生し、血小板の凝集を抑える。", "C": "活性化した血小板のGPIIb/IIIaに結合し、血小板どうしの凝集を仲介する。", "D": "活性化した血小板が放出し、血小板の凝集と血管の収縮を促す。", "E": "内因系の凝固因子で、血中ではvon Willebrand因子と結合して安定化している。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'ABO式血液型の抗体', 2, 'CBT', 'ABO式血液型では、赤血球にない抗原に対する抗体が、輸血や妊娠の経験がなくても血漿中に存在する。O型の人の血漿中に存在する抗体はどれか。', '[{"key": "A", "text": "抗A抗体も抗B抗体もない"}, {"key": "B", "text": "抗D抗体"}, {"key": "C", "text": "抗A抗体と抗B抗体"}, {"key": "D", "text": "抗A抗体のみ"}, {"key": "E", "text": "抗B抗体のみ"}]'::jsonb, 'C', 'ABO式血液型の抗A抗体と抗B抗体は、腸内細菌などがもつ似た糖鎖抗原への反応で生後に自然に生じる規則抗体で、主にIgMである。O型の赤血球はA抗原もB抗原ももたないため血漿中に両方の抗体があり、AB型にはどちらもない。ABO不適合輸血では、IgM抗体が補体を活性化して血管内で急激な溶血を起こし、ショックや腎不全をきたす。', '{"A": "AB型の人の血漿の特徴である。", "B": "Rh陰性の人が感作されたときに生じる抗体で、生まれつき存在するものではない。", "D": "B型の人の血漿中にある抗体である。", "E": "A型の人の血漿中にある抗体である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '脾臓の白脾髄', 2, 'CBT', '脾臓の割面を肉眼で見ると、赤い組織の中に白い小さな点が散在している。この白脾髄の主な機能はどれか。', '[{"key": "A", "text": "成人でも主な造血の場として赤血球をつくる"}, {"key": "B", "text": "胆汁を産生して十二指腸に分泌する"}, {"key": "C", "text": "エリスロポエチンを分泌して造血を促す"}, {"key": "D", "text": "リンパ球による免疫応答の場となる"}, {"key": "E", "text": "老化した赤血球を捕らえて処理する"}]'::jsonb, 'D', '白脾髄は中心動脈を取り巻くT細胞の鞘と、B細胞のリンパ濾胞からなり、血液中の抗原に対する免疫応答の場となる。赤脾髄は脾索と脾洞からなり、老化した赤血球や血中の異物を処理する。脾臓は莢膜をもつ細菌の除去に特に重要で、脾摘後は肺炎球菌などによる重症感染症（脾摘後重症感染症）の危険が高く、ワクチンの接種が勧められる。', '{"A": "脾臓での造血は胎児期にみられ、成人では通常行われない。", "B": "肝臓の機能である。", "C": "主に腎臓の機能である。", "E": "主に赤脾髄の機能である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'リンパ節の傍皮質', 2, 'CBT', 'リンパ節の中では、T細胞とB細胞がそれぞれ決まった領域に集まっている。リンパ節でT細胞が主に分布する領域はどれか。', '[{"key": "A", "text": "皮質のリンパ濾胞"}, {"key": "B", "text": "髄索"}, {"key": "C", "text": "辺縁洞"}, {"key": "D", "text": "被膜"}, {"key": "E", "text": "傍皮質"}]'::jsonb, 'E', 'リンパ節の皮質にはB細胞のリンパ濾胞があり、その深部の傍皮質にT細胞が集まる。傍皮質には高内皮細静脈があり、血中のリンパ球はここからリンパ節に入る。樹状細胞は抗原を傍皮質に運んでT細胞に提示する。胸腺が形成されないDiGeorge症候群では傍皮質のT細胞が少なく、B細胞が欠損するBrutonの無γグロブリン血症ではリンパ濾胞がみられない。', '{"A": "主にB細胞が集まり、抗原刺激で胚中心をつくる。", "B": "形質細胞やマクロファージが多い領域である。", "C": "輸入リンパ管からのリンパが最初に流れ込む洞である。", "D": "リンパ節を包む結合組織で、リンパ球が集まる領域ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '橈骨神経麻痺', 2, 'CBT', '上腕骨骨幹部を骨折した患者で、手関節と手指を伸展できなくなった（下垂手）。損傷された可能性が最も高い神経はどれか。', '[{"key": "A", "text": "橈骨神経"}, {"key": "B", "text": "正中神経"}, {"key": "C", "text": "尺骨神経"}, {"key": "D", "text": "腋窩神経"}, {"key": "E", "text": "筋皮神経"}]'::jsonb, 'A', '橈骨神経は上腕骨の後面の橈骨神経溝をらせん状に走るため、骨幹部の骨折で損傷されやすい。手関節と手指の伸筋が麻痺して下垂手となり、手背の母指と示指の間の感覚が低下する。腕枕での長時間の圧迫でも生じる（土曜夜の麻痺）。肘を伸ばす上腕三頭筋の枝は損傷部位より高い位置で分かれるため、肘の伸展は保たれることが多い。', '{"B": "手根管症候群などで障害され、母指球筋の萎縮や母指の対立障害をきたす。", "C": "肘部管などで障害され、骨間筋の萎縮や鷲手をきたす。", "D": "上腕骨外科頸の骨折や肩関節脱臼で障害され、三角筋の麻痺をきたす。", "E": "上腕二頭筋を支配し、障害されると肘の屈曲が弱くなる。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '手根管症候群', 2, 'CBT', '妊娠中の女性が、夜間から明け方に強くなる母指から環指の橈側のしびれを訴えた。障害されている神経はどれか。', '[{"key": "A", "text": "内側前腕皮神経"}, {"key": "B", "text": "正中神経"}, {"key": "C", "text": "尺骨神経"}, {"key": "D", "text": "橈骨神経浅枝"}, {"key": "E", "text": "筋皮神経"}]'::jsonb, 'B', '手根管は手根骨と横手根靱帯に囲まれたトンネルで、正中神経と指の屈筋腱が通る。妊娠、透析、甲状腺機能低下症、関節リウマチ、手の使いすぎなどで内圧が上がると正中神経が圧迫され、母指から環指の橈側のしびれ、進行すると母指球筋の萎縮と母指の対立障害が生じる。手関節の掌側をたたくとしびれが放散する（Tinel徴候）。', '{"A": "前腕の内側の皮膚感覚を支配する。", "C": "小指と環指の尺側の感覚を支配し、Guyon管や肘部管で障害される。", "D": "手背の母指側の感覚を支配し、手掌のしびれの原因ではない。", "E": "前腕の外側の皮膚感覚を支配し、手指のしびれの原因ではない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '総腓骨神経麻痺', 2, 'CBT', '長時間あぐらをかいていた人や、下肢をギプスで固定された人で、足関節と足趾を背屈できなくなることがある。腓骨頭の付近で圧迫されて下垂足をきたす神経はどれか。', '[{"key": "A", "text": "閉鎖神経"}, {"key": "B", "text": "上殿神経"}, {"key": "C", "text": "総腓骨神経"}, {"key": "D", "text": "脛骨神経"}, {"key": "E", "text": "大腿神経"}]'::jsonb, 'C', '総腓骨神経は坐骨神経から分かれて腓骨頭の外側を皮膚の直下で回るため、外からの圧迫を受けやすい。障害されると前脛骨筋などの足関節と足趾の背屈筋が麻痺して下垂足となり、つま先を高く上げて歩く（鶏歩）。下腿の外側から足背の感覚も低下する。ギプスや体位による圧迫を避けることが予防となる。', '{"A": "大腿の内転筋群を支配する。", "B": "中殿筋と小殿筋を支配し、障害されるとTrendelenburg徴候がみられる。", "D": "下腿後面の筋を支配し、障害されると足関節の底屈が障害される。", "E": "大腿四頭筋を支配し、障害されると膝の伸展が障害される。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '回旋筋腱板', 2, 'CBT', '中高年者で、腕を上げるときの肩の痛みと挙上の困難が続き、回旋筋腱板の断裂が疑われた。回旋筋腱板を構成する筋はどれか。', '[{"key": "A", "text": "上腕二頭筋"}, {"key": "B", "text": "大胸筋"}, {"key": "C", "text": "広背筋"}, {"key": "D", "text": "棘上筋"}, {"key": "E", "text": "三角筋"}]'::jsonb, 'D', '回旋筋腱板は棘上筋、棘下筋、小円筋、肩甲下筋の4つの筋の腱からなり、上腕骨頭を関節窩に引きつけて肩関節を安定させる。最も断裂しやすいのは、肩峰の下を通る棘上筋の腱である。棘上筋は外転の初動を担い、断裂すると腕を上げる途中で痛みが出たり、挙上位を保てずに腕が落ちたりする。', '{"A": "肘の屈曲と前腕の回外に働き、回旋筋腱板には含まれない。", "B": "肩関節の内転と内旋に働き、回旋筋腱板には含まれない。", "C": "肩関節の伸展、内転、内旋に働き、回旋筋腱板には含まれない。", "E": "肩関節を外転させる主な筋だが、回旋筋腱板には含まれない。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '赤筋線維', 2, 'CBT', '骨格筋の筋線維は、収縮の速さと代謝の性質によって赤筋線維と白筋線維に分けられる。赤筋線維（タイプI線維）の特徴として正しいのはどれか。', '[{"key": "A", "text": "解糖系への依存が大きく、疲労しやすい"}, {"key": "B", "text": "収縮が速く、短時間に大きな力を出す"}, {"key": "C", "text": "ミオグロビンが乏しく、白っぽく見える"}, {"key": "D", "text": "短距離走のような瞬発的な運動で主に動員される"}, {"key": "E", "text": "ミオグロビンに富み疲労しにくい"}]'::jsonb, 'E', '赤筋線維は収縮が遅いが、ミトコンドリア、毛細血管、酸素を蓄えるミオグロビンに富み、酸化的リン酸化でATPをつくるため疲労しにくい。姿勢を保つ筋や、持久的な運動で主に働く。白筋線維は解糖系に依存し、速く強く収縮するが疲労しやすい。持久的なトレーニングでは筋のミトコンドリアや毛細血管が増える。', '{"A": "白筋線維（タイプII線維）の特徴である。", "B": "主に白筋線維の特徴である。", "C": "白筋線維の特徴である。", "D": "瞬発的な運動では主に白筋線維が動員される。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '表皮の基底層', 2, 'CBT', '表皮は重層扁平上皮で、深い層から表層に向かって角化しながら細胞が移動していく。表皮で細胞分裂を行って新しい角化細胞を供給する層はどれか。', '[{"key": "A", "text": "基底層"}, {"key": "B", "text": "角質層"}, {"key": "C", "text": "顆粒層"}, {"key": "D", "text": "有棘層"}, {"key": "E", "text": "淡明層"}]'::jsonb, 'A', '基底層の角化細胞は分裂して上方へ移動し、有棘層、顆粒層を経て角質層となり、最後は垢として剥がれる。この過程にはおよそ4週間かかる。基底層にはメラニンをつくるメラノサイトや、触覚に関わるMerkel細胞もある。乾癬ではこの回転が異常に速くなり、厚い鱗屑を伴う紅斑となる。', '{"B": "核を失った角化細胞が重なった最表層で、分裂はしない。", "C": "ケラトヒアリン顆粒をもつ層で、角化の準備が進む。", "D": "デスモソームで強く結合した細胞の層で、分裂の主な場ではない。", "E": "手掌や足底の厚い表皮にだけみられる薄い層である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '遠近の調節', 2, 'CBT', '40歳代になると、本や新聞を目から離さないと読みにくくなる。近くを見るときに起こる眼の調節の仕組みとして正しいのはどれか。', '[{"key": "A", "text": "交感神経の作用で毛様体筋が収縮する"}, {"key": "B", "text": "毛様体筋が収縮してZinn小帯が緩み、水晶体が厚くなる"}, {"key": "C", "text": "毛様体筋が弛緩してZinn小帯が緊張し、水晶体が厚くなる"}, {"key": "D", "text": "毛様体筋が収縮して、水晶体が薄くなる"}, {"key": "E", "text": "瞳孔散大筋が収縮して、焦点深度が深くなる"}]'::jsonb, 'B', '近くを見るときは動眼神経の副交感線維の働きで毛様体筋が収縮し、Zinn小帯が緩んで水晶体が自らの弾性で厚くなり、屈折力が増す。同時に両眼が内側に寄り（輻湊）、瞳孔が縮小する（近見反応）。加齢で水晶体が硬くなると厚くなりにくくなり、近くが見えにくくなる（老視）。', '{"A": "毛様体筋は主に動眼神経の副交感線維で収縮する。", "C": "毛様体筋が弛緩すると、Zinn小帯が引っ張られて水晶体は薄くなる。", "D": "毛様体筋が収縮すると水晶体は自らの弾性で厚くなる。", "E": "近くを見るときは瞳孔が縮小する。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '房水の流れ', 2, 'CBT', '眼圧は房水の産生と排出のバランスで決まり、排出が妨げられると眼圧が上がって緑内障の原因となる。房水の産生と排出について正しいのはどれか。', '[{"key": "A", "text": "硝子体で産生され、視神経乳頭から排出される"}, {"key": "B", "text": "虹彩で産生され、後房から硝子体へ吸収される"}, {"key": "C", "text": "毛様体で産生され、隅角から排出される"}, {"key": "D", "text": "水晶体で産生され、網膜の血管へ吸収される"}, {"key": "E", "text": "涙腺で産生され、角膜を通って前房に入る"}]'::jsonb, 'C', '房水は毛様体の上皮で産生されて後房に出て、瞳孔を通って前房へ流れ、隅角の線維柱帯からSchlemm管を経て静脈へ排出される。一部は毛様体の組織の間を通って排出される（ぶどう膜強膜流出路）。隅角が閉じると急激に眼圧が上がり、激しい眼痛、頭痛、嘔吐をきたす（急性閉塞隅角緑内障）。炭酸脱水酵素阻害薬やβ遮断薬は房水の産生を抑える。', '{"A": "硝子体は房水を産生せず、排出路でもない。", "B": "房水は後房から瞳孔を通って前房に流れ、隅角から排出される。", "D": "房水は毛様体の上皮で産生される。", "E": "涙液の説明で、房水とは異なる。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '蝸牛の周波数局在', 2, 'CBT', '加齢による難聴（老人性難聴）では、高い音から聞こえにくくなる。高い周波数の音で最も大きく振動する蝸牛の部位はどれか。', '[{"key": "A", "text": "三半規管の膨大部"}, {"key": "B", "text": "球形嚢と卵形嚢"}, {"key": "C", "text": "鼓膜の中央部"}, {"key": "D", "text": "基底回転（卵円窓に近い部位）"}, {"key": "E", "text": "頂回転（蝸牛の先端に近い部位）"}]'::jsonb, 'D', '蝸牛の基底板は、卵円窓に近い基底回転では幅が狭く硬いため高音に、先端の頂回転では幅が広く柔らかいため低音によく振動する（周波数局在）。老人性難聴や騒音性難聴では基底回転の有毛細胞が傷みやすく、高音域から聴力が低下する。騒音性難聴では4,000Hz付近の聴力が特に落ちる（c5 dip）。', '{"A": "頭部の回転を感知する部位で、音は感知しない。", "B": "直線加速度と頭の傾きを感知する耳石器である。", "C": "外耳と中耳の境で、蝸牛の部位ではない。", "E": "低い周波数の音で大きく振動する部位である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', '左反回神経', 2, 'CBT', '胸部大動脈瘤や左肺癌の患者で、嗄声が出現することがある。大動脈弓の下を前方から後方へ回って上行する神経はどれか。', '[{"key": "A", "text": "右反回神経"}, {"key": "B", "text": "左横隔神経"}, {"key": "C", "text": "左交感神経幹"}, {"key": "D", "text": "胸管"}, {"key": "E", "text": "左反回神経"}]'::jsonb, 'E', '迷走神経から分かれる反回神経は、左では大動脈弓の下を、右では鎖骨下動脈の下を回って気管と食道の間の溝を上行し、輪状甲状筋以外の喉頭の筋を支配する。左は胸腔内を長く走るため、大動脈瘤、肺癌や縦隔リンパ節の転移、食道癌、心臓・大血管の手術などで障害されやすく、声帯の麻痺による嗄声や誤嚥をきたす。甲状腺の手術でも損傷に注意が必要である。', '{"A": "右鎖骨下動脈の下を回って上行する。", "B": "大動脈弓の前外側を下行して横隔膜に至る。", "C": "椎体の外側を縦に走り、大動脈弓の下を回らない。", "D": "神経ではなく、リンパを静脈角へ運ぶリンパ管である。"}'::jsonb, 'public', 'M', 'C-2', '', 'pending', 'llm'),
('基礎医学', 'グラム陽性菌の細胞壁', 2, 'CBT', 'Gram染色では、細胞壁の構造の違いによって細菌が紫色と赤色に染め分けられる。紫色に染まるグラム陽性菌の細胞壁の特徴として正しいのはどれか。', '[{"key": "A", "text": "厚いペプチドグリカン層をもつ"}, {"key": "B", "text": "ペプチドグリカン層の外側にリポ多糖を含む外膜をもつ"}, {"key": "C", "text": "細胞壁をまったくもたない"}, {"key": "D", "text": "ミコール酸に富む脂質の層をもつ"}, {"key": "E", "text": "細胞膜にエルゴステロールを含む"}]'::jsonb, 'A', 'グラム陽性菌は厚いペプチドグリカン層にタイコ酸を含み、クリスタル紫とヨウ素の複合体がアルコールで脱色されにくいため紫色に染まる。グラム陰性菌はペプチドグリカン層が薄く、その外側にリポ多糖を含む外膜があり、脱色されて後染色の赤色に染まる。外膜は一部の抗菌薬が入りにくい障壁にもなる。', '{"B": "グラム陰性菌の特徴である。", "C": "マイコプラズマの特徴で、Gram染色では染まらない。", "D": "抗酸菌の特徴で、Gram染色では染まりにくい。", "E": "真菌の特徴である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'エンドトキシン', 2, 'CBT', 'グラム陰性桿菌による敗血症では、菌体の成分が発熱、血圧低下、播種性血管内凝固を引き起こす。グラム陰性桿菌のエンドトキシン（内毒素）の本体はどれか。', '[{"key": "A", "text": "運動に使われる鞭毛の蛋白質"}, {"key": "B", "text": "外膜のリポ多糖"}, {"key": "C", "text": "細胞壁のペプチドグリカン"}, {"key": "D", "text": "菌が分泌する蛋白質の毒素"}, {"key": "E", "text": "菌体を覆う多糖体の莢膜"}]'::jsonb, 'B', 'エンドトキシンはグラム陰性菌の外膜のリポ多糖（LPS）で、毒性の中心はリピドAである。菌が壊れたときにも放出され、マクロファージのToll様受容体4に認識されてTNF-α、IL-1、IL-6などの大量産生を引き起こし、発熱やショック、播種性血管内凝固をきたす。熱に安定で、外毒素のように無毒化してワクチンに使うことはできない。', '{"A": "運動器官の成分で、エンドトキシンではない。", "C": "グラム陽性菌で厚い構造で、エンドトキシンの本体ではない。", "D": "外毒素の性質である。", "E": "食細胞による貪食を妨げる病原因子で、エンドトキシンではない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '芽胞形成菌', 2, 'CBT', '入院中の患者で抗菌薬の投与後に下痢が続き、便の毒素検査が陽性となった。原因菌は芽胞を形成し、アルコール製剤では消毒できない。芽胞を形成する菌はどれか。', '[{"key": "A", "text": "肺炎球菌"}, {"key": "B", "text": "緑膿菌"}, {"key": "C", "text": "クロストリディオイデス・ディフィシル"}, {"key": "D", "text": "大腸菌"}, {"key": "E", "text": "黄色ブドウ球菌"}]'::jsonb, 'C', '芽胞は乾燥、熱、消毒薬に強い休眠型の構造で、クロストリディオイデス属、クロストリジウム属、バシラス属のグラム陽性桿菌がつくる。クロストリディオイデス・ディフィシルは抗菌薬で腸内細菌叢が乱れると増殖して毒素を産生し、偽膜性腸炎などを起こす。芽胞にはアルコールが効かないため、流水と石けんによる手洗いと、次亜塩素酸ナトリウムによる環境の消毒が必要となる。', '{"A": "芽胞を形成しないグラム陽性双球菌である。", "B": "芽胞を形成しないグラム陰性桿菌である。", "D": "芽胞を形成しないグラム陰性桿菌である。", "E": "芽胞を形成しないグラム陽性球菌である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '抗酸菌の細胞壁', 2, 'CBT', '喀痰のZiehl-Neelsen染色で赤く染まる桿菌を認め、塩酸アルコールでも脱色されなかった。この菌が脱色されにくい性質のもとになっている細胞壁の成分はどれか。', '[{"key": "A", "text": "タイコ酸"}, {"key": "B", "text": "エルゴステロール"}, {"key": "C", "text": "ヒアルロン酸の莢膜"}, {"key": "D", "text": "ミコール酸"}, {"key": "E", "text": "リポ多糖"}]'::jsonb, 'D', '結核菌などの抗酸菌は、細胞壁に長鎖脂肪酸のミコール酸を大量に含み、いったん染まると酸やアルコールでも脱色されにくい。この脂質の厚い壁のため多くの消毒薬や抗菌薬が効きにくく、増殖も遅い。結核菌は培養でコロニーが見えるまでに数週間かかるため、迅速な診断には核酸増幅検査も用いられる。', '{"A": "グラム陽性菌の細胞壁の成分である。", "B": "真菌の細胞膜の成分である。", "C": "一部のレンサ球菌がもつ莢膜の成分である。", "E": "グラム陰性菌の外膜の成分である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '偏性細胞内寄生菌', 2, 'CBT', '細菌の多くは人工培地で増殖できるが、宿主の細胞の中でしか増殖できない細菌もある。人工培地で増殖できない偏性細胞内寄生菌はどれか。', '[{"key": "A", "text": "マイコプラズマ"}, {"key": "B", "text": "大腸菌"}, {"key": "C", "text": "緑膿菌"}, {"key": "D", "text": "黄色ブドウ球菌"}, {"key": "E", "text": "クラミジア"}]'::jsonb, 'E', 'クラミジアとリケッチアは、自らATPを十分につくれないなど宿主の細胞に依存しており、細胞の中でしか増殖できない。クラミジアは感染性の基本小体と増殖型の網様体の2つの形をとる。診断には核酸増幅検査や血清検査を用い、治療には細胞内に移行しやすいマクロライド系やテトラサイクリン系の抗菌薬を使う。', '{"A": "細胞壁をもたないが、特殊な人工培地で増殖できる。", "B": "普通の人工培地でよく増殖する。", "C": "普通の人工培地でよく増殖し、特有の色素をつくる。", "D": "普通の人工培地でよく増殖する。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'マイコプラズマ', 2, 'CBT', '若年者の乾性咳嗽が長引く肺炎で、β-ラクタム系抗菌薬が効かなかった。β-ラクタム系抗菌薬が効かない理由が細胞壁をもたないことにある病原体はどれか。', '[{"key": "A", "text": "肺炎マイコプラズマ"}, {"key": "B", "text": "肺炎球菌"}, {"key": "C", "text": "インフルエンザ菌"}, {"key": "D", "text": "肺炎桿菌"}, {"key": "E", "text": "モラクセラ・カタラーリス"}]'::jsonb, 'A', 'マイコプラズマは細胞壁をもたない最小の自己増殖性の細菌で、細胞膜にステロールを含む。β-ラクタム系は細胞壁の合成を阻害して作用するため無効で、マクロライド系、テトラサイクリン系、キノロン系を用いる。Gram染色では染まらない。寒冷凝集素の上昇を伴うことがある。', '{"B": "細胞壁をもち、ペニシリン系が基本的に有効である。", "C": "細胞壁をもち、β-ラクタム系が使われる。", "D": "細胞壁をもつグラム陰性桿菌である。", "E": "細胞壁をもつグラム陰性球菌である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'ボツリヌス毒素', 2, 'CBT', '自家製の瓶詰めの食品を食べた数日後に、複視、嚥下障害、四肢の脱力が出現した。発熱や意識障害はない。原因となった毒素の作用機序として正しいのはどれか。', '[{"key": "A", "text": "電位依存性ナトリウムチャネルを遮断する"}, {"key": "B", "text": "神経終末からのアセチルコリンの放出を阻害する"}, {"key": "C", "text": "抑制性介在ニューロンからの伝達物質の放出を阻害する"}, {"key": "D", "text": "ニコチン性アセチルコリン受容体を遮断する"}, {"key": "E", "text": "アセチルコリンエステラーゼを阻害する"}]'::jsonb, 'B', 'ボツリヌス毒素は神経終末に取り込まれ、SNARE蛋白質を切断してアセチルコリンの放出を妨げ、弛緩性の麻痺を起こす。脳神経の症状から始まり、下行性に進んで呼吸筋の麻痺に至ることがある。嫌気的な保存食品のほか、乳児では蜂蜜に含まれる芽胞が腸内で増殖して発症するため、1歳未満の乳児に蜂蜜を与えない。微量の毒素は眼瞼けいれんや痙縮の治療に用いられる。', '{"A": "フグ毒のテトロドトキシンの作用機序である。", "C": "破傷風毒素の作用機序で、筋の強直を起こす。", "D": "クラーレなどの作用で、ボツリヌス毒素の機序ではない。", "E": "有機リン系農薬などの作用機序である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'コレラ毒素', 2, 'CBT', '大量の米のとぎ汁様の水様便を繰り返し、高度の脱水をきたした患者がいる。この下痢を起こす毒素の作用機序として正しいのはどれか。', '[{"key": "A", "text": "神経筋接合部でアセチルコリンの放出を阻害する"}, {"key": "B", "text": "腸管の平滑筋を麻痺させて内容物を停滞させる"}, {"key": "C", "text": "cAMPを増やして塩化物イオンの分泌を促す"}, {"key": "D", "text": "腸管上皮を破壊して粘膜から出血させる"}, {"key": "E", "text": "リボソームを不活化して蛋白質の合成を止める"}]'::jsonb, 'C', 'コレラ毒素はGsαをADPリボシル化してGTPase活性を失わせ、アデニル酸シクラーゼを活性化し続ける。上皮細胞内のcAMPが増えてCFTRから塩化物イオンが分泌され、水とナトリウムが腸管内へ出て大量の水様便となる。腸管の構造は壊れないため、治療の中心は経口補水液や輸液による水と電解質の補充である。ナトリウムとブドウ糖の共輸送は保たれるため、経口補水液が有効である。', '{"A": "ボツリヌス毒素の機序である。", "B": "水様性下痢の機序ではない。", "D": "赤痢菌などの侵入性の細菌の機序で、血便となる。", "E": "志賀毒素やジフテリア毒素の機序である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '志賀毒素', 2, 'CBT', '焼肉店で加熱不十分な肉を食べた小児が、腹痛と血便ののちに乏尿、貧血、血小板減少をきたした。原因菌が産生する志賀毒素の作用として正しいのはどれか。', '[{"key": "A", "text": "神経終末からの伝達物質の放出を阻害する"}, {"key": "B", "text": "MHCクラスII分子とT細胞受容体を直接架橋する"}, {"key": "C", "text": "赤血球の膜に孔をあけて直接溶血させる"}, {"key": "D", "text": "rRNAを修飾して蛋白質合成を止める"}, {"key": "E", "text": "アデニル酸シクラーゼを持続的に活性化する"}]'::jsonb, 'D', '腸管出血性大腸菌（O157など）が産生する志賀毒素（ベロ毒素）は、細胞に取り込まれると60Sリボソームの28S rRNAから特定のアデニン塩基を外して蛋白質の合成を止め、細胞を死に至らせる。腸管の血管内皮や腎の糸球体内皮が傷害され、出血性大腸炎や溶血性尿毒症症候群（溶血性貧血、血小板減少、急性腎障害）をきたす。少ない菌量で感染するため、二次感染にも注意が要る。', '{"A": "ボツリヌス毒素や破傷風毒素の作用である。", "B": "スーパー抗原の作用である。", "C": "溶血素の作用で、志賀毒素の主な作用ではない。", "E": "コレラ毒素などの作用である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'スーパー抗原', 2, 'CBT', 'タンポンを長時間使用していた女性が、高熱、血圧低下、びまん性の紅斑をきたした。原因となる毒素（TSST-1）がショックを起こす機序として正しいのはどれか。', '[{"key": "A", "text": "特定の抗原に反応するごく少数のT細胞だけを活性化する"}, {"key": "B", "text": "マスト細胞の表面のIgEを架橋して脱顆粒させる"}, {"key": "C", "text": "補体の古典経路を直接活性化する"}, {"key": "D", "text": "心筋細胞を直接壊死させて収縮力を失わせる"}, {"key": "E", "text": "抗原提示を経ずに多数のT細胞を活性化する"}]'::jsonb, 'E', 'スーパー抗原は抗原提示細胞のMHCクラスII分子とT細胞受容体のβ鎖の可変部を、抗原ペプチドの溝の外側で直接つなぐ。そのため特定のβ鎖をもつT細胞がまとめて活性化され、全T細胞の最大で2割程度にも及ぶ。大量のサイトカインが放出され、発熱、ショック、多臓器障害をきたす（毒素性ショック症候群）。黄色ブドウ球菌のTSST-1やエンテロトキシン、化膿レンサ球菌の発熱毒素が代表例である。', '{"A": "通常の抗原による反応で、スーパー抗原の特徴ではない。", "B": "I型アレルギーの機序である。", "C": "スーパー抗原の主な機序ではない。", "D": "スーパー抗原の主な機序ではない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'コアグラーゼ', 2, 'CBT', '血液培養からグラム陽性球菌が検出され、ブドウの房状に集まっていた。黄色ブドウ球菌を、表皮ブドウ球菌などほかのブドウ球菌と区別する性状はどれか。', '[{"key": "A", "text": "コアグラーゼ陽性"}, {"key": "B", "text": "カタラーゼ陽性"}, {"key": "C", "text": "グラム陰性"}, {"key": "D", "text": "芽胞を形成する"}, {"key": "E", "text": "偏性嫌気性"}]'::jsonb, 'A', '黄色ブドウ球菌は血漿を凝固させるコアグラーゼをもち、ほかのブドウ球菌はもたない（コアグラーゼ陰性ブドウ球菌）。ブドウ球菌はカタラーゼ陽性で、カタラーゼ陰性のレンサ球菌と区別できる。表皮ブドウ球菌は皮膚の常在菌で、血液培養では汚染菌のことが多いが、カテーテルや人工物の感染では病原菌となる。', '{"B": "ブドウ球菌に共通の性状で、黄色ブドウ球菌に特有ではない。", "C": "ブドウ球菌はいずれもグラム陽性である。", "D": "ブドウ球菌は芽胞を形成しない。", "E": "ブドウ球菌は通性嫌気性である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '肺炎球菌の莢膜', 2, 'CBT', '高齢者に接種が勧められている肺炎球菌ワクチンは、菌の表面のある構造を抗原としている。肺炎球菌の主な病原因子で、ワクチンの抗原となっている構造はどれか。', '[{"key": "A", "text": "鞭毛"}, {"key": "B", "text": "多糖体の莢膜"}, {"key": "C", "text": "コアグラーゼ"}, {"key": "D", "text": "外膜のリポ多糖"}, {"key": "E", "text": "芽胞"}]'::jsonb, 'B', '肺炎球菌の莢膜は補体によるオプソニン化と食細胞の貪食を妨げる主要な病原因子で、90種類以上の血清型がある。莢膜を認識する抗体ができると貪食されやすくなるため、莢膜多糖体をワクチンの抗原とする。多糖体だけではT細胞の助けを得られず乳幼児で抗体ができにくいため、蛋白質に結合させた結合型ワクチンが乳幼児に用いられる。脾臓を摘出した人は重症化しやすい。', '{"A": "肺炎球菌は鞭毛をもたない。", "C": "黄色ブドウ球菌の酵素である。", "D": "グラム陰性菌の成分で、肺炎球菌はグラム陽性菌である。", "E": "肺炎球菌は芽胞を形成しない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'MRSAの耐性機序', 2, 'CBT', 'MRSA（メチシリン耐性黄色ブドウ球菌）は、ほぼすべてのβ-ラクタム系抗菌薬が効かない。MRSAがβ-ラクタム系抗菌薬に耐性を示す主な機序はどれか。', '[{"key": "A", "text": "30Sリボソームの標的部位を変化させる"}, {"key": "B", "text": "細胞壁のD-Ala-D-AlaをD-Ala-D-Lacに置き換える"}, {"key": "C", "text": "β-ラクタム系が結合しにくいペニシリン結合蛋白を新たにもつ"}, {"key": "D", "text": "ペニシリンを分解するβ-ラクタマーゼだけを産生する"}, {"key": "E", "text": "外膜のポーリンを減らして薬剤を入りにくくする"}]'::jsonb, 'C', 'MRSAはmecA遺伝子がコードするペニシリン結合蛋白2′（PBP2a）をもつ。この蛋白質はβ-ラクタム系抗菌薬との親和性が低いため、ほかのPBPが阻害されても細胞壁の合成を続けられる。治療にはバンコマイシン、リネゾリド、ダプトマイシンなどを用いる。医療従事者の手を介して広がるため、手洗いと接触予防策が重要である。', '{"A": "アミノグリコシド系などに対する耐性機序である。", "B": "バンコマイシン耐性腸球菌の耐性機序である。", "D": "ペニシリナーゼ産生菌の機序で、メチシリンなどは分解されない。", "E": "主にグラム陰性菌の耐性機序である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '接合による遺伝子伝達', 2, 'CBT', '薬剤耐性遺伝子は、菌種を越えて細菌の間で広がることがある。細菌どうしが直接接触し、性線毛を介して遺伝子を受け渡す仕組みで運ばれるものはどれか。', '[{"key": "A", "text": "菌の外に放出された裸のDNA"}, {"key": "B", "text": "芽胞"}, {"key": "C", "text": "莢膜"}, {"key": "D", "text": "プラスミド"}, {"key": "E", "text": "バクテリオファージ"}]'::jsonb, 'D', '細菌の遺伝子の水平伝達には、接合、形質導入、形質転換がある。接合では、プラスミドをもつ菌が性線毛で相手と接触してプラスミドを受け渡す。耐性遺伝子を載せたプラスミドは菌種を越えて広がり、ESBLやカルバペネマーゼの産生菌が拡散する原因となる。形質導入はバクテリオファージが、形質転換は菌の外のDNAの取り込みが担う。', '{"A": "周囲のDNAを取り込むのは形質転換である。", "B": "休眠のための構造で、遺伝子を受け渡す仕組みではない。", "C": "貪食を妨げる構造で、遺伝子を受け渡す仕組みではない。", "E": "ファージが細菌の遺伝子を運ぶのは形質導入で、細菌どうしの接触は要らない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '高圧蒸気滅菌', 2, 'CBT', '手術器具は、使用前に芽胞を含むすべての微生物を死滅させておく必要がある。芽胞まで死滅させることができる方法はどれか。', '[{"key": "A", "text": "70%エタノールでの清拭"}, {"key": "B", "text": "100°Cで5分間の煮沸"}, {"key": "C", "text": "塩化ベンザルコニウム液への浸漬"}, {"key": "D", "text": "紫外線ランプを当てること"}, {"key": "E", "text": "高圧蒸気滅菌"}]'::jsonb, 'E', '滅菌はすべての微生物を死滅させることで、消毒は病原性のある微生物を害のない程度まで減らすことである。高圧蒸気滅菌（オートクレーブ）は飽和水蒸気で121°C、15〜20分以上加熱し、芽胞まで死滅させる。熱に弱い器材には酸化エチレンガスや過酸化水素ガスプラズマによる滅菌を用いる。プリオンは通常の滅菌条件では失活しにくい。', '{"A": "芽胞には効果がなく、消毒の方法である。", "B": "多くの栄養型の菌は死滅するが、芽胞は生き残る。", "C": "低水準の消毒薬で、芽胞には効果がない。", "D": "物の表面の一部の微生物を減らすだけで、芽胞まで確実には死滅させられない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'ノロウイルスの消毒', 2, 'CBT', '高齢者施設でノロウイルスによる胃腸炎が集団発生し、嘔吐物の処理と環境の消毒を行う。消毒に最も適した薬剤はどれか。', '[{"key": "A", "text": "次亜塩素酸ナトリウム"}, {"key": "B", "text": "70%エタノール"}, {"key": "C", "text": "塩化ベンザルコニウム"}, {"key": "D", "text": "クロルヘキシジン"}, {"key": "E", "text": "ポビドンヨード"}]'::jsonb, 'A', 'ノロウイルスはエンベロープをもたないため、アルコールや界面活性剤で失活しにくい。環境や嘔吐物の処理には次亜塩素酸ナトリウムを用い、手指は流水と石けんでよく洗う。少量のウイルスで感染し、嘔吐物が乾燥して舞い上がったものを吸い込んでも感染するため、嘔吐物は手袋やマスクをつけて速やかに処理する。', '{"B": "エンベロープをもたないノロウイルスには効果が不十分である。", "C": "低水準の消毒薬で、ノロウイルスには効果が不十分である。", "D": "低水準の消毒薬で、ノロウイルスには効果が不十分である。", "E": "皮膚や粘膜の消毒に用いるもので、環境の消毒には用いない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'エンベロープをもつウイルス', 2, 'CBT', 'ウイルスには、核酸と蛋白質の殻の外側を脂質の膜が覆っているものと、覆っていないものがある。エンベロープをもつウイルスの性質として正しいのはどれか。', '[{"key": "A", "text": "エンベロープには宿主の細胞への吸着に関わる蛋白質がない"}, {"key": "B", "text": "アルコールや界面活性剤で失活しやすい"}, {"key": "C", "text": "乾燥や熱に強く、環境中で長く感染力を保つ"}, {"key": "D", "text": "胃酸や胆汁に強く、主に糞口感染する"}, {"key": "E", "text": "エンベロープは宿主の細胞膜とは無関係につくられる"}]'::jsonb, 'B', 'エンベロープは、ウイルスが細胞膜などから出芽するときに宿主の脂質二重膜を取り込んでつくられ、ウイルスの糖蛋白質が埋め込まれている。脂質の膜なのでアルコールや界面活性剤、乾燥に弱い。インフルエンザウイルス、HIV、ヘルペスウイルス、コロナウイルスなどがもつ。エンベロープのないウイルスは環境中で安定で、糞口感染するものが多い。', '{"A": "エンベロープの糖蛋白質が細胞への吸着と侵入を担う。", "C": "エンベロープのないウイルスの性質で、エンベロープのあるウイルスは乾燥に弱い。", "D": "エンベロープのないウイルス（ノロウイルスなど）の性質である。", "E": "エンベロープは細胞から出芽するときに宿主の膜を取り込んでつくられる。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'インフルエンザの抗原不連続変異', 2, 'CBT', 'インフルエンザAは、数十年に一度、多くの人が免疫をもたない新しい亜型が現れて世界的に大流行する。この新しい亜型が生じる主な機序はどれか。', '[{"key": "A", "text": "細菌からプラスミドを取り込む"}, {"key": "B", "text": "潜伏感染していたウイルスが再活性化する"}, {"key": "C", "text": "分節ゲノムの再集合"}, {"key": "D", "text": "毎年少しずつ起こる点変異が蓄積する"}, {"key": "E", "text": "逆転写酵素でゲノムがDNAに変換される"}]'::jsonb, 'C', 'インフルエンザAウイルスのゲノムは8本の分節に分かれており、ヒトと鳥やブタのウイルスが同じ細胞に感染すると分節が入れ替わり、ヘマグルチニンやノイラミニダーゼが全く新しい亜型が生じる（抗原不連続変異）。多くの人が免疫をもたないため世界的な大流行となる。一方、点変異の蓄積による抗原連続変異は毎年の流行の原因となり、ワクチンの株を毎年選び直す理由となる。', '{"A": "ウイルスがプラスミドを取り込むことはない。", "B": "ヘルペスウイルスなどの性質で、インフルエンザには当たらない。", "D": "抗原連続変異（ドリフト）で、毎年の流行の原因となる。", "E": "インフルエンザウイルスは逆転写酵素をもたない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '水痘・帯状疱疹ウイルスの潜伏', 2, 'CBT', '小児期に水痘にかかった高齢者が、片側の胸部に帯状に並ぶ痛みを伴う水疱を生じた。水痘のあと、このウイルスが潜伏している部位はどれか。', '[{"key": "A", "text": "単球やマクロファージ"}, {"key": "B", "text": "肝細胞の核"}, {"key": "C", "text": "皮膚の表皮細胞"}, {"key": "D", "text": "知覚神経節"}, {"key": "E", "text": "末梢血のB細胞"}]'::jsonb, 'D', '水痘・帯状疱疹ウイルスは初感染で水痘を起こしたあと、知覚神経を上行して後根神経節や脳神経の神経節に潜伏する。加齢や免疫の低下で再活性化すると、その神経節の支配する皮膚分節に沿って痛みを伴う水疱が生じる（帯状疱疹）。皮疹が治ったあとも痛みが残ることがある（帯状疱疹後神経痛）。50歳以上ではワクチンで発症を予防できる。', '{"A": "サイトメガロウイルスが潜伏する主な細胞である。", "B": "B型肝炎ウイルスが持続感染する場である。", "C": "水疱をつくる場だが、潜伏する部位ではない。", "E": "EBウイルスが潜伏する細胞である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'HIVの標的細胞', 2, 'CBT', 'HIV感染症では、未治療のまま経過すると数年から十数年で高度の免疫不全に至る。HIVが主に感染して減少させる細胞はどれか。', '[{"key": "A", "text": "CD8陽性T細胞"}, {"key": "B", "text": "B細胞"}, {"key": "C", "text": "好中球"}, {"key": "D", "text": "赤血球"}, {"key": "E", "text": "CD4陽性T細胞"}]'::jsonb, 'E', 'HIVはエンベロープの糖蛋白質gp120がCD4と補助受容体（CCR5やCXCR4）に結合して、CD4陽性T細胞やマクロファージに感染する。逆転写酵素でゲノムをDNAにし、宿主の染色体に組み込む。CD4陽性T細胞が減ると細胞性免疫が低下し、ニューモシスチス肺炎などを発症する。CD4陽性T細胞数は病期と治療の指標となる。', '{"A": "感染細胞を傷害する側の細胞で、HIVの主な標的ではない。", "B": "HIVの主な標的ではないが、活性化の異常で高γグロブリン血症がみられる。", "C": "HIVの主な標的ではない。", "D": "CD4をもたず、HIVは感染しない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'プリオン', 2, 'CBT', '急速に進行する認知症とミオクローヌスを示し、脳波で周期性同期性放電を認めた患者がいる。この疾患の病原体の性質として正しいのはどれか。', '[{"key": "A", "text": "異常な構造の蛋白質で、滅菌に抵抗性を示す"}, {"key": "B", "text": "小さな環状のRNAを遺伝子としてもつ"}, {"key": "C", "text": "ホルマリンや通常の加熱処理によって容易に失活する"}, {"key": "D", "text": "抗菌薬の投与で治療できる"}, {"key": "E", "text": "脳に強い炎症細胞の浸潤を引き起こす"}]'::jsonb, 'A', 'プリオン病は、正常なプリオン蛋白が異常な立体構造のものに変わり、それが正常型を次々に異常型に変えて蓄積する疾患である。Creutzfeldt-Jakob病では脳に海綿状変化が生じ、急速に進行する認知症を示す。病原体は核酸をもたない蛋白質で、通常の高圧蒸気滅菌やホルマリンでは失活しにくいため、手術器具には特別な処理が必要となる。', '{"B": "プリオンは核酸をもたない。", "C": "通常の消毒や滅菌の条件では失活しにくい。", "D": "有効な治療法は確立していない。", "E": "炎症は乏しく、神経細胞の脱落と空胞形成（海綿状変化）が特徴である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'エルゴステロール', 2, 'CBT', '抗真菌薬の多くは、ヒトの細胞にはなく真菌にだけある構造を標的とする。真菌の細胞膜に含まれ、アムホテリシンBやアゾール系抗真菌薬の標的となる成分はどれか。', '[{"key": "A", "text": "ミコール酸"}, {"key": "B", "text": "エルゴステロール"}, {"key": "C", "text": "コレステロール"}, {"key": "D", "text": "ペプチドグリカン"}, {"key": "E", "text": "リポ多糖"}]'::jsonb, 'B', '真菌の細胞膜のステロールはエルゴステロールである。アムホテリシンBはエルゴステロールに結合して膜に孔をあけ、アゾール系はエルゴステロールの合成酵素（ラノステロール14α-脱メチル酵素）を阻害する。真菌の細胞壁のβ-D-グルカンの合成を阻害するのがエキノキャンディン系である。アムホテリシンBはコレステロールにもわずかに結合するため、腎障害などの副作用が多い。', '{"A": "抗酸菌の細胞壁の成分である。", "C": "ヒトの細胞膜のステロールで、真菌の主なステロールではない。", "D": "細菌の細胞壁の成分で、真菌にはない。", "E": "グラム陰性菌の外膜の成分である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'クリプトコックス', 2, 'CBT', '免疫不全の患者が頭痛と発熱を訴え、髄液の墨汁染色で厚い莢膜に囲まれた酵母様の真菌を認めた。原因として最も考えられる真菌はどれか。', '[{"key": "A", "text": "ムーコル"}, {"key": "B", "text": "ニューモシスチス"}, {"key": "C", "text": "クリプトコックス"}, {"key": "D", "text": "カンジダ"}, {"key": "E", "text": "アスペルギルス"}]'::jsonb, 'C', 'クリプトコックスはハトの糞などの環境中にいる酵母様真菌で、吸入により肺に感染し、細胞性免疫が低下した人では髄膜炎を起こしやすい。多糖体の厚い莢膜が病原因子で、墨汁染色では莢膜が抜けて白く見える。髄液や血清の莢膜抗原の検出が診断に役立つ。治療にはアムホテリシンBとフルシトシンなどを用いる。', '{"A": "隔壁の乏しい太い菌糸を形成する糸状菌である。", "B": "主に肺炎を起こし、墨汁染色で莢膜は見られない。", "D": "口腔や腟の粘膜の常在菌で、仮性菌糸をつくる。厚い莢膜はない。", "E": "隔壁のある菌糸を形成する糸状菌である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'アスペルギルス', 2, 'CBT', '好中球減少が続く白血病の患者に、肺の結節影とその周囲のすりガラス影が出現した。組織で鋭角に分岐し、隔壁のある菌糸がみられる真菌はどれか。', '[{"key": "A", "text": "カンジダ"}, {"key": "B", "text": "クリプトコックス"}, {"key": "C", "text": "ヒストプラズマ"}, {"key": "D", "text": "アスペルギルス"}, {"key": "E", "text": "ムーコル"}]'::jsonb, 'D', 'アスペルギルスは環境中に広くいる糸状菌で、胞子を吸い込んで感染する。組織では幅のそろった隔壁のある菌糸が約45度の鋭角に分岐する。好中球減少の患者では血管に侵入する侵襲性肺アスペルギルス症を起こし、CTでは結節の周囲のすりガラス影（halo sign）がみられる。血清のガラクトマンナン抗原が診断に役立ち、ボリコナゾールなどで治療する。', '{"A": "酵母と仮性菌糸の形をとる。", "B": "厚い莢膜をもつ酵母様真菌である。", "C": "マクロファージの中にみられる小さな酵母で、日本ではまれである。", "E": "隔壁の乏しい太い菌糸が、ほぼ直角に分岐する。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'マラリアの媒介', 2, 'CBT', 'アフリカから帰国した旅行者が、周期的な高熱と悪寒戦慄を訴えた。血液塗抹標本で赤血球内に原虫を認めた。この疾患を媒介する生物はどれか。', '[{"key": "A", "text": "ネッタイシマカ"}, {"key": "B", "text": "コガタアカイエカ"}, {"key": "C", "text": "ツツガムシ"}, {"key": "D", "text": "マダニ"}, {"key": "E", "text": "ハマダラカ"}]'::jsonb, 'E', 'マラリアはプラスモジウム属の原虫による感染症で、ハマダラカの雌が吸血するときに感染する。原虫は肝細胞で増殖したあと赤血球に侵入して増殖と破壊を繰り返し、周期的な発熱、貧血、脾腫をきたす。熱帯熱マラリアは重症化しやすく、脳症や腎障害、播種性血管内凝固をきたすため、流行地からの帰国後の発熱では必ず鑑別する。', '{"A": "デング熱やジカウイルス感染症、黄熱を媒介する。", "B": "日本脳炎を媒介する。", "C": "つつが虫病の病原体を媒介するダニである。", "D": "日本紅斑熱や重症熱性血小板減少症候群などを媒介する。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'アニサキス', 2, 'CBT', 'サバの刺身を食べた数時間後に、激しい心窩部痛を訴えて受診した。上部消化管内視鏡検査で胃粘膜に刺入した白い糸状の虫体を認めた。この寄生虫はどれか。', '[{"key": "A", "text": "アニサキス"}, {"key": "B", "text": "日本海裂頭条虫"}, {"key": "C", "text": "回虫"}, {"key": "D", "text": "蟯虫"}, {"key": "E", "text": "肝吸虫"}]'::jsonb, 'A', 'アニサキスはクジラやイルカを終宿主とする線虫で、その幼虫がサバ、イカ、サンマなどの海産魚介類にいる。生食すると幼虫が胃や腸の粘膜に刺入し、数時間後に激しい腹痛を起こす。胃アニサキス症は内視鏡で虫体を摘出すれば速やかに改善する。幼虫は加熱や冷凍（-20°Cで24時間以上）で死滅するが、酢や醤油では死なない。', '{"B": "サケやマスの生食で感染し、長い虫体が肛門から出ることで気づかれる。", "C": "野菜などに付いた虫卵を経口摂取して感染する。", "D": "肛門周囲に産卵し、夜間の肛門周囲のかゆみを起こす。", "E": "コイなどの淡水魚の生食で感染し、胆管に寄生する。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'トキソプラズマ', 2, 'CBT', '妊娠中に初めて感染すると、胎児に水頭症、脈絡網膜炎、頭蓋内石灰化をきたすことがある原虫がいる。ネコの糞便や加熱が不十分な肉から感染するこの原虫はどれか。', '[{"key": "A", "text": "クリプトスポリジウム"}, {"key": "B", "text": "トキソプラズマ"}, {"key": "C", "text": "赤痢アメーバ"}, {"key": "D", "text": "ランブル鞭毛虫"}, {"key": "E", "text": "腟トリコモナス"}]'::jsonb, 'B', 'トキソプラズマはネコ科の動物を終宿主とする原虫で、ネコの糞便に含まれるオーシストや、加熱不十分な肉の中のシストから感染する。健常者では無症状のことが多いが、妊娠中の初感染では胎盤を通して先天感染を起こす。細胞性免疫の低下した人では脳炎を起こす。妊婦には肉の十分な加熱や、ネコの糞の処理を避けることを勧める。', '{"A": "水系感染で下痢を起こし、塩素消毒に強い。", "C": "汚染された飲食物から感染し、大腸炎や肝膿瘍を起こす。", "D": "汚染された水から感染し、小腸に寄生して下痢を起こす。", "E": "性行為で感染し、腟炎を起こす。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '腸内細菌叢の主体', 2, 'CBT', 'ヒトの大腸には多数の細菌が常在し、代謝や感染防御に関わっている。健常成人の大腸の常在菌叢で最も多い菌群はどれか。', '[{"key": "A", "text": "真菌"}, {"key": "B", "text": "偏性好気性菌"}, {"key": "C", "text": "偏性嫌気性菌"}, {"key": "D", "text": "大腸菌などの通性嫌気性菌"}, {"key": "E", "text": "黄色ブドウ球菌"}]'::jsonb, 'C', '大腸の内腔は酸素が乏しく、バクテロイデス属やクロストリジウム属、ビフィドバクテリウム属などの偏性嫌気性菌が常在菌の大部分を占める。大腸菌などの通性嫌気性菌はその数百分の一程度である。常在菌叢は食物繊維から短鎖脂肪酸をつくり、病原菌の定着を防ぐ。抗菌薬で菌叢が乱れると、クロストリディオイデス・ディフィシル腸炎などが起こりやすい。', '{"A": "カンジダなどが少数いるが、主体ではない。", "B": "酸素の乏しい大腸の内腔では少数派である。", "D": "代表的な常在菌だが、数では偏性嫌気性菌の数百分の一程度にとどまる。", "E": "主に皮膚や鼻腔の常在菌で、大腸の主体ではない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'レジオネラ', 2, 'CBT', '循環式浴槽のある入浴施設の利用者に、高熱、意識障害、低ナトリウム血症を伴う重症肺炎が集団発生した。原因として最も考えられる菌はどれか。', '[{"key": "A", "text": "インフルエンザ菌"}, {"key": "B", "text": "肺炎マイコプラズマ"}, {"key": "C", "text": "黄色ブドウ球菌"}, {"key": "D", "text": "レジオネラ"}, {"key": "E", "text": "肺炎球菌"}]'::jsonb, 'D', 'レジオネラは土壌や水中にいるグラム陰性桿菌で、循環式浴槽、冷却塔、加湿器などで増えた菌をエアロゾルとして吸い込んで感染する。ヒトからヒトへはうつらない。マクロファージの中で増殖する細胞内寄生菌で、β-ラクタム系は無効であり、キノロン系やマクロライド系で治療する。尿中抗原検査が迅速診断に用いられる。', '{"A": "ヒトの気道の常在菌で、環境水から感染するものではない。", "B": "ヒトからヒトへ飛沫で感染し、環境水から感染するものではない。", "C": "インフルエンザ後の肺炎などを起こすが、環境水から集団発生するものではない。", "E": "市中肺炎の代表的な原因菌だが、循環式浴槽の水からの集団発生は特徴的でない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'ピロリ菌のウレアーゼ', 2, 'CBT', 'ヘリコバクター・ピロリは強い酸性の胃の中で生き延びることができる。この菌が胃酸を中和するために産生する酵素はどれか。', '[{"key": "A", "text": "コアグラーゼ"}, {"key": "B", "text": "カタラーゼ"}, {"key": "C", "text": "β-ラクタマーゼ"}, {"key": "D", "text": "ヒアルロニダーゼ"}, {"key": "E", "text": "ウレアーゼ"}]'::jsonb, 'E', 'ヘリコバクター・ピロリは強いウレアーゼ活性をもち、尿素をアンモニアと二酸化炭素に分解して菌の周囲の酸を中和する。この性質を利用して、標識した尿素を飲ませて呼気中の二酸化炭素を測る尿素呼気試験や、迅速ウレアーゼ試験で感染を診断する。慢性胃炎、消化性潰瘍、胃癌、胃MALTリンパ腫の原因となり、除菌治療が行われる。', '{"A": "黄色ブドウ球菌が産生し、血漿を凝固させる酵素である。", "B": "過酸化水素を分解する酵素で、胃酸の中和には働かない。", "C": "β-ラクタム系抗菌薬を分解する酵素である。", "D": "結合組織を分解して菌の拡散を助ける酵素である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '黄色ブドウ球菌の食中毒', 2, 'CBT', '昼食に手作りのおにぎりを食べた数名が、2〜3時間後に激しい嘔吐を繰り返した。発熱はない。おにぎりを握った人の手指に化膿した傷があった。原因として最も考えられる菌はどれか。', '[{"key": "A", "text": "黄色ブドウ球菌"}, {"key": "B", "text": "カンピロバクター"}, {"key": "C", "text": "サルモネラ"}, {"key": "D", "text": "腸炎ビブリオ"}, {"key": "E", "text": "ノロウイルス"}]'::jsonb, 'A', '黄色ブドウ球菌は食品の中で増殖して耐熱性のエンテロトキシンを産生し、食べた数時間後に嘔吐を主とする食中毒を起こす。毒素がすでにできている毒素型の食中毒なので、潜伏期が短く、発熱は少ない。毒素は加熱しても壊れないため、調理後に再加熱しても防げない。化膿した傷のある人が素手で調理しないことが予防の要点である。', '{"B": "鶏肉などから感染し、潜伏期は2〜7日と長い。", "C": "鶏卵や肉から感染し、潜伏期は半日から2日程度で、発熱を伴うことが多い。", "D": "海産魚介類から感染し、潜伏期は半日前後で、腹痛と下痢が主となる。", "E": "潜伏期は1〜2日で、冬に多い。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'バイオフィルム', 2, 'CBT', '中心静脈カテーテルの感染では、抗菌薬を投与してもカテーテルを抜去しない限り感染が治りにくい。その主な理由となる細菌の性質はどれか。', '[{"key": "A", "text": "毒素を産生して抗菌薬を分解する"}, {"key": "B", "text": "表面にバイオフィルムをつくる"}, {"key": "C", "text": "カテーテルの内腔で芽胞を形成する"}, {"key": "D", "text": "細胞壁を失ってL型菌になる"}, {"key": "E", "text": "宿主の細胞の中に入り込んで増殖する"}]'::jsonb, 'B', 'バイオフィルムは、菌が人工物や組織の表面に付着して菌体外多糖の基質の中で集団をつくったものである。中の菌は代謝が落ちて抗菌薬が効きにくく、好中球や抗体も届きにくい。表皮ブドウ球菌、黄色ブドウ球菌、緑膿菌、カンジダなどがつくる。カテーテル、人工弁、人工関節の感染では、抗菌薬に加えて人工物の抜去や交換が必要になることが多い。', '{"A": "毒素が抗菌薬を分解することはない。", "C": "カテーテル感染の主な原因菌は芽胞を形成しない。", "D": "カテーテル感染が治りにくい主な理由ではない。", "E": "主な理由はカテーテルの表面での菌の集団形成である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '空気感染する病原体', 2, 'CBT', '病原体を含む飛沫の水分が蒸発した微粒子（飛沫核）は、空気の流れに乗って遠くまで運ばれる。このような空気感染（飛沫核感染）を起こす病原体はどれか。', '[{"key": "A", "text": "B型肝炎ウイルス"}, {"key": "B", "text": "ムンプスウイルス"}, {"key": "C", "text": "麻疹ウイルス"}, {"key": "D", "text": "インフルエンザウイルス"}, {"key": "E", "text": "ノロウイルス"}]'::jsonb, 'C', '空気感染する代表的な病原体は、麻疹ウイルス、水痘・帯状疱疹ウイルス、結核菌である。患者を陰圧の個室に収容し、医療従事者はN95マスクを着用する。麻疹は感染力がきわめて強く、免疫のない人が同じ空間にいるとほぼ確実に感染する。ワクチンの2回接種で予防する。', '{"A": "血液や体液を介して感染する。", "B": "主に飛沫感染と接触感染で広がる。", "D": "主に飛沫感染と接触感染で広がる。", "E": "主に糞口感染と接触感染で広がる。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'B群レンサ球菌', 2, 'CBT', '生後1日目の新生児が、呼吸障害と血圧低下をきたし、血液培養からグラム陽性の連鎖状の球菌が検出された。母親の腟や直腸に常在し、分娩時に児へ感染するこの菌はどれか。', '[{"key": "A", "text": "肺炎球菌"}, {"key": "B", "text": "黄色ブドウ球菌"}, {"key": "C", "text": "腸球菌"}, {"key": "D", "text": "B群レンサ球菌"}, {"key": "E", "text": "A群レンサ球菌"}]'::jsonb, 'D', 'B群レンサ球菌（Streptococcus agalactiae）は妊婦の腟や直腸に常在し、分娩時に児に感染すると、生後早期の敗血症、肺炎、髄膜炎を起こす。妊娠後期に腟と肛門周囲の培養で保菌を調べ、陽性であれば分娩時にペニシリン系抗菌薬を投与して児への感染を防ぐ。大腸菌も新生児の敗血症や髄膜炎の主な原因である。', '{"A": "乳幼児の肺炎や髄膜炎の原因となるが、母体の腟から分娩時に感染する主な菌ではない。", "B": "ブドウの房状に集まる球菌で、連鎖状には並ばない。", "C": "腸管の常在菌で、新生児の早発型敗血症の主な原因ではない。", "E": "咽頭炎、猩紅熱、蜂窩織炎などを起こし、新生児の早発型敗血症の主な原因ではない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'リステリア', 2, 'CBT', '妊婦がナチュラルチーズや生ハムを食べたあとに発熱し、胎児への感染が心配された。冷蔵庫の温度でも増殖でき、妊婦や高齢者に敗血症や髄膜炎を起こす菌はどれか。', '[{"key": "A", "text": "腸炎ビブリオ"}, {"key": "B", "text": "カンピロバクター"}, {"key": "C", "text": "ボツリヌス菌"}, {"key": "D", "text": "ウェルシュ菌"}, {"key": "E", "text": "リステリア"}]'::jsonb, 'E', 'リステリアはグラム陽性桿菌で、低温や高い塩分でも増殖できるため、冷蔵保存したチーズ、生ハム、スモークサーモンなどから感染する。細胞内で増殖し、細胞性免疫の低下した人、高齢者、妊婦、新生児で重症化する。妊娠中の感染は流産や早産、新生児の敗血症や髄膜炎の原因となる。セフェム系抗菌薬は無効で、アンピシリンを用いる。', '{"A": "海産魚介類から感染し、低温ではほとんど増殖しない。", "B": "鶏肉などから感染し、ギラン・バレー症候群の先行感染となる。", "C": "嫌気的な保存食品で毒素をつくり、麻痺を起こす。", "D": "大量調理した煮込み料理などで増殖し、下痢を起こす。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'Toll様受容体', 2, 'CBT', '自然免疫の細胞は、多くの病原体に共通する分子の構造を見分けて速やかに反応する。細菌のリポ多糖や二本鎖RNAなど、病原体に共通の分子パターンを認識する受容体はどれか。', '[{"key": "A", "text": "Toll様受容体"}, {"key": "B", "text": "T細胞受容体"}, {"key": "C", "text": "B細胞受容体"}, {"key": "D", "text": "MHCクラスI分子"}, {"key": "E", "text": "Fc受容体"}]'::jsonb, 'A', 'Toll様受容体（TLR）はマクロファージや樹状細胞などにあるパターン認識受容体で、TLR4はリポ多糖を、TLR3は二本鎖RNAを、TLR9は非メチル化CpG DNAを認識する。刺激を受けると炎症性サイトカインやI型インターフェロンを産生し、樹状細胞の成熟を促して獲得免疫の立ち上がりを助ける。胚細胞系列の遺伝子にコードされており、T細胞受容体のような遺伝子再構成はない。', '{"B": "抗原ペプチドとMHC分子の複合体を特異的に認識する獲得免疫の受容体である。", "C": "抗原の立体構造を特異的に認識する獲得免疫の受容体である。", "D": "抗原ペプチドをT細胞に提示する分子で、病原体を直接認識する受容体ではない。", "E": "抗体のFc部分に結合する受容体で、病原体の分子パターンを直接認識しない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'NK細胞の標的', 2, 'CBT', 'ウイルスに感染した細胞や腫瘍細胞の一部は、細胞傷害性T細胞から逃れるために表面の分子を減らす。NK細胞が標的細胞を傷害しやすくなるのはどのような細胞か。', '[{"key": "A", "text": "胸腺で自己抗原を提示された細胞"}, {"key": "B", "text": "MHCクラスI分子の発現が低下した細胞"}, {"key": "C", "text": "MHCクラスII分子を細胞表面に多く発現した細胞"}, {"key": "D", "text": "以前に同じ抗原で感作された細胞"}, {"key": "E", "text": "補体が結合していない細胞"}]'::jsonb, 'B', 'NK細胞は、正常な細胞がもつMHCクラスI分子を抑制性受容体で認識すると攻撃をやめる。ウイルス感染や腫瘍化でMHCクラスI分子の発現が下がると抑制が外れ、パーフォリンとグランザイムで標的細胞を殺す（missing self）。抗体が結合した細胞をFc受容体で認識して殺す抗体依存性細胞傷害も担う。事前の感作を必要としない自然免疫のリンパ球である。', '{"A": "NK細胞の標的の選別とは関係しない。", "C": "MHCクラスII分子の発現はNK細胞の標的の決め手ではない。", "D": "NK細胞は抗原特異的な記憶によらずに働く。", "E": "NK細胞の標的の選別は補体の結合に依存しない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'C5a', 2, 'CBT', '補体は活性化されると次々に分解され、生じた断片がそれぞれ異なる働きをもつ。補体の活性化で生じ、強い好中球遊走作用とアナフィラトキシン作用をもつ断片はどれか。', '[{"key": "A", "text": "C1q"}, {"key": "B", "text": "C4b"}, {"key": "C", "text": "C5a"}, {"key": "D", "text": "C3b"}, {"key": "E", "text": "C5b-9"}]'::jsonb, 'C', '補体の活性化で生じるC3aとC5aはアナフィラトキシンとよばれ、マスト細胞からのヒスタミン放出を促して血管透過性を高める。特にC5aは好中球を強く引き寄せる走化因子である。C3bは病原体を覆って貪食を促し（オプソニン化）、C5b-9は膜侵襲複合体として細菌の膜に孔をあける。補体は古典経路、第二経路、レクチン経路のいずれでもC3の分解に合流する。', '{"A": "抗原抗体複合体に結合して古典経路を開始させる。", "B": "古典経路とレクチン経路でC3転換酵素の一部となる。", "D": "病原体の表面に結合して貪食を促すオプソニンとして働く。", "E": "細菌の膜に孔をあける膜侵襲複合体である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '膜侵襲複合体の欠損', 2, 'CBT', '補体の後期成分（C5〜C9）が先天的に欠損している人では、特定の菌による感染症を繰り返しやすい。この患者で反復しやすい感染症の原因菌はどれか。', '[{"key": "A", "text": "結核菌"}, {"key": "B", "text": "カンジダ"}, {"key": "C", "text": "緑膿菌"}, {"key": "D", "text": "髄膜炎菌"}, {"key": "E", "text": "黄色ブドウ球菌"}]'::jsonb, 'D', 'ナイセリア属の菌は膜侵襲複合体による溶菌に特に弱く、C5〜C9の欠損ではナイセリア髄膜炎や淋菌の播種性感染を繰り返しやすい。補体C5に対する抗体薬（エクリズマブなど）で発作性夜間ヘモグロビン尿症などを治療する際も同じ危険が生じるため、投与前に髄膜炎菌ワクチンを接種する。C3の欠損では莢膜をもつ菌の感染を広く繰り返す。', '{"A": "主に細胞性免疫の低下で発症しやすい。", "B": "主に細胞性免疫の低下や好中球の減少で発症しやすい。", "C": "主に好中球の減少や人工物の感染で問題となる。", "E": "主に好中球の数や機能の異常で反復しやすい。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'MHCクラスIによる抗原提示', 2, 'CBT', 'ウイルスに感染した細胞は、細胞質でつくられたウイルス蛋白質の断片を細胞表面に提示して、細胞傷害性T細胞に認識される。この抗原提示に用いられる分子と、それを認識するT細胞の組合せはどれか。', '[{"key": "A", "text": "MHCクラスII分子 — CD8陽性T細胞"}, {"key": "B", "text": "MHCクラスI分子 — CD4陽性T細胞"}, {"key": "C", "text": "MHCクラスII分子 — NK細胞"}, {"key": "D", "text": "CD1分子 — B細胞"}, {"key": "E", "text": "MHCクラスI分子 — CD8陽性T細胞"}]'::jsonb, 'E', '細胞質の蛋白質はプロテアソームで分解され、ペプチドがTAPで小胞体に運ばれてMHCクラスI分子に載せられる。MHCクラスI分子はほぼすべての有核細胞に発現しており、CD8陽性T細胞が感染細胞や腫瘍細胞を見つけて傷害する。一方、エンドサイトーシスで取り込んだ外来の抗原は、抗原提示細胞のMHCクラスII分子に載せられてCD4陽性T細胞に提示される。', '{"A": "MHCクラスII分子に提示された抗原はCD4陽性T細胞が認識する。", "B": "MHCクラスI分子に提示された抗原はCD8陽性T細胞が認識する。", "C": "NK細胞はMHCクラスII分子上の抗原を特異的には認識しない。", "D": "細胞質のウイルス蛋白の提示経路ではない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '樹状細胞', 2, 'CBT', '初めて出会う抗原に対する獲得免疫の応答は、抗原を捕らえた細胞がリンパ節へ移動して始まる。未感作（ナイーブ）T細胞を最も効率よく活性化する抗原提示細胞はどれか。', '[{"key": "A", "text": "樹状細胞"}, {"key": "B", "text": "好中球"}, {"key": "C", "text": "形質細胞"}, {"key": "D", "text": "好塩基球"}, {"key": "E", "text": "赤血球"}]'::jsonb, 'A', '樹状細胞は皮膚や粘膜などで抗原を取り込み、成熟しながら所属リンパ節の傍皮質へ移動し、MHC分子に載せた抗原とCD80/86などの共刺激分子でナイーブT細胞を活性化する。皮膚の表皮にある樹状細胞はLangerhans細胞とよばれる。マクロファージやB細胞も抗原を提示するが、主に既に活性化されたT細胞との相互作用で働く。', '{"B": "病原体を貪食して殺菌する細胞で、ナイーブT細胞の活性化の主役ではない。", "C": "抗体を産生する最終分化したB細胞で、抗原提示の主役ではない。", "D": "ヒスタミンなどを放出する顆粒球で、ナイーブT細胞の活性化の主役ではない。", "E": "MHC分子をもたず、抗原提示を行わない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'T細胞の共刺激', 2, 'CBT', 'T細胞は、抗原を認識するだけでは十分に活性化せず、むしろ不応答になることがある。抗原提示細胞のCD80/86と結合して、T細胞の活性化に必要な共刺激を伝えるT細胞側の分子はどれか。', '[{"key": "A", "text": "CD19"}, {"key": "B", "text": "CD28"}, {"key": "C", "text": "CTLA-4"}, {"key": "D", "text": "PD-1"}, {"key": "E", "text": "CD8"}]'::jsonb, 'B', 'T細胞の活性化には、T細胞受容体による抗原の認識（第1シグナル）と、CD28とCD80/86の結合による共刺激（第2シグナル）が必要である。共刺激がないと、T細胞は不応答（アネルギー）の状態になる。活性化後に発現するCTLA-4はCD80/86をCD28と奪い合って応答を止める。CTLA-4とIgの融合蛋白のアバタセプトは、共刺激を妨げて関節リウマチの治療に用いられる。', '{"A": "B細胞の表面にある分子である。", "C": "CD80/86に強く結合するが、T細胞の活性化を抑える方向に働く。", "D": "PD-L1と結合してT細胞の働きを抑える受容体である。", "E": "MHCクラスI分子に結合する補助受容体である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'PD-1', 2, 'CBT', '肺癌や悪性黒色腫などの治療に、PD-1やPD-L1に対する抗体（免疫チェックポイント阻害薬）が用いられる。PD-1について正しいのはどれか。', '[{"key": "A", "text": "B細胞の抗体のクラススイッチを誘導する"}, {"key": "B", "text": "阻害しても自己免疫性の副作用は生じない"}, {"key": "C", "text": "PD-L1と結合してT細胞の働きを抑える"}, {"key": "D", "text": "腫瘍細胞だけに発現し、腫瘍の増殖を直接促す"}, {"key": "E", "text": "T細胞の活性化に必要な共刺激を伝える"}]'::jsonb, 'C', 'PD-1は慢性的に刺激された活性化T細胞に発現し、PD-L1やPD-L2と結合してT細胞の働きを抑える。本来は自己への過剰な反応を防ぐブレーキだが、多くの腫瘍はPD-L1を発現して免疫から逃れている。抗PD-1抗体や抗PD-L1抗体はこのブレーキを外して腫瘍への免疫を回復させる。副作用として、甲状腺機能異常、間質性肺炎、大腸炎、1型糖尿病などの自己免疫性の病態に注意が要る。', '{"A": "クラススイッチを誘導するのはCD40LとCD40の結合などである。", "B": "阻害すると免疫が過剰になり、甲状腺炎、大腸炎、1型糖尿病などの免疫関連の副作用が起こる。", "D": "PD-1はT細胞に発現し、腫瘍細胞に多いのはPD-L1である。", "E": "共刺激を伝えるのはCD28で、PD-1は抑制性の受容体である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'CD40リガンドとクラススイッチ', 2, 'CBT', '乳児期から細菌感染を繰り返す男児で、血清IgMは高値だが、IgG、IgA、IgEはいずれも著しく低かった。この患児で障害されている、B細胞のクラススイッチに必要な分子の相互作用はどれか。', '[{"key": "A", "text": "NK細胞とMHCクラスI分子"}, {"key": "B", "text": "マスト細胞のFcε受容体とIgE"}, {"key": "C", "text": "好中球の接着分子と血管内皮のセレクチン"}, {"key": "D", "text": "CD40リガンドとCD40の結合"}, {"key": "E", "text": "CD8陽性T細胞とMHCクラスI分子"}]'::jsonb, 'D', 'B細胞が抗原を取り込んでCD4陽性T細胞に提示すると、T細胞のCD40リガンドがB細胞のCD40に結合し、サイトカインとともにクラススイッチと親和性成熟を促す。X連鎖性の高IgM症候群はCD40リガンドの遺伝子異常によるもので、IgMはつくれるがIgGやIgAがつくれず、細菌感染やニューモシスチス肺炎を起こしやすい。', '{"A": "NK細胞の抑制に関わる相互作用で、クラススイッチには関わらない。", "B": "I型アレルギーに関わる相互作用である。", "C": "好中球が血管から出るときの相互作用である。", "E": "細胞傷害性T細胞の抗原認識で、クラススイッチには関わらない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '抗体の抗原結合部位', 2, 'CBT', '抗体（免疫グロブリン）は、2本の重鎖と2本の軽鎖がY字形に組み合わさった分子である。抗原と結合する部位を形成している部分はどれか。', '[{"key": "A", "text": "重鎖の定常部からなるFc部分"}, {"key": "B", "text": "軽鎖の定常部だけ"}, {"key": "C", "text": "J鎖"}, {"key": "D", "text": "分泌成分"}, {"key": "E", "text": "重鎖と軽鎖の可変部"}]'::jsonb, 'E', '抗体の先端（Fab部分）では、重鎖と軽鎖の可変部が組み合わさって抗原結合部位をつくる。可変部の中でも特に変化に富む超可変部（相補性決定領域）が抗原の形に合う。Fc部分はクラスごとに異なり、Fc受容体への結合、補体の活性化、胎盤の通過などの働きを決める。パパインで切断すると2つのFabと1つのFcに分かれる。', '{"A": "Fc受容体や補体との結合を担い、抗原とは結合しない。", "B": "抗原結合部位は重鎖と軽鎖の可変部が一緒につくる。", "C": "IgMやIgAの多量体をつなぐ分子で、抗原結合部位ではない。", "D": "分泌型IgAが上皮を通過するときに付く分子で、抗原結合部位ではない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '分泌型IgA', 2, 'CBT', '母乳、唾液、涙、腸管の粘液には、粘膜の表面で病原体の侵入を防ぐ抗体が多く含まれる。この分泌型IgAの特徴として正しいのはどれか。', '[{"key": "A", "text": "二量体で、J鎖と分泌成分をもつ"}, {"key": "B", "text": "単量体で、胎盤を通過する"}, {"key": "C", "text": "五量体で、補体を最も強く活性化する"}, {"key": "D", "text": "マスト細胞のFc受容体に結合している"}, {"key": "E", "text": "血中濃度が最も高い免疫グロブリンである"}]'::jsonb, 'A', '粘膜固有層の形質細胞がJ鎖でつないだ二量体のIgAを産生し、上皮細胞の多量体免疫グロブリン受容体に結合して上皮を通り抜ける。管腔側で受容体の一部が切れて分泌成分として残り、IgAを消化酵素から守る。分泌型IgAは病原体や毒素に結合して上皮への付着を防ぐ（中和）。母乳のIgAは乳児の腸管を守る。選択的IgA欠損症は日本人ではまれだが、欧米では最も多い原発性免疫不全症である。', '{"B": "IgGの特徴である。", "C": "IgMの特徴である。", "D": "IgEの特徴である。", "E": "血中で最も多いのはIgGである。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '初期応答の抗体', 2, 'CBT', 'ある感染症の急性期と回復期の血清で抗体価を比べたり、特定のクラスの抗体を測ったりして、初感染を診断する。初めて抗原に出会ったときに最初に産生され、初感染の診断に用いられる抗体のクラスはどれか。', '[{"key": "A", "text": "IgD"}, {"key": "B", "text": "IgM"}, {"key": "C", "text": "IgG"}, {"key": "D", "text": "IgA"}, {"key": "E", "text": "IgE"}]'::jsonb, 'B', '初回の抗原刺激では、まずIgMが産生され、その後クラススイッチによってIgGが産生される。IgMは五量体で抗原との結合力（結合価）が高く、補体を強く活性化する。特定の病原体に対するIgM抗体が陽性であれば、最近の初感染を示唆する。IgMは胎盤を通過しないため、新生児の血中のIgMが高値なら子宮内感染を疑う。', '{"A": "成熟したナイーブB細胞の表面にあり、血中にはわずかしかない。", "C": "IgMに遅れて産生され、長く持続するため既往の感染も反映する。", "D": "主に粘膜で働く抗体で、初感染の診断の指標としては一般的でない。", "E": "寄生虫感染やI型アレルギーに関わる抗体である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'ヒスタミン', 2, 'CBT', 'スギ花粉症の患者では、花粉を吸い込むと数分以内にくしゃみ、鼻汁、鼻閉が起こる。この反応でマスト細胞から放出され、血管透過性の亢進やかゆみを起こす主な化学伝達物質はどれか。', '[{"key": "A", "text": "C1q"}, {"key": "B", "text": "インターロイキン2"}, {"key": "C", "text": "ヒスタミン"}, {"key": "D", "text": "IgE"}, {"key": "E", "text": "インターフェロンγ"}]'::jsonb, 'C', 'I型アレルギーでは、感作によりつくられたIgEがマスト細胞や好塩基球のFcε受容体に結合しており、再び入ってきた抗原がIgEを架橋すると脱顆粒が起こる。放出されたヒスタミンは血管透過性の亢進、平滑筋の収縮、かゆみを起こし、続いて産生されるロイコトリエンやプロスタグランジンが症状を長引かせる。全身に及ぶとアナフィラキシーとなる。', '{"A": "補体の古典経路の開始成分である。", "B": "T細胞が産生し、T細胞の増殖を促すサイトカインである。", "D": "マスト細胞の表面に結合して抗原を受け止める抗体で、放出される伝達物質ではない。", "E": "主にTh1細胞やNK細胞が産生し、マクロファージを活性化する。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'II型アレルギー', 2, 'CBT', 'アレルギー反応は、関わる免疫の成分と障害の機序によってI〜IV型に分けられる。細胞や組織の表面の抗原に抗体が結合して障害を起こすII型アレルギーに分類される疾患はどれか。', '[{"key": "A", "text": "血清病"}, {"key": "B", "text": "金属による接触皮膚炎"}, {"key": "C", "text": "ループス腎炎"}, {"key": "D", "text": "自己免疫性溶血性貧血"}, {"key": "E", "text": "気管支喘息のアトピー型"}]'::jsonb, 'D', 'II型アレルギーでは、IgGやIgMが細胞や基底膜などの表面の抗原に結合し、補体の活性化、オプソニン化による貪食、抗体依存性細胞傷害によって細胞を壊す。自己免疫性溶血性貧血、不適合輸血、新生児溶血性疾患、Goodpasture症候群、免疫性血小板減少症などが含まれる。受容体に結合して機能を変えるBasedow病や重症筋無力症をII型に含めることもある。', '{"A": "免疫複合体の沈着によるIII型アレルギーである。", "B": "感作T細胞によるIV型アレルギーである。", "C": "免疫複合体の沈着によるIII型アレルギーである。", "E": "IgEとマスト細胞によるI型アレルギーである。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'III型アレルギー', 2, 'CBT', '咽頭炎の2週間後に、血尿、浮腫、高血圧が出現した小児で、血清補体価が低下していた。この疾患の主な組織障害の機序として正しいのはどれか。', '[{"key": "A", "text": "IgEが結合したマスト細胞が脱顆粒する"}, {"key": "B", "text": "糸球体基底膜の抗原に自己抗体が直接結合する"}, {"key": "C", "text": "感作T細胞がサイトカインを放出して組織を傷つける"}, {"key": "D", "text": "細菌が糸球体で直接増殖して組織を壊す"}, {"key": "E", "text": "免疫複合体の沈着と補体の活性化"}]'::jsonb, 'E', '溶連菌感染後急性糸球体腎炎では、レンサ球菌の抗原と抗体の免疫複合体が糸球体に沈着し、補体を活性化して好中球を呼び寄せ、糸球体を傷害する。血清補体価（C3）が一時的に低下し、通常は2か月ほどで回復する。III型アレルギーには血清病、ループス腎炎、クリオグロブリン血症、Arthus反応などがある。', '{"A": "I型アレルギーの機序である。", "B": "Goodpasture症候群などのII型の機序である。", "C": "IV型アレルギーの機序である。", "D": "この疾患は細菌の直接の侵入によるものではない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'IV型アレルギー', 2, 'CBT', '金属のアクセサリーを着けた部位に、48〜72時間後に紅斑、丘疹、小水疱が生じた。この反応と同じ型のアレルギーはどれか。', '[{"key": "A", "text": "結核菌抗原の皮内反応"}, {"key": "B", "text": "ペニシリン投与直後のアナフィラキシー"}, {"key": "C", "text": "ABO不適合輸血による溶血"}, {"key": "D", "text": "異種血清の投与後に生じる血清病"}, {"key": "E", "text": "食物摂取直後の蕁麻疹"}]'::jsonb, 'A', 'IV型アレルギーは感作されたT細胞が抗原に反応してサイトカインを放出し、マクロファージなどを呼び寄せて組織を傷つける遅延型の反応で、48〜72時間で最も強くなる。金属やウルシによる接触皮膚炎、結核菌の抗原の皮内反応、移植片の急性拒絶反応、肉芽腫の形成などが含まれる。抗体は関与しないため、血清を移しても伝わらない。', '{"B": "IgEによるI型アレルギーである。", "C": "抗体による細胞傷害で、II型アレルギーである。", "D": "免疫複合体によるIII型アレルギーである。", "E": "IgEによるI型アレルギーである。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'Th2細胞', 2, 'CBT', 'アトピー性皮膚炎や気管支喘息では、ある種のヘルパーT細胞の働きが優位になっている。IL-4、IL-5、IL-13を産生し、IgEの産生や好酸球の動員を促すヘルパーT細胞はどれか。', '[{"key": "A", "text": "CD8陽性T細胞"}, {"key": "B", "text": "Th2細胞"}, {"key": "C", "text": "Th1細胞"}, {"key": "D", "text": "Th17細胞"}, {"key": "E", "text": "制御性T細胞"}]'::jsonb, 'B', 'ナイーブCD4陽性T細胞は、周囲のサイトカインによって異なるヘルパーT細胞に分化する。Th2細胞はIL-4でB細胞のIgEへのクラススイッチを、IL-5で好酸球の分化と活性化を、IL-13で気道の粘液の分泌を促し、寄生虫の排除とアレルギーに関わる。IL-5やIL-4受容体に対する抗体薬が重症の喘息やアトピー性皮膚炎に用いられる。', '{"A": "ヘルパーT細胞ではなく、感染細胞を傷害する細胞である。", "C": "インターフェロンγを産生し、マクロファージを活性化して細胞内寄生菌を排除する。", "D": "IL-17を産生し、好中球の動員や乾癬の病態に関わる。", "E": "IL-10やTGF-βなどで免疫応答を抑える。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '制御性T細胞', 2, 'CBT', '転写因子FOXP3の遺伝子異常では、乳児期から重い腸炎、1型糖尿病、湿疹などの多臓器の自己免疫疾患が生じる。FOXP3を発現し、免疫応答を抑える働きをもつ細胞はどれか。', '[{"key": "A", "text": "形質細胞"}, {"key": "B", "text": "NK細胞"}, {"key": "C", "text": "制御性T細胞"}, {"key": "D", "text": "Th1細胞"}, {"key": "E", "text": "Th17細胞"}]'::jsonb, 'C', '制御性T細胞はCD4とCD25（IL-2受容体α鎖）を強く発現し、FOXP3を主な転写因子とする。IL-10やTGF-βの産生、CTLA-4によるCD80/86の除去などで、自己に反応するT細胞や過剰な免疫応答を抑える（末梢性免疫寛容）。FOXP3の異常はIPEX症候群とよばれ、多臓器の自己免疫疾患を乳児期から起こす。', '{"A": "抗体を産生する細胞で、FOXP3は発現しない。", "B": "自然免疫のリンパ球で、FOXP3は発現しない。", "D": "インターフェロンγを産生して細胞性免疫を促す。", "E": "IL-17を産生して炎症を促す。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '胸腺での正の選択', 2, 'CBT', '胸腺では、発生途中のT細胞が選別を受け、成熟するのはごく一部に限られる。胸腺の皮質で起こる正の選択の意義として正しいのはどれか。', '[{"key": "A", "text": "B細胞の抗体のクラスを切り替える"}, {"key": "B", "text": "T細胞に抗原への記憶をもたせる"}, {"key": "C", "text": "NK細胞に抑制性受容体を発現させる"}, {"key": "D", "text": "自己MHCを認識できるT細胞を残す"}, {"key": "E", "text": "自己抗原に強く反応するT細胞を除去する"}]'::jsonb, 'D', '胸腺の皮質では、上皮細胞の自己MHC分子と自己ペプチドの複合体をある程度認識できるT細胞だけが生き残り、認識できないものは死滅する（正の選択）。このときMHCクラスIを認識したものはCD8、クラスIIを認識したものはCD4の単独陽性細胞となる。髄質では自己抗原に強く反応するT細胞が除去される（負の選択）。こうして自己のMHC拘束性と自己寛容の両方が成り立つ。', '{"A": "胸腺の選択とは関係しない。", "B": "記憶は末梢での抗原刺激によってつくられる。", "C": "胸腺の正の選択とは関係しない。", "E": "負の選択の説明で、主に髄質で起こる。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm')
),
added AS (
    INSERT INTO quiz_question (category, topic, difficulty, exam_type, question_text, choices, correct_choice_key, explanation, choice_explanations, visibility, question_type, blueprint_code, class_group, status, source, correct_rate, answer_count, created_at)
    SELECT v.category, v.topic, v.difficulty, v.exam_type, v.question_text, v.choices, v.correct_choice_key, v.explanation, v.choice_explanations, v.visibility, v.question_type, v.blueprint_code, v.class_group, v.status, v.source, 0, 0, now()
    FROM v
    WHERE NOT EXISTS (
        SELECT 1 FROM quiz_question q
        WHERE q.exam_type = v.exam_type
          AND q.question_text = v.question_text
          AND q.choices = v.choices)
    RETURNING 1
)
SELECT (SELECT count(*) FROM added) AS "追加した問題",
       (SELECT count(*) FROM v) - (SELECT count(*) FROM added) AS "すでにあった問題",
       (SELECT count(*) FROM v) AS "このファイルの問題";
